const OPS_BRAIN_CHAT_SCHEMA_VERSION = "companion-state-v13";
const OPS_BRAIN_CONVERSATION_SESSION_SCHEMA = "ops-conversation-session-v1";
const OPS_BRAIN_CHAT_HISTORY_LIMIT = 64;
const OPS_BRAIN_CHAT_SCOPE_LIMIT = 80;
const DETAIL_AI_CHAT_HISTORY_LIMIT = 18;
const DETAIL_AI_CHAT_AWB_LIMIT = 40;
const CANONICAL_GMAIL_INGESTION_PIPELINE = "gmail-direct-oauth-cron";
const PIKIIO_APP_RUNTIME_VERSION = "ops-loop-v13";
const TRUTH_API_NETWORK_TIMEOUT_MIN_MS = 4000;
const TRUTH_API_NETWORK_TIMEOUT_MS = 6000;
const TRUTH_API_SLOW_NETWORK_TIMEOUT_MS = 8000;
const TRUTH_API_NETWORK_ATTEMPTS = 2;
const TRUTH_API_RESPONSE_MARGIN_MS = 1500;
const TRUTH_API_LIVE_REREAD_HEADER = "x-pikiio-live-truth-reread";
if (typeof window !== "undefined") window.PIKIIO_APP_RUNTIME_VERSION = PIKIIO_APP_RUNTIME_VERSION;

function truthApiNetworkAttemptTimeoutMs(connection = typeof navigator !== "undefined" ? navigator.connection : null) {
  const effectiveType = String(connection?.effectiveType || "").toLowerCase();
  const timeoutMs = ["slow-2g", "2g", "3g"].includes(effectiveType)
    ? TRUTH_API_SLOW_NETWORK_TIMEOUT_MS
    : TRUTH_API_NETWORK_TIMEOUT_MS;
  return Math.max(TRUTH_API_NETWORK_TIMEOUT_MIN_MS, timeoutMs);
}

function truthApiRequestTimeoutMs(options = {}) {
  const attempts = options.liveReread === true ? 1 : TRUTH_API_NETWORK_ATTEMPTS;
  return truthApiNetworkAttemptTimeoutMs() * attempts + TRUTH_API_RESPONSE_MARGIN_MS;
}

function emptyOpsBrainConversationSessionState() {
  return {
    schema: OPS_BRAIN_CONVERSATION_SESSION_SCHEMA,
    focusedAwb: "",
    focusedStation: "",
    lastResultItemIds: [],
    lastIntent: "",
    lastCounterpartyRole: "",
    pendingClarification: null,
  };
}

function normalizeOpsBrainConversationOption(option) {
  if (!option || typeof option !== "object" || Array.isArray(option)) return null;
  const id = String(option.id || "").toLowerCase().replace(/[^a-z0-9:_-]/g, "").slice(0, 80);
  const scope = ["fleet", "shipment", "station"].includes(option.scope) ? option.scope : "";
  const awb = scope === "shipment" ? opsBrainAwbKey(option.awb) : "";
  const station = scope === "station" || scope === "shipment"
    ? String(option.station || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 5)
    : "";
  if (!id || !scope || (scope === "shipment" && !awb) || (scope === "station" && !station)) return null;
  return { id, scope, awb, station };
}

function normalizeOpsBrainConversationSessionState(value) {
  const input = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const intents = ["status", "next-action", "blocker-why", "contacts", "eta", "pod", "cargo", "urgent", "stuck", "waiting-on", "arrived-window", "last-outbound"];
  const roles = ["station", "customs-broker", "pickup-broker", "consignee", "carrier", "driver"];
  const pendingInput = input.pendingClarification && typeof input.pendingClarification === "object"
    ? input.pendingClarification
    : null;
  const pendingOptions = pendingInput
    ? (pendingInput.options || []).map(normalizeOpsBrainConversationOption).filter(Boolean).slice(0, 2)
    : [];
  const pendingClarification = pendingInput && ["scope", "reference", "router"].includes(pendingInput.kind) && pendingOptions.length
    ? {
        kind: pendingInput.kind,
        intent: intents.includes(pendingInput.intent) ? pendingInput.intent : "status",
        options: pendingOptions,
      }
    : null;
  return {
    schema: OPS_BRAIN_CONVERSATION_SESSION_SCHEMA,
    focusedAwb: opsBrainAwbKey(input.focusedAwb),
    focusedStation: String(input.focusedStation || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 5),
    lastResultItemIds: [...new Set((input.lastResultItemIds || []).map(opsBrainAwbKey).filter(Boolean))].slice(0, 12),
    lastIntent: intents.includes(input.lastIntent) ? input.lastIntent : "",
    lastCounterpartyRole: roles.includes(input.lastCounterpartyRole) ? input.lastCounterpartyRole : "",
    pendingClarification,
  };
}

function normalizeOpsBrainClarification(value) {
  if (!value || typeof value !== "object" || !["scope", "reference", "router"].includes(value.kind)) return null;
  const options = (value.options || []).map((option) => {
    const safe = normalizeOpsBrainConversationOption(option);
    if (!safe) return null;
    return {
      ...safe,
      label: String(option.label || "").slice(0, 80),
      question: String(option.question || "").slice(0, 80),
    };
  }).filter(Boolean).slice(0, 2);
  return options.length ? { kind: value.kind, options } : null;
}

