function readDetailAiChats() {
  try {
    const values = JSON.parse(localStorage.getItem("pikiio-detail-ai-chats") || "{}");
    if (!values || typeof values !== "object" || Array.isArray(values)) return {};
    const entries = Object.entries(values)
      .map(([awb, messages]) => [
        opsBrainAwbKey(awb),
        Array.isArray(messages) ? messages.map(normalizeDetailAiMessage).filter(Boolean).slice(-DETAIL_AI_CHAT_HISTORY_LIMIT) : [],
      ])
      .filter(([awb, messages]) => awb && messages.length)
      .slice(-DETAIL_AI_CHAT_AWB_LIMIT);
    return Object.fromEntries(entries);
  } catch {
    return {};
  }
}

