function retireLegacyBrowserOperatorTruth() {
  // These stores were browser-only shadow truth. Removing them is migration,
  // not evidence deletion: neither store was a canonical source ledger.
  try { localStorage.removeItem("pikiio-ops-brain-operator-notes"); } catch { /* storage may be unavailable */ }
  try { localStorage.removeItem("pikiio-operator-truth-floors-v1"); } catch { /* storage may be unavailable */ }
}

