function operatorNotificationTimeMs(notification) {
  const parsed = Date.parse(notification?.occurredAt || notification?.createdAt || "");
  return Number.isFinite(parsed) ? parsed : 0;
}

function operatorNotificationConditionKey(notification) {
  const explicit = String(notification?.conditionKey || notification?.source?.conditionKey || "").trim();
  if (explicit) return explicit;
  const awb = opsBrainAwbKey(notification?.awb || notification?.source?.awb || notification?.subtitle || "");
  const type = String(notification?.type || notification?.eventType || "operator-event").toLowerCase().trim();
  return awb && type ? `${awb}:${type}` : String(notification?.id || "");
}

function operatorNotificationSeenKey(notification) {
  // System notifications (no AWB/type pair) key by their stable id.
  if (notification?.system && notification?.notificationId) return notification.notificationId;
  return operatorNotificationConditionKey(notification) || String(notification?.id || "");
}

function mergeOperatorNotificationCondition(previous, incoming) {
  if (!previous) return incoming;
  const previousTime = operatorNotificationTimeMs(previous);
  const incomingTime = operatorNotificationTimeMs(incoming);
  const first = previousTime && incomingTime && incomingTime < previousTime ? incoming : previous;
  const latest = incomingTime >= previousTime ? incoming : previous;
  return {
    ...first,
    ...latest,
    id: first.id || latest.id,
    eventId: first.eventId || first.id || latest.eventId || latest.id,
    operatorEventId: first.operatorEventId || first.eventId || first.id || latest.operatorEventId || latest.eventId || latest.id,
    source: latest.source || first.source || {},
  };
}

function normalizedOperatorNotificationTitle(type, title) {
  if (!/^(?:Shipment needs attention|Shipment update)$/i.test(String(title || "").trim())) return title;
  const normalizedType = String(type || "").toLowerCase();
  if (normalizedType === "pickup-location-requested") return "Pickup location needed";
  if (normalizedType === "pickup-docs-needed") return "Delivery order/docs needed";
  if (normalizedType === "driver-waiting") return "Driver waiting at airport";
  if (normalizedType === "station-cargo-not-found") return "Cargo not found at station";
  if (normalizedType === "station-release-not-visible" || normalizedType === "airline-transmission-blocker") return "Airport release blocker";
  if (normalizedType === "piece-count-mismatch") return "Piece count mismatch";
  if (normalizedType === "storage-or-detention-cost") return "Storage/detention cost";
  if (normalizedType === "delivery-facility-closed") return "Delivery blocked";
  if (normalizedType === "storage-needed-after-delivery-blocker") return "Storage decision needed";
  if (normalizedType === "loading-problem") return "Loading problem";
  if (normalizedType === "broker-release-pending") return "Release/DO needed";
  if (normalizedType === "pickup-onsite") return "Carrier onsite";
  if (normalizedType === "pickup-loaded") return "Truck loaded";
  if (normalizedType === "delivered-pod-received") return "Delivered; POD found";
  if (normalizedType === "delivered-pod-missing") return "Delivered; POD missing";
  return title || "Shipment update";
}

function normalizeOperatorNotification(notification) {
  if (!notification) return notification;
  const type = notification.eventType || notification.type || "operator-event";
  return {
    ...notification,
    type,
    title: normalizedOperatorNotificationTitle(type, notification.title),
  };
}

function collapseOperatorNotifications(notifications) {
  const byCondition = new Map();
  for (const notification of notifications || []) {
    if (!notification?.id) continue;
    const normalized = normalizeOperatorNotification(notification);
    const key = operatorNotificationConditionKey(normalized);
    if (!key) continue;
    byCondition.set(key, mergeOperatorNotificationCondition(byCondition.get(key), normalized));
  }
  return [...byCondition.values()];
}

function operatorEventAsNotification(event) {
  if (!event?.eventId && !event?.id) return null;
  return normalizeOperatorNotification({
    id: event.eventId || event.id,
    eventId: event.eventId || event.id,
    awb: event.awb || "",
    type: event.eventType || event.type || "operator-event",
    conditionKey: event.conditionKey || event.source?.conditionKey || "",
    severity: event.notificationSeverity || event.source?.notificationSeverity || event.severity || "work",
    status: event.status || "active",
    title: event.title || "Shipment update",
    subtitle: event.subtitle || event.awb || "",
    message: event.message || event.title || "Shipment needs attention.",
    nextAction: event.nextAction || event.next_action || "Open Yael and decide the next move.",
    occurredAt: event.occurredAt || event.occurred_at || "",
    createdAt: event.createdAt || event.created_at || "",
    source: event.source || {},
    operatorEventId: event.eventId || event.id,
  });
}

function applyOperatorEventsToNotifications() {
  const eventNotifications = (state.operatorEvents || []).map(operatorEventAsNotification).filter(Boolean);
  if (!eventNotifications.length) return;
  const existing = state.operatorNotifications?.notifications || [];
  const byId = new Map();
  for (const notification of collapseOperatorNotifications([...existing, ...eventNotifications])) {
    if (notification?.id) byId.set(notification.id, notification);
  }
  const eventSignature = eventNotifications
    .map((notification) => [notification.id, notification.status, notification.occurredAt].join("@"))
    .join("|");
  state.operatorNotifications = {
    ...(state.operatorNotifications || {}),
    source: state.operatorNotifications?.source || "operator-events",
    snapshotTime: state.operatorNotifications?.snapshotTime || new Date().toISOString(),
    contentSignature: [
      state.operatorNotifications?.contentSignature || "",
      eventSignature ? `operator-events:${eventSignature}` : "",
    ].filter(Boolean).join(":"),
    notifications: [...byId.values()],
  };
}

function opsBrainSnapshotKey() {
  const snapshotTime = state.opsBrain?.snapshotTime || state.snapshotTime || "";
  const gmailProofTime = state.gmailProof?.snapshotTime || "";
  const notificationKey = state.operatorNotifications?.contentSignature || state.operatorNotifications?.snapshotTime || "";
  return [snapshotTime, gmailProofTime, notificationKey, OPS_BRAIN_CHAT_SCHEMA_VERSION].filter(Boolean).join(":");
}

function syncOpsBrainChatToSnapshot() {
  const snapshotKey = opsBrainSnapshotKey();
  if (!snapshotKey) return;
  const storedKey = localStorage.getItem("pikiio-ops-brain-chat-snapshot") || "";
  if ((storedKey && storedKey !== snapshotKey) || (!storedKey && state.opsBrainChatHistory.length)) {
    state.opsBrainChatSessions = {};
    state.opsBrainActiveChatKey = "global";
    state.opsBrainChatHistory = [];
    state.opsBrainThinkingQuestion = "";
    state.opsBrainHasReadyAnswer = false;
    state.opsBrainConversationSessionState = emptyOpsBrainConversationSessionState();
    state.opsBrainContext = { awb: "", topic: "", station: "", contactRole: "" };
    localStorage.setItem("pikiio-ops-brain-chat", "[]");
    localStorage.setItem("pikiio-ops-brain-chat-sessions", "{}");
    localStorage.setItem("pikiio-ops-brain-context", "{}");
  }
  repairOpsBrainAwbChatHistory();
  localStorage.setItem("pikiio-ops-brain-chat-snapshot", snapshotKey);
}

function activeOperatorNotifications() {
  return collapseOperatorNotifications(state.operatorNotifications?.notifications || [])
    .filter((notification) => notification?.id && notification.status !== "resolved" && notification.status !== "dismissed")
    .filter((notification) => ["immediate", "urgent", "needs-action", "work", "today"].includes(String(notification.severity || "").toLowerCase()))
    .filter(operatorNotificationStillRelevant)
    .sort((a, b) => Date.parse(a.occurredAt || a.createdAt || "") - Date.parse(b.occurredAt || b.createdAt || ""));
}

function shipmentForOperatorNotification(notification) {
  const awbKey = opsBrainAwbKey(notification?.awb || notification?.source?.awb || "");
  return opsBrainAllShipments().find((shipment) =>
    awbKey && (opsBrainAwbKey(shipment.awb || "") === awbKey || opsBrainAwbKey(shipment.id || "") === awbKey)
  ) || null;
}

function operatorNotificationStillRelevant(notification) {
  const shipment = shipmentForOperatorNotification(notification);
  if (!shipment) return true;
  const type = String(notification?.type || "");
  const resolved = opsBrainResolvedShipmentState(shipment);
  if (/delivered-pod-missing/.test(type) && (resolved.podReceived || shipmentHasPodProof(shipment))) return false;
  if (/pickup-(?:onsite|docs-needed|location-requested)|release|delivery-order|customs/i.test(type) &&
    (resolved.pickedUp || resolved.delivered || resolved.deliveryScheduledTodayOrFuture || shipmentHasPodProof(shipment))) {
    return false;
  }
  return true;
}

function operatorNotificationSourceContact(notification) {
  const from = notification?.source?.from || "";
  const email = addressEmails(from)[0] || "";
  if (!email || /@(demo-freight\.example|harbor-forwarding\.example)$/i.test(email)) return null;
  return {
    email,
    name: addressDisplayName(from) || email,
  };
}

function operatorNotificationFallbackAction(notification, shipment) {
  const type = String(notification?.type || "");
  if (!shipment || !/(pickup-loaded|delivered-pod-missing)/.test(type)) return null;
  const contact = operatorNotificationSourceContact(notification);
  if (!contact) return null;
  const awb = notification.awb || shipment.awb || "";
  const delivered = /delivered-pod-missing/.test(type);
  const resolved = opsBrainResolvedShipmentState(shipment);
  if (!delivered && resolved.deliveryScheduledTodayOrFuture && !resolved.podPending) return null;
  return {
    id: `operator-notification:${notification.id}:pod-followup`,
    type: "pod-followup",
    channel: "gmail",
    status: "suggested",
    label: `Request POD from ${contact.name}`,
    awb,
    shipmentId: shipment.id || "",
    targetName: contact.name,
    targetEmail: contact.email,
    subject: notification.source?.subject || `${awb} - POD request`,
    reason: delivered
      ? "Delivery was reported, but the signed POD is still missing."
      : "Truck loaded; delivery/POD is the next proof to collect.",
    timing: {
      stage: delivered ? "delivered" : "picked-up",
      trigger: delivered ? "delivered-pod-missing" : "pickup-loaded",
      source: "operator-event",
      dueAt: notification.occurredAt || "",
      leadHours: null,
    },
    threadPolicy: "reply_existing",
    threadTopic: "pickup",
    body: [
      "Hi,",
      "",
      delivered
        ? `Can you please send the signed POD/delivery confirmation for AWB ${awb}?`
        : `Can you please send POD/delivery confirmation for AWB ${awb} once delivered?`,
      "",
      "Thank you,",
      "Alex",
    ].join("\n"),
    conversation: {
      threadId: notification.source?.threadId || "",
      replyMessageId: notification.source?.messageId || "",
      subject: notification.source?.subject || "",
    },
    safety: { mode: "draft-only" },
  };
}

function operatorNotificationActions(notification) {
  const shipment = shipmentForOperatorNotification(notification);
  if (!shipment) return [];
  const type = String(notification?.type || "");
  const rows = [
    ...airportDwellActionsForShipment(shipment),
    ...draftActionsForShipment(shipment),
  ].filter((action) => action && !isPlatformAlertAction(action) && actionMatchesShipmentState(action, shipment));
  const wanted = (action) => {
    if (/pickup-location-requested/.test(type)) return action.type === "pickup-location-reply";
    if (/pickup-docs-needed/.test(type)) return action.type === "delivery-order" || /delivery order|docs/i.test(`${action.label || ""} ${action.reason || ""}`);
    if (/pickup-onsite/.test(type)) return /broker-status-followup|dispatch-pickup-followup|delivery-order|pickup-location-reply/.test(action.type || "");
    if (/pickup-loaded/.test(type)) return /pod-followup|broker-status-followup|tms-pod-closeout-experience/.test(action.type || "");
    if (/delivered-pod-missing/.test(type)) return /pod-followup|broker-status-followup/.test(action.type || "");
    if (/delivered-pod-received/.test(type)) return /tms-pod-closeout-experience/.test(action.type || "");
    return true;
  };
  const prioritized = rows.filter(wanted);
  const fallback = operatorNotificationFallbackAction(notification, shipment);
  return uniqueRowsByKey(
    [...(prioritized.length ? prioritized : rows), fallback].filter(Boolean),
    (action) => action.id || `${action.type}:${action.targetEmail}:${action.subject}`,
  ).slice(0, 2).map((action) => ({
    ...action,
    operatorEventId: notification.operatorEventId || notification.eventId || notification.id || "",
  }));
}

function isMorningReportNotification(notification) {
  return String(notification?.type || notification?.eventType || "").toLowerCase() === "morning-report" ||
    String(notification?.source?.kind || "").toLowerCase() === "morning-report";
}

function morningReportFromNotification(notification) {
  return notification?.source?.report && typeof notification.source.report === "object"
    ? notification.source.report
    : null;
}

function morningReportMessage(notification) {
  const report = morningReportFromNotification(notification) || {};
  const counts = report.counts || {};
  const rows = Array.isArray(report.rows) && report.rows.length
    ? report.rows
    : [
        ...(report.delivery?.items || []),
        ...(report.arrivals?.items || []),
        ...(report.priority?.items || []),
      ];
  const actions = Array.isArray(report.actions) ? report.actions : [];
  const summary = report.summary || notification.message || "Morning report is ready.";
  return {
    role: "assistant",
    title: "Morning report",
    subtitle: notification.subtitle || "7:00 AM operator report",
    content: summary.replace(/\.$/, "."),
    facts: [
      Number.isFinite(Number(counts.deliveryToday)) ? `Delivery today: ${counts.deliveryToday}` : "",
      Number.isFinite(Number(counts.arrivalsToHandle)) ? `Arrivals to handle: ${counts.arrivalsToHandle}` : "",
      Number.isFinite(Number(counts.priorityItems)) ? `Priority list: ${counts.priorityItems}` : "",
    ].filter(Boolean),
    items: rows.slice(0, 3),
    allItems: rows,
    actions: rows.length ? [] : actions.slice(0, 3).map((action) => ({
      ...action,
      operatorEventId: notification.operatorEventId || notification.eventId || notification.id || "",
    })),
    shipmentIds: rows.map((row) => row.id || row.awb).filter(Boolean).slice(0, 12),
    notificationId: notification.id,
    notificationConditionKey: operatorNotificationSeenKey(notification),
    createdAt: new Date().toISOString(),
    context: { topic: "morning-report", date: report.localDate || "" },
  };
}

function operatorNotificationMessage(notification) {
  if (isMorningReportNotification(notification)) return morningReportMessage(notification);
  const shipment = shipmentForOperatorNotification(notification);
  const context = notification.subtitle || [shipment?.station, shipment?.airline].filter(Boolean).join(" · ");
  const lines = [
    notification.awb || shipment?.awb || "",
    context,
    notification.message || notification.title || "Shipment needs attention.",
    `Now: ${notification.nextAction || "Open the thread and decide the next move."}`,
  ].filter(Boolean);
  return {
    role: "assistant",
    title: notification.awb || shipment?.awb || notification.title || "Shipment update",
    subtitle: notification.title || "Operator message",
    content: lines.join("\n"),
    facts: notification.occurredAt ? [`Detected ${formatShortDate(notification.occurredAt)}`] : [],
    actions: operatorNotificationActions(notification),
    shipmentIds: shipment?.id ? [shipment.id] : [],
    notificationId: notification.id,
    notificationConditionKey: operatorNotificationSeenKey(notification),
    createdAt: new Date().toISOString(),
  };
}

function refreshOperatorNotificationChatMessages() {
  const history = state.opsBrainChatHistory || [];
  if (!history.length) return;
  const notifications = state.operatorNotifications?.notifications || [];
  let changed = false;
  const refreshed = history.map((message) => {
    if (!message.notificationId) return message;
    const messageCondition = message.notificationConditionKey || "";
    const notification = notifications.find((item) =>
      item.id === message.notificationId ||
      (messageCondition && operatorNotificationSeenKey(item) === messageCondition)
    );
    if (!notification || !operatorNotificationStillRelevant(notification)) {
      changed = true;
      return null;
    }
    const nextMessage = operatorNotificationMessage(notification);
    changed = true;
    return {
      ...nextMessage,
      createdAt: message.createdAt || nextMessage.createdAt,
    };
  }).filter(Boolean);
  if (!changed) return;
  state.opsBrainChatHistory = refreshed.slice(-OPS_BRAIN_CHAT_HISTORY_LIMIT);
  persistOpsBrainChatHistory();
}

function syncOperatorNotificationsToChat() {
  refreshOperatorNotificationChatMessages();
  const notifications = activeOperatorNotifications()
    .filter((notification) => !state.seenOperatorNotifications.has(operatorNotificationSeenKey(notification)))
    .filter((notification) => !(state.opsBrainChatHistory || []).some((message) =>
      message.notificationId === notification.id ||
      message.notificationConditionKey === operatorNotificationSeenKey(notification)
    ));
  if (!notifications.length) return;
  const messages = notifications.map(operatorNotificationMessage);
  state.opsBrainChatHistory = [...(state.opsBrainChatHistory || []), ...messages].slice(-OPS_BRAIN_CHAT_HISTORY_LIMIT);
  for (const notification of notifications) state.seenOperatorNotifications.add(operatorNotificationSeenKey(notification));
  persistSeenOperatorNotifications();
  persistOpsBrainChatHistory();
  state.opsBrainHasReadyAnswer = true;
}

function operatorNotificationTargetFromPayload(payload = {}, fallback = {}) {
  const data = payload?.data && typeof payload.data === "object" ? payload.data : {};
  const source = payload?.source && typeof payload.source === "object" ? payload.source : {};
  const notificationId = payload.notificationId || payload.eventId || payload.id || data.eventId || data.id || fallback.notificationId || "";
  const awb = opsBrainAwbKey(payload.awb || data.awb || source.awb || fallback.awb || "");
  const type = String(payload.type || data.eventType || data.type || fallback.type || "").toLowerCase().trim();
  return { notificationId, awb, type };
}

function operatorNotificationMatchesTarget(notification, target) {
  if (!notification || !target) return false;
  if (target.notificationId && [notification.id, notification.eventId, notification.operatorEventId].includes(target.notificationId)) return true;
  const awb = opsBrainAwbKey(notification.awb || notification.source?.awb || "");
  const type = String(notification.type || notification.eventType || "").toLowerCase().trim();
  return Boolean(target.awb && awb === target.awb && (!target.type || target.type === type));
}

function findOperatorNotificationTarget(target) {
  const notifications = collapseOperatorNotifications([
    ...(state.operatorNotifications?.notifications || []),
    ...(state.operatorEvents || []).map(operatorEventAsNotification).filter(Boolean),
  ]);
  return notifications.find((notification) => operatorNotificationMatchesTarget(notification, target)) || null;
}

function selectShipmentByAwbTarget(awb) {
  const awbKey = opsBrainAwbKey(awb);
  if (!awbKey) return false;
  const shipment = opsBrainAllShipments().find((item) =>
    opsBrainAwbKey(item.awb || item.id || "") === awbKey
  );
  if (!shipment) return false;
  state.selectedId = shipment.id || shipment.awb || awbKey;
  state.selectedGroupId = null;
  state.selectedVisualGroupKey = null;
  state.detailOpen = true;
  setOpsBrainContextFromShipment(shipment, "selection");
  return true;
}

function forceOperatorNotificationIntoChat(notification, options = {}) {
  if (!notification) return false;
  const nextMessage = operatorNotificationMessage(notification);
  const conditionKey = nextMessage.notificationConditionKey || operatorNotificationSeenKey(notification);
  state.opsBrainChatHistory = (state.opsBrainChatHistory || [])
    .filter((message) =>
      message.notificationId !== nextMessage.notificationId &&
      (!conditionKey || message.notificationConditionKey !== conditionKey)
    )
    .concat(nextMessage)
    .slice(-OPS_BRAIN_CHAT_HISTORY_LIMIT);
  if (conditionKey) state.seenOperatorNotifications.add(conditionKey);
  persistSeenOperatorNotifications();
  persistOpsBrainChatHistory();
  state.opsBrainHasReadyAnswer = true;
  if (!options.keepFilter) state.filter = "brain";
  selectShipmentByAwbTarget(notification.awb || notification.source?.awb || "");
  return true;
}

function openOperatorNotificationTarget(payload = {}, options = {}) {
  const target = operatorNotificationTargetFromPayload(payload, state.pendingOperatorNotificationTarget || {});
  if (!target.notificationId && !target.awb) return false;
  const notification = findOperatorNotificationTarget(target);
  if (!options.keepFilter) state.filter = "brain";
  if (notification) return forceOperatorNotificationIntoChat(notification, options);
  if (target.awb && selectShipmentByAwbTarget(target.awb)) {
    state.opsBrainHasReadyAnswer = true;
    if (options.askFallback) submitOpsBrainQuestion(`what needs action on ${opsBrainDisplayAwb(target.awb)}?`);
    return true;
  }
  return false;
}

function repairOpsBrainAwbChatHistory() {
  const history = state.opsBrainChatHistory || [];
  if (!history.length) return;
  const repaired = [];
  let changed = false;
  for (let index = 0; index < history.length; index += 1) {
    const message = history[index];
    repaired.push(message);
    if (message.role !== "user" || !opsBrainShipmentForQuery(message.content)) continue;
    const answer = opsBrainAnswer(message.content);
    const assistant = opsBrainAssistantHistoryMessage(answer, history[index + 1]?.createdAt || new Date().toISOString());
    repaired.push(assistant);
    if (history[index + 1]?.role === "assistant") index += 1;
    changed = true;
  }
  if (!changed) return;
  state.opsBrainChatHistory = repaired.slice(-OPS_BRAIN_CHAT_HISTORY_LIMIT);
  localStorage.setItem("pikiio-ops-brain-chat", JSON.stringify(state.opsBrainChatHistory));
}

