function operatorTruthAttemptFor(entry, previous = {}) {
  const semanticKey = JSON.stringify([
    entry.command,
    entry.awb,
    entry.contactName,
    entry.contactOrganization,
    entry.proof || "",
    entry.note || "",
  ]);
  if (previous._truthAttempt?.semanticKey === semanticKey) {
    return { ...entry, _truthAttempt: previous._truthAttempt };
  }
  const fallbackKey = `operator_browser_${Date.now().toString(36)}_${Math.random().toString(36).slice(2)}_${Math.random().toString(36).slice(2)}`
    .replace(/[^A-Za-z0-9_-]/g, "_")
    .padEnd(32, "0")
    .slice(0, 128);
  return {
    ...entry,
    _truthAttempt: {
      semanticKey,
      idempotencyKey: globalThis.crypto?.randomUUID?.() || fallbackKey,
      occurredAt: new Date().toISOString(),
    },
  };
}

async function saveStructuredOperatorTruthViaApi(entry) {
  const attempt = entry?._truthAttempt || {};
  const response = await fetch("/api/truth/operator-browser-event", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-pikiio-operator-csrf": "structured-phone-truth-v1",
      "idempotency-key": attempt.idempotencyKey || "",
    },
    body: JSON.stringify({
      schemaVersion: "operator-browser-truth-command-v1",
      command: entry.command,
      subject: { awb: opsBrainAwbKey(entry.awb) },
      occurredAt: attempt.occurredAt,
      contact: {
        name: String(entry.contactName || "").trim(),
        organization: String(entry.contactOrganization || "").trim(),
      },
      reference: {
        proof: String(entry.proof || "").trim(),
        note: String(entry.note || "").trim(),
      },
    }),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(result.error || "Unable to record structured operator truth");
    error.statusCode = response.status;
    error.code = result.code || "";
    error.outcomeUnknown = result.outcomeUnknown === true;
    error.safeToRetryWithSameIdempotencyKey = result.safeToRetryWithSameIdempotencyKey === true;
    throw error;
  }
  return result;
}

async function loadHostedSnapshots(keysToLoad = snapshotKeys) {
  const keys = (Array.isArray(keysToLoad) ? keysToLoad : snapshotKeys)
    .map((key) => String(key || "").trim())
    .filter(Boolean);
  if (!keys.length) return null;
  const url = `/api/snapshots?keys=${encodeURIComponent(keys.join(","))}&slim=1&ts=${Date.now()}`;
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), truthApiRequestTimeoutMs());
  try {
    const response = await fetch(url, {
      cache: "no-store",
      signal: controller.signal,
      headers: { accept: "application/json", "cache-control": "no-cache" },
    });
    const result = await response.json().catch(() => ({}));
    if (truthApiResponseIsCacheFallback(response)) {
      applyTruthApiPayloadHealth(markTruthApiPayloadAsCacheFallback(result, { syncingLive: true }));
      scheduleBrainTruthCacheFallbackRecovery();
      return null;
    }
    if (!response.ok || result.ok === false) return null;

    const snapshots = result.snapshots && typeof result.snapshots === "object" && !Array.isArray(result.snapshots)
      ? { ...result.snapshots }
      : {};
    if (result.updatedAt) snapshots.updatedAt = result.updatedAt;

    return Object.keys(snapshots).length ? snapshots : null;
  } finally {
    window.clearTimeout(timeout);
  }
}

const TRUTH_API_CACHE_FALLBACK_WARNING =
  "Showing an old backup copy because the live truth API did not answer within the browser timeout.";

function truthApiResponseIsCacheFallback(response) {
  return String(response?.headers?.get?.("x-pikiio-cache-fallback") || "") === "1";
}

function truthApiCacheFallbackSyncState() {
  return {
    state: "stale-fallback",
    tone: "bad",
    lockActions: true,
    title: "Showing an old backup copy — not live data",
    sub: "Live shipment data did not answer in time. Sending and status changes are locked until live data is back.",
  };
}

function truthApiCacheFallbackSyncingState() {
  return {
    state: "syncing-live",
    tone: "warn",
    lockActions: true,
    title: "Syncing live truth…",
    sub: "Showing a stale backup copy while live shipment truth loads. Sending and status changes stay locked.",
  };
}

function markTruthApiPayloadAsCacheFallback(payload = {}, options = {}) {
  const warnings = [...new Set([
    TRUTH_API_CACHE_FALLBACK_WARNING,
    ...(Array.isArray(payload.warnings) ? payload.warnings : []),
    ...(Array.isArray(payload.sourceTruthWarnings) ? payload.sourceTruthWarnings : []),
  ].filter(Boolean))];
  return {
    ...payload,
    ok: false,
    status: "degraded",
    cacheFallback: true,
    syncState: options.syncingLive === true
      ? truthApiCacheFallbackSyncingState()
      : truthApiCacheFallbackSyncState(),
    sourceHealth: {
      ...(payload.sourceHealth && typeof payload.sourceHealth === "object" ? payload.sourceHealth : {}),
      status: "degraded",
      degraded: true,
      bundledFallback: true,
      reason: TRUTH_API_CACHE_FALLBACK_WARNING,
    },
    warnings,
    sourceTruthWarnings: warnings,
    operatorGuidance: "Wait for a live truth response before acting on this cached shipment view.",
  };
}

function applyTruthApiPayloadHealth(payload = {}) {
  state.payloadSyncState = payload?.syncState || null;
  state.payloadSourceHealth = payload?.sourceHealth && typeof payload.sourceHealth === "object"
    ? payload.sourceHealth
    : null;
  state.payloadSourceTruthWarnings = Array.isArray(payload?.sourceTruthWarnings)
    ? payload.sourceTruthWarnings.filter(Boolean)
    : [];
  if (payload?.cacheFallback) {
    state.sourceTruthError = TRUTH_API_CACHE_FALLBACK_WARNING;
  } else if (isCanonicalTruthPayload(payload)) {
    state.sourceTruthError = truthPacketFreshnessProblem(payload, payload.snapshotTime || "");
  }
}

function settleTruthApiCacheFallbackRecoveryFailure() {
  applyTruthApiPayloadHealth(markTruthApiPayloadAsCacheFallback({
    sourceHealth: state.payloadSourceHealth,
    warnings: state.payloadSourceTruthWarnings,
  }));
}

let truthHealthCacheFallbackRecoveryInFlight = null;
let truthHealthCacheFallbackRecoveryScheduled = false;

function scheduleTruthHealthCacheFallbackRecovery() {
  if (truthHealthCacheFallbackRecoveryScheduled || truthHealthCacheFallbackRecoveryInFlight) return;
  truthHealthCacheFallbackRecoveryScheduled = true;
  window.setTimeout(() => {
    truthHealthCacheFallbackRecoveryScheduled = false;
    truthHealthCacheFallbackRecoveryInFlight = loadTruthHealth({ liveReread: true })
      .then((payload) => {
        render();
        return payload;
      })
      .finally(() => {
        truthHealthCacheFallbackRecoveryInFlight = null;
      });
  }, 0);
}

async function loadTruthHealth(options = {}) {
  const liveReread = options.liveReread === true;
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), truthApiRequestTimeoutMs({ liveReread }));
  try {
    const response = await fetch(`/api/truth/health?ts=${Date.now()}`, {
      cache: "no-store",
      signal: controller.signal,
      headers: {
        "cache-control": "no-cache",
        ...(liveReread ? { [TRUTH_API_LIVE_REREAD_HEADER]: "1" } : {}),
      },
    });
    const rawPayload = await response.json().catch(() => null);
    const cacheFallback = truthApiResponseIsCacheFallback(response);
    const payload = cacheFallback
      ? markTruthApiPayloadAsCacheFallback(rawPayload || {}, { syncingLive: !liveReread })
      : rawPayload;
    if (!response.ok || !payload) throw new Error(`Truth health unavailable: ${response.status}`);
    state.truthHealth = payload;
    if (cacheFallback && !liveReread) scheduleTruthHealthCacheFallbackRecovery();
    if (payload.status && payload.status !== "live" && Array.isArray(payload.warnings) && payload.warnings.length) {
      state.sourceTruthError = payload.warnings[0];
    } else if (!cacheFallback && state.sourceTruthError === TRUTH_API_CACHE_FALLBACK_WARNING) {
      state.sourceTruthError = "";
    }
    return payload;
  } catch (error) {
    if (liveReread && state.truthHealth?.cacheFallback) {
      state.truthHealth = markTruthApiPayloadAsCacheFallback(state.truthHealth);
      return state.truthHealth;
    }
    state.truthHealth = {
      ok: false,
      status: "degraded",
      checkedAt: new Date().toISOString(),
      warnings: [`Truth health API unavailable: ${error instanceof Error ? error.message : String(error)}`],
      operatorGuidance: "Refresh source health before trusting email-owned shipment states.",
    };
    return state.truthHealth;
  } finally {
    window.clearTimeout(timeout);
  }
}

function hostedPersistenceDegraded() {
  if (!truthHealthKnown()) return true;
  return Boolean(
    state.truthHealth &&
      state.truthHealth.status !== "live" &&
      (!state.truthHealth.hostedPersistence || state.truthHealth.hostedPersistence.ok === false),
  );
}

function truthHealthKnown() {
  return Boolean(state.truthHealth && state.truthHealth.checkedAt);
}

function refreshTruthHealthAfterRender() {
  loadTruthHealth()
    .then(() => render())
    .catch(() => {});
}

