function jobAvailableForClaim(job = {}) {
  const availableAt = Date.parse(job.available_at || job.created_at || "");
  return !Number.isFinite(availableAt) || availableAt <= Date.now();
}

function sourceBackfillQueueBlocker(job) {
  if (!job || String(job.status || "").toLowerCase() !== "queued") return null;
  const priority = Number(job.priority);
  if (!Number.isFinite(priority)) return null;
  const createdAt = Date.parse(job.created_at || "");
  return (state.agentJobs || [])
    .filter((candidate) => {
      if (!candidate || candidate.id === job.id || candidate.job_type !== CANONICAL_GMAIL_INGESTION_PIPELINE) return false;
      const status = String(candidate.status || "").toLowerCase();
      if (!["queued", "running", "waiting_external"].includes(status)) return false;
      if (status === "running") return true;
      if (!jobAvailableForClaim(candidate)) return false;
      const candidatePriority = Number(candidate.priority);
      if (!Number.isFinite(candidatePriority)) return false;
      if (candidatePriority < priority) return true;
      const candidateCreatedAt = Date.parse(candidate.created_at || "");
      return candidatePriority === priority &&
        Number.isFinite(candidateCreatedAt) &&
        Number.isFinite(createdAt) &&
        candidateCreatedAt < createdAt;
    })
    .sort((a, b) => {
      const statusOrder = (jobStatus) => String(jobStatus || "").toLowerCase() === "running" ? 0 : 1;
      const statusDelta = statusOrder(a.status) - statusOrder(b.status);
      if (statusDelta) return statusDelta;
      const priorityDelta = (Number(a.priority) || 50) - (Number(b.priority) || 50);
      if (priorityDelta) return priorityDelta;
      return Date.parse(a.created_at || "") - Date.parse(b.created_at || "");
    })[0] || null;
}

function sourceBackfillStatusNote(sourceState, action = {}) {
  if (sourceState?.blocked && sourceState.blocker) {
    const blocker = sourceState.blocker;
    return `Blocked by older ${blocker.job_type || "repair"} ${blocker.status || "job"} from ${shortAge(blocker.updated_at || blocker.created_at) || "the queue"}.`;
  }
  if (sourceState?.job) {
    return `Job ${sourceState.job.status || "queued"}${sourceState.job.updated_at ? ` since ${shortAge(sourceState.job.updated_at)}` : ""}.`;
  }
  if (sourceState?.request) {
    if (String(sourceState.request.status || "").toLowerCase() === "cron-owned") {
      return "Canonical Gmail ingestion owns this source repair; no legacy email_refresh job was queued.";
    }
    const activityAt = sourceState.request.completedAt || sourceState.request.updatedAt || sourceState.request.claimedAt || sourceState.request.queuedAt || sourceState.request.requestedAt || "";
    return `Local request ${sourceState.request.status || "queued"}${activityAt ? ` since ${shortAge(activityAt)}` : ""}.`;
  }
  return action.safety?.note || "Records source repair only; no outbound email is sent.";
}

