function renderPlatformActionMeta(action) {
  const platform = action?.platform;
  if (!platform || platform.schema !== "platform-action-v1") return "";
  const statusLabel = {
    ready: "Ready",
    draft_only: "Draft only",
    needs_missing_info: "Needs info",
    blocked: "Blocked",
  }[platform.safeStatus] || platform.safeStatus || "";
  const missing = (platform.missingFields || []).length
    ? `<span class="platform-action-missing">Missing: ${escapeHtml((platform.missingFields || []).join(", "))}</span>`
    : "";
  const proof = platform.expectedProof
    ? `<span class="platform-action-proof" title="${escapeHtml(platform.expectedProof)}">Then: ${escapeHtml(platform.expectedProof)}</span>`
    : "";
  const freshness = globalProofFreshness();
  const staleEt = freshness.lastWriteAt ? formatEtTime(freshness.lastWriteAt) : "";
  const staleChip = freshness.level !== "fresh"
    ? `<span class="platform-action-stale" title="Actions derive from email evidence; ${escapeHtml(freshness.label)}${escapeHtml(staleEt ? ` (last proof ${staleEt})` : "")}.">${escapeHtml(freshness.level === "refresh-failed" ? freshness.label : `Confidence: stale — ${freshness.label}`)}${escapeHtml(staleEt ? ` (${staleEt})` : "")}</span>`
    : "";
  return `<span class="platform-action-meta" data-platform-action-type="${escapeHtml(platform.actionType || "")}" data-platform-safe-status="${escapeHtml(platform.safeStatus || "")}">` +
    `<span class="platform-action-status platform-action-status-${escapeHtml(platform.safeStatus || "unknown")}">${escapeHtml(statusLabel)}</span>${missing}${proof}${staleChip}</span>`;
}

function desktopCompanionPartLooksOperational(part) {
  return /\b(?:arrived|not arrived|pre[-\s]?arrival|customs|pickup|delivery|delivered|pod|fees|broker|station|phone|email|next|now|monitor|call|draft|waiting|blocked|ready|released|hold|driver|storage|available|missing|unknown|exception|release\/?d\.?o|release\/?do|delivery order)\b/i.test(
    String(part || ""),
  );
}

function desktopCompanionStripRedundantContext(text) {
  const value = cleanOpsBrainMessageContent(text).replace(/\s+/g, " ").trim();
  if (!value) return "";
  const parts = value.split(/\s+·\s+/).map((part) => part.trim()).filter(Boolean);
  if (parts.length <= 1) return value;
  const stationIndex = parts.findIndex((part) => /^station$/i.test(part));
  if (
    stationIndex >= 0 &&
    parts.length > stationIndex + 1 &&
    parts.slice(stationIndex + 1).some((part) => /@|\b\d{3}[-\s]?\d{3}[-\s]?\d{4}\b|\bcargo\b|\bterminal\b|\bwarehouse\b/i.test(part))
  ) {
    return parts.slice(stationIndex + 1).join(" · ");
  }
  const actionableIndex = parts.findIndex(desktopCompanionPartLooksOperational);
  if (actionableIndex > 0) return parts.slice(actionableIndex).join(" · ");
  return value;
}

function desktopCompanionSentenceAfter(label, text) {
  const match = String(text || "").match(new RegExp(`\\b${label}:\\s*([^\\n.]+)`, "i"));
  return match?.[1] ? match[1].trim().replace(/\s+/g, " ") : "";
}

function desktopCompanionCleanNext(text) {
  return String(text || "")
    .replace(/\buntil\b\s*$/i, "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[.;,\s]+$/g, "");
}

function desktopCompanionCompactOperationalText(message) {
  const value = desktopCompanionStripRedundantContext(message?.content || "");
  if (!value) return "";
  if ((message?.actions || []).length && /^draft ready\b/i.test(value)) return "Draft ready. Preview below.";
  if (/\btransfer exception\b|\bflight deleted\b|\bdeleted in uc360\b|\bnot in (?:the )?ua area\b/i.test(value)) {
    const next = desktopCompanionSentenceAfter("Now", value) || desktopCompanionSentenceAfter("Next", value);
    const summary = value
      .replace(/^.*?(?:WFS CDG transfer exception:|Transfer exception:)\s*/i, "")
      .split(/\bPickup quotes:|\bNow:|\bNext:/i)[0]
      .trim()
      .replace(/\bparcels were not in (?:the )?UA area\b/i, "parcels not in UA area")
      .replace(/\bthe flight was deleted in UC360\b/i, "flight deleted in UC360")
      .replace(/;?\s*WFS says transfer is expected this.*$/i, "")
      .replace(/[.;\s]+$/g, "");
    return [
      `WFS/CDG transfer is incomplete: ${summary || "transfer not completed"}.`,
      next ? `${desktopCompanionCleanNext(next)}.` : "",
    ].filter(Boolean).join(" ");
  }
  const lines = [];
  if (/\bcustoms hold\b.*\bblocking pickup\b|\bcustoms\b[^.]{0,40}\bblocked\b|\bgovernment hold\b/i.test(value)) {
    lines.push("Customs hold blocks pickup.");
  } else if (/\bnot arrived yet\b/i.test(value)) {
    lines.push("Not arrived yet.");
  } else if (/\bpre[-\s]?arrival\b/i.test(value)) {
    lines.push("Pre-arrival. Keep tracking.");
  } else {
    const first = value.split(/(?<=[.!?])\s+/)[0] || value;
    lines.push(desktopCompanionCleanNext(first));
  }
  const customs = desktopCompanionSentenceAfter("Customs", value)
    .replace(/^blocked\s*[-:]\s*/i, "")
    .replace(/^unknown\s*[-:]\s*/i, "");
  if (customs && !/customs hold blocks pickup/i.test(lines[0] || "")) {
    lines.push(`Customs is ${desktopCompanionCleanNext(customs)}.`);
  }
  const broker = desktopCompanionSentenceAfter("Pickup broker", value) || desktopCompanionSentenceAfter("Broker", value);
  if (broker) lines.push(`The pickup broker ${desktopCompanionCleanNext(broker)}.`);
  const now = desktopCompanionSentenceAfter("Now", value) || desktopCompanionSentenceAfter("Next", value);
  if (now) lines.push(`${desktopCompanionCleanNext(now)}.`);
  return lines.filter(Boolean).join(" ");
}

function desktopCompanionMessageText(message) {
  if (!message) return "";
  if (message.role === "user") return message.content || "";
  const itemCount = Array.isArray(message.items) ? message.items.length : 0;
  if (itemCount) {
    const total = Math.max(itemCount, Array.isArray(message.allItems) ? message.allItems.length : 0);
    const hidden = Math.max(0, total - itemCount);
    return hidden
      ? `${itemCount} highest-priority ${opsBrainListNoun(message, itemCount)}; ${hidden} more.`
      : `${itemCount} ${opsBrainListNoun(message, itemCount)}.`;
  }
  // Coworker answers (last-outbound, waiting-on, missing-proof, focus…) are
  // already written for the operator line-by-line — compacting them to one
  // extracted line destroys the answer.
  if (String(message.context?.topic || "").startsWith("coworker-") && message.content) return message.content;
  return desktopCompanionCompactOperationalText(message) ||
    desktopCompanionStripRedundantContext(message.content || "") ||
    [message.title, message.subtitle].filter(Boolean).join(" · ");
}

// Every multi-shipment answer is actionable: AWB, who, state, why, next move,
// evidence freshness — and the row opens exactly that shipment.
function renderDesktopCompanionResultRows(message) {
  const items = Array.isArray(message.items) ? message.items.filter((item) => item && item.awb) : [];
  if (!items.length) return "";
  return `
    <div class="ops-brain-result-list companion-result-list desktop-companion-result-list">
      ${items.map((item) => {
        const presentation = opsBrainResultPresentation(item);
        return `
          <button class="ops-brain-result-row companion-result-row desktop-companion-result-row" type="button" aria-label="Open ${escapeHtml(presentation.awb)}" data-companion-open-awb="${escapeHtml(item.awb)}">
            ${renderOpsBrainResultCardContent(presentation, { copyAwb: false, phrasing: true })}
          </button>
        `;
      }).join("")}
    </div>
  `;
}

function renderDesktopCompanionThread(historyArg = null, thinkingArg = null) {
  const history = (historyArg || state.opsBrainChatHistory || []).slice(-6);
  const thinking = thinkingArg !== null ? thinkingArg : state.opsBrainThinkingQuestion;
  if (!history.length && !thinking) return "";
  return `
    ${history.map((message) => {
      const actions = message.role === "assistant" ? (message.actions || []).filter(Boolean) : [];
      const messageText = desktopCompanionMessageText(message);
      const messageLimit = message.role === "user" ? 180 : (String(message.context?.topic || "").startsWith("coworker-") ? 700 : 240);
      const displayText = opsBrainSoftLimit(
        message.role === "assistant" ? opsBrainSentenceCase(messageText) : opsBrainTextWithoutInlineSources(messageText),
        messageLimit,
      ) || "No answer text";
      return `
        <article class="desktop-companion-message ${escapeHtml(message.role || "assistant")} ${actions.length ? "has-actions" : ""}">
          <span class="desktop-companion-speaker">${escapeHtml(message.role === "user" ? "You" : "Companion")}</span>
          ${renderOpsBrainNarrativeLead(message, true)}<p>${escapeHtml(displayText)}</p>
          ${message.role === "assistant" ? renderOpsBrainClarificationOptions(message.clarification) : ""}
          ${message.role === "assistant" && !message.items?.length ? renderOpsBrainSourceTags([
            ...opsBrainSourceNames(message.content),
            ...opsBrainStructuredSourceNames(message),
          ], "desktop-companion-sources") : ""}
          ${message.role === "assistant" ? renderDesktopCompanionResultRows(message) : ""}
          ${actions.length ? `<div class="ops-brain-message-actions desktop-companion-action-stack">${actions.map(renderOpsBrainCompanionActionCard).join("")}</div>` : ""}
        </article>
      `;
    }).join("")}
    ${thinking ? `
      <article class="desktop-companion-message assistant typing">
        <span class="desktop-companion-speaker">Companion</span>
        <p><i></i><i></i><i></i></p>
      </article>
    ` : ""}
  `;
}

// ============================================================
// Desktop action stage (desktop-only; the phone companion in
// renderOpsBrainScreen is untouched). The stage is where work
// gets done: idle = the ranked day queue, selected = the
// shipment cockpit. Chat stays available but secondary.
// ============================================================

function desktopStageSelectedShipment() {
  if (state.stageFocus !== "shipment" || !state.selectedId) return null;
  return state.shipments.find((shipment) => shipment.id === state.selectedId) || null;
}

function desktopStageDegraded(shipment = null) {
  const freshness = globalProofFreshness();
  if (["stale", "refresh-failed", "source-gap"].includes(freshness.level)) return true;
  const healthDegraded = Boolean(state.truthHealth && state.truthHealth.status && state.truthHealth.status !== "live");
  if (!healthDegraded) return false;
  return sourceHealthDegradationAppliesToShipment(shipment);
}

function desktopStageTruthGatheringAction(action) {
  return isSourceBackfillAction(action) ||
    isCarrierTrackingRefreshAction(action) ||
    isMoneyContextAction(action) ||
    isOperatorStateCheckAction(action) ||
    isStationContactResearchAction(action) ||
    isReleaseContactGapAction(action) ||
    isStationFeeAction(action) ||
    isPrearrivalQuoteDecisionAction(action) ||
    actionWorkstreamForUi(action) === "truth-repair";
}

function shipmentGmailCoverageIsCurrent(shipment) {
  const coverage = shipment?.gmailCoverage || {};
  const certification = shipment?.sourceCertification || {};
  const coverageStatus = String(coverage.status || "").toLowerCase();
  const certificationStatus = String(certification.status || "").toLowerCase();
  return coverageStatus === "covered" &&
    coverage.problem !== true &&
    ["", "certified"].includes(certificationStatus);
}

// Staleness gate: an action that ASSERTS shipment truth outward (email/TMS/document)
// is unsafe while evidence is stale or source-gapped — newer replies could contradict
// it. Truth-GATHERING actions (repairs, calls, operator recordings) stay live: they
// collect new truth instead of asserting stale truth.
function desktopStageActionLock(action, shipment = actionShipment(action)) {
  if (!action) return "";
  // The planner's reply-contract verdict is authoritative: an action that
  // could not hydrate its thread subject/recipient says exactly why instead
  // of reaching the composer as a "(no subject)" draft.
  if (action.readiness && action.readiness.ready === false) {
    return action.readiness.reason || action.blockedReason || "Not ready — the parent thread could not be resolved from evidence.";
  }
  // A served backup copy locks every action, truth-gathering included — the
  // board itself may be describing a world that no longer exists.
  const observed = observedSyncState();
  if (observed?.lockActions) {
    return observed.state === "syncing-live"
      ? "Locked — syncing live truth while a stale backup copy is visible. Wait for the live read before acting."
      : "Locked — showing an old backup copy, not live data. Wait for live data before acting.";
  }
  if (desktopStageTruthGatheringAction(action)) return "";
  const channel = normalizeChannel(action.channel);
  const assertsTruth = isDocumentAction(action) ||
    ["gmail", "couriercloud", "tms", "couriercloud-tms"].includes(channel);
  if (!assertsTruth) return "";
  const shipmentStale = shipment?.evidencePacket?.freshness?.staleSources || [];
  if (shipmentStale.includes("gmail") && !shipmentGmailCoverageIsCurrent(shipment)) {
    return "Needs proof — this shipment's email trail isn't fully synced. Refresh email sync before sending.";
  }
  if (shipment && shipmentHasSourceGap(shipment)) {
    const category = shipmentSourceGapCategory(shipment);
    if (category === "backup") {
      return "Locked — showing an old backup copy, not live data. Wait for live data before acting.";
    }
    if (category === "tms") {
      return "Needs TMS inventory — publish fresh CourierCloud/TMS snapshots before acting.";
    }
    if (category === "cloud") {
      return "Needs cloud truth — restore hosted shipment truth before acting.";
    }
    if (category === "terminal") {
      return "Needs truth review — terminal arrival/delivery state is not certified yet.";
    }
    if (category === "email") {
      return "Needs proof — this shipment's email history isn't fully synced. Repair it before acting.";
    }
    return "Needs source proof — repair live shipment truth before acting.";
  }
  const freshness = globalProofFreshness();
  if (["stale", "refresh-failed", "source-gap"].includes(freshness.level)) {
    const age = freshness.lastWriteText ? ` (${freshness.lastWriteText})` : "";
    return `Locked — email sync is behind${age}. This shipment may have new replies. Refresh email sync first.`;
  }
  return "";
}

function desktopStageActionClass(action) {
  if (isSourceBackfillAction(action) || isCarrierTrackingRefreshAction(action) || actionWorkstreamForUi(action) === "truth-repair") return "repair";
  if (actionBlockedReason(action)) return "blocked";
  if (isDocumentAction(action)) return "document";
  if (isOperatorStateCheckAction(action)) return "call";
  if (isPlatformAlertAction(action)) return actionPhoneInfo(action) ? "call" : "decide";
  return "draft";
}

const DESKTOP_STAGE_KICKERS = {
  draft: "Draft ready",
  document: "Document ready",
  call: "Call / confirm",
  decide: "Needs your decision",
  repair: "Check needed",
  blocked: "Needs info",
};

function dominantSourceGapCategory(shipments = []) {
  const counts = new Map();
  for (const shipment of shipments) {
    const category = shipmentSourceGapCategory(shipment);
    counts.set(category, (counts.get(category) || 0) + 1);
  }
  const priority = ["backup", "tms", "cloud", "terminal", "email", "source"];
  return priority
    .map((category) => ({ category, count: counts.get(category) || 0 }))
    .sort((a, b) => b.count - a.count || priority.indexOf(a.category) - priority.indexOf(b.category))[0]?.category || "source";
}

function sourceGapStageCopy(shipment = null, count = 1, categoryOverride = "") {
  const category = categoryOverride || (shipment ? shipmentSourceGapCategory(shipment) : observedSyncState()?.state === "stale-fallback" ? "backup" : "source");
  if (category === "backup") {
    if (observedSyncState()?.state === "syncing-live") {
      return {
        kicker: "Syncing live truth…",
        title: `Checking ${count === 1 ? "this stale backup row" : `${count} stale backup rows`} against live truth`,
        body: "The backup copy is not live. Sending and status changes stay locked while the live shipment read finishes.",
        groupTitle: "Syncing live truth…",
        showRefresh: false,
      };
    }
    return {
      kicker: "Live data offline",
      title: `Showing ${count === 1 ? "an old backup copy" : `${count} rows from an old backup copy`}`,
      body: "Live shipment data could not be read. Sending and status changes stay locked until the hosted truth read path is back.",
      groupTitle: "Live data offline",
      showRefresh: false,
    };
  }
  if (category === "tms") {
    return {
      kicker: "TMS inventory missing",
      title: `${count} shipment${count === 1 ? " needs" : "s need"} fresh TMS inventory`,
      body: "Publish the CourierCloud/TMS active inventory snapshots and rebuild shipment truth before acting.",
      groupTitle: "TMS inventory missing",
      showRefresh: false,
    };
  }
  if (category === "cloud") {
    return {
      kicker: "Cloud truth degraded",
      title: `${count} shipment${count === 1 ? " is" : "s are"} waiting on cloud truth`,
      body: "Hosted shipment truth is degraded. Restore the cloud read/publish path before acting.",
      groupTitle: "Cloud truth degraded",
      showRefresh: false,
    };
  }
  if (category === "terminal") {
    return {
      kicker: "Terminal state disputed",
      title: `${count} shipment${count === 1 ? " needs" : "s need"} arrival/delivery truth review`,
      body: "Arrival, pickup, delivery, or POD was inferred from weak terminal evidence. Verify direct source proof before acting or closing.",
      groupTitle: "Terminal state disputed",
      showRefresh: false,
    };
  }
  if (category === "email") {
    return {
      kicker: "Waiting on email sync",
      title: `${count} shipment${count === 1 ? " is" : "s are"} waiting on the latest email replies`,
      body: "I locked sending for them until email sync catches up. You can still call, and refreshing unlocks drafting.",
      groupTitle: "Waiting on email sync",
      showRefresh: true,
    };
  }
  return {
    kicker: "Source proof needed",
    title: `${count} shipment${count === 1 ? " has" : "s have"} degraded source truth`,
    body: "Shipment truth is not certified yet. Repair the source evidence and reload live truth before acting.",
    groupTitle: "Source proof needed",
    showRefresh: false,
  };
}

function sourceGapRowsForUi(rows = state.shipments) {
  return (rows || []).filter((shipment) => !shipmentTruthComplete(shipment) && shipmentHasSourceGap(shipment));
}

function sourceGapSummaryForUi(rows = state.shipments) {
  const rowsWithGap = sourceGapRowsForUi(rows);
  if (!rowsWithGap.length) return null;
  const category = dominantSourceGapCategory(rowsWithGap);
  return {
    rows: rowsWithGap,
    count: rowsWithGap.length,
    category,
    copy: sourceGapStageCopy(null, rowsWithGap.length, category),
  };
}

function desktopStageQueueItems(rows = state.shipments) {
  const degraded = desktopStageDegraded();
  const entries = [];
  let gapCount = 0;
  for (const shipment of rows) {
    if (shipmentTruthComplete(shipment)) continue;
    if (isFallbackShipment(shipment)) continue;
    // An urgent interrupt (driver stuck at pickup) is the TOP work — it
    // outranks agency quieting and normal ranking.
    if (shipment.urgentInterrupt) {
      entries.push({ kind: "interrupt", shipment, interrupt: shipment.urgentInterrupt });
      continue;
    }
    // Import-desk agency: export-side / pre-departure / waiting shipments are
    // visible but QUIET — they are not calls, drafts, or countable work.
    const agency = shipment.operatorAgency || shipment.truthPacket?.operatorAgency || null;
    if (agency && agency.countsAsWork === false && agency.agency !== "monitor_only" && !shipmentHasSourceGap(shipment)) {
      entries.push({ kind: "monitor", shipment, agency });
      continue;
    }
    const action = shipmentDecisionPrimaryAction(shipment);
    if (action) {
      entries.push({
        kind: "action",
        shipment,
        action,
        cls: desktopStageActionClass(action),
        lock: desktopStageActionLock(action, shipment),
      });
      continue;
    }
    // Source-gapped shipments have no safe primary action — surface the repair
    // itself as the work item instead of hiding the shipment from the queue.
    if (shipmentHasSourceGap(shipment)) {
      gapCount += 1;
      entries.push({ kind: "gap", shipment });
    }
  }
  // Shipments that already carry an urgent interrupt own their story — their
  // inbox notifications must not duplicate into extra cards.
  const interruptAwbs = new Set(entries
    .filter((entry) => entry.kind === "interrupt")
    .map((entry) => opsBrainAwbKey(entry.shipment.awb || entry.shipment.id || "")));
  for (const item of operatorInboxRows(rows)) {
    if (item.kind !== "notification") continue;
    if (!(["immediate", "urgent", "needs-action"].includes(String(item.severity || "")) || item.immediateAttention)) continue;
    if (item.awb && interruptAwbs.has(opsBrainAwbKey(item.awb))) continue;
    const key = item.notificationId || "";
    if (key && (state.seenOperatorNotifications.has(key) || state.seenOperatorNotifications.has(operatorNotificationSeenKey(item)))) continue;
    entries.push({ kind: "inbox", inbox: item });
    if (entries.filter((entry) => entry.kind === "inbox").length >= 3) break;
  }
  const classRank = degraded
    ? { repair: 0, call: 10, decide: 20, draft: 30, document: 30, blocked: 40 }
    : { draft: 0, document: 5, call: 10, decide: 20, repair: 30, blocked: 40 };
  const rank = (entry) => {
    if (entry.kind === "interrupt") return -10;
    // High severity (arrived+blocked, <24h arrival unprepared, decision asked)
    // tops Today's Work without screaming.
    if (entry.kind === "action" && entry.shipment?.severity?.level === "high") return -5;
    if (entry.kind === "monitor") return 90;
    if (entry.kind === "inbox") return 50;
    if (entry.kind === "gap" || entry.kind === "gap-collapsed") return degraded ? 0 : 35;
    let value = classRank[entry.cls] ?? 25;
    if (entry.lock && !degraded) value += 15;
    return value;
  };
  // Identical gap cards teach nothing shipment-by-shipment — collapse 3+ into
  // one card that says how many are waiting and offers the one fix.
  const gaps = entries.filter((entry) => entry.kind === "gap");
  const collapsed = gaps.length >= 3
    ? [{ kind: "gap-collapsed", count: gaps.length, category: dominantSourceGapCategory(gaps.map((entry) => entry.shipment)) }, ...entries.filter((entry) => entry.kind !== "gap")]
    : entries;
  return collapsed.sort((a, b) =>
    rank(a) - rank(b) ||
    actionPriorityRankForUi(a.action || {}) - actionPriorityRankForUi(b.action || {}) ||
    String(a.action?.createdAt || "").localeCompare(String(b.action?.createdAt || "")));
}

function renderDesktopStageQueueCard(entry) {
  if (entry.kind === "interrupt") {
    const shipment = entry.shipment;
    const interrupt = entry.interrupt;
    return `
      <button class="desktop-stage-card interrupt" type="button" data-stage-card="interrupt" data-stage-select="${escapeHtml(shipment.id)}">
        <span class="desktop-stage-card-top">
          <span class="desktop-stage-kicker interrupt">Urgent — happening now</span>
          <strong class="desktop-stage-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong>
        </span>
        <strong class="desktop-stage-card-title">${escapeHtml(shortText(interrupt.title, "Driver stuck at pickup", 90))}</strong>
        <p>${escapeHtml(shortText(interrupt.preparedAction, "", 140))}</p>
        ${alertCadenceLabel(interrupt.id) ? `<span class="desktop-stage-cadence">${escapeHtml(alertCadenceLabel(interrupt.id))}</span>` : ""}
      </button>
    `;
  }
  if (entry.kind === "gap-collapsed") {
    const copy = sourceGapStageCopy(null, entry.count, entry.category);
    return `
      <div class="desktop-stage-card repair collapsed" data-stage-card="repair">
        <span class="desktop-stage-card-top">
          <span class="desktop-stage-kicker repair">${escapeHtml(copy.kicker)}</span>
        </span>
        <strong class="desktop-stage-card-title">${escapeHtml(copy.title)}</strong>
        <p>${escapeHtml(copy.body)}</p>
        ${copy.showRefresh
          ? `<span class="desktop-stage-card-actions">${renderGmailRetryControl().replace(">Retry Gmail refresh<", ">Refresh email sync<").replace(">Retry again<", ">Refresh again<")}</span>`
          : ""}
      </div>
    `;
  }
  if (entry.kind === "gap") {
    const shipment = entry.shipment;
    const stateLabel = controlRoomRowState(shipment);
    const copy = sourceGapStageCopy(shipment, 1);
    return `
      <button class="desktop-stage-card repair" type="button" data-stage-card="repair" data-stage-select="${escapeHtml(shipment.id)}">
        <span class="desktop-stage-card-top">
          <span class="desktop-stage-kicker repair">${escapeHtml(copy.kicker)}</span>
          <strong class="desktop-stage-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong>
          <em class="desktop-stage-lane ${escapeHtml(stateLabel.tone || "")}">${escapeHtml(desk2DisplayLabel(stateLabel.label))}</em>
        </span>
        <strong class="desktop-stage-card-title">${escapeHtml(copy.title)}${operationalStation(shipment) ? ` · ${escapeHtml(operationalStation(shipment))}` : ""}</strong>
        <p>${escapeHtml(shortText(desk2TranslateReason(shipmentSourceGapReason(shipment)), "Missing the latest Gmail replies for this shipment.", 132))}</p>
      </button>
    `;
  }
  if (entry.kind === "inbox") {
    const item = entry.inbox;
    const title = desk2TranslateReason(item.title || item.message || "");
    return `
      <button class="desktop-stage-card inbox" type="button" data-stage-card="inbox" data-stage-select="${escapeHtml(item.shipmentId || "")}">
        <span class="desktop-stage-card-top">
          <span class="desktop-stage-kicker inbox">Inbox · ${escapeHtml(String(item.severity || "update"))}</span>
          ${item.awb ? `<strong class="desktop-stage-awb">${escapeHtml(opsBrainDisplayAwb(item.awb))}</strong>` : ""}
          <em class="desktop-stage-card-open">${item.shipmentId ? "Open shipment" : "Open inbox"} →</em>
        </span>
        <strong class="desktop-stage-card-title">${escapeHtml(shortText(title, "Shipment update", 84))}</strong>
        ${item.subtitle ? `<p>${escapeHtml(shortText(desk2TranslateReason(item.subtitle), "", 120))}</p>` : ""}
      </button>
    `;
  }
  const { shipment, action, cls, lock } = entry;
  const stateLabel = controlRoomRowState(shipment);
  return `
    <button class="desktop-stage-card ${escapeHtml(cls)} ${lock ? "locked" : ""}" type="button" data-stage-card="${escapeHtml(cls)}" ${lock ? `data-stage-locked="true"` : ""} data-stage-select="${escapeHtml(shipment.id)}">
      <span class="desktop-stage-card-top">
        <span class="desktop-stage-kicker ${escapeHtml(cls)}">${escapeHtml(DESKTOP_STAGE_KICKERS[cls] || "Next move")}</span>
        <strong class="desktop-stage-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong>
        <em class="desktop-stage-lane ${escapeHtml(stateLabel.tone || "")}">${escapeHtml(stateLabel.label)}</em>
        ${actionModePill(action)}
      </span>
      <strong class="desktop-stage-card-title">${escapeHtml(shortText(operatorFacingActionLabel(action), "Review this shipment", 88))}</strong>
      <p>${escapeHtml(shortText(desk2TranslateReason(actionReasonLine(action)), "", 132))}</p>
      ${lock
        ? `<span class="desktop-stage-lock-note">${escapeHtml(lock)}</span>`
        : `<span class="desk2-row-go desk2-go-${escapeHtml(cls)} desk2-hero-go">${{ draft: "Review draft", document: "Review", call: "Call", decide: "Decide", repair: "Fix", blocked: "Open" }[cls] || "Open"}</span>`}
    </button>
  `;
}

function renderDesktopStageQueue(rows, precomputedEntries = null) {
  const entries = precomputedEntries || desktopStageQueueItems(rows);
  if (!entries.length) {
    const freshness = globalProofFreshness();
    // Never say "all clear" while the queue on the left flags shipments.
    const flagged = controlRoomRows(rows, "attention").length;
    return `
      <div class="desktop-stage-queue is-clear" data-stage-queue data-stage-empty="true">
        <div class="desktop-stage-clear">
          ${flagged ? `
            <strong>${flagged} shipment${flagged === 1 ? "" : "s"} ${flagged === 1 ? "is" : "are"} flagged in Needs attention.</strong>
            <span>Open ${flagged === 1 ? "it" : "them"} from the queue on the left — no prepared action is pending here.</span>
          ` : `
            <strong>Nothing needs you right now.</strong>
            <span>Every active shipment has a live plan. ${escapeHtml(freshness.lastWriteText ? `Last email check ${freshness.lastWriteText}.` : "")}</span>
          `}
        </div>
      </div>
    `;
  }
  // Attention hierarchy: ONE recommended next action gets the full card; the
  // rest fold into typed groups of compact rows. Sixteen identical full cards
  // teach nothing — one hero plus scannable groups does. Waiting/export-side
  // shipments render last, quiet, and uncounted.
  const monitors = entries.filter((entry) => entry.kind === "monitor");
  const [hero, ...rest] = entries.filter((entry) => entry.kind !== "monitor");
  const groupOf = (entry) => {
    if (entry.kind === "inbox") return "inbox";
    if (entry.kind === "gap" || entry.kind === "gap-collapsed") return "gap";
    if (entry.cls === "draft" || entry.cls === "document") return "draft";
    return entry.cls || "decide";
  };
  const GROUPS = [
    ["draft", "Drafts ready to review"],
    ["call", "Calls to make"],
    ["decide", "Decisions"],
    ["repair", "Checks needed"],
    ["blocked", "Waiting on info"],
    ["gap", "Source repair"],
    ["inbox", "Urgent inbox"],
  ];
  const byGroup = new Map(GROUPS.map(([key]) => [key, []]));
  for (const entry of rest) {
    const key = groupOf(entry);
    if (byGroup.has(key)) byGroup.get(key).push(entry);
  }
  const groups = GROUPS.map(([key, title]) => {
    const members = byGroup.get(key) || [];
    if (!members.length) return "";
    const gapCopy = key === "gap"
      ? sourceGapStageCopy(null, members.length, dominantSourceGapCategory(members.map((entry) => entry.shipment).filter(Boolean)))
      : null;
    const lockedInGroup = members.filter((entry) => entry.lock).length;
    const lockedCopy = lockedInGroup
      ? `${lockedInGroup} ${key === "gap" ? "locked until source repair" : "locked pending confirmation"}`
      : "";
    return `
      <section class="desktop-stage-group" data-stage-group="${escapeHtml(key)}">
        <h3 class="desktop-stage-group-head">${escapeHtml(gapCopy?.groupTitle || title)} ${key === "gap" ? "" : `<b>${members.length}</b>`}${lockedCopy ? `<em>${escapeHtml(lockedCopy)}</em>` : ""}</h3>
        ${members.map(renderDesktopStageGroupRow).join("")}
      </section>
    `;
  }).filter(Boolean).join("");
  const waitingSection = monitors.length ? (() => {
    // The same waiting reason repeated on every row is noise: say each reason
    // once and list its shipments compactly under it.
    const byReason = new Map();
    for (const entry of monitors) {
      const reason = String(entry.agency?.reason || "Waiting on the other side — no import action yet.");
      if (!byReason.has(reason)) byReason.set(reason, []);
      byReason.get(reason).push(entry);
    }
    return `
    <section class="desktop-stage-group waiting" data-stage-group="waiting">
      <h3 class="desktop-stage-group-head">Waiting — not our move yet <b>${monitors.length}</b></h3>
      ${[...byReason.entries()].map(([reason, members]) => `
        <p class="desktop-stage-waiting-reason">${escapeHtml(reason)}</p>
        ${members.map((entry) => {
          const shipment = entry.shipment;
          const stateLabel = controlRoomRowState(shipment);
          const who = shipment.client || shipment.consignee || "";
          return `
          <button class="desktop-stage-row waiting" type="button" data-stage-card="waiting" data-stage-select="${escapeHtml(shipment.id)}">
            <strong class="desktop-stage-row-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong>
            <span class="desktop-stage-row-title">${escapeHtml(shortText(who, "", 60))}</span>
            <em class="desktop-stage-row-state">${escapeHtml(desk2DisplayLabel(stateLabel.label))}</em>
          </button>
        `;
        }).join("")}
      `).join("")}
    </section>
  `;
  })() : "";
  return `
    <div class="desktop-stage-queue" data-stage-queue>
      ${hero ? `
        <div class="desktop-stage-hero" data-stage-hero>
          <span class="desktop-stage-hero-label">Recommended next</span>
          ${renderDesktopStageQueueCard(hero)}
        </div>
      ` : ""}
      ${groups}
      ${renderPlanningAheadSection()}
      ${waitingSection}
    </div>
  `;
}

// Planning ahead: proactive and calm — visibly quieter than urgent work.
function renderPlanningAheadSection() {
  const items = Array.isArray(state.planningAhead) ? state.planningAhead : [];
  if (!items.length) {
    // Explainable absence: one calm muted line instead of silence, only when
    // the API actually reported a planning status.
    const reason = state.planningStatus?.reason || "";
    return reason ? `
      <div class="desktop-stage-planning-empty" data-planning-empty>
        Planning ahead — ${escapeHtml(shortText(reason, "", 90))}
      </div>
    ` : "";
  }
  return `
    <section class="desktop-stage-group planning" data-stage-group="planning">
      <h3 class="desktop-stage-group-head">Planning ahead <b>${items.length}</b></h3>
      ${items.map((item) => `
        <div class="desktop-stage-row planning ${escapeHtml(item.kind || "")} ${item.countsAsWork ? "tightening" : ""}" data-planning-item="${escapeHtml(item.id)}" data-planning-kind="${escapeHtml(item.kind || "")}">
          <span class="desktop-stage-row-title">
            <strong>${escapeHtml(shortText(item.title, "", 96))}</strong>
            <small>${escapeHtml(shortText(item.detail, "", 130))}</small>
            ${Array.isArray(item.roster) && item.roster.length ? `<span class="ac-chips">${item.roster.slice(0, 5).map((entry) => `<span class="ac-chip">${escapeHtml(entry.name || entry.email)}${entry.confidence ? ` · ${escapeHtml(entry.confidence)}` : ""}</span>`).join("")}</span>` : ""}
          </span>
          <em class="desktop-stage-row-state">${item.countsAsWork ? "arriving soon" : "prepared"}</em>
        </div>
      `).join("")}
    </section>
  `;
}

function renderDesktopStageGroupRow(entry) {
  if (entry.kind === "gap-collapsed") return renderDesktopStageQueueCard(entry);
  if (entry.kind === "inbox") {
    const item = entry.inbox;
    return `
      <button class="desktop-stage-row inbox" type="button" data-stage-card="inbox" data-stage-select="${escapeHtml(item.shipmentId || "")}">
        ${item.awb ? `<strong class="desktop-stage-row-awb">${escapeHtml(opsBrainDisplayAwb(item.awb))}</strong>` : `<strong class="desktop-stage-row-awb">Inbox</strong>`}
        <span class="desktop-stage-row-title">${escapeHtml(shortText(desk2TranslateReason(item.title || item.message || ""), "Shipment update", 72))}</span>
        <em class="desktop-stage-row-state">${escapeHtml(String(item.severity || "update"))}</em>
      </button>
    `;
  }
  if (entry.kind === "gap") {
    const shipment = entry.shipment;
    const stateLabel = controlRoomRowState(shipment);
    const copy = sourceGapStageCopy(shipment, 1);
    return `
      <button class="desktop-stage-row repair" type="button" data-stage-card="repair" data-stage-select="${escapeHtml(shipment.id)}">
        <strong class="desktop-stage-row-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong>
        <span class="desktop-stage-row-title">${escapeHtml(copy.groupTitle || copy.kicker)}</span>
        <em class="desktop-stage-row-state ${escapeHtml(stateLabel.tone || "")}">${escapeHtml(desk2DisplayLabel(stateLabel.label))}</em>
      </button>
    `;
  }
  const { shipment, action, cls, lock } = entry;
  const stateLabel = controlRoomRowState(shipment);
  const who = shortText(shipment.client || shipment.delivery?.consignee || shipment.consignee || "", "", 34);
  return `
    <button class="desktop-stage-row ${escapeHtml(cls)} ${lock ? "locked" : ""}" type="button" data-stage-card="${escapeHtml(cls)}" ${lock ? `data-stage-locked="true"` : ""} data-stage-select="${escapeHtml(shipment.id)}" ${lock ? `title="${escapeHtml(lock)}"` : ""}>
      ${desk2VerbIcon(cls)}
      <span class="desktop-stage-row-main">
        <span class="desktop-stage-row-title">${escapeHtml(shortText(operatorFacingActionLabel(action), "Review this shipment", 96))}</span>
        <span class="desktop-stage-row-meta">${who ? `${escapeHtml(who)} · ` : ""}<strong class="desktop-stage-row-awb">${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id))}</strong> · <em class="desktop-stage-row-statein">${escapeHtml(stateLabel.label)}</em></span>
      </span>
      ${lock ? `<em class="desktop-stage-row-lock">locked</em>` : `<span class="desk2-row-go desk2-go-${escapeHtml(cls)}">${{ draft: "Review draft", document: "Review", call: "Call", decide: "Decide", repair: "Fix", blocked: "Open" }[cls] || "Open"}</span>`}
    </button>
  `;
}

// Sonoma verb icons: one glyph per action family so the queue reads as moves.
function desk2VerbIcon(cls) {
  const icons = {
    draft: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 4.5l5.5 4 5.5-4M3.5 3.5h9a1 1 0 011 1v7a1 1 0 01-1 1h-9a1 1 0 01-1-1v-7a1 1 0 011-1z"/></svg>`,
    document: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5h5.5L12 5v8.5H4z"/><path d="M6 8h4M6 10.5h4"/></svg>`,
    call: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 2.5h2.6l1.2 3-1.7 1.3a9.5 9.5 0 003.6 3.6l1.3-1.7 3 1.2v2.6a1 1 0 01-1.1 1A11.5 11.5 0 012.5 3.6a1 1 0 011-1.1z"/></svg>`,
    decide: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.8l6 10.4H2z"/><path d="M8 7v3M8 12h.01"/></svg>`,
    repair: `<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="6"/><path d="M8 4.8V8l2.2 1.6"/></svg>`,
    blocked: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4.5 2.5h7M4.5 13.5h7M5 2.5c0 5 6 6 6 11M11 2.5c0 5-6 6-6 11"/></svg>`,
    inbox: `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 9.5h3l1.2 2h2.6l1.2-2h3M3.5 3.5h9l1 6v3h-11v-3z"/></svg>`,
  };
  return `<i class="desk2-verb desk2-verb-${escapeHtml(cls)}" aria-hidden="true">${icons[cls] || icons.decide}</i>`;
}

function desktopStageEvidenceFacts(shipment) {
  const packetFacts = shipment?.evidencePacket?.sourceFacts;
  const mapped = Array.isArray(packetFacts) && packetFacts.length
    ? packetFacts.map((fact) => ({
        source: fact.sourceSystem || fact.sourceRef?.source || "source",
        actor: fact.actor || "",
        at: fact.observedAt || fact.capturedAt || "",
        text: cleanFactText(fact.claim || fact.rawSnippet || ""),
      }))
    : (Array.isArray(shipment?.factLedger) ? shipment.factLedger : []).map((fact) => ({
        source: fact.source || "fact ledger",
        actor: "",
        at: fact.at || "",
        text: cleanFactText(fact.summary || fact.note || ""),
      }));
  const seen = new Set();
  return mapped
    .filter((fact) => fact.text && !seen.has(fact.text) && seen.add(fact.text))
    .sort((a, b) => String(b.at).localeCompare(String(a.at)));
}

function renderDesktopStageEvidence(shipment) {
  const facts = desktopStageEvidenceFacts(shipment);
  const staleSources = shipment?.evidencePacket?.freshness?.staleSources || [];
  if (!facts.length && !staleSources.length) return "";
  const shown = facts.slice(0, 3);
  return `
    <details class="desktop-stage-evidence" data-stage-evidence>
      <summary class="desktop-stage-section-head">Why the system believes this · ${facts.length} source${facts.length === 1 ? "" : "s"}</summary>
      ${shown.map((fact) => `
        <blockquote class="desktop-stage-evidence-item">
          <span>${escapeHtml(shortText([fact.source, fact.actor].filter(Boolean).join(" · ").replace(/-/g, " "), "source", 52))}${fact.at ? ` · ${escapeHtml(shortAge(fact.at) || "")}` : ""}</span>
          <q>${escapeHtml(shortText(fact.text, "", 190))}</q>
        </blockquote>
      `).join("")}
      ${staleSources.length ? `<span class="desktop-stage-evidence-missing">Not fully synced: ${escapeHtml(staleSources.join(", "))} — newer messages may change this.</span>` : ""}
      ${facts.length > shown.length ? `<span class="desktop-stage-evidence-more">+ ${facts.length - shown.length} more in full detail</span>` : ""}
    </details>
  `;
}

function renderDesktopStageHealthStrip(shipment = null) {
  const freshness = globalProofFreshness();
  const degraded = desktopStageDegraded(shipment);
  const staleSources = shipment?.evidencePacket?.freshness?.staleSources || [];
  const effectiveStaleSources = staleSources.filter((source) =>
    !(source === "gmail" && shipmentGmailCoverageIsCurrent(shipment)));
  if (!degraded && !effectiveStaleSources.length) return "";
  const sourceGapCopy = shipment && shipmentHasSourceGap(shipment) ? sourceGapStageCopy(shipment, 1) : null;
  const gmailStale = degraded || effectiveStaleSources.includes("gmail");
  const message = sourceGapCopy
    ? sourceGapCopy.body
    : degraded
    ? `Email sync is behind${freshness.lastWriteText ? ` (${freshness.lastWriteText})` : ""} — ${shipment ? "this shipment" : "shipments"} may be missing new replies. Sending is locked until it refreshes; you can still call.`
    : gmailStale
      ? "This shipment's email trail isn't fully synced yet — sending is locked until it catches up. You can still call."
      : "Some shipment data is still syncing — treat listed states with care.";
  const action = sourceGapCopy
    ? sourceGapCopy.showRefresh
    : gmailStale;
  return `
    <div class="desktop-stage-health" data-stage-health>
      <span class="desktop-stage-health-note">${escapeHtml(message)}</span>
      ${action ? `<span class="desktop-stage-health-action">${renderGmailRetryControl().replace(">Retry Gmail refresh<", ">Refresh email sync<").replace(">Retry again<", ">Refresh again<")}</span>` : ""}
    </div>
  `;
}

function renderDesktopStageActionCard(action, shipment) {
  const lock = desktopStageActionLock(action, shipment);
  if (!lock) return renderOpsBrainCompanionActionCard(action);
  const title = shortText(operatorFacingActionLabel(action), "Review this", 72);
  const reason = shortText(actionReasonLine(action), "", 126);
  return `
    <article class="ops-brain-companion-action blocked desktop-stage-locked-action" data-stage-locked="true">
      <div class="ops-brain-companion-action-main">
        <div class="ops-brain-companion-action-kicker">
          <span>Needs proof</span>
          ${actionModePill(action)}
        </div>
        <strong>${escapeHtml(title)}</strong>
        ${reason ? `<p>${escapeHtml(reason)}</p>` : ""}
        <div class="ops-brain-companion-action-meta"><small>${escapeHtml(lock)}</small></div>
      </div>
      <div class="ops-brain-companion-action-controls">
        ${renderCallButton(action)}
        <button class="mini-button primary" type="button" disabled>Locked</button>
      </div>
    </article>
  `;
}

function desktopStageCockpitActions(shipment) {
  const primary = shipmentDecisionPrimaryAction(shipment);
  const rest = actionsForShipment(shipment);
  const byId = new Map();
  for (const action of [primary, ...rest]) {
    if (action && action.id && !byId.has(action.id)) byId.set(action.id, action);
  }
  const ordered = [...byId.values()];
  if (desktopStageDegraded()) {
    ordered.sort((a, b) => Number(desktopStageTruthGatheringAction(b)) - Number(desktopStageTruthGatheringAction(a)));
  }
  return ordered;
}

function buildShipmentStory(shipment) {
  const rowState = controlRoomRowState(shipment);
  const rawMeta = controlRoomRowMeta(shipment);
  const rawNext = nextStep(shipment);
  const stateLabel = shortText(desk2DisplayLabel(rowState.label), "Shipment update", 48);
  const stateClause = {
    "Arrival watch": "The shipment is approaching arrival",
    "Arrived blocked": "The shipment has arrived but is blocked",
    "AWB copy needed": "The pickup team still needs the air waybill copy",
    "Backup copy": "The latest shipment update may be missing",
    "Cloud data issue": "The latest shipment update may be missing",
    "Closeout": "The shipment is ready to close",
    "Customs hold": "The shipment is on customs hold",
    "Delivery blocked": "Delivery is blocked",
    "Exception": "The shipment has an operational exception",
    "Fees due": "Ground fees are due",
    "Needs email sync": "The latest email update may still be catching up",
    "Not arrived": "The shipment has not landed yet",
    "Partial arrival": "The shipment has a partial arrival update",
    "Pickup blocked": "Pickup is blocked",
    "Pickup docs needed": "Pickup paperwork is still needed",
    "Pickup location needed": "The pickup location is still needed",
    "Pickup scheduled": "Pickup is scheduled",
    "Pickup/POD": "The shipment is in pickup or delivery",
    "POD pending": "The shipment was delivered and the POD is still needed",
    "POD needed": "The shipment was delivered and the POD is still needed",
    "Pre-arrival": "The shipment has not landed yet",
    "Release pending": "The shipment is waiting on release paperwork",
    "Source gap": "The latest shipment update may be missing",
    "TMS missing": "The shipment details may be out of date",
    "Tracking": "The shipment is being tracked",
    "Verify terminal state": "Delivery status is not confirmed",
    "Wrong consignee": "The shipment went to the wrong consignee",
  }[stateLabel] || `The shipment is ${stateLabel.toLowerCase()}`;
  let meta = String(desk2DisplayMeta(rawMeta) || "")
    .replace(/^Blocker:\s*/i, "")
    .replace(/arrival\/delivery proof disputed/gi, "arrival or delivery is not confirmed")
    .replace(/release proof missing/gi, "release paperwork is not confirmed")
    .replace(/release\/d\.?o\.?/gi, "release paperwork")
    .replace(/conflicting shipment info/gi, "the latest update may be incomplete")
    .replace(/thread relation/gi, "email trail")
    .replace(/source backfill/gi, "shipment update")
    .replace(/\bproof\b/gi, "confirmation")
    .replace(/\bbackfill\b/gi, "update")
    .replace(/[.!?]+$/, "")
    .trim();
  const machineNext = shipmentHasSourceGap(shipment) ||
    /\b(?:source[-\s]?backfill|repair\s+(?:gmail|email|source)|find\s+(?:release|dispatch|delivery|source)\s+proof|restore\s+(?:hosted|live|ingestion)|reload\s+live)\b/i.test(rawNext);
  let next = machineNext
    ? "no operator action is needed until the latest shipment update arrives"
    : String(desk2TranslateReason(rawNext) || "")
      .replace(/find release proof/gi, "confirm the release paperwork")
      .replace(/repair gmail proof/gi, "wait for the latest email update")
      .replace(/release\/d\.?o\.?/gi, "release paperwork")
      .replace(/thread relation/gi, "email trail")
      .replace(/source backfill/gi, "shipment update")
      .replace(/\bproof\b/gi, "confirmation")
      .replace(/\bbackfill\b/gi, "update")
      .replace(/\bgmail\b/gi, "email")
      .replace(/\bshipment truth\b/gi, "shipment record")
      .replace(/[.!?]+$/, "")
      .trim();
  if (/^no action\b/i.test(next)) next = "no operator action is needed";
  next = shortText(next, "monitor the shipment", 124)
    .replace(/^([A-Z])(?=[a-z])/, (letter) => letter.toLowerCase());
  meta = shipmentHasSourceGap(shipment) ? "" : shortText(meta, "", 96);
  return `${stateClause}${meta ? ` (${meta})` : ""}; next, ${next}.`;
}

function renderShipmentJourney(shipment) {
  const gates = Array.isArray(shipment?.gates) && shipment.gates.length
    ? shipment.gates
    : Array.isArray(shipment?.truthPacket?.gates)
      ? shipment.truthPacket.gates
      : [];
  const gatesByName = new Map(gates.map((gate) => [
    String(gate?.gate || "").toLowerCase().replace(/[_\s]+/g, "-"),
    gate,
  ]));
  const progressed = new Set(["true", "done", "delivered", "received", "scheduled", "out-for-delivery"]);
  const steps = [
    // Journey labels name gates, not unproven outcomes. The state marker says
    // whether Arrival is current or complete; "Landed: current" falsely reads
    // as positive arrival evidence on a canonical pre-arrival packet.
    { label: "Arrival", gates: ["arrival"] },
    { label: "Customs", gates: ["customs"] },
    { label: "Release/Pickup", gates: ["fees", "pickup"] },
    { label: "Out for delivery", gates: ["delivery"] },
    { label: "Delivered", gates: ["pod"] },
  ].map((step) => ({
    ...step,
    done: step.gates.every((gateName) => {
      const gate = gatesByName.get(gateName);
      const status = String(gate?.status ?? gate?.rawStatus ?? "").toLowerCase().replace(/[_\s]+/g, "-");
      return progressed.has(status);
    }),
  }));
  const currentIndex = steps.findIndex((step) => !step.done);
  return `
    <ol class="shipment-journey" aria-label="Shipment journey">
      ${steps.map((step, index) => {
        const stateClass = step.done ? "is-done" : index === currentIndex ? "is-current" : "is-future";
        const stateText = step.done ? "complete" : index === currentIndex ? "current" : "upcoming";
        return `
          <li class="shipment-journey-step ${stateClass}" ${index === currentIndex ? 'aria-current="step"' : ""} aria-label="${escapeHtml(`${step.label}: ${stateText}`)}">
            <span class="shipment-journey-dot" aria-hidden="true">${step.done ? "&#10003;" : ""}</span>
            <span class="shipment-journey-label">${escapeHtml(step.label)}</span>
          </li>
        `;
      }).join("")}
    </ol>
  `;
}

function renderDesktopStageCockpit(shipment) {
  const stateLabel = controlRoomRowState(shipment);
  const plainCockpitText = (value) => String(desk2TranslateReason(value) || "")
    .replace(/conflicting shipment info/gi, "Latest update may be incomplete")
    .replace(/needs source backfill/gi, "Latest update is still syncing")
    .replace(/needs proof/gi, "Waiting on latest update")
    .replace(/find release proof/gi, "Confirm release paperwork")
    .replace(/repair gmail proof/gi, "Wait for the latest email update")
    .replace(/release\/d\.?o\.?/gi, "release paperwork")
    .replace(/thread relation/gi, "email trail")
    .replace(/source backfill/gi, "shipment update")
    .replace(/\bproof\b/gi, "confirmation")
    .replace(/\bbackfill\b/gi, "update")
    .replace(/\bshipment truth\b/gi, "shipment record");
  const allActions = desktopStageCockpitActions(shipment);
  const actions = allActions.filter((action) =>
    !isSourceBackfillAction(action) && actionWorkstreamForUi(action) !== "truth-repair");
  const shown = actions.slice(0, 3);
  const cards = shown.map((action) => renderDesktopStageActionCard(action, shipment)
    .replace(/>([^<>]+)</g, (match, text) => `>${plainCockpitText(text)}<`));
  const sourceGapCopy = shipmentHasSourceGap(shipment) ? sourceGapStageCopy(shipment, 1) : null;
  const sourceGapSignal = sourceGapCopy
    ? `${sourceGapCopy.groupTitle || sourceGapCopy.kicker} ${sourceGapCopy.body}`
    : "";
  const staleSources = Array.isArray(shipment?.evidencePacket?.freshness?.staleSources)
    ? shipment.evidencePacket.freshness.staleSources
    : [];
  const gmailBehind = (staleSources.includes("gmail") && !shipmentGmailCoverageIsCurrent(shipment)) ||
    /\b(?:gmail|email)\b/i.test(sourceGapSignal);
  const machineNote = gmailBehind
    ? "Email sync is behind — I may be missing a newer reply."
    : sourceGapCopy || desktopStageDegraded(shipment)
      ? "Live shipment data is still catching up — I may be missing a newer update."
      : "";
  const primaryCard = cards[0] || "";
  const secondaryCards = cards.slice(1).join("");
  return `
    <div class="desktop-stage-cockpit" data-stage-cockpit="${escapeHtml(shipment.id)}">
      <div class="desktop-stage-cockpit-head">
        <button class="mini-button desktop-stage-back" data-stage-back type="button" aria-label="Back to today queue">Today</button>
        ${renderAwbTitle(shipment.awb || shipment.id, "strong", "awb-title desktop-stage-cockpit-awb")}
        <span class="control-status-pill ${escapeHtml(stateLabel.tone || "")}">${escapeHtml(desk2DisplayLabel(stateLabel.label))}</span>
        <button class="mini-button desk2-open-detail" data-open-detail-drawer type="button">Full detail</button>
      </div>
      <p class="cockpit-story">${escapeHtml(buildShipmentStory(shipment))}</p>
      ${renderShipmentJourney(shipment)}
      ${machineNote ? `<p class="cockpit-note">${escapeHtml(machineNote)}</p>` : ""}
      ${shipment.urgentInterrupt ? `
        <div class="desktop-stage-interrupt-note" data-cockpit-interrupt="${escapeHtml(shipment.urgentInterrupt.id)}">
          <strong>${escapeHtml(shortText(plainCockpitText(shipment.urgentInterrupt.title), "Urgent shipment issue", 90))}</strong>
          <span>${escapeHtml(shortText(plainCockpitText(shipment.urgentInterrupt.preparedAction), "", 150))}</span>
          ${shipment.urgentInterrupt.message ? `<q>${escapeHtml(shortText(plainCockpitText(shipment.urgentInterrupt.message), "", 150))}</q>` : ""}
          ${alertCadenceLabel(shipment.urgentInterrupt.id) ? `<em class="desktop-stage-cadence">${escapeHtml(plainCockpitText(alertCadenceLabel(shipment.urgentInterrupt.id)))}</em>` : ""}
        </div>
      ` : ""}
      ${primaryCard ? `
        <div class="desktop-stage-actions desktop-companion-action-stack desktop-stage-primary-action">
          ${primaryCard}
        </div>
      ` : `<div class="desktop-stage-clear"><strong>No open operator action.</strong><span>Monitoring — no operator move needed.</span></div>`}
      ${secondaryCards ? `
        <details class="desktop-stage-more-actions">
          <summary>Other actions · ${cards.length - 1}</summary>
          <div class="desktop-stage-actions desktop-companion-action-stack">${secondaryCards}</div>
        </details>
      ` : ""}
      ${actions.length > shown.length ? `<span class="desktop-stage-overflow">+ ${actions.length - shown.length} more actions in shipment detail</span>` : ""}
      ${renderDesktopStageEvidence(shipment)}
      ${renderDesktopCockpitChat(shipment)}
    </div>
  `;
}

// Shipment chat lives INSIDE the cockpit page — the operator asks about the
// shipment they are looking at and keeps working on it. No window, no modal,
// no wondering where the message goes: the section is labeled with the AWB
// and the thread is that shipment's own conversation.
function desktopShipmentChatSession(shipment) {
  const key = opsBrainChatScopeKeyForShipment(shipment);
  if (String(state.opsBrainActiveChatKey || "") === key) {
    return { history: state.opsBrainChatHistory || [], draft: state.opsBrainDraftInput || "", thinking: state.opsBrainThinkingQuestion || "" };
  }
  const session = state.opsBrainChatSessions?.[key] || {};
  return { history: session.history || [], draft: session.draftInput || "", thinking: "" };
}

function renderDesktopCockpitChat(shipment) {
  if (!shipment || isFallbackShipment(shipment)) return "";
  const awb = opsBrainDisplayAwb(shipment.awb || shipment.id);
  const session = desktopShipmentChatSession(shipment);
  const thread = renderDesktopCompanionThread(session.history, session.thinking);
  // The general companion column owns the screen's other chat input — never
  // show two competing composers at once.
  const composer = state.companionPanelOpen ? "" : `
    <form class="desktop-dock-composer cockpit" data-ops-brain-form data-chat-surface="cockpit" ${session.draft.trim() ? `data-has-draft="true"` : ""}>
      <div class="desktop-companion-input-row">
        <textarea data-ops-brain-input data-chat-surface="cockpit" rows="1" placeholder="Ask about ${escapeHtml(awb)}…">${escapeHtml(session.draft)}</textarea>
        <button type="submit" aria-label="Ask about this shipment" ${session.draft.trim() ? "" : "disabled"}>Ask</button>
      </div>
    </form>`;
  return `
    <section class="desktop-cockpit-chat" aria-label="Shipment chat" data-cockpit-chat="${escapeHtml(shipment.id)}">
      <div class="desktop-cockpit-chat-head">
        <span>Shipment chat</span>
        <strong>${escapeHtml(awb)}</strong>
      </div>
      ${thread ? `<div class="desktop-cockpit-chat-thread" aria-live="polite">${thread}</div>` : ""}
      ${composer || `<p class="desktop-cockpit-chat-note">General companion is open — close it to chat about this shipment here.</p>`}
    </section>
  `;
}

function renderDesktopActionStage(stageItems = null) {
  if (!isDesktopWorkspace()) return "";
  const rows = state.shipments;
  const shipment = desktopStageSelectedShipment();
  const entries = shipment ? null : (stageItems || desktopStageQueueItems(rows));
  const queueCount = entries ? desktopStageCountableEntries(entries).length : 0;
  const title = shipment ? opsBrainDisplayAwb(shipment.awb || shipment.id) : "Today";
  const subtitle = shipment
    ? shortText(desk2TranslateReason(nextStep(shipment)), "Review and approve the prepared action", 120)
    : state.shipments.some((item) => isFallbackShipment(item))
      ? "Live shipment memory is not loaded in this browser; open the local server link."
      : queueCount
        ? `${queueCount} item${queueCount === 1 ? "" : "s"} need you — approve, call, or repair from here`
        : "All clear — review the board or ask Yael";
  // The work canvas carries NO chat input: the conversation column owns the
  // composer, so there is exactly one place a typed message can go. A shipment
  // canvas offers a scoped chat entry; general chat opens from the top bar.
  return `
    <section class="desktop-companion-bar desktop-action-stage has-messages ${shipment ? "stage-shipment" : "stage-queue"}" aria-label="Action stage" data-desktop-action-stage>
      <div class="desktop-companion-head">
        <div class="desktop-companion-context">
          <strong>${escapeHtml(title)}</strong>
          <em>${escapeHtml(subtitle)}</em>
        </div>
      </div>
      <div class="desktop-companion-workspace">
        <div class="desktop-companion-thread" aria-live="polite">
          ${renderDesktopCaughtInterrupter()}
          ${shipment ? renderDesktopStageCockpit(shipment) : renderDesktopStageQueue(rows, entries)}
        </div>
      </div>
    </section>
  `;
}

// The SURFACE a message is typed in owns its scope: the dock is always the
// general companion; the cockpit composer is always the selected shipment.
function activateOpsBrainScopeForSurface(surface) {
  if (!isDesktopWorkspace()) return;
  if (surface === "dock") {
    activateOpsBrainChatScope("global");
  } else if (surface === "cockpit") {
    const shipment = desktopStageSelectedShipment();
    if (shipment) activateOpsBrainChatScopeForShipment(shipment, "selection");
  }
}

function focusDesktopCompanionInput() {
  window.setTimeout(() => {
    const input = document.querySelector(".desktop-companion-panel [data-ops-brain-input]");
    if (input) {
      input.focus();
      input.setSelectionRange(input.value.length, input.value.length);
    }
  }, 30);
}

// The conversation column is the GENERAL companion — a docked column the
// layout makes room for, never an overlay. Shipment-specific chat lives
// inside the shipment cockpit instead; this column always answers across the
// whole operation, owns its own composer, and closes back to an untouched
// canvas.
function renderDesktopCompanionPanel() {
  if (!isDesktopWorkspace() || !state.companionPanelOpen) return "";
  const isGlobalScope = String(state.opsBrainActiveChatKey || "global") === "global";
  const session = isGlobalScope
    ? { history: state.opsBrainChatHistory || [], draft: state.opsBrainDraftInput || "", thinking: state.opsBrainThinkingQuestion || "" }
    : { history: state.opsBrainChatSessions?.global?.history || [], draft: state.opsBrainChatSessions?.global?.draftInput || "", thinking: "" };
  const thread = renderDesktopCompanionThread(session.history, session.thinking);
  return `
    <aside class="desktop-companion-panel scope-general" aria-label="General companion" data-companion-dock>
      <div class="desktop-companion-panel-head">
        <div class="desktop-companion-panel-title">
          <span>Companion</span>
          <strong>All shipments</strong>
        </div>
        <button class="desktop-companion-close" data-close-companion-panel type="button" aria-label="Close chat and return to the board">Close</button>
      </div>
      <div class="desktop-companion-panel-thread" aria-live="polite">
        ${thread || `<div class="operator-inbox-empty">Ask about the operation — what arrived, what's blocked, what needs you today.</div>`}
      </div>
      <form class="desktop-dock-composer" data-ops-brain-form data-chat-surface="dock" ${session.draft.trim() ? `data-has-draft="true"` : ""}>
        <span class="desktop-companion-hint">Yael answers across the whole operation — every shipment, station, and plan.</span>
        <div class="desktop-companion-input-row">
          <textarea data-ops-brain-input data-chat-surface="dock" rows="1" placeholder="Ask Yael — any shipment, station, or plan…">${escapeHtml(session.draft)}</textarea>
          <button type="submit" aria-label="Ask Yael" ${session.draft.trim() ? "" : "disabled"}>Ask</button>
        </div>
      </form>
    </aside>
  `;
}

function renderControlRoomRow(shipment) {
  const selected = state.selectedId === shipment.id;
  const station = operationalStation(shipment) || shipment.station || "N/A";
  const carrier = shipment.airline || shipment.handler || shipment.tms?.carrier || "Carrier";
  const consignee = shipment.delivery?.consignee || shipment.client || shipment.consignee || "Consignee unknown";
  const action = nextStep(shipment);
  const primaryAction = shipmentDecisionPrimaryAction(shipment);
  const stateLabel = controlRoomRowState(shipment);
  const stateMeta = controlRoomRowMeta(shipment);
  const owner = controlRoomRowOwner(shipment, primaryAction);
  const context = mainIssue(shipment);
  return `
    <tr class="shipment-row control-table-row ${selected ? "active" : ""} ${globalProofFreshness().level !== "fresh" ? "stale-evidence" : ""}" data-id="${escapeHtml(shipment.id)}" tabindex="0">
      <td class="control-awb-cell">${renderAwbTitle(shipment.awb, "strong", "awb-title control-awb-title")}</td>
      <td><strong>${escapeHtml(station)}</strong><span>${escapeHtml(shortText(carrier, "Carrier", 24))}</span></td>
      <td><strong>${escapeHtml(shortText(consignee, "Consignee unknown", 34))}</strong><span>${escapeHtml(shortText(context || mainIssue(shipment), "", 54))}</span></td>
      <td class="control-status-cell">
        <span class="control-status-pill ${escapeHtml(stateLabel.tone)}">${escapeHtml(stateLabel.label)}</span>
        ${stateMeta ? `<span class="control-row-meta">${escapeHtml(shortText(stateMeta, "", 70))}</span>` : ""}
      </td>
      <td class="control-next-cell">
        <strong>${escapeHtml(shortText(action, "Review shipment", 82))}</strong>
        ${owner ? `<span class="control-next-owner">${escapeHtml(shortText(owner, "", 54))}</span>` : ""}
      </td>
    </tr>
  `;
}

function renderControlRoomTable(rows, activeLane) {
  if (!rows.length) {
    return `<div class="control-room-empty">No shipments in ${escapeHtml(controlRoomLaneDefinitions(state.shipments).find((lane) => lane.id === activeLane)?.title || "this lane")}.</div>`;
  }
  return `
    <section class="control-room-table-shell" aria-label="Control room queue">
      <table class="control-room-table">
        <thead>
          <tr>
            <th>AWB</th>
            <th>Station</th>
            <th>Consignee / state</th>
            <th>Status</th>
            <th>Next action</th>
          </tr>
        </thead>
        <tbody>${rows.map(renderControlRoomRow).join("")}</tbody>
      </table>
    </section>
  `;
}

function operatorInboxUnreadStats(rows) {
  // "Unread" is not an operator concept: the badge means interrupts + work.
  const center = operatorChangeCenter(rows);
  return {
    unread: center.interrupts.length,
    urgentUnread: center.interrupts.length,
    interrupts: center.interrupts.length,
    needsYou: center.needsYou.length,
    changes: center.changes.length,
  };
}

function renderControlRoomInboxSummary(rows) {
  const count = operatorInboxCount(rows);
  const stats = operatorInboxUnreadStats(rows);
  const unreadBadge = stats.unread
    ? `<em class="control-room-inbox-unread ${stats.urgentUnread ? "urgent" : ""}">${stats.unread} unread${stats.urgentUnread ? ` · ${stats.urgentUnread} urgent` : ""}</em>`
    : "";
  return `
    <section class="control-room-inbox-strip" aria-label="Operator inbox summary">
      <button class="control-room-inbox-button ${count ? "has-items" : "is-clear"} ${stats.urgentUnread ? "has-urgent-unread" : ""} ${state.operatorInboxOpen ? "active" : ""}" data-open-control-inbox type="button" aria-expanded="${state.operatorInboxOpen ? "true" : "false"}">
        <span>Inbox</span>
        <strong>${count}</strong>${unreadBadge}
        <small>${state.operatorInboxOpen ? "Open on this board" : count ? "Shipment-linked messages and work" : "No shipment messages need attention"}</small>
      </button>
    </section>
  `;
}

function renderDesktopControlUtilities(rows, sourceTruthBanner = "") {
  return `
    <div class="desktop-control-utilities" aria-label="Control room alerts and inbox">
      ${sourceTruthBanner}
      ${renderControlRoomInboxSummary(rows)}
    </div>
  `;
}

function renderControlRoomInboxDrawer(rows) {
  if (!state.operatorInboxOpen) return "";
  return `
    <div class="control-room-inbox-layer" aria-label="Operator inbox panel">
      <button class="control-room-inbox-scrim" data-close-control-inbox type="button" aria-label="Close inbox"></button>
      <aside class="control-room-inbox-drawer" aria-label="Operator inbox">
        <div class="control-room-inbox-drawer-head">
          <div>
            <span>Changes</span>
            <strong>Changes</strong>
          </div>
          <button class="mini-button" data-close-control-inbox type="button">Close</button>
        </div>
        ${renderOperatorInboxScreen(rows)}
      </aside>
    </div>
  `;
}

// ============================================================
// Desktop shell v2 — a calm control room. One top bar (search
// lives in the static header, sync status + inbox here), one
// grouped work queue on the left, the action stage as the work
// column on the right. Detail opens on demand. Phone untouched.
// ============================================================

// Plain operator words for the sync state. One sentence, one obvious action.
function observedSyncState() {
  // The payload's own verdict (bundled-fallback) outranks the health poll's.
  const cachedHealthSuperseded = Boolean(state.truthHealth?.cacheFallback && payloadSourceHealthLive());
  const observed = state.payloadSyncState || (cachedHealthSuperseded ? null : state.truthHealth?.syncState) || null;
  if (observed) return observed;
  const fallbackText = sourceTruthBackupWarningText();
  if (!fallbackText) return null;
  return {
    state: "stale-fallback",
    tone: "bad",
    lockActions: true,
    title: "Showing an old backup copy — not live data",
    sub: "Live shipment data could not be read. Sending and status changes are locked until live data is back.",
  };
}

function desk2SyncStatus() {
  // Observable pipeline states come first: a served backup copy or a stuck
  // request is the headline, whatever the freshness math says.
  const observed = observedSyncState();
  if (observed?.state === "syncing-live") {
    return { tone: "warn", title: observed.title, sub: observed.sub, showRefresh: false };
  }
  if (observed?.state === "stale-fallback") {
    return { tone: "bad", title: observed.title, sub: observed.sub, showRefresh: true };
  }
  if (observed?.state === "stuck-unclaimed") {
    return { tone: "bad", title: observed.title, sub: observed.sub, showRefresh: true };
  }
  const freshness = globalProofFreshness();
  const health = state.truthHealth;
  const hosted = health?.hostedPersistence;
  const hostedPressure = Boolean(hosted && (hosted.ok === false || hosted.circuit?.open));
  // Heartbeat-honest wording: an old proof that fresh refresh runs verified as
  // unchanged means "no new email", never "up to date as of 3 days ago".
  const lastWriteAgeMinutes = freshness.ageMinutes !== null
    ? freshness.ageMinutes
    : freshness.lastWriteAt
      ? Math.round((Date.now() - new Date(freshness.lastWriteAt).getTime()) / 60000)
      : null;
  const oldButVerified = lastWriteAgeMinutes !== null && lastWriteAgeMinutes > 60;
  // Three different clocks, three different words: the CHECK is the cron run
  // (refreshHealth), the WRITE is the proof snapshot (lastWriteText = when new
  // email evidence last landed). Never label a write time as a check.
  const refreshRun = health?.gmail?.refreshHealth || null;
  // ageMinutes was computed when the health payload was FETCHED; rendering it
  // later reads "Checked 11m ago" against a 5m cadence. Recompute from the run
  // timestamp at render time whenever one is present.
  // The sidecar snapshot_time can lag one cycle behind the row's write clock —
  // take the newer of the two; the write time IS the check time.
  const refreshRunAt = Math.max(
    Date.parse(refreshRun?.snapshotTime || "") || 0,
    Date.parse(refreshRun?.updatedAt || "") || 0,
  );
  const lastCheckAge = refreshRunAt > 0
    ? Math.max(0, Math.round((Date.now() - refreshRunAt) / 60000))
    : refreshRun && Number.isFinite(Number(refreshRun.ageMinutes)) ? Number(refreshRun.ageMinutes) : null;
  const lastCheckOk = String(refreshRun?.lastRunStatus || "") === "success";
  const checked = lastCheckAge !== null && lastCheckOk
    ? `Checked ${lastCheckAge <= 1 ? "just now" : `${lastCheckAge}m ago`} · ${freshness.lastWriteText ? `no new email since ${freshness.lastWriteText}` : "no new email"}`
    : freshness.lastWriteText
      ? oldButVerified
        ? `No new email since ${freshness.lastWriteText} — checked recently`
        : `Last new email ${freshness.lastWriteText}`
      : "Checking email sync";
  // Never claim all-clear while overall shipment data health is not "live",
  // even when email itself is current.
  const healthNotLive = Boolean(health && health.status && health.status !== "live" && !payloadSourceHealthLive());
  // The global heartbeat can be healthy while individual shipments still wait
  // on a specific source family. Never say a plain "up to date" while the
  // board shows source gaps, and never translate non-email gaps into Gmail work.
  const sourceGapSummary = sourceGapSummaryForUi();
  const gappedRows = sourceGapSummary?.rows || [];
  const gappedCount = sourceGapSummary?.count || 0;
  if (sourceGapSummary && sourceGapSummary.category !== "email") {
    return {
      tone: "warn",
      title: sourceGapSummary.copy.title,
      sub: sourceGapSummary.copy.body,
      showRefresh: sourceGapSummary.copy.showRefresh,
    };
  }
  if (freshness.level === "fresh" && !hostedPressure && !healthNotLive && gappedCount > 0) {
    return {
      tone: "warn",
      title: sourceGapSummary.copy.title,
      sub: sourceGapSummary.copy.body,
      showRefresh: sourceGapSummary.copy.showRefresh,
    };
  }
  if (freshness.level === "fresh" && !hostedPressure && !healthNotLive) {
    // The operator can always run a real refresh — a healthy pill still shows
    // the control (it reports "checked, no new mail" honestly when pressed).
    return { tone: "ok", title: "Email sync up to date", sub: checked, showRefresh: true };
  }
  if (freshness.level === "fresh" && healthNotLive) {
    const cause = desk2TranslateReason((Array.isArray(health.warnings) && health.warnings[0]) || health.operatorGuidance || "");
    return {
      tone: "warn",
      title: "Some shipment data is catching up",
      sub: shortText(cause, "Email is current; other shipment data is still refreshing.", 90),
      showRefresh: false,
    };
  }
  if (freshness.level === "refresh-failed") {
    return {
      tone: "bad",
      title: "Email sync is failing",
      sub: "Shipment data may be missing new replies — refresh email sync.",
      showRefresh: true,
    };
  }
  if (freshness.level === "stale" || freshness.level === "source-gap") {
    if (sourceGapSummary) {
      return {
        tone: "warn",
        title: sourceGapSummary.copy.title,
        sub: sourceGapSummary.copy.body,
        showRefresh: sourceGapSummary.copy.showRefresh,
      };
    }
    const lastGood = lastCheckAge !== null && lastCheckOk
      ? `last successful check ${lastCheckAge}m ago`
      : freshness.lastWriteText
        ? `last successful check ${freshness.lastWriteText}`
        : "";
    return {
      tone: "warn",
      title: "Email sync is behind",
      sub: `Shipment data may be missing new replies${lastGood ? ` — ${lastGood}` : ""}. Refresh email sync.`,
      showRefresh: true,
    };
  }
  return {
    tone: hostedPressure ? "warn" : "ok",
    title: hostedPressure ? "Saving to cloud is slow right now" : "Email sync up to date",
    sub: hostedPressure ? "Shipment data still loads; changes may save late." : checked,
    showRefresh: false,
  };
}

function renderDesk2TopBar(rows, precomputed = {}) {
  const sync = desk2SyncStatus();
  const count = precomputed.inboxCount ?? operatorInboxCount(rows);
  const stats = precomputed.inboxStats || operatorInboxUnreadStats(rows);
  return `
    <header class="desk2-top" aria-label="Control room status bar">
      <div class="desk2-sync ${escapeHtml(sync.tone)}" data-sync-status data-sync-tone="${escapeHtml(sync.tone)}">
        <span class="desk2-sync-dot" aria-hidden="true"></span>
        <div class="desk2-sync-copy">
          <strong>${escapeHtml(sync.title)}</strong>
          <span>${escapeHtml(sync.sub)}</span>
        </div>
        ${sync.showRefresh ? `<span class="desk2-sync-action">${renderGmailRetryControl().replace(">Retry Gmail refresh<", ">Refresh email sync<").replace(">Retry again<", ">Refresh again<")}</span>` : ""}
      </div>
      <button class="desk2-companion ${state.companionPanelOpen ? "active" : ""}" data-open-companion-panel type="button" aria-expanded="${state.companionPanelOpen ? "true" : "false"}">
        <strong>Ask Yael</strong>
        <em>${state.companionPanelOpen ? "chat open" : "companion"}</em>
      </button>
      <button class="desk2-inbox ${stats.interrupts ? "urgent" : count ? "has-items" : ""}" data-open-control-inbox type="button" aria-expanded="${state.operatorInboxOpen ? "true" : "false"}">
        <strong>Changes</strong>
        <b>${count}</b>
        ${stats.interrupts ? `<em>${stats.interrupts} urgent</em>` : count ? `<em>waiting on you</em>` : `<em>all clear</em>`}
      </button>
    </header>
  `;
}

const DESK2_LANE_TITLES = {
  attention: "Needs attention",
  ready: "Ready for pickup",
  "not-ready": "Arrived — not ready yet",
  moving: "Pickup & delivery",
  transit: "On the way",
};

const DESK2_LANE_ORDER = ["attention", "ready", "moving", "not-ready", "transit"];

// Desk2 speaks operator language on the surface; canonical labels stay intact
// underneath (they are fixture-pinned and feed the truth pipeline).
function desk2DisplayLabel(label) {
  return label;
}

function desk2DisplayMeta(meta) {
  return { "truth source degraded": "Waiting on email sync" }[meta] || meta;
}

// Translate the most common data-authored repair sentences into operator words
// for the primary surface. The untranslated canonical text stays available in
// full detail — this is translation, not concealment.
function desk2TranslateReason(text) {
  const value = String(text || "");
  const coverage = value.match(/(\d+) active row\(s\) lack clean per-AWB Gmail coverage/i);
  if (coverage) {
    const count = Number(coverage[1]) || 0;
    return count > 1
      ? `${count} shipments are missing their latest Gmail replies.`
      : "This shipment is missing its latest Gmail replies.";
  }
  return value
    .replace(/^Email proof is stale\b/i, "Email sync is behind")
    .replace(/Terminal shipment state is not certified:?\s*/i, "Terminal state is not certified: ")
    .replace(/Terminal delivery\/POD proof is not certified:?\s*/i, "Terminal state is not certified: ")
    .replace(/Direct Gmail OAuth ingestion is not configured\.?/i, "Email connection is not set up in this environment.")
    .replace(/Canonical truth/g, "The shipment record")
    .replace(/canonical truth/g, "the shipment record")
    .replace(/Restore Gmail\/Supabase ingestion health, then refresh Gmail truth before acting on this shipment state\.?/i,
      "Refresh email sync before acting on this shipment.")
    .replace(/Verify direct arrival, pickup, delivery, and POD evidence before treating this shipment as delivered or closed\.?/i,
      "Verify direct arrival/delivery proof before closing this shipment.")
    .replace(/hosted shipment-truth-packets?/gi, "the cloud shipment data")
    .replace(/shipment-truth-packets?/gi, "shipment data");
}

// One stable hue per client so rows scan by identity (Sonoma tag dots).
function desk2ClientHue(name = "") {
  let h = 0;
  const text = String(name || "").toLowerCase();
  for (let i = 0; i < text.length; i += 1) h = (h * 31 + text.charCodeAt(i)) % 360;
  return h;
}

// Operators say AWBs by their tail: small prefix, bold last four.
function desk2CompactAwb(awb = "") {
  const digits = String(awb || "").replace(/\D/g, "");
  if (digits.length !== 11) return escapeHtml(String(awb || ""));
  return `${escapeHtml(digits.slice(0, 3))}-${escapeHtml(digits.slice(3, 7))}<b>${escapeHtml(digits.slice(7))}</b>`;
}

function renderDesk2QueueRow(shipment) {
  const selected = state.selectedId === shipment.id && state.stageFocus === "shipment";
  const stateLabel = controlRoomRowState(shipment);
  const consignee = shortText(shipment.client || shipment.delivery?.consignee || shipment.consignee || "Consignee unknown", "Consignee unknown", 42);
  // Gapped shipments all share one generic repair sentence — repeating it per
  // row helps nobody. Show what differs (station/route) instead.
  const gapped = shipmentHasSourceGap(shipment);
  const place = operationalStation(shipment) || shipment.station || shipment.route || "";
  const lastEmailAge = shortAge(shipment.lastEmail?.at || "");
  const next = gapped
    ? [place, sourceGapDisplayMeta(shipment), shipmentSourceGapCategory(shipment) === "email" && lastEmailAge ? `last email ${lastEmailAge}` : ""].filter(Boolean).join(" · ")
    : shortText(desk2TranslateReason(nextStep(shipment)), "Review shipment", 64);
  return `
    <button class="shipment-row desk2-row ${selected ? "active" : ""}" data-id="${escapeHtml(shipment.id)}" type="button">
      <span class="desk2-row-dot ${escapeHtml(stateLabel.tone || "")}" style="--client-hue:${desk2ClientHue(consignee)}" aria-hidden="true"></span>
      <span class="desk2-row-main">
        <span class="desk2-row-top">
          <strong class="desk2-row-client">${escapeHtml(consignee)}</strong>
          <em class="desk2-row-awb">${desk2CompactAwb(shipment.awb || shipment.id)}${operationalStation(shipment) ? ` · ${escapeHtml(operationalStation(shipment))}` : ""}</em>
        </span>
        <span class="desk2-row-next">${escapeHtml(next)}</span>
      </span>
      <span class="desk2-row-state ${escapeHtml(stateLabel.tone || "")}">${escapeHtml(desk2DisplayLabel(stateLabel.label))}</span>
    </button>
  `;
}

// AWB-shaped searches should match identity, not narrative text that may quote
// any AWB (shared reason strings once made every search return the whole board).
function desk2RefineSearch(rows) {
  const query = String(state.query || "").trim();
  if (!/^[\d-]{5,}$/.test(query)) return rows;
  const digits = query.replace(/\D/g, "");
  const refined = rows.filter((shipment) => String(shipment.awb || shipment.id || "").replace(/\D/g, "").includes(digits));
  return refined.length ? refined : rows;
}

function desktopStageCountableEntries(entries = []) {
  // Waiting/export-side uncertainty is visible but never counted as work.
  return entries.filter((entry) => entry.kind !== "monitor");
}

function renderDesk2Queue(rows, stageItems = null) {
  const queueRows = desk2RefineSearch(rows);
  // Count identity: this line sits beside the Today panel, so it must count
  // the SAME items the panel renders (incl. the staleness lock). The canonical
  // workBoard (state.workBoard) stays payload-only until every surface swaps
  // to it together — a half-adoption showed 16 vs 17 on one screen.
  const needsYou = desktopStageCountableEntries(stageItems || desktopStageQueueItems(queueRows)).length;
  const active = queueRows.filter((shipment) => !shipmentTruthComplete(shipment)).length;
  // One classification pass instead of one controlRoomRows() sweep per lane.
  const byLane = new Map(DESK2_LANE_ORDER.map((laneId) => [laneId, []]));
  for (const shipment of controlRoomBoardRows(queueRows)) {
    const laneId = controlRoomLaneForShipment(shipment);
    if (byLane.has(laneId)) byLane.get(laneId).push(shipment);
  }
  // Lane headers FILTER the rail (toggle): clicking "Pickup & delivery" shows
  // only that lane; clicking again (or "Show all") clears. The filter never
  // touches Today's Work — the rail is navigation, the stage is work.
  const laneFilter = state.desk2LaneFilter && DESK2_LANE_ORDER.includes(state.desk2LaneFilter) ? state.desk2LaneFilter : null;
  if (!(state.desk2OpenRollups instanceof Set)) state.desk2OpenRollups = new Set();
  const renderLaneRows = (laneId, laneRows) => {
    // Quiet lanes roll up by client: N same-client shipments become one line
    // ("CLIENT xN") that expands in place. Working lanes always show every row.
    if (!["transit", "not-ready"].includes(laneId) || laneRows.length < 4) {
      return laneRows.map((shipment) => renderDesk2QueueRow(shipment)).join("");
    }
    const byClient = new Map();
    for (const shipment of laneRows) {
      const key = shortText(shipment.client || shipment.delivery?.consignee || shipment.consignee || "Unknown", "Unknown", 42);
      if (!byClient.has(key)) byClient.set(key, []);
      byClient.get(key).push(shipment);
    }
    return [...byClient.entries()].map(([client, members]) => {
      if (members.length < 3) return members.map((shipment) => renderDesk2QueueRow(shipment)).join("");
      const rollKey = `${laneId}:${client}`;
      const open = state.desk2OpenRollups.has(rollKey);
      const stations = [...new Set(members.map((m) => operationalStation(m)).filter(Boolean))].slice(0, 3).join(" · ");
      return `
        <button class="desk2-roll ${open ? "open" : ""}" type="button" data-desk2-roll="${escapeHtml(rollKey)}">
          <span class="desk2-row-dot" style="--client-hue:${desk2ClientHue(client)}" aria-hidden="true"></span>
          <strong class="desk2-roll-client">${escapeHtml(client)} ×${members.length}</strong>
          <span class="desk2-roll-where">${escapeHtml(stations)} <i class="desk2-roll-chev">▸</i></span>
        </button>
        ${open ? members.map((shipment) => renderDesk2QueueRow(shipment)).join("") : ""}
      `;
    }).join("");
  };
  const sections = DESK2_LANE_ORDER.map((laneId) => {
    if (laneFilter && laneId !== laneFilter) return "";
    const laneRows = (byLane.get(laneId) || []).sort((a, b) => {
      const aGroup = { primary: a, bucket: lifecycleState(a).id, station: operationalStation(a) || "", client: a.client || "" };
      const bGroup = { primary: b, bucket: lifecycleState(b).id, station: operationalStation(b) || "", client: b.client || "" };
      return compareCargoGroups(aGroup, bGroup);
    });
    if (!laneRows.length) return laneFilter ? `
      <section class="desk2-lane" data-desk2-lane-section="${escapeHtml(laneId)}">
        <button class="desk2-lane-head active" type="button" data-desk2-lane="${escapeHtml(laneId)}">${escapeHtml(DESK2_LANE_TITLES[laneId] || laneId)} <b>0</b></button>
        <div class="desk2-lane-empty">Nothing in this lane right now.</div>
      </section>
    ` : "";
    return `
      <section class="desk2-lane" data-desk2-lane-section="${escapeHtml(laneId)}">
        <button class="desk2-lane-head ${laneFilter === laneId ? "active" : ""}" type="button" data-desk2-lane="${escapeHtml(laneId)}" aria-pressed="${laneFilter === laneId ? "true" : "false"}">
          ${escapeHtml(DESK2_LANE_TITLES[laneId] || laneId)} <b>${laneRows.length}</b>
        </button>
        ${renderLaneRows(laneId, laneRows)}
      </section>
    `;
  }).join("");
  const filterPill = laneFilter ? `
    <div class="desk2-lane-filter" data-desk2-lane-filter>
      <span>Showing ${escapeHtml(DESK2_LANE_TITLES[laneFilter] || laneFilter)}</span>
      <button type="button" data-desk2-lane-clear>Show all</button>
    </div>
  ` : "";
  return `
    <nav class="desk2-queue" aria-label="Shipment queue">
      <div class="desk2-day">
        <strong>${active} active shipment${active === 1 ? "" : "s"}</strong>
        <span>${needsYou ? `${needsYou} need${needsYou === 1 ? "s" : ""} you today` : "nothing needs you right now"}</span>
      </div>
      ${filterPill}
      ${sections || `<div class="desk2-lane-empty">No active shipments on the board.</div>`}
    </nav>
  `;
}

// Urgent interrupt toasts: imperative, id-keyed DOM appended OUTSIDE the
// render tree, so an arriving interrupt never wipes an open composer or any
// other in-progress work. Idempotent — safe to call on every render pass.
// Client mirror of lib/alert-cadence.js (the lib is the verified authority;
// the browser bundle cannot require it). Interrupt once, then follow the
// schedule: remind after REMIND, escalate after ESCALATE (pinned, no more
// toasts), re-alert only on material change; ack suppresses until nextAlertAt.
const ALERT_REMIND_MS = 30 * 60000;
const ALERT_ESCALATE_MS = 60 * 60000;

function alertMaterialKey(interrupt = {}) {
  return [interrupt.kind || "", interrupt.cause || "", String(interrupt.message || "").replace(/\s+/g, " ").trim().toLowerCase().slice(0, 120)].join("|");
}

function advanceAlertState(interrupt, nowMs = Date.now()) {
  if (!(state.alertStates instanceof Map)) state.alertStates = new Map();
  const prior = state.alertStates.get(interrupt.id) || null;
  const materialKey = alertMaterialKey(interrupt);
  let record;
  if (!prior || prior.materialKey !== materialKey) {
    record = {
      materialKey,
      firstSeenAt: prior?.firstSeenAt || nowMs,
      lastAlertedAt: nowMs,
      alertCount: (prior?.alertCount || 0) + 1,
      nextAlertAt: nowMs + ALERT_REMIND_MS,
      escalationLevel: 0,
      acknowledgedAt: 0,
      shouldToast: true,
    };
  } else {
    record = { ...prior, shouldToast: false };
    if (nowMs - record.firstSeenAt >= ALERT_ESCALATE_MS) record.escalationLevel = Math.max(1, record.escalationLevel);
    const suppressed = record.acknowledgedAt && nowMs < record.nextAlertAt;
    if (nowMs >= record.nextAlertAt && !suppressed && record.escalationLevel < 1) {
      record.lastAlertedAt = nowMs;
      record.alertCount += 1;
      record.nextAlertAt = nowMs + ALERT_REMIND_MS;
      record.shouldToast = true;
    }
  }
  state.alertStates.set(interrupt.id, record);
  return record;
}

function alertCadenceLabel(interruptId, nowMs = Date.now()) {
  const record = state.alertStates instanceof Map ? state.alertStates.get(interruptId) : null;
  if (!record) return "";
  const openMinutes = Math.max(1, Math.round((nowMs - record.firstSeenAt) / 60000));
  const openLabel = openMinutes >= 60 ? `${Math.round(openMinutes / 6) / 10}h` : `${openMinutes}m`;
  if (record.escalationLevel >= 1) return `Escalated · waiting ${openLabel}`;
  const untilNext = Math.round((record.nextAlertAt - nowMs) / 60000);
  return `Open ${openLabel}${untilNext > 0 ? ` · next reminder in ${untilNext}m` : ""}`;
}

function acknowledgeInterruptAlert(interruptId, nowMs = Date.now()) {
  if (!(state.alertStates instanceof Map)) return;
  const record = state.alertStates.get(interruptId);
  if (record) state.alertStates.set(interruptId, { ...record, acknowledgedAt: nowMs, nextAlertAt: nowMs + ALERT_REMIND_MS, shouldToast: false });
}

function maybeShowInterruptToasts(rows = state.shipments) {
  if (!isDesktopWorkspace()) return;
  if (!(state.dismissedInterruptToasts instanceof Set)) state.dismissedInterruptToasts = new Set();
  const live = new Set();
  for (const shipment of rows) {
    const interrupt = shipment.urgentInterrupt;
    if (!interrupt || !interrupt.id) continue;
    live.add(interrupt.id);
    const cadence = advanceAlertState(interrupt);
    if (!cadence.shouldToast) continue;
    if (document.getElementById(`urgent-toast-${interrupt.id.replace(/[^a-z0-9-]/gi, "-")}`)) continue;
    const toast = document.createElement("div");
    toast.className = "urgent-interrupt-toast";
    toast.id = `urgent-toast-${interrupt.id.replace(/[^a-z0-9-]/gi, "-")}`;
    toast.setAttribute("role", "status");
    toast.innerHTML = `
      <strong>${escapeHtml(shortText(interrupt.title, "Urgent shipment issue", 80))}</strong>
      <span>${escapeHtml(shortText(interrupt.preparedAction, "", 110))}</span>
      <span class="urgent-interrupt-toast-actions">
        <button type="button" data-toast-open="${escapeHtml(shipment.id)}" data-toast-id="${escapeHtml(interrupt.id)}">Open</button>
        <button type="button" data-toast-dismiss="${escapeHtml(interrupt.id)}">Dismiss</button>
      </span>
    `;
    toast.addEventListener("click", (event) => {
      const open = event.target.closest("[data-toast-open]");
      const dismiss = event.target.closest("[data-toast-dismiss]");
      if (open) {
        state.dismissedInterruptToasts.add(open.dataset.toastId || "");
        acknowledgeInterruptAlert(open.dataset.toastId || "");
        state.selectedId = open.dataset.toastOpen;
        state.detailOpen = false;
        state.operatorInboxOpen = false;
        toast.remove();
        renderList();
      } else if (dismiss) {
        state.dismissedInterruptToasts.add(dismiss.dataset.toastDismiss || "");
        acknowledgeInterruptAlert(dismiss.dataset.toastDismiss || "");
        toast.remove();
      }
    });
    document.body.appendChild(toast);
  }
  // Auto-clean: resolved/superseded interrupts take their toasts with them.
  document.querySelectorAll(".urgent-interrupt-toast").forEach((element) => {
    const id = element.id.replace(/^urgent-toast-/, "");
    const stillLive = [...live].some((liveId) => liveId.replace(/[^a-z0-9-]/gi, "-") === id);
    if (!stillLive) element.remove();
  });
}

// Async loaders (notifications, events, hosted snapshots) can land AFTER a
// paint without triggering a render, leaving the inbox badge stale ("10 all
// read" beside a 30/22-unread drawer). After each paint, reconcile once: if
// the rendered badge disagrees with the live count, re-render — unless a
// composer/preview is open (never wipe in-progress work).
let inboxBadgeReconcileTimer = 0;
function scheduleInboxBadgeReconcile() {
  window.clearTimeout(inboxBadgeReconcileTimer);
  inboxBadgeReconcileTimer = window.setTimeout(() => {
    if (state.previewActionId || state.operatorInboxOpen) return;
    const badge = document.querySelector(".desk2-inbox b");
    if (!badge) return;
    const rendered = Number(badge.textContent.trim() || "0");
    const live = operatorInboxCount(state.shipments);
    if (rendered !== live) renderList();
  }, 1500);
}

function renderDesktopControlRoom(rows, sourceTruthBanner = "") {
  void sourceTruthBanner; // desktop v2 carries sync state in the top bar, in operator words
  window.setTimeout(() => maybeShowInterruptToasts(rows), 0);
  scheduleInboxBadgeReconcile();
  const activeLane = activeControlLane(rows);
  state.controlLane = activeLane;
  const laneRows = controlRoomRows(rows, activeLane);
  if (isDesktopWorkspace() && laneRows.length && !state.detailOpen && !state.selectedGroupId && !state.selectedVisualGroupKey) {
    // Default a selection ONLY when the current one no longer exists anywhere
    // on the board. An explicit click on any lane's row must never be stolen
    // by lane math (production bug: every Pickup/Arrived/On-the-way click
    // snapped back to the first Needs-Attention shipment).
    const selectedExists = rows.some((shipment) => shipment.id === state.selectedId);
    if (!selectedExists) state.selectedId = laneRows[0].id;
  }
  // Compute the expensive shared inputs once per render pass.
  const stageItems = desktopStageSelectedShipment() ? null : desktopStageQueueItems(state.shipments);
  const precomputed = {
    inboxCount: operatorInboxCount(rows),
    inboxStats: operatorInboxUnreadStats(rows),
  };
  return `
    <section class="desktop-control-room desk2 ${state.operatorInboxOpen ? "inbox-open" : ""} ${state.companionPanelOpen ? "companion-docked" : ""}" aria-label="ELAI control room">
      ${renderDesk2TopBar(rows, precomputed)}
      <div class="desk2-main">
        ${renderDesk2Queue(rows, stageItems)}
        <div class="desk2-work">
          ${renderDesktopActionStage(stageItems)}
        </div>
        ${renderDesktopCompanionPanel()}
      </div>
      ${renderControlRoomInboxDrawer(rows)}
    </section>
  `;
}

function lifecycleCount(rows, id) {
  if (id === "today") return todayActionRows(rows).length;
  return rows.filter((shipment) => lifecycleState(shipment).id === id).length;
}

function tabTitle(stage, meta) {
  return {
    inbox: "Inbox",
    today: "Action",
    brain: "Brain",
    transit: "In transit",
    ready: "Ready",
    customs: "Holds",
    arrived: "Arrived",
    origin: "Origin",
  }[stage] || meta.title;
}

function lifecycleIcon(stage) {
  const icons = {
    inbox: `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6.5A2.5 2.5 0 0 1 6.5 4h11A2.5 2.5 0 0 1 20 6.5v11a2.5 2.5 0 0 1-2.5 2.5h-11A2.5 2.5 0 0 1 4 17.5v-11Z"/><path d="M4 13h4.2l1.6 2.4h4.4L15.8 13H20"/></svg>`,
    today: `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.2 2.8 4.8 13.4a.8.8 0 0 0 .6 1.3h5.1l-1.2 6.5 9.9-11.7a.8.8 0 0 0-.6-1.3h-5.2l-.2-5.4Z"/></svg>`,
    brain: `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3.2"/><circle cx="5.2" cy="7" r="1.8"/><circle cx="18.8" cy="7" r="1.8"/><circle cx="6.5" cy="18" r="1.8"/><circle cx="17.5" cy="18" r="1.8"/><path d="M7 7.8 9.6 10"/><path d="M17 7.8 14.4 10"/><path d="M8.1 17 10 14.4"/><path d="M15.9 17 14 14.4"/></svg>`,
    ready: `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19V7.5h9.5V19"/><path d="M7.8 19v-7.2h4.8V19"/><path d="M7.8 11.8h4.8"/><path d="M15.5 14h3.1l2 2.2V19h-1.7"/><path d="M15.5 19h1.2"/><circle cx="8.8" cy="19" r="1.4"/><circle cx="18.2" cy="19" r="1.4"/></svg>`,
    customs: `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3.3 8.8 15.2a1.6 1.6 0 0 1-1.4 2.4H4.6a1.6 1.6 0 0 1-1.4-2.4L12 3.3Z"/><path d="M12 8.7v5.2"/><path d="M12 17.6h.01"/></svg>`,
    transit: `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5.5" cy="17.5" r="2.1"/><circle cx="18.5" cy="6.5" r="2.1"/><path d="M7.5 16.8c3.5-7.2 8.6-1.2 10-8.2" stroke-dasharray="1 3.2"/></svg>`,
  };
  return icons[stage] || icons.today;
}

function renderLifecycleOverview(rows) {
  const stages = ["inbox", "today", "ready", "brain", "customs", "transit"];
  return `
    <section class="journey-overview" aria-label="Shipment lifecycle overview">
      ${stages
        .map((stage) => {
          const meta = lifecycleMeta(stage);
          const count = stage === "brain" || stage === "inbox" ? countRowsForFilter(state.shipments, stage) : lifecycleCount(rows, stage);
          if (!count && stage !== "brain") return "";
          const label = tabTitle(stage, meta);
          const brainStatus = stage === "brain" && state.opsBrainThinkingQuestion
            ? `<strong class="brain-status typing" aria-label="Brain is typing"><i></i><i></i><i></i></strong>`
            : stage === "brain" && state.opsBrainHasReadyAnswer
              ? `<strong class="brain-status ready" aria-label="Brain answer ready"></strong>`
              : "";
          return `
            <button class="journey-tile ${meta.tone} ${state.filter === stage ? "active" : ""}" data-filter="${stage}" type="button" aria-label="${escapeHtml(label)}: ${count}" title="${escapeHtml(label)}">
              <i class="journey-icon">${lifecycleIcon(stage)}</i>
              <span>${escapeHtml(label)}</span>
              ${stage === "brain" ? brainStatus : `<strong>${count}</strong>`}
            </button>
          `;
        })
        .join("")}
    </section>
  `;
}

function renderWorkBoard(rows, mode) {
  const groups = visualShipmentRows(rows)
    .sort(compareCargoGroups)
    .filter((group) => !state.dismissedCargoCards.has(cargoDoneKey(group)));
  return `
    <section class="focus-board native-feed" aria-label="Shipment feed">
      <div class="card-stack">
        ${groups.map(renderCargoCard).join("")}
      </div>
    </section>
  `;
}

function actionMatchesQuery(action) {
  const query = state.query.trim().toLowerCase();
  if (!query) return true;
  if (awbIdentityMatchesSearch([action.awb, action.shipmentAwb, action.shipmentId], query)) return true;
  return [
    action.awb,
    action.label,
    action.type,
    action.targetName,
    action.targetEmail,
    action.reason,
    action.subject,
  ].some((value) => String(value || "").toLowerCase().includes(query));
}

function hiddenDraftActions() {
  const activeShipmentIds = new Set(state.shipments.map((shipment) => shipment.id));
  return state.actions
    .filter((action) =>
      isVisibleDraftWork(action) &&
      !activeShipmentIds.has(action.shipmentId) &&
      actionMatchesQuery(action)
    )
    .sort((a, b) =>
      Number(isTmsAction(b)) - Number(isTmsAction(a)) ||
      String(a.awb || "").localeCompare(String(b.awb || "")) ||
      String(a.label || "").localeCompare(String(b.label || ""))
    );
}

function hiddenDraftGroups(actions) {
  const tmsReviews = actions.filter(isTmsAction);
  const drafts = actions.filter((action) => !isTmsAction(action));
  return [
    tmsReviews.length ? { label: "TMS alerts", className: "tms-review-drafts", actions: tmsReviews } : null,
    drafts.length ? { label: "Drafts", className: "gmail-drafts", actions: drafts } : null,
  ].filter(Boolean);
}

function renderHiddenDraftQueue(actions) {
  if (!actions.length) return "";
  const groups = hiddenDraftGroups(actions);
  return `
    <section class="hidden-draft-section operator-section" aria-label="Draft reviews outside active shipments">
      ${groups
        .map((group) => `
          <div class="hidden-draft-group ${group.className}">
            <div class="hidden-draft-heading">
              <h3>${group.label}</h3>
              <span>${group.actions.length}</span>
            </div>
            <div class="action-list">
              ${group.actions.map((action) => renderActionCard(action, { showAwb: true })).join("")}
            </div>
          </div>
        `)
        .join("")}
    </section>
  `;
}

function renderCargoCard(group) {
  const primary = group.primary;
  const counts = cardCounts(group);
  const meta = lifecycleMeta(group.bucket);
  const lifecycle = lifecycleState(primary);
  const ops = opsState(primary);
  const awbs = group.shipments.map((shipment) => shipment.awb);
  const customs = customsStage(primary);
  const dispatch = dispatchStage(primary);
  const title = counts.total > 1 ? `${counts.total} AWBs` : primary.awb;
  const route = [group.station, primary.airline].filter(Boolean).join(" · ") || "Station unknown";
  const eta = group.eta ? shortText(group.eta, "ETA unknown", 38) : "ETA unknown";
  const action = cardActionLine(primary, lifecycle, customs, dispatch);
  const draftSummary = draftWorkSummary(primary);
  const active = state.selectedVisualGroupKey === group.key || (!state.selectedVisualGroupKey && state.selectedId === primary.id);
  const doneKey = cargoDoneKey(group);
  const pending = state.pendingDoneKeys.has(doneKey);
  const doneSubtitle = [title, group.client, route].filter(Boolean).join(" · ");
  return `
    <article class="cargo-card ${meta.tone} ${active ? "active" : ""} ${pending ? "done-pending" : ""}" data-visual-group="${group.key}" data-primary-id="${primary.id}" data-group-size="${counts.total}" data-cargo-dismiss-key="${escapeHtml(doneKey)}" data-cargo-done-subtitle="${escapeHtml(doneSubtitle)}" role="button" tabindex="0">
      <span class="cargo-top">
        ${counts.total === 1 ? renderAwbTitle(primary.awb, "strong", "awb-title cargo-awb-title") : `<strong>${escapeHtml(title)}</strong>`}
        <em>${ops.label || lifecycle.short}</em>
      </span>
      <span class="cargo-route">${route} · ${eta}</span>
      <span class="cargo-client">${shortText(group.client, "Client unknown", 58)}</span>
      ${action ? `<span class="cargo-status"><b>${shortText(action, "Monitor", 52)}</b></span>` : ""}
      ${draftSummary ? `<span class="cargo-draft ${draftSummary.tms ? "tms" : ""}">${draftSummary.label}</span>` : ""}
      ${renderCargoTags(primary, counts, awbs, customs, dispatch, lifecycle)}
    </article>
  `;
}

function cargoDoneKey(group) {
  const primary = group?.primary || {};
  const key = group?.key || primary.awb || primary.id || "shipment";
  return [
    todayActionDismissalDay(),
    "cargo",
    stableTodayActionKeySegment(key),
    stableTodayActionKeySegment(group?.bucket || lifecycleState(primary).id || "shipment"),
  ].filter(Boolean).join(":");
}

function openCargoCard(cargoCard) {
  state.selectedVisualGroupKey = cargoCard.dataset.groupSize === "1" ? null : cargoCard.dataset.visualGroup;
  state.selectedId = cargoCard.dataset.groupSize === "1" ? cargoCard.dataset.primaryId : null;
  state.selectedGroupId = null;
  state.detailOpen = true;
  renderList();
  renderDetail();
}

function bindCargoCardEvents() {
  $("shipmentList").querySelectorAll("[data-dismiss-today-action]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      dismissTodayAction(button.dataset.dismissTodayAction);
    });
  });
  $("shipmentList").querySelectorAll(".today-action-card[data-today-shipment-id]").forEach((card) => {
    card.addEventListener("click", (event) => {
      const target = event.target;
      if (
        target instanceof Element &&
        target.closest("[data-dismiss-today-action], [data-open-today-done], [data-cancel-today-done], [data-confirm-today-done], .today-done-modal")
      ) {
        return;
      }
      if (Date.now() < state.suppressTodayClickUntil) return;
      state.selectedId = card.dataset.todayShipmentId;
      state.selectedGroupId = null;
      state.selectedVisualGroupKey = null;
      state.detailOpen = true;
      renderList();
      renderDetail();
    });
  });
  $("shipmentList").querySelectorAll(".cargo-card[data-visual-group]").forEach((card) => {
    card.addEventListener("click", (event) => {
      event.stopPropagation();
      if (Date.now() < state.suppressTodayClickUntil) return;
      openCargoCard(card);
    });
  });
}

function cardActionLine(shipment, lifecycle, customs, dispatch) {
  const opsText = [
    shipment.opsState?.phase,
    shipment.opsState?.label,
    shipment.opsState?.summary,
    shipment.opsState?.nextAction,
    shipment.currentState,
  ].filter(Boolean).join(" ").toLowerCase();
  if (isHandled(shipment) || ["completed", "delivered"].includes(shipment.opsState?.phase)) return "";
  if (operationalException(shipment)) return "Resolve exception";
  if (/customs[-\s]?hold|release hold/.test(opsText) || /hold/i.test([shipment.customsBroker?.status, shipment.opsState?.label, customs.label].filter(Boolean).join(" "))) {
    return "Release hold";
  }
  if (/cargo[-\s]?not[-\s]?found|pickup[-\s]?blocked|loading[-\s]?blocked/.test(opsText)) return "Resolve pickup blocker";
  if (storageRiskForShipment(shipment)) return "Storage risk";
  if (shipment.opsState?.phase === "linehaul") return "Confirm destination";
  if (shipmentOutForDeliveryToday(shipment) || /out[-\s]?for[-\s]?delivery|delivered[-\s]?pod[-\s]?pending|pod[-\s]?needed/.test(opsText)) return "Track delivery";
  if (freightPickedUpFromAirport(shipment)) {
    return /\bdetention\b/i.test(freightEvidenceText(shipment)) && freightNeedsPodOrDetentionFollowup(shipment)
      ? "Get POD and detention"
      : "Get POD";
  }
  if (freightDriverWaitingForLoad(shipment)) return "Track loading";
  if (freightLoadedForDelivery(shipment)) return "Track delivery";
  if (shipment.opsState?.phase === "prearrival-quotes") return "Prepare quotes";
  if (shipment.arrivalStatus !== "arrived" && recommendedQuoteForShipment(shipment)) return "Review quote plan";
  if (recommendedQuoteForShipment(shipment) && shipment.freightBroker?.status === "freight-requested") {
    return "Award best quote";
  }
  if (shipment.emailValidation?.status === "email-conflict") return "Resolve conflict";
  if (journeyStage(shipment) === "late") return "Confirm arrival";
  if (lifecycle.id === "customs") {
    return customs.label === "Unknown" ? "Find release" : "Clear customs";
  }
  if (lifecycle.id === "ready") {
    if (dispatch.label === "No broker") return "Request pickup quote";
    if (dispatch.label === "Quote asked") return "Compare quotes";
    return brokerFollowUpNeeded(shipment) ? "Follow pickup" : "Confirm pickup";
  }
  if (lifecycle.id === "arrived") return "Confirm station";
  if (lifecycle.id === "transit") return "Track arrival";
  if (lifecycle.id === "origin") return "Watch departure";
  return "";
}

function renderCargoTags(shipment, counts, awbs, customs, dispatch, lifecycle) {
  const tags = [];
  if (lifecycle.id === "origin" || lifecycle.id === "transit") {
    if (isCustomsResolvedStatus(shipment.customsBroker?.status)) tags.push(compactCustomsChip(shipment, customs));
    if (["freight-awarded", "freight-requested"].includes(shipment.freightBroker?.status)) {
      tags.push(compactDispatchChip(shipment, dispatch));
    }
  } else if (lifecycle.id === "customs") {
    tags.push(compactCustomsChip(shipment, customs));
    if (["freight-awarded", "freight-requested"].includes(shipment.freightBroker?.status)) {
      tags.push(compactDispatchChip(shipment, dispatch));
    }
  } else {
    const movementChip = compactMovementChip(shipment, lifecycle);
    if (movementChip) tags.push(movementChip);
    tags.push(compactCustomsChip(shipment, customs));
    tags.push(compactDispatchChip(shipment, dispatch));
  }

  if (counts.total > 1) tags.push(shortText(awbs.join(", "), "AWBs", 38));
  if (!tags.length) return "";
  return `<span class="cargo-tags">${tags.map((tag) => `<i>${tag}</i>`).join("")}</span>`;
}

function compactMovementChip(shipment, lifecycle) {
  if (lifecycle.id !== "ready") return "";
  if (shipment.pickupStatus === "delivered") return "Delivered";
  if (shipment.pickupStatus === "airport-picked-up") return "Picked up";
  if (shipment.arrivalStatus === "arrived" || isAtAirport(shipment)) return "Arrived";
  return "";
}

function canonicalUiGate(shipment, name) {
  return shipment?.opsState?.gates?.[name] || shipment?.canonicalState?.gates?.[name] || {};
}

function canonicalUiGateStatus(shipment, name) {
  return String(canonicalUiGate(shipment, name).status || "").toLowerCase();
}

function canonicalUiGateBroker(shipment, name) {
  const gate = canonicalUiGate(shipment, name);
  return gate.selectedBroker || gate.broker || "";
}

function canonicalUiGateEvidence(shipment, name) {
  const gate = canonicalUiGate(shipment, name);
  return [gate.evidence, gate.summary, gate.reason].filter(Boolean).join(" ");
}

function compactCustomsChip(shipment, customs) {
  const gateStatus = canonicalUiGateStatus(shipment, "customs");
  const gateBroker = canonicalUiGateBroker(shipment, "customs");
  if (["done", "released", "cleared"].includes(gateStatus)) {
    const evidence = canonicalUiGateEvidence(shipment, "customs");
    const prefix = /d\.?o|delivery order|release\/?do|release\/?d\/?o/i.test(evidence)
      ? "Release+DO"
      : "Released";
    return gateBroker ? `${prefix} · ${shortText(gateBroker, "Broker", 20)}` : prefix;
  }
  if (["blocked", "customs-hold", "hold", "exam-hold"].includes(gateStatus)) {
    return gateBroker ? `Hold · ${shortText(gateBroker, "Broker", 20)}` : "Customs hold";
  }
  if (["pending", "waiting"].includes(gateStatus)) {
    return gateBroker ? `Customs · ${shortText(gateBroker, "Broker", 20)}` : "Customs pending";
  }
  if (isCustomsResolvedStatus(shipment.customsBroker?.status)) {
    const prefix = customs.label === "Release + DO" ? "Release+DO" : customs.label === "Released" ? "Released" : "Clear";
    return shipment.customsBroker?.broker && shipment.customsBroker.broker !== "Not found"
      ? `${prefix} · ${shortText(shipment.customsBroker.broker, "Broker", 20)}`
      : prefix;
  }
  if (customs.label === "Unknown") return "Customs unknown";
  return `Customs ${customs.label.toLowerCase()}`;
}

function compactDispatchChip(shipment, dispatch) {
  const storageRisk = storageRiskForShipment(shipment);
  if (storageRisk) return storageRisk.chip;
  const gateStatus = canonicalUiGateStatus(shipment, "dispatch");
  const gateBroker = canonicalUiGateBroker(shipment, "dispatch");
  const gate = canonicalUiGate(shipment, "dispatch");
  if (["done", "broker-awarded", "dispatched"].includes(gateStatus)) {
    const rate = gate.amount ? ` · ${gate.amount}` : "";
    return gateBroker ? `${shortText(gateBroker, "Broker", 18)}${rate}` : "Assigned";
  }
  if (["sent", "broker-alerted"].includes(gateStatus)) {
    return gateBroker ? `${shortText(gateBroker, "Broker", 18)} · alerted` : "Broker alerted";
  }
  const quote = recommendedQuoteForShipment(shipment);
  if (quote && shipment.freightBroker?.status === "freight-requested") {
    return `${quote.broker} · ${quoteAmountLabel(quote)}`;
  }
  if (shipment.freightBroker?.status === "freight-awarded") {
    const broker = shipment.freightBroker.broker && shipment.freightBroker.broker !== "Not found"
      ? shortText(shipment.freightBroker.broker, "Broker", 18)
      : "Assigned";
    const rate = shipment.freightBroker.rate && shipment.freightBroker.rate !== "Not found"
      ? ` · ${shipment.freightBroker.rate}`
      : "";
    return `${broker}${rate}`;
  }
  if (dispatch.label === "No broker") return "Need broker";
  if (dispatch.label === "Quote asked") return "Quote asked";
  return dispatch.label;
}

function categorySortScore(group) {
  const bucketScore = {
    ready: 0,
    customs: 10,
    arrived: 20,
    transit: 30,
    origin: 40,
  }[group.bucket] ?? 60;
  return bucketScore;
}

function operatorMorningSortScore(shipment) {
  if (storageRiskForShipment(shipment)) return 0;
  if (operationalException(shipment)) return 1;
  if (lifecycleState(shipment).id === "ready") {
    const dispatch = dispatchStage(shipment);
    if (dispatch.label === "No broker") return 2;
    if (dispatch.label === "Quote asked") return 3;
  }
  if (currentPlanScheduledLater(shipment) || hasFutureScheduledPickupOrDelivery(shipment)) return 40;
  if (freightDriverWaitingForLoad(shipment)) return 2;
  if (freightPickedUpFromAirport(shipment)) return 3;
  if (shipment.pickupStatus === "delivered" && !isHandled(shipment)) return 4;
  if (isAtAirport(shipment) && isCustomsResolvedStatus(shipment.customsBroker?.status) && dispatchNeedsWork(shipment)) return 5;
  if (isAtAirport(shipment) && isCustomsResolvedStatus(shipment.customsBroker?.status)) return 6;
  if (isAtAirport(shipment) && customsNeedsWork(shipment)) return 20;
  if (draftActionsForShipment(shipment).length) return 30;
  return 50;
}

function shipmentUrgencyScore(shipment) {
  if (isProblem(shipment)) return 0;
  const drafts = draftActionsForShipment(shipment);
  if (drafts.some((action) => action.priority === "high")) return 1;
  if (isActionNeeded(shipment)) return 2;
  if (drafts.length) return 3;
  return 4;
}

function draftSortScore(group) {
  const drafts = draftActionsForShipment(group.primary);
  const high = drafts.filter((action) => action.priority === "high").length;
  return {
    high,
    total: drafts.length,
    tms: drafts.some(isTmsAction) ? 1 : 0,
  };
}

function compareCargoGroups(a, b) {
  const bucketScore = categorySortScore(a) - categorySortScore(b);
  if (bucketScore) return bucketScore;

  const morningScore = operatorMorningSortScore(a.primary) - operatorMorningSortScore(b.primary);
  if (morningScore) return morningScore;

  const urgencyScore = shipmentUrgencyScore(a.primary) - shipmentUrgencyScore(b.primary);
  if (urgencyScore) return urgencyScore;

  const aDrafts = draftSortScore(a);
  const bDrafts = draftSortScore(b);
  const highDraftScore = bDrafts.high - aDrafts.high;
  if (highDraftScore) return highDraftScore;

  const totalDraftScore = bDrafts.total - aDrafts.total;
  if (totalDraftScore) return totalDraftScore;

  const tmsDraftScore = bDrafts.tms - aDrafts.tms;
  if (tmsDraftScore) return tmsDraftScore;

  const stationScore = String(a.station || "").localeCompare(String(b.station || ""), undefined, {
    sensitivity: "base",
  });
  if (stationScore) return stationScore;

  const actionScore = actionLevel(a.primary).localeCompare(actionLevel(b.primary));
  if (actionScore) return actionScore;

  return String(a.primary.awb || "").localeCompare(String(b.primary.awb || ""), undefined, {
    numeric: true,
    sensitivity: "base",
  });
}

function renderLane(lane) {
  return `
    <section class="work-lane" data-lane="${lane.id}">
      <div class="lane-head">
        <div>
          <h2>${lane.title}</h2>
          <p>${lane.hint}</p>
        </div>
        <strong>${lane.rows.length}</strong>
      </div>
      <div class="lane-list">
        ${lane.items.map(renderWorkItem).join("")}
      </div>
    </section>
  `;
}

function renderWorkItem(item) {
  if (item.type === "group") return renderGroupRow(item);
  return renderShipmentRow(item.shipment);
}

function renderGroupRow(item) {
  const group = item.group;
  const isActive = group.groupId === state.selectedGroupId;
  const awbs = item.shipments.map((shipment) => shipment.awb);
  const counts = group.counts || {};
  const arrivedCount = (counts.arrived || 0) + (counts.ready || 0) + (counts.airportPickedUp || 0) + (counts.delivered || 0);
  const headline = group.action || `${arrivedCount}/${counts.total || item.shipments.length} physically arrived`;
  const proof = groupProofLine(group);
  return `
    <button class="shipment-row group-row ${isActive ? "active" : ""}" data-group-id="${group.groupId}" type="button">
      <span class="row-primary">
        <span class="awb-line"><strong>${group.counts?.total || item.shipments.length} AWBs together</strong><em>${group.station || "Station"}</em></span>
        <span class="client-line">${shortText(group.client || group.consignee, "Client unknown", 74)}</span>
        <span class="mini-line">${shortText(awbs.join(", "), "AWBs", 86)}</span>
      </span>
      <span class="row-decision">
        <strong>${shortText(headline, "Review group", 92)}</strong>
        <span>${shortText(group.deliveryAddress || group.eta, "Destination or ETA unknown", 104)}</span>
      </span>
      <span class="row-proof">
        <span class="status-line">
          ${stagePill({ label: groupStatusLine(group), color: arrivedCount ? "green" : "blue" })}
          ${pill(groupCustomsStatus(group))}
        </span>
        <span class="mini-grid">
          <span><b>Customs</b>${groupCustomsLine(group)}</span>
          <span><b>Dispatch</b>${groupFreightLine(group)}</span>
          <span><b>Proof</b>${proof}</span>
        </span>
      </span>
    </button>
  `;
}

function renderShipmentRow(shipment) {
  const movement = movementStage(shipment);
  const customs = customsStage(shipment);
  const dispatch = dispatchStage(shipment);
  const proof = proofStage(shipment);
  const ops = opsState(shipment);
  return `
    <button class="shipment-row ${shipment.id === state.selectedId ? "active" : ""}" data-id="${shipment.id}" type="button">
      <span class="row-primary">
        <span class="awb-line"><strong>${shipment.awb}</strong><em>${shipment.station || "N/A"}</em></span>
        <span class="client-line">${shipment.client || "Client unknown"}</span>
        <span class="mini-line">${destinationLine(shipment)}</span>
      </span>
      <span class="row-decision">
        <strong>${shortText(ops.summary || shipmentHeadline(shipment), "Review shipment", 96)}</strong>
        <span>Next: ${shortText(ops.nextAction || nextStep(shipment), "Review shipment", 112)}</span>
      </span>
      <span class="row-proof">
        <span class="status-line">
          ${stagePill(movement)}
          ${stagePill(customs)}
          ${stagePill(dispatch)}
          ${stagePill(proof)}
        </span>
        <span class="mini-grid">
          <span><b>Tracking</b>${shortText(movement.note, "Unknown", 64)}</span>
          <span><b>Customs</b>${shortText(customs.note, "Unknown", 64)}</span>
          <span><b>Freight</b>${shortText(dispatch.note, "Unknown", 64)}</span>
        </span>
      </span>
    </button>
  `;
}

function renderTruthList(rows) {
  return `
    <div class="truth-list">
      ${rows
        .filter((row) => row.value || row.note)
        .map(
          (row) => `
            <div class="truth-row">
              <span>${row.label}</span>
              <strong>${shortText(row.value, "Unknown", 78)}</strong>
              ${row.note ? `<small>${shortText(row.note, "", 112)}</small>` : ""}
            </div>
          `,
        )
        .join("")}
    </div>
  `;
}

function renderProofList(evidence) {
  const rows = evidence.filter((item) => item?.note).slice(0, 3);
  if (!rows.length) return "";
  return `
    <section class="section">
      <h3>Proof</h3>
      <div class="proof-list">
        ${rows
          .map(
            (item) => `
              <div>
                <span>${item.label || item.source || "Evidence"}</span>
                <strong>${shortText(item.note, "Unknown", 118)}</strong>
              </div>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function renderOperatorBrief(shipment, { movement, customs, dispatch, statusLabel, heroTitle, heroNextStep }) {
  const groundFees = groundFeesStage(shipment);
  const pickup = pickupBriefStage(shipment);
  const execution = executionBriefForShipment(shipment);

  return `
    <section class="detail-brief">
      <div class="brief-kicker">
        <span class="${actionClass(shipment)}">${statusLabel}</span>
        <em>${[operationalStation(shipment), shipment.airline].filter(Boolean).join(" · ") || "Station unknown"}</em>
      </div>
      <h3>${heroTitle}</h3>
      ${detailHeroNote(heroTitle, heroNextStep)}
      ${renderExecutionBrief(execution)}
      <div class="brief-grid">
        ${renderBriefCell("Tracking", movement.label, movement.note, movement.color)}
        ${renderBriefCell("Customs", customs.label, customs.note, customs.color)}
        ${renderBriefCell("Ground fees", groundFees.label, groundFees.note, groundFees.color)}
        ${renderBriefCell("Pickup", pickup.label, pickup.note, pickup.color)}
      </div>
    </section>
  `;
}

function renderExecutionBrief(execution) {
  if (!execution?.facts?.length && !execution?.recommendation) return "";
  return `
    <div class="execution-brief">
      <span>Execution brief</span>
      ${execution.facts?.length ? `<p>${escapeHtml(shortText(execution.facts.join(". "), "", 210))}</p>` : ""}
      ${execution.recommendation ? `<strong>${escapeHtml(shortText(execution.recommendation, "", 112))}</strong>` : ""}
    </div>
  `;
}

function renderBriefCell(label, value, note, color = "gray") {
  return `
    <div class="brief-cell ${color}">
      <span>${label}</span>
      <strong>${shortText(value, "Unknown", 34)}</strong>
      ${note ? `<small>${shortText(note, "", 72)}</small>` : ""}
    </div>
  `;
}

function contactDisplay(parts, fallback = "Not confirmed") {
  const values = parts.filter(isUsableContact);
  return values.length ? values.join(" · ") : fallback;
}

function stationContactMissingAction(shipment) {
  return actionsForShipment(shipment).find((action) => action.type === "station-confirmation" && action.stationContactMissing);
}

function stationMemoryNote(shipment) {
  const action = stationContactMissingAction(shipment);
  if (action) return action.originalTargetEmail ? "Needs memory" : "Memory gap";

  const context = shipment.stationContext || {};
  const confidence = context.contactConfidence || context.confidence || "";
  if (context.contactSource || context.source || context.rememberedAt || confidence) {
    return ["Memory", confidence].filter(Boolean).join(" · ");
  }
  if (context.stations?.length) return "Memory gap";
  return "";
}

function stationContactDisplay(shipment) {
  if (operationalException(shipment)) {
    return contactDisplay([shipment.freightBroker?.contactEmail, shipment.freightBroker?.contactPhone]);
  }
  const action = stationContactMissingAction(shipment);
  if (action?.originalTargetEmail) return "Not confirmed";
  return contactDisplay([shipment.stationEmail, shipment.stationPhone]);
}

function renderContactDeck(shipment) {
  const stationContact = stationContactDisplay(shipment);
  const stationOwner = operationalStationOwner(shipment);
  const customsContact = formatCustomsContact(shipment.customsBroker);
  const freightContact = formatFreightContact(shipment.freightBroker);
  const clientAddress = cleanAddress(shipment.delivery?.fullAddress || destinationLine(shipment), shipment.client);

  return `
    <div class="contact-deck">
      ${renderContactCard("Station", stationOwner, stationContact, stationMemoryNote(shipment))}
      ${renderContactCard("Customs", customsLine(shipment), customsContact)}
      ${renderContactCard("Pickup", brokerLine(shipment), freightContact)}
      ${renderContactCard("Client", shipment.client || "Unknown", clientAddress)}
    </div>
    ${renderStationMemoryEditor(shipment, stationOwner)}
  `;
}

function stationMemoryPendingConfirmed(shipment, pending = {}) {
  const savedEmail = String(pending.stationEmail || "").trim().toLowerCase();
  const savedPhone = String(pending.stationPhone || "").trim();
  const rowEmail = String(shipment.stationEmail || "").trim().toLowerCase();
  const rowPhone = String(shipment.stationPhone || "").trim();
  return Boolean((savedEmail && savedEmail === rowEmail) || (savedPhone && savedPhone === rowPhone));
}

function renderStationMemoryEditor(shipment, stationOwner, options = {}) {
  const saving = state.savingStationMemory.has(shipment.id);
  let status = state.stationMemoryStatusById[shipment.id] || null;
  // A save is only truly done when the shipment row itself carries the taught
  // contact (packet rebuild applied it); until then keep the typed fields.
  if (status?.kind === "saved" && stationMemoryPendingConfirmed(shipment, state.pendingStationMemoryEntries[shipment.id])) {
    delete state.pendingStationMemoryEntries[shipment.id];
    delete state.stationMemoryStatusById[shipment.id];
    status = null;
  }
  const open = options.open || saving || Boolean(status) || state.expandedStationMemoryEditors.has(shipment.id);
  const storage = shipment.operationalMemory?.storage || shipment.stationContext?.storage || {};
  const pending = state.pendingStationMemoryEntries[shipment.id] || {};
  const pendingStorage = pending.storage || {};
  const stationEmail = pending.stationEmail ?? (isUsableContact(shipment.stationEmail) ? shipment.stationEmail : "");
  const stationPhone = pending.stationPhone ?? (isUsableContact(shipment.stationPhone) ? shipment.stationPhone : "");
  const handlerName = pending.handlerName ?? stationOwner ?? "";
  const source = pending.source ?? shipment.stationContext?.contactSource ?? shipment.stationContext?.source ?? "Operator saved from PQ dashboard";
  const freeStorage = pendingStorage.freeStorage ?? storage.freeStorage ?? storage.freeStorageHours ?? "";
  const confidence = pending.confidence ?? shipment.stationContext?.contactConfidence ?? shipment.stationContext?.confidence ?? "medium";
  return `
    <details class="memory-editor" data-station-memory-editor="${shipment.id}" ${open ? "open" : ""}>
      <summary>
        <span>Teach station</span>
        <strong>${shortText([operationalStation(shipment), shipment.airline].filter(Boolean).join(" · "), "Station memory", 42)}</strong>
      </summary>
      <form ${options.formId ? `id="${escapeHtml(options.formId)}"` : ""} data-station-memory-form="${shipment.id}">
        <label>
          Handler
          <input name="handlerName" value="${escapeHtml(handlerName)}" autocomplete="off">
        </label>
        <label>
          Email
          <input name="stationEmail" value="${escapeHtml(stationEmail)}" inputmode="email" autocomplete="off">
        </label>
        <label>
          Phone
          <input name="stationPhone" value="${escapeHtml(stationPhone)}" inputmode="tel" autocomplete="off">
        </label>
        <label>
          Free storage
          <input name="freeStorage" value="${escapeHtml(freeStorage)}" autocomplete="off">
        </label>
        <label>
          Source
          <input name="source" value="${escapeHtml(source)}" autocomplete="off">
        </label>
        <div class="memory-editor-actions">
          <select name="confidence" aria-label="Memory confidence">
            ${["high", "medium", "low"].map((value) => `
              <option value="${value}" ${String(confidence) === value ? "selected" : ""}>${value}</option>
            `).join("")}
          </select>
          <button class="mini-button primary" type="submit" ${saving ? "disabled" : ""}>${saving ? "Saving" : "Save"}</button>
        </div>
        ${status ? `<p class="memory-editor-status" data-status-kind="${escapeHtml(status.kind)}">${escapeHtml(status.message || "")}</p>` : ""}
      </form>
    </details>
  `;
}

function renderContactCard(label, title, detail, note = "") {
  return `
    <div class="contact-card">
      <span>${label}${note ? `<em>${shortText(note, "", 28)}</em>` : ""}</span>
      <strong>${shortText(title, "Unknown", 54)}</strong>
      ${detail ? `<small>${shortText(detail, "", 86)}</small>` : ""}
    </div>
  `;
}

function renderEvidenceDeck(evidence) {
  const rows = evidence.filter((item) => item?.note).slice(0, 4);
  if (!rows.length) return "";
  return `
    <section class="section operator-section">
      <h3>Proof</h3>
      <div class="evidence-deck">
        ${rows
          .map(
            (item) => `
              <div>
                <span>${item.label || item.source || "Evidence"}</span>
                <strong>${shortText(item.note, "Unknown", 122)}</strong>
              </div>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function cleanFactText(value) {
  return String(value || "")
    .replace(/\b(?:gmail\s*)?(?:threads?|messages?|msgs?)\s+[a-z0-9_-]{8,}(?:\s*(?:,|\/|and|&)\s*[a-z0-9_-]{8,})*\s*(?:·\s*)?/gi, "")
    .replace(/\b(?:thread|message|msg)\s+[a-z0-9_-]{8,}\s*(?:·\s*)?/gi, "")
    .replace(/\s+·\s+·\s+/g, " · ")
    .replace(/^\s*·\s*|\s*·\s*$/g, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function releaseResolvedForUi(shipment) {
  return (isCustomsResolvedStatus(shipment?.customsBroker?.status || "") || isHandled(shipment)) &&
    !/customs|problem|hold|exception/i.test(String(shipment?.opsState?.phase || ""));
}

function releasePositiveText(value) {
  return /\b(customs\s*rel|release\/?DO confirmed|release or DO confirmed|98\s+released|release attached|attached release|d\.?\/?o\.?\s+(?:received|attached|sent)|delivery order\s+(?:received|attached|sent)|customs[-\s]cleared|customs release\/DO is confirmed)\b/i.test(
    cleanFactText(value),
  );
}

function staleReleaseNegativeText(shipment, value) {
  if (!releaseResolvedForUi(shipment)) return false;
  const text = cleanFactText(value);
  if (!text || releasePositiveText(text)) return false;
  return /\b(no|not found|missing|pending|unclear|needed|waiting|follow|find|confirm)\b.{0,80}\b(release|d\.?\/?o\.?|delivery order|customs proof|customs broker)\b|\b(release|d\.?\/?o\.?|delivery order|customs proof|customs broker)\b.{0,80}\b(no|not found|missing|pending|unclear|needed|waiting|follow|find|confirm)\b|\bpre[-\s]?alert\b.{0,120}\b(no|without|before|pending|follow|waiting)\b.{0,80}\b(release|d\.?\/?o\.?|delivery order)\b/i.test(
    text,
  );
}

function staleReleaseFact(shipment, fact) {
  if (!releaseResolvedForUi(shipment)) return false;
  const text = [
    fact?.type,
    fact?.label,
    fact?.summary,
    fact?.operatorSummary,
    fact?.source,
    fact?.action,
  ].filter(Boolean).join(" ");
  if (releasePositiveText(text)) return false;
  if (staleReleaseNegativeText(shipment, text)) return true;
  return /\b(?:pre[-\s]?alert|routing|departed|audit[-\s]?coverage)\b/i.test(text) &&
    /\b(?:customs|release|d\.?\/?o\.?|delivery order)\b/i.test(text);
}

function factSourceLine(fact) {
  return [
    cleanFactText(fact.source),
    fact.confidence ? `${fact.confidence} confidence` : "",
  ].filter(Boolean).join(" · ");
}

function displayFactLabel(fact) {
  if (fact.type === "handler-payment-dispatch") return "Payment";
  if (isStorageFact(fact)) return "Storage";
  return fact.label || fact.type || "Fact";
}

function paymentHandlerName(fact) {
  const label = cleanFactText(fact.label);
  if (/swissport/i.test(label)) return "EL AL/Swissport BOS";
  if (/wfs/i.test(label)) return label.replace(/\bc\/o\b/i, "/").replace(/\s+/g, " ");
  return label || "station handler";
}

function displayFactSummary(fact) {
  if (fact.operatorSummary) {
    const summary = cleanFactText(fact.operatorSummary);
    if (/\bdrafted (?:draft )?to\b/i.test(summary)) return "Status-check draft";
    return summary;
  }
  if (fact.type === "handler-payment-dispatch") {
    return `CargoSprint to ${paymentHandlerName(fact)}; dispatch after DO/payment.`;
  }
  if (isStorageFact(fact)) return compactStorageFactSummary(fact);
  const summary = cleanFactText(fact.summary);
  if (/\bdrafted (?:draft )?to\b/i.test(summary)) return "Status-check draft";
  return summary;
}

function displayFactSource(fact) {
  if (fact.type === "handler-payment-dispatch") {
    return ["Payment + broker award proof", fact.confidence ? `${fact.confidence} confidence` : ""].filter(Boolean).join(" · ");
  }
  if (isStorageFact(fact)) {
    return ["Storage memory", fact.confidence ? `${fact.confidence} confidence` : ""].filter(Boolean).join(" · ");
  }
  return factSourceLine(fact);
}

function displayFactAction(fact) {
  if (fact.type === "handler-payment-dispatch") {
    return "Confirm payment/DO, then follow broker for recovery and POD.";
  }
  if (isStorageFact(fact)) return "Pickup before storage.";
  return cleanFactText(fact.action);
}

function isStorageFact(fact) {
  const text = `${fact?.type || ""} ${fact?.label || ""} ${fact?.summary || ""} ${fact?.source || ""}`;
  return fact?.type === "storage" || /last free|storage starts?|storage accruing|\$\s*[\d,.]+\s*(?:\/|per )day/i.test(text);
}

function compactStorageDate(value) {
  const text = String(value || "");
  const iso = text.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  const slash = text.match(/\b(\d{1,2})\/(\d{1,2})\/(?:20)?\d{2}\b/);
  const named = text.match(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+(\d{1,2})\b/i);
  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  if (iso) return `${monthNames[Number(iso[2]) - 1] || iso[2]} ${Number(iso[3])}`;
  if (slash) return `${monthNames[Number(slash[1]) - 1] || slash[1]} ${Number(slash[2])}`;
  if (named) {
    const month = monthNames.find((item) => item.toLowerCase() === named[1].slice(0, 3).toLowerCase()) || named[1];
    return `${month} ${Number(named[2])}`;
  }
  return "";
}

function compactStorageRate(value) {
  const text = String(value || "");
  const match = text.match(/\$[\d,.]+(?:\s*(?:\/|per)\s*day|\/day)?/i);
  if (!match) return "";
  return match[0]
    .replace(/\s+/g, "")
    .replace(/perday/i, "/d")
    .replace(/\/day/i, "/d");
}

function storageTextBlob(storage) {
  if (!storage) return "";
  return [
    storage.lastFreeDay,
    storage.storageStartsAt,
    storage.storageAccruingSince,
    storage.dailyStorageRate,
    storage.freeStorage,
    storage.lastFreeDayRule,
    ...(Array.isArray(storage.evidence) ? storage.evidence : []),
  ].filter(Boolean).join(" ");
}

function storageDateFromText(text, pattern) {
  const datePattern = "([0-9]{4}-[0-9]{2}-[0-9]{2}|[0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4}|(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\\.?\\s+[0-9]{1,2})";
  const match = String(text || "").match(new RegExp(`(?:${pattern})[^\\n;,.]{0,40}${datePattern}`, "i"));
  return match ? match[1] : "";
}

function compactStorageFactSummary(fact) {
  const text = cleanFactText(`${fact.summary || ""} ${fact.source || ""}`);
  return compactStorageTextSummary(text) || cleanFactText(fact.summary);
}

function compactStorageTextSummary(text) {
  const cleanText = cleanFactText(text);
  const lastFree = storageDateFromText(text, "last free(?: day)?");
  const lfd = storageDateFromText(text, "\\bLFD\\b");
  const starts = storageDateFromText(text, "storage starts?|storage start date|storage begins|storage from");
  const accruing = storageDateFromText(text, "storage accruing since|storage accrues since");
  const rate = compactStorageRate(text);
  const lfdValue = lastFree || lfd;
  const mainDate = lfdValue
    ? `LFD ${compactStorageDate(lfdValue) || lfdValue}`
    : accruing
      ? `Storage ${compactStorageDate(accruing) || accruing}`
      : starts
        ? `Starts ${compactStorageDate(starts) || starts}`
        : "";
  const parts = [
    mainDate,
    rate,
  ].filter(Boolean);
  if (!parts.length && /storage|last free|free day|lfd/i.test(cleanText)) {
    return "";
  }
  return parts.length ? parts.join(" · ") : "";
}

function hasStorageMemoryValue(storage) {
  if (!storage || typeof storage !== "object" || storage.status !== "known") return false;
  return [
    storage.freeStorage,
    storage.freeStorageHours,
    storage.lastFreeDayRule,
    storage.lastFreeDay,
    storage.storageStartsAt,
    storage.storageAccruingSince,
    storage.dailyStorageRate,
  ].some((value) => String(value || "").trim());
}

function storageMemoryForShipment(shipment) {
  const shipmentMemory = shipment.operationalMemory?.storage;
  if (hasStorageMemoryValue(shipmentMemory)) return shipmentMemory;
  const stationMemory = shipment.stationContext?.storage;
  if (hasStorageMemoryValue(stationMemory)) return stationMemory;
  return null;
}

function storageDetailParts(storage) {
  if (!storage) return [];
  const text = storageTextBlob(storage);
  const lastFreeValue = storage.lastFreeDay || storageDateFromText(text, "last free(?: day)?");
  const startsValue = storage.storageStartsAt || storageDateFromText(text, "storage starts?|storage start date");
  const accruingValue = storage.storageAccruingSince || storageDateFromText(text, "storage accruing since|storage accrues since");
  const lastFreeDay = lastFreeValue ? `LFD ${compactStorageDate(lastFreeValue) || lastFreeValue}` : "";
  const accruing = accruingValue
    ? `Storage ${compactStorageDate(accruingValue) || accruingValue}`
    : "";
  const starts = startsValue ? `Starts ${compactStorageDate(startsValue) || startsValue}` : "";
  const rate = compactStorageRate(storage.dailyStorageRate) || compactStorageRate(text);
  const freeStorage = !lastFreeDay && !accruing && !starts
    ? storage.freeStorage || (storage.freeStorageHours ? `${storage.freeStorageHours}h free` : "")
    : "";
  return [
    lastFreeDay || accruing || starts,
    rate,
    freeStorage,
  ].filter(Boolean).map((part) => cleanFactText(part));
}

function storageHasShipmentDate(storage) {
  if (!storage) return false;
  const text = storageTextBlob(storage);
  return Boolean(
    storage.lastFreeDay ||
      storage.storageStartsAt ||
      storage.storageAccruingSince ||
      storageDateFromText(text, "last free(?: day)?") ||
      storageDateFromText(text, "storage starts?|storage start date") ||
      storageDateFromText(text, "storage accruing since|storage accrues since"),
  );
}

function storageFactForShipment(shipment) {
  return (Array.isArray(shipment.factLedger) ? shipment.factLedger : []).find((fact) => isStorageFact(fact));
}

function storageEvidenceTextForShipment(shipment) {
  const proofNotes = shipment.emailValidation?.proof || [];
  const exception = operationalException(shipment);
  return [
    storageTextBlob(shipment.storage),
    storageTextBlob(shipment.operationalMemory?.storage),
    storageTextBlob(shipment.stationContext?.storage),
    ...(Array.isArray(shipment.money?.evidence) ? shipment.money.evidence : []),
    ...(Array.isArray(shipment.facts) ? shipment.facts : []).map((fact) => `${fact.label || ""} ${fact.summary || ""} ${fact.source || ""}`),
    ...(Array.isArray(shipment.factLedger) ? shipment.factLedger : []).map((fact) => `${fact.label || ""} ${fact.summary || ""} ${fact.source || ""}`),
    ...(Array.isArray(proofNotes) ? proofNotes : []).map((proof) => `${proof.label || ""} ${proof.note || ""} ${proof.filename || ""}`),
    shipment.lastEmail?.summary,
    exception?.summary,
    exception?.nextAction,
  ].filter(Boolean).join(" ");
}

function shipmentHasStorageSignal(shipment) {
  const storageEvidence = Array.isArray(shipment.operationalMemory?.storage?.evidence)
    ? shipment.operationalMemory.storage.evidence.join(" ")
    : "";
  const exception = operationalException(shipment);
  const exceptionText = [
    exception?.summary,
    exception?.nextAction,
    ...(Array.isArray(exception?.blockers) ? exception.blockers : []),
  ].filter(Boolean).join(" ");
  return /storage|last free|lfd|demurrage/i.test(`${storageEvidence} ${exceptionText}`);
}

function stationStorageInfo(shipment) {
  const risk = storageRiskForShipment(shipment);
  if (risk) {
    const detail = cleanFactText(risk.detail);
    if (!detail) return null;
    return {
      detail,
      color: "red",
    };
  }

  const memory = storageMemoryForShipment(shipment);
  if (memory) {
    if (!storageHasShipmentDate(memory)) return null;
    const detail = storageDetailParts(memory).join(" · ");
    if (!detail) return null;
    return {
      detail,
      color: isAtAirport(shipment) ? "amber" : "gray",
    };
  }

  const fact = storageFactForShipment(shipment);
  if (fact) {
    const detail = compactStorageFactSummary(fact);
    if (!detail) return null;
    return {
      detail,
      color: isAtAirport(shipment) ? "amber" : "gray",
    };
  }

  return null;
}

function isOperatorActionFact(fact) {
  const text = `${fact?.type || ""} ${fact?.label || ""} ${fact?.summary || ""} ${fact?.source || ""}`;
  return fact?.type === "action" ||
    /pod check|request pod|drafted to|dashboard outbox|tms review inbox|tms experience inbox/i.test(text);
}

function fallbackFactLedger(evidence) {
  return evidence
    .filter((item) => item?.note)
    .slice(0, 5)
    .map((item, index) => ({
      id: `fallback-${index}`,
      type: "proof",
      label: item.label || item.source || "Proof",
      summary: item.note,
      source: item.source || "",
      confidence: "medium",
    }));
}

function isInternalTmsReviewFact(fact) {
  return /tms[-\s]?(pod|closeout|review)|pod check|request pod|TMS review inbox|TMS experience inbox/i.test(
    `${fact?.type || ""} ${fact?.label || ""} ${fact?.summary || ""} ${fact?.source || ""}`,
  );
}

function visibleFactLedgerFacts(facts, shipment = null) {
  let storageShown = false;
  const visible = [];
  const indexByKey = new Map();
  for (const fact of facts) {
    if (isOperatorActionFact(fact)) continue;
    if (isInternalTmsReviewFact(fact)) continue;
    if (staleReleaseFact(shipment, fact)) continue;
    if (isStorageFact(fact)) {
      if (!compactStorageFactSummary(fact)) continue;
      if (storageShown) continue;
      storageShown = true;
    }
    const key = cleanFactText(displayFactLabel(fact)).toLowerCase();
    if (!key) {
      visible.push(fact);
      continue;
    }
    const existingIndex = indexByKey.get(key);
    if (existingIndex === undefined) {
      indexByKey.set(key, visible.length);
      visible.push(fact);
      continue;
    }
    const existing = visible[existingIndex];
    if (!releasePositiveText(`${existing.summary || ""} ${existing.action || ""}`) &&
      releasePositiveText(`${fact.summary || ""} ${fact.action || ""}`)) {
      visible[existingIndex] = fact;
    }
  }
  return visible;
}

function renderFactLedgerSection(shipment, evidence) {
  const facts = (Array.isArray(shipment.factLedger) && shipment.factLedger.length
    ? shipment.factLedger
    : fallbackFactLedger(evidence)
  );
  const visibleFacts = visibleFactLedgerFacts(facts, shipment).slice(0, 8);
  if (!visibleFacts.length) return "";

  return `
    <section class="section operator-section">
      <h3>What it knows</h3>
      <div class="fact-ledger">
        ${visibleFacts
          .map((fact) => {
            const source = displayFactSource(fact);
            return `
              <div class="fact-row ${fact.type || "proof"}">
                <span>${shortText(displayFactLabel(fact), "Fact", 28)}</span>
                <strong>${shortText(displayFactSummary(fact), "No summary", 132)}</strong>
                ${source ? `<small>${shortText(source, "", 112)}</small>` : ""}
              </div>
            `;
          })
          .join("")}
      </div>
    </section>
  `;
}

function timelineLabelForFact(fact) {
  const type = String(fact?.type || "").toLowerCase();
  const text = `${fact?.label || ""} ${fact?.summary || ""} ${fact?.action || ""}`;
  if (type === "customs" && releasePositiveText(text)) return "Released";
  if (type === "tms") return "TMS";
  if (type === "tracking") return "Tracking";
  if (type === "exception") return shortText(displayFactLabel(fact), "Exception", 18);
  if (type === "email") return "Email";
  if (type === "customs") return "Customs";
  if (type === "broker" || type === "quote") return "Pickup";
  if (type === "storage") return "Storage";
  if (type === "pod") return "POD";
  return shortText(displayFactLabel(fact), "Fact", 18);
}

function timelineLabelForAction(event) {
  if (event.type === "quote-request") return "Quote";
  if (event.type === "quote-followup") return "Follow-up";
  if (event.type === "station-confirmation") return "Station";
  if (event.type === "customs-followup") return "Customs";
  if (event.type === "pod-followup") return "POD";
  if (event.type === "broker-award") return "Award";
  return "Action";
}

function timelineKindClass(value) {
  const type = String(value || "").toLowerCase();
  if (/storage|hold|failed|problem|customs|exception|detention/.test(type)) return "watch";
  if (/quote|broker|award|pickup|pod/.test(type)) return "action";
  if (/tracking|tms|email|proof|station/.test(type)) return "proof";
  return "neutral";
}

function isStaleQuoteHistoryFact(shipment, fact) {
  if (shipment.freightBroker?.quoteDecision?.status !== "stale-operational-exception") return false;
  const text = `${fact?.type || ""} ${fact?.label || ""} ${fact?.summary || ""} ${fact?.action || ""}`;
  return /\bquote\b|\$\s*\d|compare quote|award(?:ing)? broker/i.test(text);
}

function isStaleCustomsPendingFact(shipment, fact) {
  if (!isCustomsResolvedStatus(shipment.customsBroker?.status || "")) return false;
  const text = `${fact?.type || ""} ${fact?.label || ""} ${fact?.summary || ""} ${fact?.action || ""}`;
  return /\bcustoms\b/i.test(text) &&
    /\b(no|not|without|missing|pending|requested|awaiting|waiting)\b.{0,80}\b(release|clearance|d\.?\/?o\.?|delivery order)\b|\b(release|clearance|d\.?\/?o\.?|delivery order)\b.{0,80}\b(no|not|without|missing|pending|requested|awaiting|waiting)\b/i.test(text) &&
    !releasePositiveText(text);
}

function timelineActionStatusClass(event) {
  const status = draftDisplayStatus(event, event.status || "");
  if (status === "failed") return "problem";
  if (["queued", "running", "waiting_external"].includes(status)) return "watch";
  if (status === "drafted" || status === "sent") return "done";
  return "neutral";
}

function compactTimelineText(value, event = {}) {
  const text = cleanFactText(value)
    .replace(/release\/DO/gi, "release or DO")
    .replace(/POD\/delivery/gi, "POD or delivery")
    .replace(/\s+\/\s+/g, " and ");
  if (!text) return "";

  if (/storage/i.test(`${event.label || ""} ${text}`)) {
    const compact = compactStorageFactSummary({ summary: text });
    if (compact && compact.length < text.length) return compact;
    return "";
  }
  if (/picked up|recovered/i.test(text) && /detention/i.test(text)) return "Picked up; detention pending";
  if (/driver.*(?:onsite|on site)|still onsite/i.test(text)) return "Driver onsite; loading pending";
  if (/open truck|flatbed/i.test(text)) return "Open truck required";
  if (/cannot purchase insurance/i.test(text)) return "Artwork insurance not covered";
  if (/insurance/i.test(text) && /artwork|limit|100k|100,000/i.test(text)) return "Insurance limit needs review";
  if (/terminat(?:e|ed|ing).*jfk|jfk.*terminat|rct|routing/i.test(text)) return "JFK routing change confirmed";
  if (/customs release|release or DO|delivery order/i.test(text) && /pending|missing|not proven|no /i.test(text)) {
    return "Release or DO pending";
  }
  if (/ace .*\.pdf|customs release attachment|customs-release-attachment-received/i.test(text)) {
    return "Release file received";
  }
  if (/customs\/tms now shows release|customs release\/do is confirmed|customs release or do is confirmed/i.test(text)) {
    return "Released; continue pickup";
  }
  if (/^human already emailed/i.test(text)) return "Human already emailed";
  if (/\bdrafted (?:draft )?to\b/i.test(text)) return "Status-check draft";
  if (/ai draft expired/i.test(text)) return "Draft expired";
  if (/drafted draft/i.test(text)) return text.replace(/Drafted draft/i, "Drafted");
  return text;
}

function compactTimelineDetail(value, title) {
  const detail = compactTimelineText(value);
  if (!detail) return "";
  if (/^(human already emailed|draft expired)$/i.test(title)) return "";
  if (/^storage/i.test(title) && /storage/i.test(detail)) return "";
  if (/^status-check draft$/i.test(title)) return cleanFactText(detail.split("·")[0]);
  if (/^(?:gmail|email)(?:\s·\s(?:gmail|email))*\s*(?:·\s*(?:high|medium|low) confidence)?$/i.test(detail)) return "";
  if (/^(gmail|dashboard outbox|storage memory|couriercloud|parsed-text|el al tracking)(?:\s·\s\w+ confidence)?$/i.test(detail)) return "";
  if (title && detail.toLowerCase() === title.toLowerCase()) return "";
  if (/^compare quote before awarding broker\.?$/i.test(detail)) return "";
  return detail;
}

function timelineProofForFact(fact) {
  const rawSummary = cleanFactText(fact.operatorSummary || fact.summary);
  const source = cleanFactText(fact.source);
  const action = cleanFactText(fact.action);
  const sourceLine = displayFactSource(fact);
  const evidenceLabel = /gmail|email/i.test(`${fact?.source || ""} ${sourceLine}`) ? "Email" : "Proof";
  const parts = [
    rawSummary,
    source && !sourceLine.includes(source) ? source : "",
    action && action !== rawSummary ? action : "",
    sourceLine && !/^(gmail|storage memory|dashboard outbox)(?:\s·\s\w+ confidence)?$/i.test(sourceLine) ? sourceLine : "",
  ].filter(Boolean);
  return parts.length ? `${evidenceLabel}: ${parts.join(" · ")}` : "";
}

function timelineProofForAction(event, target) {
  const detail = cleanFactText(draftHistoryDetail(event, target, event.at));
  const subject = cleanFactText(event.subject || event.reason || event.summary);
  const pieces = [subject, detail].filter(Boolean);
  return pieces.length ? `Action: ${pieces.join(" · ")}` : "";
}

function compactTimelineProof(value) {
  return cleanFactText(value)
    .replace(/\s+\/\s+/g, " and ")
    .replace(/\bGmail(?:\s·\sGmail)+\b/gi, "Gmail")
    .replace(/\s·\sGmail\s·\s(?:high|medium|low) confidence$/i, "")
    .replace(/\b(?:gmail\s*)?(?:threads?|messages?|msgs?)\s+[a-z0-9_-]{8,}(?:\s*(?:,|\/|and|&)\s*[a-z0-9_-]{8,})*\b/gi, "")
    .replace(/\bthread\s+[a-z0-9_-]{8,}\b/gi, "")
    .replace(/\bmessage\s+[a-z0-9_-]{8,}\b/gi, "")
    .replace(/\bmsg\s+[a-z0-9_-]{8,}\b/gi, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function timelineEventsForShipment(shipment, evidence) {
  const facts = (Array.isArray(shipment.factLedger) && shipment.factLedger.length
    ? shipment.factLedger
    : fallbackFactLedger(evidence)
  );
  const factEvents = visibleFactLedgerFacts(facts, shipment)
    .filter((fact) => !isStaleQuoteHistoryFact(shipment, fact))
    .filter((fact) => !isStaleCustomsPendingFact(shipment, fact))
    .map((fact, index) => ({
    id: `${shipment.id}:fact:${fact.id || index}`,
    sourceOrder: index,
    at: fact.at || "",
    label: timelineLabelForFact(fact),
    title: displayFactSummary(fact),
    detail: displayFactAction(fact) || displayFactSource(fact),
    proof: timelineProofForFact(fact),
    kind: timelineKindClass(fact.type || fact.label),
  }));
  const storageInfo = stationStorageInfo(shipment);
  const hasStorageEvent = factEvents.some((event) => event.label === "Storage");
  if (storageInfo && !hasStorageEvent) {
    factEvents.push({
      id: `${shipment.id}:fact:station-storage`,
      sourceOrder: factEvents.length,
      at: "",
      label: "Storage",
      title: storageInfo.detail,
      detail: "",
      proof: storageInfo.detail,
      kind: storageInfo.color === "red" || storageInfo.color === "amber" ? "watch" : "neutral",
    });
  }

  if (isCustomsResolvedStatus(shipment.customsBroker?.status || "")) {
    const releaseEvidence = (shipment.customsBroker?.evidence || []).find((item) =>
      releasePositiveText(`${item?.label || ""} ${item?.note || ""} ${item?.filename || ""} ${item?.attachment || ""}`),
    );
    const releaseProof = releaseEvidence
      ? [
          releaseEvidence.note,
          releaseEvidence.filename || releaseEvidence.attachment,
          releaseEvidence.threadId ? `thread ${releaseEvidence.threadId}` : "",
        ].filter(Boolean).join(" · ")
      : shipment.customsBroker?.nextAction || "Customs release is confirmed.";
    const hasReleaseEvent = factEvents.some((event) =>
      event.label === "Released" || /released|cleared|release file received/i.test(`${event.title} ${event.detail}`),
    );
    if (!hasReleaseEvent) {
      factEvents.unshift({
        id: `${shipment.id}:fact:customs-release-current`,
        sourceOrder: -1,
        at: "",
        label: "Released",
        title: "Customs released",
        detail: shipment.customsBroker?.broker || "",
        proof: `Proof: ${releaseProof}`,
        kind: "done",
      });
    }
  }

  const actionEvents = draftHistoryEvents(shipment).map((event, index) => {
    const target = event.targetName || event.targetEmail || "recipient";
    return {
      id: `${shipment.id}:action:${event.id || event.actionId || index}`,
      sourceOrder: factEvents.length + index,
      at: event.at || "",
      label: timelineLabelForAction(event),
      title: event.summary || event.label || "Action",
      detail: draftHistoryDetail(event, target, event.at),
      proof: timelineProofForAction(event, target),
      kind: timelineActionStatusClass(event),
    };
  });

  const byKey = new Map();
  for (const event of [...factEvents, ...actionEvents]) {
    const title = cleanFactText(event.title);
    if (!title) continue;
    const key = `${event.label}:${title}`.toLowerCase();
    if (!byKey.has(key)) byKey.set(key, { ...event, title });
  }

  return [...byKey.values()]
    .sort((a, b) => {
      const aTime = Date.parse(a.at || "");
      const bTime = Date.parse(b.at || "");
      const aHasTime = Number.isFinite(aTime);
      const bHasTime = Number.isFinite(bTime);
      if (aHasTime || bHasTime) return (bHasTime ? bTime : 0) - (aHasTime ? aTime : 0);
      return a.sourceOrder - b.sourceOrder;
    })
    .slice(0, 9);
}

function renderOpsTimelineSection(shipment, evidence) {
  const events = timelineEventsForShipment(shipment, evidence);
  if (!events.length) return "";

  return `
    <section class="section operator-section ops-timeline-section">
      <h3>Timeline</h3>
      <div class="ops-timeline">
        ${events
          .map((event) => {
            const time = formatShortDate(event.at);
            const title = compactTimelineText(event.title, event);
            const detail = compactTimelineDetail(event.detail, title);
            const proof = compactTimelineProof(event.proof);
            const expanded = proof && state.expandedTimelineEvents.has(event.id);
            return `
              <button class="ops-timeline-row ${event.kind} ${expanded ? "expanded" : ""}" data-toggle-timeline-event="${escapeHtml(event.id)}" type="button" aria-expanded="${expanded ? "true" : "false"}">
                <span class="ops-timeline-dot" aria-hidden="true"></span>
                <div>
                  <div class="ops-timeline-top">
                    <span>${shortText(event.label, "Event", 18)}</span>
                    ${time ? `<time>${time}</time>` : ""}
                  </div>
                  <strong>${shortText(title, "No summary", 76)}</strong>
                  ${detail ? `<small>${shortText(detail, "", 62)}</small>` : ""}
                  ${expanded ? `<em class="ops-timeline-proof"><b>Proof</b>${shortText(proof, "", 260)}</em>` : ""}
                </div>
              </button>
            `;
          })
          .join("")}
      </div>
    </section>
  `;
}

function detailHeroTitle(primaryLabel, fallbackTitle, fallbackAction) {
  const label = String(primaryLabel || "").trim().toLowerCase();
  const title = String(fallbackTitle || "").trim();
  if (label && title.toLowerCase() === label) return fallbackAction || title;
  return title || fallbackAction || "Review shipment";
}

function detailHeroNote(title, note) {
  const text = String(note || "").trim();
  if (!text || text.toLowerCase() === String(title || "").trim().toLowerCase()) return "";
  return `<p>${text}</p>`;
}

function resetDetailScrollOnOpen(detailKey) {
  if (!detailShouldRender() || !detailKey || state.detailScrollKey === detailKey) return;
  state.detailScrollKey = detailKey;
  const pane = $("detailPane");
  const overlay = $("detailOverlay");
  if (pane) pane.scrollTop = 0;
  if (overlay) overlay.scrollTop = 0;
}

function detailAiSuggestions(shipment) {
  return [
    "What is blocking this?",
    "Why do you think that?",
    "Who should I call?",
    "Draft the next email",
    "What changed last?",
  ].filter((question) => {
    if (/draft/i.test(question)) return draftActionsForShipment(shipment).length || /release|do|pod|broker|pickup/i.test(nextStep(shipment));
    return true;
  });
}

function shipmentDecisionCandidateActions(shipment) {
  if (shipmentHasSourceGap(shipment)) return [];
  if (shipmentTruthComplete(shipment)) return [];
  const rows = [
    ...quoteActionsForShipment(shipment),
    ...awardActionsForShipment(shipment),
    ...actionsForShipment(shipment),
  ].filter((action) => activeActionPanelItem(action) && actionMatchesShipmentState(action, shipment));
  const byId = new Map(rows.map((action) => [action.id, action]));
  return [...byId.values()].sort(compareActionCardsForUi);
}

function shipmentDecisionPrimaryAction(shipment) {
  // The canonical pipeline attaches ONE primary executable action per active shipment
  // (platform-action-v1). Prefer it: same object the draft pipeline consumes verbatim.
  if (shipment?.primaryAction?.platform?.schema === "platform-action-v1" && !shipmentHasSourceGap(shipment) && !shipmentTruthComplete(shipment)) {
    return shipment.primaryAction;
  }
  const actions = shipmentDecisionCandidateActions(shipment);
  return actions.find((action) => isOperatorApprovedInternalAction(action) || !isPlatformAlertAction(action) || isExecutablePlatformAction(action)) ||
    actions[0] ||
    null;
}

function shipmentDecisionTone(shipment) {
  const lifecycle = lifecycleState(shipment);
  if (shipmentPickupBlocked(shipment) || lifecycle.tone === "risk") return "risk";
  if (lifecycle.tone === "ready") return "ready";
  if (opsState(shipment).needsHuman || shipmentDecisionPrimaryAction(shipment)) return "watch";
  return lifecycle.tone || "neutral";
}

function shipmentDecisionBlocker(shipment) {
  if (shipmentHasSourceGap(shipment)) {
    return {
      label: sourceGapDisplayLabel(shipment),
      detail: sourceGapOperatorAction(shipment),
    };
  }
  const ops = opsState(shipment);
  const lifecycle = lifecycleState(shipment);
  const label = cleanFactText(
    shipmentPickupBlocked(shipment)
      ? ops.label || "Pickup blocked"
      : ops.label || lifecycle.short || shortAction(shipment),
  );
  const detail = cleanFactText(
    shipmentPickupBlocked(shipment)
      ? shipmentPickupBlockedNextAction(shipment)
      : ops.summary || shipment.currentState || lifecycle.note || shipmentHeadline(shipment),
  );
  return {
    label: label || "Shipment state",
    detail: detail || nextStep(shipment),
  };
}

function shipmentDecisionContextText(shipment, action) {
  const ops = opsState(shipment);
  return [
    ops.phase,
    ops.label,
    ops.summary,
    ops.nextAction,
    shipment.currentState,
    shipment.nextAction,
    shipment.customsBroker?.status,
    shipment.customsBroker?.nextAction,
    shipment.freightBroker?.status,
    shipment.freightBroker?.nextAction,
    action?.label,
    action?.reason,
    action?.problem,
    action?.nextAction,
    action?.subject,
  ].filter(Boolean).join(" ");
}

function shipmentDecisionContactLine(name, ...contacts) {
  const parts = [name, ...contacts].filter(isUsableContact);
  return parts.join(" · ");
}

function firstUsableContact(...values) {
  return values.find(isUsableContact) || "";
}

function shipmentDecisionStationContact(shipment) {
  return shipmentDecisionContactLine(
    operationalStationOwner(shipment),
    firstUsableContact(shipment.stationEmail, shipment.stationContext?.email),
    firstUsableContact(shipment.stationPhone, shipment.stationContext?.phone, shipment.stationContext?.stationPhone),
  );
}

function shipmentDecisionCustomsContact(shipment) {
  return shipmentDecisionContactLine(
    shipment.customsBroker?.broker,
    shipment.customsBroker?.contactEmail,
    shipment.customsBroker?.contactPhone,
  );
}

function shipmentDecisionPickupContact(shipment) {
  return shipmentDecisionContactLine(
    shipment.freightBroker?.broker,
    shipment.freightBroker?.contactEmail,
    shipment.freightBroker?.contactPhone,
  );
}

function shipmentDecisionOwner(shipment, action) {
  const text = shipmentDecisionContextText(shipment, action).toLowerCase();
  const station = shipmentDecisionStationContact(shipment);
  const customs = shipmentDecisionCustomsContact(shipment);
  const pickup = shipmentDecisionPickupContact(shipment);

  if (shipmentTruthComplete(shipment)) {
    return {
      value: "Closeout",
      note: "POD received; no operator action is open.",
    };
  }

  if (shipmentHasSourceGap(shipment)) {
    return {
      value: sourceGapDisplayOwner(shipment),
      note: shipmentSourceGapReason(shipment),
    };
  }

  const platformTarget = action?.platform;
  if (platformTarget && (platformTarget.targetName || platformTarget.targetEmail)) {
    return {
      value: platformTarget.targetName || platformTarget.targetEmail,
      note: platformTarget.targetEmail && platformTarget.targetEmail !== platformTarget.targetName
        ? platformTarget.targetEmail
        : platformTarget.targetRole.replace(/-/g, " "),
    };
  }

  if (shipmentTruthClearTransit(shipment)) {
    return {
      value: station || operationalStationOwner(shipment) || "Station / handler",
      note: "Arrival/availability owner",
    };
  }

  if (/cargo not found|physically located|station.*pickup broker|pickup broker.*station/.test(text)) {
    return {
      value: "Station + pickup broker",
      note: [station, pickup || "Pickup broker missing"].filter(Boolean).join(" | "),
    };
  }

  if (/ground fees?|handler payment|station fee|storage|demurrage/.test(text)) {
    return {
      value: "Station / handler",
      note: station || "Station fee owner",
    };
  }

  if (
    ["dispatch-ready", "pickup-dispatched", "ready-for-pickup"].includes(String(opsState(shipment).phase || "")) ||
    ["broker-status-followup", "delivery-order-email", "dispatch-pickup-followup"].includes(action?.type)
  ) {
    return {
      value: pickup || "Pickup broker",
      note: shipment.freightBroker?.nextAction || "Pickup owner",
    };
  }

  if (/customs|release|clearance|entry|in[-\s]?bond|d\/?o|delivery order/.test(text)) {
    return {
      value: customs || "Customs broker",
      note: shipment.customsBroker?.nextAction || "Release owner",
    };
  }

  if (/pickup|dispatch|broker|truck|pod|delivery/.test(text)) {
    return {
      value: pickup || "Pickup broker",
      note: shipment.freightBroker?.nextAction || "Pickup owner",
    };
  }

  if (/arrival|available|station|cargo|handler|warehouse/.test(text)) {
    return {
      value: station || operationalStationOwner(shipment),
      note: "Station owner",
    };
  }

  return {
    value: opsState(shipment).needsHuman ? "Operator" : operationalStationOwner(shipment),
    note: opsState(shipment).needsHuman ? "Human decision owner" : "Station owner",
  };
}

function shipmentDecisionNextClick(action, shipment = {}) {
  if (shipmentHasSourceGap(shipment)) {
    return {
      value: sourceGapDisplayOwner(shipment),
      note: sourceGapOperatorAction(shipment),
    };
  }
  if (!action) {
    return {
      value: "Monitor",
      note: "No executable action packet is open.",
    };
  }
  const recipient = actionRecipientLabel(action);
  const recipientLabel = recipient ? `${isTmsAction(action) ? "Target" : "To"} ${recipient}` : "";
  return {
    value: `${actionModeLabel(action)} · ${shortText(operatorFacingActionLabel(action), "Action", 52)}`,
    note: [actionExecutionOutput(action), recipientLabel, actionExecutionThread(action), actionStatusLine(action)]
      .filter(Boolean)
      .join(" · "),
  };
}

function shipmentDecisionEvidenceItemText(item) {
  if (!item) return "";
  if (typeof item === "string") return item;
  if (Array.isArray(item)) return item.map(shipmentDecisionEvidenceItemText).filter(Boolean).join(" ");
  return cleanFactText([
    item.label,
    item.status,
    item.note,
    item.summary,
    item.evidence,
    item.source,
  ].filter(Boolean).join(" "));
}

function shipmentDecisionGateEvidence(shipment) {
  const gateLabels = {
    arrival: "Arrival",
    customs: "Customs",
    release: "Release",
    fees: "Fees",
    dispatch: "Dispatch",
    pickup: "Pickup",
    delivery: "Delivery",
    pod: "POD",
  };
  const gates = Object.entries(opsState(shipment).gates || {})
    .map(([key, gate]) => ({
      label: gateLabels[key] || key,
      status: cleanFactText(gate?.status),
      evidence: shipmentDecisionEvidenceItemText(gate),
    }))
    .filter((row) => row.status || row.evidence);
  const actionable = gates.find((row) =>
    /\b(?:blocked|hold|rejected|pending|needed|missing|unknown|not[-\s]?found|not[-\s]?released|due)\b/i.test(`${row.status} ${row.evidence}`) &&
    row.evidence,
  );
  const positive = gates.find((row) => row.evidence && !/^unknown$/i.test(row.status));
  const row = actionable || positive;
  if (!row) return "";
  return [row.label, row.status, row.evidence].filter(Boolean).join(": ");
}

function shipmentDecisionWhy(shipment, action) {
  const ops = opsState(shipment);
  if (shipmentTruthComplete(shipment)) return "POD received; delivery is complete.";
  if (shipmentHasSourceGap(shipment)) return shipmentSourceGapReason(shipment);
  const evidence = [
    action ? actionReasonLine(action) : "",
    shipmentDecisionGateEvidence(shipment),
    ...(ops.blockers || []),
    ...(ops.evidence || []).map(shipmentDecisionEvidenceItemText),
    shipment.emailValidation?.summary,
    ...(shipment.statusAudit?.evidence || []).map(shipmentDecisionEvidenceItemText),
    shipment.lastEmail?.summary,
  ].map(cleanFactText).find(Boolean);
  return evidence || lifecycleState(shipment).note || shipmentHeadline(shipment);
}

function renderShipmentDecisionCell(label, value, note = "", className = "") {
  return `
    <div class="${className}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(shortText(value, "Unknown", 96))}</strong>
      ${note ? `<small>${escapeHtml(shortText(note, "", 112))}</small>` : ""}
    </div>
  `;
}

function renderShipmentDecisionStrip(shipment) {
  const action = shipmentDecisionPrimaryAction(shipment);
  const blocker = shipmentDecisionBlocker(shipment);
  const owner = shipmentDecisionOwner(shipment, action);
  const nextClick = shipmentDecisionNextClick(action, shipment);
  const why = shipmentDecisionWhy(shipment, action);
  return `
    <section class="shipment-decision-strip ${shipmentDecisionTone(shipment)}" data-shipment-decision-strip="${escapeHtml(shipment.id)}">
      <div class="shipment-decision-main">
        <span>${escapeHtml(shortText(blocker.label, "State", 34))}</span>
        <strong>${escapeHtml(shortText(blocker.detail, "Review shipment state.", 156))}</strong>
      </div>
      <div class="shipment-decision-grid">
        ${renderShipmentDecisionCell("Owner", owner.value, owner.note)}
        ${renderShipmentDecisionCell("Next click", nextClick.value, nextClick.note, "next-click")}
        ${renderShipmentDecisionCell("Why", why, "", "wide")}
      </div>
      ${action ? `<div class="shipment-decision-controls">${actionButtons(action)}${renderPlatformActionMeta(action)}</div>` : ""}
    </section>
  `;
}

function renderDetailAiConsole(shipment) {
  const awb = detailAiAwbKey(shipment);
  if (!awb) return "";
  const messages = detailAiMessages(shipment);
  const thinking = state.detailAiThinkingAwb === awb;
  const draft = state.detailAiDraftInputs[awb] || "";
  const suggestions = detailAiSuggestions(shipment);
  const messageMarkup = messages.length
    ? messages.map((message, index) => renderOpsBrainMessage(message, index)).join("")
    : `<article class="detail-ai-empty">
        <strong>Ask in this shipment</strong>
        <span>Questions and draft actions stay anchored to ${escapeHtml(opsBrainDisplayAwb(awb))}.</span>
      </article>`;
  return `
    <section class="section operator-section detail-ai-console" data-detail-ai-awb="${escapeHtml(awb)}">
      <div class="detail-ai-head">
        <h3>Companion</h3>
        <span>${escapeHtml(opsBrainDisplayAwb(awb))}</span>
      </div>
      <div class="detail-ai-log" aria-live="polite">
        ${messageMarkup}
        ${thinking ? `
          <article class="ops-brain-message assistant typing" aria-label="AI console is typing">
            <p><i></i><i></i><i></i></p>
          </article>
        ` : ""}
      </div>
      <div class="detail-ai-chips">
        ${suggestions.map((question) => `<button type="button" data-detail-ai-question="${escapeHtml(question)}" data-detail-ai-shipment="${escapeHtml(shipment.id)}">${escapeHtml(question)}</button>`).join("")}
      </div>
      <form class="detail-ai-composer" data-detail-ai-form="${escapeHtml(shipment.id)}" ${draft.trim() ? `data-has-draft="true"` : ""}>
        <textarea data-detail-ai-input="${escapeHtml(shipment.id)}" rows="1" placeholder="Yael AI">${escapeHtml(draft)}</textarea>
        <button type="submit" aria-label="Ask about shipment" ${draft.trim() && !state.detailAiThinkingAwb ? "" : "disabled"}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5"></path><path d="m6 11 6-6 6 6"></path></svg>
        </button>
      </form>
    </section>
  `;
}

function compactShipmentDimensionText(value) {
  const text = cleanFactText(value);
  if (!text) return "";
  const match = text.match(/\b\d+(?:\.\d+)?\s*x\s*\d+(?:\.\d+)?\s*x\s*\d+(?:\.\d+)?\s*(?:in|cm|mm)?\b/i);
  return match?.[0] || "";
}

function compactShipmentWeightText(value) {
  const text = cleanFactText(value);
  if (!text) return "";
  const match = text.match(/\b\d+(?:\.\d+)?\s*(?:kg|kgs|lb|lbs)\b/i);
  return match?.[0] || text;
}

function compactTmsWeightText(value, unit = "") {
  const text = cleanFactText(value);
  if (!text) return "";
  if (/\b(?:kg|kgs|lb|lbs)\b/i.test(text)) return compactShipmentWeightText(text);
  const cleanedUnit = cleanFactText(unit);
  if (cleanedUnit) return compactShipmentWeightText(`${text} ${cleanedUnit}`);
  return /^\d+(?:\.\d+)?$/.test(text) ? `${text} KG` : compactShipmentWeightText(text);
}

function compactShipmentCountText(value, unit = "") {
  const text = cleanFactText(value);
  if (!text) return "";
  if (unit && /^\d+(?:\.\d+)?$/.test(text)) return `${text} ${unit}`;
  return text;
}

function usableShipmentDryFact(value) {
  const text = cleanFactText(value);
  if (!text) return "";
  if (/^(?:unknown|n\/a|na|not found|not available|null|undefined|-|0\s*(?:pallets?|skids?)?)$/i.test(text)) return "";
  return text;
}

function shipmentFactSearchRows(shipment) {
  return [
    ...(shipment.facts || []),
    ...(shipment.factLedger || []),
    ...(shipment.operationalFacts || []),
    ...(shipment.opsState?.events || []),
    ...(shipment.opsState?.exceptions || []),
    ...(shipment.sourceEvents || []),
    ...(shipment.sourceProof || []),
    ...(shipment.emailValidation?.events || []),
    ...(shipment.emailValidation?.proof || []),
    ...(shipment.statusAudit?.evidence || []),
  ];
}

function firstShipmentFactValue(shipment, patterns) {
  const facts = shipmentFactSearchRows(shipment);
  for (const fact of facts) {
    const text = [
      fact?.type,
      fact?.label,
      fact?.summary,
      fact?.note,
      fact?.evidence,
      fact?.text,
      fact?.extractedTextPreview,
    ].filter(Boolean).join(" ");
    if (!text || !patterns.some((pattern) => pattern.test(text))) continue;
    const cleaned = cleanFactText(text);
    if (cleaned) return cleaned;
  }
  return "";
}

function shipmentCargoPieces(shipment) {
  return usableShipmentDryFact(compactShipmentCountText(
    shipment.tms?.pieces ||
      shipment.tms?.pieceCount ||
      shipment.cargo?.pieces ||
      shipment.cargo?.pieceCount ||
      shipment.pieces ||
      shipment.pieceCount ||
      firstShipmentFactValue(shipment, [/\b\d+\s*(?:pcs?|pieces?|slac)\b/i]),
    "pcs",
  ));
}

function shipmentCargoPallets(shipment) {
  return usableShipmentDryFact(compactShipmentCountText(
    shipment.tms?.pallets ||
      shipment.tms?.skids ||
      shipment.cargo?.pallets ||
      shipment.cargo?.skids ||
      shipment.pallets ||
      shipment.skids ||
      firstShipmentFactValue(shipment, [/\b\d+\s*(?:pallets?|skids?)\b/i]),
    "pallets",
  ));
}

function shipmentCargoWeight(shipment) {
  const tmsWeight = compactTmsWeightText(
    shipment.tms?.weight ||
      shipment.tms?.grossWeight ||
      shipment.tms?.chargeableWeight ||
      "",
    shipment.tms?.weightUom || shipment.tms?.weightUnit || "",
  );
  const weight = tmsWeight || String(
    shipment.cargo?.weight ||
      shipment.cargo?.grossWeight ||
      shipment.cargo?.chargeableWeight ||
      shipment.weight ||
      shipment.grossWeight ||
      shipment.chargeableWeight ||
      "",
  ).trim();
  const factWeight = weight ? "" : compactShipmentWeightText(firstShipmentFactValue(shipment, [/\b(?:weight|gross weight|chargeable)\b/i, /\b\d+(?:\.\d+)?\s*(?:kg|kgs|lb|lbs)\b/i]));
  const value = weight || factWeight;
  if (!value) return "";
  const uom = String(shipment.weightUom || shipment.weightUnit || "").trim();
  return usableShipmentDryFact(compactShipmentWeightText([value, /\b(?:kg|kgs|lb|lbs)\b/i.test(value) ? "" : uom].filter(Boolean).join(" ")));
}

function shipmentChargeableWeight(shipment) {
  const value = [
    shipment.tms?.chargeableWeight,
    shipment.cargo?.chargeableWeight,
    shipment.chargeableWeight,
  ].map(compactShipmentWeightText).find(Boolean) || compactShipmentWeightText(firstShipmentFactValue(shipment, [/\bchargeable\b/i]));
  const gross = shipmentCargoWeight(shipment);
  return usableShipmentDryFact(value && value !== gross ? value : "");
}

function shipmentCommodityLine(shipment) {
  return usableShipmentDryFact([
    shipment.tms?.commodity,
    shipment.tms?.commodityDescription,
    shipment.commodity,
    shipment.goodsDescription,
    shipment.descriptionOfGoods,
    shipment.cargo?.commodity,
    shipment.cargo?.description,
  ].map(cleanFactText).find(Boolean) || firstShipmentFactValue(shipment, [
    /\bcommodity\b/i,
    /\bdescription of goods\b/i,
    /\bgoods description\b/i,
  ]));
}

function shipmentDimensionsLine(shipment) {
  return usableShipmentDryFact([
    shipment.tms?.dimensions,
    shipment.tms?.dims,
    shipment.tms?.dimension,
    shipment.dimensions,
    shipment.dims,
    shipment.cargo?.dimensions,
    shipment.cargo?.dims,
  ].map(compactShipmentDimensionText).find(Boolean) || compactShipmentDimensionText(firstShipmentFactValue(shipment, [
    /\bdim(?:ension)?s?\b/i,
    /\b\d+(?:\.\d+)?\s*x\s*\d+(?:\.\d+)?\s*x\s*\d+(?:\.\d+)?/i,
  ])));
}

function shipmentFlightValues(shipment) {
  const flightRows = [
    ...(Array.isArray(shipment.flights) ? shipment.flights : []),
    ...(Array.isArray(shipment.flightDetails?.flights) ? shipment.flightDetails.flights : []),
    ...(Array.isArray(shipment.liveTracking?.flights) ? shipment.liveTracking.flights : []),
    shipment.flightDetails?.primaryFlight,
    shipment.flightDetails?.tmsFlight,
    shipment.liveTracking?.primaryFlight,
    shipment.liveTracking?.tmsFlight,
    shipment.tmsFlight,
    shipment.flight,
    shipment.flightNumber,
    shipment.tms?.flight,
    shipment.tms?.flightNumber,
  ];
  return uniqueRowsByKey(
    flightRows
      .map((item) => typeof item === "string" ? item : item?.flight || item?.number || item?.flightNumber || "")
      .map(cleanFactText)
      .filter(Boolean),
    (item) => item.toUpperCase(),
  ).slice(0, 4);
}

function shipmentFlightLine(shipment) {
  const flights = shipmentFlightValues(shipment).join(", ");
  const eta = usableShipmentDryFact(
    shipment.flightDetails?.etaHint ||
      shipment.flightDetails?.scheduledArrival ||
      shipment.liveTracking?.etaHint ||
      shipment.liveTracking?.scheduledArrival ||
      shipment.scheduledArrival ||
      shipment.eta ||
      "",
  );
  return [flights, eta].filter(Boolean).join(" · ");
}

function shipmentRoutingLine(shipment) {
  const route = usableShipmentDryFact(
    shipment.flightDetails?.route ||
      shipment.liveTracking?.route ||
      shipment.route ||
      shipment.routing ||
      shipment.tms?.route ||
      shipment.tms?.routing ||
      [shipment.origin, shipment.destination || shipment.station].filter(Boolean).join("-"),
  );
  return route && !/^-$/.test(route) ? route : "";
}

function shipmentConsigneeLine(shipment) {
  const consignee = usableShipmentDryFact(shipment.delivery?.consignee || shipment.consignee);
  if (!consignee || consignee === shipment.client) return "";
  return consignee;
}

function shipmentDryFactRows(shipment) {
  const rows = [
    { label: "Pieces", value: shipmentCargoPieces(shipment), tone: "primary" },
    { label: "Pallets", value: shipmentCargoPallets(shipment) },
    { label: "Weight", value: shipmentCargoWeight(shipment), tone: "primary" },
    { label: "Chargeable", value: shipmentChargeableWeight(shipment) },
    { label: "Dimensions", value: shipmentDimensionsLine(shipment), tone: "wide" },
    { label: "Flight / ETA", value: shipmentFlightLine(shipment), tone: "wide" },
    { label: "Route", value: shipmentRoutingLine(shipment) },
    { label: "TMS", value: shipment.tms?.order || shipment.id },
    { label: "Commodity", value: shipmentCommodityLine(shipment), tone: "wide" },
    { label: "Consignee", value: shipmentConsigneeLine(shipment), tone: "wide" },
    { label: "Address", value: cleanAddress(shipment.delivery?.fullAddress || "", shipment.delivery?.consignee || shipment.client), tone: "wide" },
  ]
    .map((row) => ({ ...row, value: usableShipmentDryFact(row.value) }))
    .filter((row) => row.value);
  return uniqueRowsByKey(rows, (row) => `${row.label}:${row.value}`.toLowerCase()).slice(0, 12);
}

function renderShipmentDryFacts(shipment) {
  const rows = shipmentDryFactRows(shipment);

  if (!rows.length) return "";
  return `
    <section class="section operator-section detail-dry-facts">
      <h3>Cargo details</h3>
      <div class="detail-dry-grid">
        ${rows.map((row) => `
          <div class="${escapeHtml(row.tone || "")}" title="${escapeHtml(row.value)}">
            <span>${escapeHtml(row.label)}</span>
            <strong>${escapeHtml(shortText(row.value, "", row.tone === "wide" || row.label === "Address" ? 92 : 54))}</strong>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function shipmentInboxAwbKey(shipment = {}) {
  return opsBrainAwbKey(shipment.awb || shipment.id || "");
}

function shipmentInboxMatchesAwb(shipment = {}, ...values) {
  const shipmentKey = shipmentInboxAwbKey(shipment);
  if (!shipmentKey) return false;
  return values.some((value) => opsBrainAwbKey(value || "") === shipmentKey);
}

function shipmentInboxTone(value = "") {
  const text = String(value || "").toLowerCase();
  if (/\b(?:critical|urgent|immediate|high|risk)\b/.test(text)) return "critical";
  if (/\b(?:ready|done|resolved|delivered)\b/.test(text)) return "ready";
  return "work";
}

function shipmentInboxTimeMs(item = {}) {
  const value = item.occurredAt || item.createdAt || item.updatedAt || item.dueAt || "";
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function shipmentInboxActionControls(action) {
  if (!action) return "";
  const formBoundPlatformAction =
    isStationContactResearchAction(action) ||
    isReleaseContactGapAction(action) ||
    isOperatorStateCheckAction(action) ||
    isStationFeeAction(action) ||
    isPrearrivalQuoteDecisionAction(action);
  if (!formBoundPlatformAction) return actionButtons(action);
  const callButton = renderCallButton(action);
  if (isHandledOpsBrainAction(action)) return `${callButton}<span class="action-alert-state handled">Saved</span>`;
  return `${callButton}<button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
}

function shipmentInboxNotificationItems(shipment = {}) {
  const notifications = collapseOperatorNotifications([
    ...(state.operatorNotifications?.notifications || []),
    ...(state.operatorEvents || []).map(operatorEventAsNotification).filter(Boolean),
  ]);
  return notifications
    .filter((notification) =>
      notification?.id &&
      !["resolved", "dismissed", "archived"].includes(String(notification.status || "").toLowerCase()) &&
      operatorNotificationStillRelevant(notification) &&
      shipmentInboxMatchesAwb(shipment, notification.awb, notification.source?.awb, notification.subtitle)
    )
    .map((notification) => {
      const notificationActions = operatorNotificationActions(notification);
      const action = notificationActions.find(activeActionPanelItem) || notificationActions[0] || null;
      if (action) rememberOpsBrainActions([action]);
      const actionKey = action ? opsBrainActionKey(action) : "";
      return {
        kind: "notification",
        key: `notification:${operatorNotificationSeenKey(notification)}`,
        actionKey,
        tone: shipmentInboxTone(`${notification.severity || ""} ${notification.type || ""}`),
        severity: notification.severity || "",
        immediateAttention: Boolean(notification.immediateAttention),
        title: notification.title || "Shipment update",
        summary: notification.message || notification.title || "Shipment needs attention.",
        next: notification.nextAction || "",
        meta: [
          notification.occurredAt ? formatShortDate(notification.occurredAt) : "",
          normalizedOperatorNotificationTitle(notification.type, notification.type || "").replace(/-/g, " "),
        ].filter(Boolean).join(" · "),
        occurredAt: notification.occurredAt || notification.createdAt || "",
        notificationId: notification.id,
        awb: notification.awb || shipment.awb || "",
        action,
      };
    });
}

function shipmentInboxActionItems(shipment = {}, hiddenActionKeys = new Set()) {
  const actions = shipmentDecisionCandidateActions(shipment)
    .filter(activeActionPanelItem)
    .filter((action) => !hiddenActionKeys.has(opsBrainActionKey(action)))
    .slice(0, 5);
  rememberOpsBrainActions(actions);
  return actions.map((action) => ({
    kind: "action",
    key: `action:${opsBrainActionKey(action)}`,
    actionKey: opsBrainActionKey(action),
    tone: shipmentInboxTone(`${action.priority || ""} ${action.type || ""}`),
    title: operatorFacingActionLabel(action),
    summary: action.problem || action.reason || action.body || action.nextAction || actionStatusLine(action),
    next: action.nextAction || actionStatusLine(action),
    meta: [actionModeLabel(action), action.timing?.dueAt ? formatShortDate(action.timing.dueAt) : ""].filter(Boolean).join(" · "),
    occurredAt: action.timing?.dueAt || action.createdAt || action.updatedAt || "",
    awb: action.awb || shipment.awb || "",
    action,
  }));
}

function shipmentInboxReasoningItems(shipment = {}) {
  if (!shipmentHasCanonicalReasoning(shipment) || shipmentTruthComplete(shipment)) return [];
  const reasoning = shipmentCanonicalReasoning(shipment);
  const next = cleanFactText(reasoning.nextAction || shipment.nextAction || shipment.opsState?.nextAction || "");
  if (!next) return [];
  const phase = shipmentReasoningPhase(shipment);
  const className = shipmentReasoningClass(shipment);
  const stateLabel = controlRoomReasoningState(shipment)?.label || controlRoomReasoningPhaseLabel(phase) || "Shipment state";
  const summary = cleanFactText(
    reasoning.summary ||
      reasoning.reason ||
      shipment.currentState ||
      shipment.opsState?.summary ||
      "",
  );
  return [{
    kind: "truth",
    key: `truth:${shipmentInboxAwbKey(shipment)}:${phase || className}:${next.toLowerCase().slice(0, 96)}`,
    actionKey: "",
    tone: shipmentInboxTone(`${className} ${phase} ${stateLabel}`),
    title: stateLabel,
    summary,
    next,
    meta: ["Truth", controlRoomReasoningPhaseLabel(phase)].filter(Boolean).join(" · "),
    occurredAt: reasoning.updatedAt || reasoning.observedAt || shipment.updatedAt || state.snapshotTime || "",
    awb: shipment.awb || "",
    action: null,
  }];
}

function shipmentInboxKindRank(item = {}) {
  if (item.kind === "notification") return 0;
  if (item.kind === "truth") return 1;
  return 2;
}

function shipmentInboxItems(shipment = {}) {
  const notifications = shipmentInboxNotificationItems(shipment);
  const hiddenActionKeys = new Set(notifications.map((item) => item.actionKey).filter(Boolean));
  const reasoning = shipmentInboxReasoningItems(shipment);
  const actions = shipmentInboxActionItems(shipment, hiddenActionKeys);
  return uniqueRowsByKey([...notifications, ...reasoning, ...actions], (item) => item.key || item.actionKey)
    .sort((a, b) =>
      shipmentInboxKindRank(a) - shipmentInboxKindRank(b) ||
      shipmentInboxTimeMs(b) - shipmentInboxTimeMs(a)
    )
    .slice(0, 4);
}

function operatorInboxShipmentHasWork(shipment = {}) {
  const phase = controlRoomCanonicalPhase(shipment) || shipmentReasoningPhase(shipment) || String(shipment.opsState?.phase || "").toLowerCase();
  return Boolean(
    controlRoomAttentionNow(shipment) ||
      currentReadyForPickupState(shipment) ||
      pickupOrDeliveryMoving(shipment) ||
      deliveredOrCloseout(shipment) ||
      todayActionRows([shipment]).some(todayActionNeedsImmediateOperator) ||
      ["fees-needed", "release-needed", "customs-hold", "pickup-docs-needed", "awb-copy-needed", "pickup-location-requested", "pod-needed", "delivered-pod-pending", "source-gap", "delivery-blocked"].includes(phase)
  );
}

function operatorInboxSeverityRank(item = {}) {
  if (item.tone === "critical") return 0;
  if (item.kind === "notification") return 1;
  if (item.tone === "ready") return 2;
  if (item.kind === "truth") return 3;
  return 4;
}

// System notifications: freshness problems surface as ONE deduped inbox row each — never
// per-render spam; dismissal uses the same seen-set as shipment notifications.
function systemInboxNotifications() {
  const freshness = globalProofFreshness();
  const sourceGapSummary = sourceGapSummaryForUi();
  const items = [];
  if (freshness.level === "refresh-failed") {
    items.push({
      kind: "notification",
      notificationId: `system:refresh-failed:${freshness.failedPhase || "unknown"}`,
      awb: "",
      severity: "urgent",
      immediateAttention: true,
      title: `Gmail refresh failed at the ${freshness.failedPhase || "unknown"} phase`,
      message: "Truth may be missing newer email evidence until a clean refresh completes.",
      nextAction: "Open the health panel and retry the Gmail refresh.",
      occurredAt: freshness.lastWriteAt || new Date().toISOString(),
      system: true,
    });
  } else if ((freshness.level === "stale" || freshness.level === "source-gap") && !sourceGapSummary) {
    items.push({
      kind: "notification",
      notificationId: "system:stale-proof",
      awb: "",
      severity: "urgent",
      immediateAttention: false,
      title: freshness.level === "stale" ? "Email proof is stale" : "Email proof source gap",
      message: `${freshness.label}. Action confidence is reduced until fresh evidence lands.`,
      nextAction: "Retry the Gmail refresh from the health panel.",
      occurredAt: freshness.lastWriteAt || new Date().toISOString(),
      system: true,
    });
  }
  return items.filter((item) => !state.seenOperatorNotifications.has(item.notificationId));
}

function operatorInboxRows(rows = state.shipments) {
  const shipments = (rows || []).filter((shipment) => !shipmentTruthComplete(shipment));
  return uniqueRowsByKey(
    shipments.flatMap((shipment) =>
      shipmentInboxItems(shipment)
        .filter((item) => item.kind === "notification" || operatorInboxShipmentHasWork(shipment))
        .map((item) => ({
          ...item,
          shipmentId: shipment.id || "",
          awb: item.awb || shipment.awb || "",
          station: operationalStation(shipment) || shipment.station || "",
          client: shipment.client || shipment.consignee || shipment.delivery?.consignee || "",
          shipment,
        }))
    ),
    (item) => [
      item.kind,
      item.notificationId || "",
      item.actionKey || "",
      item.awb || "",
      item.title || "",
      item.next || "",
    ].join("|"),
  )
    .concat(systemInboxNotifications())
    .sort((a, b) =>
      operatorInboxSeverityRank(a) - operatorInboxSeverityRank(b) ||
      shipmentInboxTimeMs(b) - shipmentInboxTimeMs(a) ||
      String(a.awb || "").localeCompare(String(b.awb || ""))
    )
    .slice(0, 48);
}

// ---- Operator change center -------------------------------------------
// The inbox is NOT mail. It answers three questions with one data source:
//   INTERRUPTS  — what needs me RIGHT NOW (critical severity, unresolved)
//   NEEDS YOU   — the same work the Today board counts (count identity)
//   WHAT CHANGED — positive truth updates from the world (delivered, POD,
//                  pickup confirmed, released) in the last 48h, deduped per
//                  shipment+class, superseded items dropped
// Raw messages/blocker history live in the shipment detail, nowhere else.
const CHANGE_CLASS_RE = /(deliver(?:ed|y completed)|\bpod\b|proof of delivery|picked ?up|נאסף|released|release received|cleared|\b1c\b|arrival notice|notice of arrival|payment (?:received|confirmed)|fee(?:s)? paid)/i;
const CHANGE_WINDOW_MS = 48 * 3600 * 1000;

function operatorChangeCenter(rows = state.shipments) {
  const active = (rows || []).filter((shipment) => !shipmentTruthComplete(shipment));
  const interrupts = active
    .filter((shipment) => String(shipment.severity?.level || "").toLowerCase() === "critical")
    .map((shipment) => ({
      kind: "interrupt",
      key: `int:${shipment.id || shipment.awb}`,
      shipmentId: shipment.id || "",
      awb: shipment.awb || "",
      station: operationalStation(shipment) || shipment.station || "",
      client: shipment.client || shipment.consignee || "",
      title: shipment.severity?.reason || shipment.urgentInterrupt?.title || "Needs you now",
      occurredAt: shipment.lastEmail?.at || "",
      tone: "urgent",
      shipment,
    }));
  const needsYou = desktopStageCountableEntries(desktopStageQueueItems(rows || state.shipments));
  const now = Date.now();
  const seenChange = new Set();
  const changes = active
    .flatMap((shipment) => shipmentInboxItems(shipment)
      .filter((item) => item.kind === "notification")
      .map((item) => ({ ...item, shipment, shipmentId: shipment.id || "", awb: item.awb || shipment.awb || "", station: operationalStation(shipment) || shipment.station || "", client: shipment.client || shipment.consignee || "" })))
    .filter((item) => {
      const text = `${item.title || ""} ${item.summary || ""}`;
      const match = text.match(CHANGE_CLASS_RE);
      if (!match) return false;
      const at = Date.parse(item.occurredAt || "");
      if (!Number.isFinite(at) || now - at > CHANGE_WINDOW_MS) return false;
      const classKey = `${opsBrainAwbKey(item.awb)}:${String(match[1]).toLowerCase().replace(/[^a-z]/g, "")}`;
      if (seenChange.has(classKey)) return false;
      seenChange.add(classKey);
      return true;
    })
    .sort((a, b) => Date.parse(b.occurredAt || 0) - Date.parse(a.occurredAt || 0))
    .slice(0, 20)
    .map((item) => ({ ...item, kind: "change", tone: "quiet" }));
  return { interrupts, needsYou, changes };
}

function operatorInboxCount(rows = state.shipments) {
  const center = operatorChangeCenter(rows);
  return center.interrupts.length + center.needsYou.length;
}

function renderOperatorInboxItem(item) {
  const actionControls = item.action ? shipmentInboxActionControls(item.action) : "";
  const meta = [
    item.kind === "notification" ? "Message" : item.meta || "Shipment work",
    item.station,
    item.awb ? opsBrainDisplayAwb(item.awb) : "",
  ].filter(Boolean).join(" · ");
  const openLabel = item.kind === "notification" ? "Open message" : "Open shipment";
  return `
    <article class="operator-inbox-item ${escapeHtml(item.tone || "work")} ${escapeHtml(item.kind || "action")}" data-open-operator-inbox-item="${escapeHtml(item.key || item.actionKey || item.notificationId || item.shipmentId || item.awb)}" data-shipment-id="${escapeHtml(item.shipmentId || "")}" data-awb="${escapeHtml(item.awb || "")}" data-notification-id="${escapeHtml(item.notificationId || "")}" tabindex="0">
      <div class="operator-inbox-main">
        <span>${escapeHtml(meta)}${item.occurredAt ? `<time>${escapeHtml(formatShortDate(item.occurredAt))}</time>` : ""}</span>
        <strong>${escapeHtml(shortText(item.title, "Shipment update", 76))}</strong>
        ${item.summary ? `<p>${escapeHtml(shortText(item.summary, "", 148))}</p>` : ""}
        ${item.next ? `<small>${escapeHtml(shortText(item.next, "", 150))}</small>` : ""}
      </div>
      <div class="operator-inbox-side">
        ${item.client ? `<em>${escapeHtml(shortText(item.client, "", 38))}</em>` : ""}
        ${actionControls}
        <button class="mini-button" data-open-inbox-shipment type="button">${escapeHtml(openLabel)}</button>
      </div>
    </article>
  `;
}

function renderChangeCenterWorkRow(entry) {
  const shipment = entry.shipment;
  const label = shortText(operatorFacingActionLabel(entry.action || {}), "Review this shipment", 76);
  return `
    <article class="operator-inbox-item work" data-open-operator-inbox-item="work:${escapeHtml(shipment.id || shipment.awb || "")}" data-shipment-id="${escapeHtml(shipment.id || "")}" data-awb="${escapeHtml(shipment.awb || "")}" tabindex="0">
      <div class="operator-inbox-main">
        <span>Needs you · ${escapeHtml(operationalStation(shipment) || shipment.station || "")} · ${escapeHtml(opsBrainDisplayAwb(shipment.awb || shipment.id || ""))}</span>
        <strong>${escapeHtml(label)}</strong>
      </div>
      <div class="operator-inbox-side">
        ${shipment.client ? `<em>${escapeHtml(shortText(shipment.client, "", 34))}</em>` : ""}
        <button class="mini-button" data-open-inbox-shipment type="button">Open shipment</button>
      </div>
    </article>
  `;
}

function renderOperatorInboxScreen(rows) {
  const center = operatorChangeCenter(rows);
  const section = (title, hint, body) => `
    <div class="operator-inbox-section">
      <h4 class="operator-inbox-section-head">${escapeHtml(title)}${hint ? ` <em>${escapeHtml(hint)}</em>` : ""}</h4>
      ${body}
    </div>
  `;
  const empty = (text) => `<div class="operator-inbox-empty">${escapeHtml(text)}</div>`;
  return `
    <section class="operator-inbox" aria-label="Operator changes">
      <div class="operator-inbox-head">
        <div>
          <span>Changes</span>
          <strong>${center.interrupts.length ? `${center.interrupts.length} need${center.interrupts.length === 1 ? "s" : ""} you right now` : center.needsYou.length ? `${center.needsYou.length} waiting on you` : "All clear"}</strong>
        </div>
      </div>
      ${section("Interrupts", "act now",
        center.interrupts.length ? `<div class="operator-inbox-list">${center.interrupts.map(renderOperatorInboxItem).join("")}</div>` : empty("Nothing is blocking a driver or burning storage right now."))}
      ${section("Waiting on you", "same items as Today",
        center.needsYou.length ? `<div class="operator-inbox-list">${center.needsYou.map(renderChangeCenterWorkRow).join("")}</div>` : empty("The Today board is clear."))}
      ${section("What changed", "truth updates · last 48h",
        center.changes.length ? `<div class="operator-inbox-list">${center.changes.map(renderOperatorInboxItem).join("")}</div>` : empty("No deliveries, PODs, pickups, or releases landed in the last 48 hours."))}
    </section>
  `;
}

// After a notification click, land the operator on the shipment's primary action strip.
function focusPrimaryActionStrip() {
  window.setTimeout(() => {
    const strip = document.querySelector("[data-shipment-decision-strip]");
    if (!strip) return;
    strip.scrollIntoView({ behavior: "smooth", block: "center" });
    strip.classList.add("notification-focus");
    window.setTimeout(() => strip.classList.remove("notification-focus"), 2400);
  }, 120);
}

function openOperatorInboxItemTarget(payload = {}, options = {}) {
  const notificationId = payload.notificationId || "";
  const awb = payload.awb || "";
  const keepControlRoom = Boolean(options.keepFilter || isDesktopWorkspace());
  if (notificationId && openOperatorNotificationTarget(payload, { ...options, keepFilter: keepControlRoom })) {
    if (keepControlRoom) {
      const selectedShipment = state.shipments.find((item) => item.id === state.selectedId) || null;
      state.operatorInboxOpen = false;
      if (state.filter === "brain" || state.filter === "inbox") state.filter = "control";
      if (selectedShipment) {
        state.controlLane = controlRoomLaneForShipment(selectedShipment);
        state.controlLaneExplicit = true;
        // Land IN the cockpit — selecting without focusing looked like the
        // click did nothing (the stage kept showing the queue).
        state.stageFocus = "shipment";
      }
    }
    focusPrimaryActionStrip();
    return true;
  }
  const shipment = state.shipments.find((item) =>
    (payload.shipmentId && item.id === payload.shipmentId) ||
      (awb && opsBrainAwbKey(item.awb || item.id || "") === opsBrainAwbKey(awb))
  );
  if (!shipment) return false;
  state.selectedId = shipment.id || shipment.awb || "";
  state.selectedGroupId = null;
  state.selectedVisualGroupKey = null;
  state.detailOpen = !isDesktopWorkspace();
  focusPrimaryActionStrip();
  if (keepControlRoom) {
    state.operatorInboxOpen = false;
    if (state.filter === "brain" || state.filter === "inbox") state.filter = "control";
    state.controlLane = controlRoomLaneForShipment(shipment);
    state.controlLaneExplicit = true;
    // Land IN the cockpit — selecting without focusing looked like the
    // click did nothing (same fix the notification branch already carries).
    state.stageFocus = "shipment";
  } else {
    state.filter = "brain";
  }
  setOpsBrainContextFromShipment(shipment, "inbox");
  activateOpsBrainChatScopeForShipment(shipment, "inbox");
  state.opsBrainHasReadyAnswer = true;
  if (options.askFallback) submitOpsBrainQuestion(`what needs action on ${opsBrainDisplayAwb(shipment.awb || shipment.id)}?`);
  return true;
}

function renderShipmentInboxItem(item) {
  const actionControls = item.action ? shipmentInboxActionControls(item.action) : "";
  const openButton = item.kind === "notification"
    ? `<button class="mini-button" data-open-shipment-inbox-notification="${escapeHtml(item.notificationId)}" data-awb="${escapeHtml(item.awb)}" type="button">Open</button>`
    : "";
  return `
    <article class="detail-inbox-item ${escapeHtml(item.tone || "work")} ${escapeHtml(item.kind || "action")}">
      <div class="detail-inbox-item-main">
        <span>${escapeHtml(item.kind === "notification" ? "Inbox" : item.meta || "Action")}${item.meta && item.kind === "notification" ? `<time>${escapeHtml(item.meta)}</time>` : ""}</span>
        <strong>${escapeHtml(shortText(item.title, "Shipment update", 58))}</strong>
        ${item.summary ? `<p>${escapeHtml(shortText(item.summary, "", 110))}</p>` : ""}
        ${item.next ? `<small>${escapeHtml(shortText(item.next, "", 112))}</small>` : ""}
      </div>
      ${actionControls || openButton ? `<div class="detail-inbox-controls">${actionControls || openButton}</div>` : ""}
    </article>
  `;
}

function renderShipmentInbox(shipment) {
  const items = shipmentInboxItems(shipment);
  return `
    <section class="section operator-section detail-inbox" aria-label="Shipment inbox">
      <div class="detail-inbox-head">
        <h3>Inbox</h3>
        <span>${escapeHtml(items.length ? `${items.length} open` : "Clear")}</span>
      </div>
      ${items.length
        ? `<div class="detail-inbox-list">${items.map(renderShipmentInboxItem).join("")}</div>`
        : `<div class="detail-inbox-empty">No shipment messages right now.</div>`}
    </section>
  `;
}

function completedSourceShipmentByAwb(awb) {
  const key = opsBrainAwbKey(awb || "");
  if (!key) return null;
  return opsBrainCompletedShipments().find((shipment) =>
    opsBrainAwbKey(shipment.awb || shipment.id || "") === key
  ) || null;
}

function sourceCoverageLabelForUi(value = "") {
  if (value === "full-cycle") return "Full cycle";
  if (value === "explained-cycle") return "Explained cycle";
  if (value === "partial-cycle") return "Partial cycle";
  if (value === "final-proof-only") return "Final proof only";
  return value ? value.replace(/-/g, " ") : "Unknown";
}

function sourceTrailText(row = {}) {
  return [
    row.type,
    row.label,
    row.summary,
    row.note,
    row.evidence,
    row.subject,
    row.filename,
  ].filter(Boolean).join(" ");
}

function sourceTrailStagesForRow(row = {}) {
  const text = sourceTrailText(row);
  const stages = [];
  if (/\b(?:booking|booked|routing|flight route|paperwork|documentation|document(?:s)? attached|awb paperwork|cargo dimensions)\b/i.test(text)) stages.push("context");
  if (/\b(?:arrival|arrived|on[-\s]?hand|available|availability|notice of arrival|noa|pre[-\s]?alert|eta)\b/i.test(text)) stages.push("arrival");
  if (/\b(?:release|customs|entry|firms|1c|d\/?o|delivery order|clearance|cleared)\b/i.test(text)) stages.push("customs");
  if (/\b(?:ground fees?|terminal charges?|handling charges?|storage charges?|payment|paid|collect charges?|airline fees?)\b/i.test(text)) stages.push("fees");
  if (/\b(?:quote|rate|\$\s*\d|price|pickup rates?)\b/i.test(text)) stages.push("quote");
  if (/\b(?:award|approved|confirm to|selected|dispatched|assigned|door move|handle pickup\/delivery|handle pickup and delivery|will handle pickup)\b/i.test(text)) stages.push("dispatch");
  if (/\b(?:picked up|pickup complete|recovery complete|recovered|loaded|out for delivery|out for del|ofd|driver(?: is)? lining up|line[-\s]?up update)\b/i.test(text)) stages.push("pickup");
  if (/\b(?:delivered|delivery completed|successfully delivered|receiver|deliver(?:y)? was completed|completed delivery)\b/i.test(text)) stages.push("delivery");
  if (/\b(?:pod|proof of delivery|signed pod|pod attached|pod found|pod received|signed[-\s]?by|signature)\b/i.test(text)) stages.push("pod");
  if (/\b(?:invoice attached|invoice found|closeout|closed in tms|tms close|billing complete)\b/i.test(text)) stages.push("closeout");
  if (!stages.length && /\b(?:hold|problem|exception|mismatch|error|storage|detention|cannot|can't|blocked|pending|not released)\b/i.test(text)) stages.push("exception");
  return [...new Set(stages.filter(Boolean))];
}

function sourceTrailRowsForUi(shipment = {}) {
  const coverage = sourceCoverageForUi(shipment) || {};
  const directStages = new Set(coverage.stages || []);
  const rows = [
    ...(shipment.sourceEvents || []).map((event, index) => ({
      id: event.id || `event-${index}`,
      kind: "event",
      at: event.at || "",
      label: event.label || event.type || "Source event",
      detail: event.summary || event.evidence || "",
      proof: event.evidence || event.subject || "",
      threadId: event.threadId || "",
      messageId: event.messageId || "",
      filename: "",
      stage: sourceTrailStagesForRow(event)[0] || "context",
    })),
    ...(shipment.sourceProof || []).map((proof, index) => ({
      id: `proof-${proof.threadId || ""}-${proof.messageId || ""}-${proof.filename || index}`,
      kind: "proof",
      at: proof.at || "",
      label: proof.label || "Proof",
      detail: proof.note || proof.pdfEvidence?.note || proof.filename || "",
      proof: proof.filename || proof.pdfEvidence?.label || "",
      threadId: proof.threadId || "",
      messageId: proof.messageId || "",
      filename: proof.filename || "",
      stage: sourceTrailStagesForRow(proof)[0] || "context",
    })),
    ...((coverage.explainedMissingStages || [])
      .filter((item) => item?.stage && !directStages.has(item.stage))
      .map((item, index) => ({
        id: `explained-${item.stage}-${index}`,
        kind: "explained",
        at: "",
        label: `${item.stage.replace(/-/g, " ")} explained`,
        detail: item.reason || "",
        proof: item.confidence || "Explained by downstream proof",
        threadId: "",
        messageId: "",
        filename: "",
        stage: item.stage,
      }))),
    ...((coverage.inferredMissingStages || [])
      .filter((item) => item?.stage && !directStages.has(item.stage))
      .map((item, index) => ({
        id: `inferred-${item.stage}-${index}`,
        kind: "inferred",
        at: "",
        label: `${item.stage.replace(/-/g, " ")} inferred`,
        detail: item.reason || "",
        proof: item.directProofMissing ? "Direct source proof still missing" : item.confidence || "Inferred",
        threadId: "",
        messageId: "",
        filename: "",
        stage: item.stage,
      }))),
  ];
  return uniqueRowsByKey(rows, (row) =>
    [row.kind, row.label, row.detail, row.threadId, row.messageId, row.filename].filter(Boolean).join("|")
  )
    .sort((a, b) => {
      const aTime = Date.parse(a.at || "");
      const bTime = Date.parse(b.at || "");
      const aHasTime = Number.isFinite(aTime);
      const bHasTime = Number.isFinite(bTime);
      if (aHasTime || bHasTime) return (aHasTime ? aTime : 0) - (bHasTime ? bTime : 0);
      return String(a.label).localeCompare(String(b.label));
    })
    .slice(0, 14);
}

function renderCompletedSourceStageStrip(shipment = {}) {
  const coverage = sourceCoverageForUi(shipment) || {};
  const stages = new Set(coverage.stages || []);
  const missing = new Set(coverage.missingPreDeliveryStages || []);
  const explained = new Set((coverage.explainedMissingStages || []).map((item) => item.stage).filter(Boolean));
  const inferred = new Set((coverage.inferredMissingStages || []).map((item) => item.stage).filter(Boolean));
  const stageRows = [
    ["context", "Context"],
    ["arrival", "Arrival"],
    ["customs", "Customs"],
    ["dispatch", "Dispatch"],
    ["pickup", "Pickup"],
    ["delivery", "Delivery"],
    ["pod", "POD"],
    ["closeout", "Closeout"],
  ].filter(([key]) => key !== "context" || stages.has("context"));
  return `
    <div class="source-trail-stages">
      ${stageRows.map(([key, label]) => {
        const status = stages.has(key) ? "done" : explained.has(key) ? "explained" : inferred.has(key) ? "inferred" : missing.has(key) ? "missing" : "quiet";
        return `<span class="${status}"><b>${escapeHtml(label)}</b><em>${status === "explained" ? "Explained" : status === "inferred" ? "Inferred" : status === "missing" ? "Missing" : status === "done" ? "Found" : "No proof"}</em></span>`;
      }).join("")}
    </div>
  `;
}

function renderCompletedSourceTrailRows(shipment = {}) {
  const rows = sourceTrailRowsForUi(shipment);
  if (!rows.length) return `<div class="action-empty">No source trail events have been backfilled yet.</div>`;
  return `
    <div class="source-trail-list">
      ${rows.map((row) => `
        <article class="${escapeHtml([row.stage || "context", ["inferred", "explained"].includes(row.kind) ? row.kind : ""].filter(Boolean).join(" "))}">
          <span>${escapeHtml(shortText(row.stage || row.kind, "Source", 18))}${row.at ? `<time>${escapeHtml(formatShortDate(row.at))}</time>` : ""}</span>
          <strong>${escapeHtml(shortText(row.label, "Source event", 76))}</strong>
          ${row.detail ? `<p>${escapeHtml(shortText(row.detail, "", 138))}</p>` : ""}
          ${row.proof ? `<small>${escapeHtml(shortText(row.proof, "", 110))}</small>` : ""}
          ${(row.threadId || row.messageId) ? `<em>${escapeHtml([row.threadId ? `thread ${row.threadId}` : "", row.messageId ? `msg ${row.messageId}` : ""].filter(Boolean).join(" · "))}</em>` : ""}
        </article>
      `).join("")}
    </div>
  `;
}

function renderCompletedSourceDetail() {
  const shipment = completedSourceShipmentByAwb(state.selectedCompletedSourceAwb);
  if (!shipment) {
    state.selectedCompletedSourceAwb = "";
    $("detailPane").innerHTML = "";
    closeDetail();
    return;
  }
  const coverage = sourceCoverageForUi(shipment) || {};
  const unresolved = Array.isArray(coverage.unresolvedMissingPreDeliveryStages)
    ? coverage.unresolvedMissingPreDeliveryStages
    : coverage.missingPreDeliveryStages || [];
  const missing = unresolved.join(", ");
  const inferredStages = (coverage.inferredMissingStages || []).map((item) => item.stage).filter(Boolean);
  const action = sourceCoverageNeedsBackfillForUi(shipment) ? completedSourceBackfillActionForUi(shipment) : null;
  const sourceState = action ? sourceBackfillStatusForAction(action) : null;
  $("detailPane").innerHTML = `
    <div class="detail-header">
      <div class="detail-title">
        <div class="detail-title-row">
          ${renderAwbTitle(shipment.awb, "h2", "awb-title detail-awb-title")}
        </div>
        <p>${escapeHtml([shipment.station, shipment.client || shipment.consignee, "completed source trail"].filter(Boolean).join(" · "))}</p>
      </div>
      <button class="icon-button" data-close-detail type="button" aria-label="Close completed source detail">×</button>
    </div>

    <section class="detail-brief completed-source-brief">
      <div class="brief-kicker">
        <span class="${coverage.needsHistoricalBackfill ? "watch" : "ok"}">${escapeHtml(sourceCoverageLabelForUi(coverage.completeness))}</span>
        <em>${escapeHtml(`${coverage.sourceEventCount || 0} events · ${coverage.sourceProofCount || 0} proof rows`)}</em>
      </div>
      <h3>${escapeHtml(coverage.needsHistoricalBackfill ? `Missing direct ${missing || "lifecycle"} proof` : coverage.explanation ? "Replayable source trail with explained gap" : "Replayable source trail")}</h3>
      ${coverage.backfillReason || coverage.explanation ? `<p>${escapeHtml(coverage.backfillReason || coverage.explanation)}</p>` : ""}
      ${inferredStages.length ? `<p>${escapeHtml(`Inferred from downstream execution: ${[...new Set(inferredStages)].join(", ")}. Direct source is still marked separately.`)}</p>` : ""}
      ${renderCompletedSourceStageStrip(shipment)}
      ${action ? `
        <div class="source-trail-actions">
          <button class="mini-button primary" data-confirm-action="${escapeHtml(action.id)}" type="button" ${sourceState.queued || sourceState.sending ? "disabled" : ""}>${escapeHtml(sourceState.buttonLabel)}</button>
          <span>${escapeHtml(sourceBackfillStatusNote(sourceState, action))}</span>
        </div>
      ` : ""}
    </section>

    <section class="section operator-section completed-source-trail">
      <h3>Source Trail</h3>
      ${renderCompletedSourceTrailRows(shipment)}
    </section>
  `;
  bindDetailEvents();
  syncDetailShell();
  resetDetailScrollOnOpen(`completed-source:${opsBrainAwbKey(shipment.awb)}`);
}

function renderDetail() {
  if (state.selectedCompletedSourceAwb) {
    renderCompletedSourceDetail();
    return;
  }

  if (state.selectedVisualGroupKey) {
    renderVisualGroupDetail();
    return;
  }

  if (state.selectedGroupId) {
    renderGroupDetail();
    return;
  }

  const shipment = state.shipments.find((item) => item.id === state.selectedId) || (state.query ? null : state.shipments[0]);
  if (!shipment) {
    $("detailPane").innerHTML = "";
    closeDetail();
    return;
  }

  const metaLine = [operationalStation(shipment), shipment.airline, shipment.client].filter(Boolean).join(" · ");
  const draftSummary = draftWorkSummary(shipment);
  const headerMetaLine = [metaLine, draftSummary?.detail].filter(Boolean).join(" · ");

  $("detailPane").innerHTML = `
    <div class="detail-header">
      <div class="detail-title">
        <div class="detail-title-row">
          ${renderAwbTitle(shipment.awb, "h2", "awb-title detail-awb-title")}
        </div>
        <p>${headerMetaLine || "Shipment detail"}</p>
      </div>
      <button class="icon-button" data-close-detail type="button" aria-label="Close shipment detail">×</button>
    </div>

    ${renderShipmentDecisionStrip(shipment)}

    ${renderShipmentDryFacts(shipment)}

    ${renderShipmentInbox(shipment)}

    ${renderDetailAiConsole(shipment)}

    ${renderActionSection(shipment)}
  `;

  bindDetailEvents();
  syncDetailShell();
  resetDetailScrollOnOpen(`shipment:${shipment.id}`);
}

function renderGroupDetail() {
  const group = state.groups.find((item) => item.groupId === state.selectedGroupId);
  const shipments = group ? (group.shipmentIds || []).map(shipmentById).filter(Boolean) : [];
  if (!group || !shipments.length) {
    $("detailPane").innerHTML = "";
    closeDetail();
    return;
  }

  $("detailPane").innerHTML = `
    <div class="detail-header">
      <div>
        <h2>${shipments.length} AWBs together</h2>
        <p>${group.station || "N/A"} · ${group.client || "Client unknown"} · ${group.consignee || "Consignee unknown"}</p>
      </div>
      <button class="icon-button" data-close-detail type="button" aria-label="Close group detail">×</button>
    </div>

    <section class="situation">
      <span class="level-dot ${groupActionClass(group)}">${groupActionLabel(group)}</span>
      <h3>${group.action || groupStatusLine(group)}</h3>
      <p>${groupStatusLine(group)} · ${groupCustomsLine(group)} customs · ${groupFreightLine(group)} dispatch</p>
    </section>

    <section class="section">
      <h3>Status</h3>
      <div class="status-board">
        <div><span>ETA</span><strong>${shortText(group.eta, "Unknown", 44)}</strong></div>
        <div><span>Flight</span><strong>${group.flight && group.flight !== "flight unknown" ? group.flight : "Unknown"}</strong></div>
        <div><span>Customs</span><strong>${groupCustomsLine(group)}</strong></div>
        <div><span>Freight</span><strong>${groupFreightLine(group)}</strong></div>
      </div>
    </section>

    <section class="section">
      <h3>Destination</h3>
      <div class="summary-list compact">
        <div><span>Consignee</span><strong>${group.consignee || "Unknown"}</strong></div>
        <div><span>Address</span><strong>${shortText(cleanAddress(group.deliveryAddress, group.consignee), "Unknown", 110)}</strong></div>
        <div><span>Pieces</span><strong>${group.totalPieces || "Unknown"}</strong></div>
        <div><span>Weight</span><strong>${group.totalWeightKg ? `${group.totalWeightKg} kg` : "Unknown"}</strong></div>
      </div>
    </section>

    <section class="section">
      <h3>AWBs</h3>
      <div class="group-list">
        ${shipments
          .map(
            (shipment) => `
              <button class="group-shipment" data-open-shipment="${shipment.id}" type="button">
                <strong>${shipment.awb}</strong>
                <span>${shipmentHeadline(shipment)}</span>
                <small>${movementStage(shipment).label} · ${customsLine(shipment)} · ${dispatchStage(shipment).label}</small>
              </button>
            `,
          )
          .join("")}
      </div>
    </section>

    ${
      group.blockers?.length
        ? `<section class="section">
            <h3>Gaps</h3>
            <div class="gap-list">${group.blockers.slice(0, 8).map((item) => `<span>${item}</span>`).join("")}</div>
          </section>`
        : ""
    }
  `;

  bindDetailEvents();
  syncDetailShell();
  resetDetailScrollOnOpen(`group:${group.groupId}`);
}

function renderVisualGroupDetail() {
  const group = visualGroups(state.shipments).find((item) => item.key === state.selectedVisualGroupKey);
  if (!group) {
    $("detailPane").innerHTML = "";
    closeDetail();
    return;
  }

  const primary = group.primary;
  const counts = cardCounts(group);
  const meta = lifecycleMeta(group.bucket);
  const lifecycle = lifecycleState(primary);
  const movement = movementStage(primary);
  const statusClass = lifecycle.tone === "risk" ? "problem" : lifecycle.id === "ready" ? "ok" : "watch";
  const title = counts.total === 1 ? primary.awb : `${counts.total} AWBs`;
  const route = [group.station, primary.airline].filter(Boolean).join(" · ") || "Station unknown";
  const heroNextStep = shortText(nextStep(primary), "Review shipment", 110);
  const heroTitle = detailHeroTitle(meta.title, shortAction(primary), heroNextStep);
  const groupEvidence = (primary.opsState?.evidence?.length ? primary.opsState.evidence : [
    { label: "Tracking", note: movement.note },
    { label: "Email", note: primary.emailValidation?.summary || "" },
  ]);

  $("detailPane").innerHTML = `
    <div class="detail-header">
      <div>
        ${counts.total === 1 ? renderAwbTitle(primary.awb, "h2", "awb-title detail-awb-title") : `<h2>${escapeHtml(title)}</h2>`}
        <p>${route} · ${shortText(group.client, "Client unknown", 70)}</p>
      </div>
      <button class="icon-button" data-close-detail type="button" aria-label="Close group detail">×</button>
    </div>

    <section class="detail-hero">
      <span class="level-dot level-${statusClass}">${meta.title}</span>
      <h3>${heroTitle}</h3>
      ${detailHeroNote(heroTitle, heroNextStep)}
    </section>

    <section class="section">
      <h3>Picture</h3>
      ${renderTruthList([
        { label: "Tracking", value: movement.label, note: movement.note },
        { label: "Customs", value: customsLine(primary) },
        { label: "Pickup", value: brokerLine(primary) },
        { label: "ETA", value: group.eta || "Unknown" },
      ])}
    </section>

    <section class="section">
      <h3>Destination</h3>
      ${renderTruthList([
        { label: "Consignee", value: group.client },
        { label: "Address", value: cleanAddress(group.destination, group.client) || "Unknown" },
      ])}
    </section>

    ${
      counts.total > 1
        ? `<section class="section">
            <h3>AWBs</h3>
            <div class="group-list">
              ${group.shipments
                .map(
                  (shipment) => `
                    <button class="group-shipment" data-open-shipment="${shipment.id}" type="button">
                      <strong>${shipment.awb}</strong>
                      <span>${customsLine(shipment)} · ${brokerLine(shipment)}</span>
                    </button>
                  `,
                )
                .join("")}
            </div>
          </section>`
        : ""
    }

    ${renderProofList(groupEvidence)}

    ${renderVisualGroupActionSection(group)}
  `;

  bindDetailEvents();
  syncDetailShell();
  resetDetailScrollOnOpen(`visual:${group.key}`);
}

function renderVisualGroupActions(group) {
  if (group.shipments.length === 1) return renderActions(group.primary);

  const sections = group.shipments
    .map((shipment) => {
      const actions = renderActions(shipment);
      if (!actions) return "";
      const expanded = state.expandedGroupActions.has(shipment.id);
      return `
        <details class="group-action-block" data-group-action-row="${shipment.id}" ${expanded ? "open" : ""}>
          <summary>
            <span>
              <strong>${escapeHtml(shipment.awb)}</strong>
              <small>${groupActionSummary(shipment)}</small>
            </span>
            <em><span class="when-closed">Open</span><span class="when-open">Close</span></em>
          </summary>
          ${actions}
        </details>
      `;
    })
    .filter(Boolean);

  return sections.join("");
}

function renderVisualGroupActionSection(group) {
  const actions = renderVisualGroupActions(group);
  if (!actions) return "";
  return `
    <section class="section">
      <h3>Actions</h3>
      ${actions}
    </section>
  `;
}

function groupActionSummary(shipment) {
  const hasQuotes = uiQuoteActionsForShipment(shipment).length > 0;
  const hasAward = awardActionsForShipment(shipment).length > 0;
  const actionLabels = actionsForShipment(shipment)
    .map((action) => action.label)
    .filter(Boolean);
  const labels = [...(hasAward ? ["Award"] : []), ...(hasQuotes ? ["Quotes"] : []), ...actionLabels];
  return labels.length ? labels.join(" + ") : "Review";
}

function readyForPickupExecutionActions(shipment) {
  if (!currentReadyForPickupState(shipment)) return [];
  if (shipmentTruthComplete(shipment)) return [];
  if (physicalPickupBlockerText(shipment)) return [];
  if (pickupOrDeliveryMoving(shipment)) return [];
  const hasPickupOwner = freightHasAssignedPickupOwner(shipment);
  const broker = hasPickupOwner
    ? brokerLine(shipment) || shipment.freightBroker?.broker || shipment.freightBroker?.contactEmail || "pickup broker"
    : "";
  const station = [shipment.station, shipment.airline || shipment.handler].filter(Boolean).join(" / ") || "the airport";
  const reason = hasPickupOwner
    ? "Canonical truth says arrival, release, fees, and dispatch are ready, but pickup/loaded/POD proof is not in the packet."
    : "Canonical truth says the shipment is ready for pickup, but no pickup broker/dispatch owner is attached to the packet.";
  const action = airportDwellBaseAction(shipment, hasPickupOwner ? "broker-status-followup" : "operator-state-check", hasPickupOwner ? "Confirm pickup execution" : "Confirm pickup broker/dispatch path", {
    channel: "platform",
    priority: "high",
    targetName: broker || "Operator",
    targetRole: "pickup",
    reason,
    problem: hasPickupOwner ? "Ready for pickup; pickup execution is not proven." : "Ready for pickup; pickup owner is missing.",
    nextAction: hasPickupOwner
      ? `Confirm with ${broker} whether the freight left ${station}; collect loaded proof and POD.`
      : `Confirm who owns pickup from ${station}, then record the broker/carrier contact before chasing pickup and POD.`,
    timingStage: "ready-for-pickup",
    timingTrigger: hasPickupOwner ? "ready-for-pickup-execution" : "ready-pickup-owner-missing",
    timingSource: "shipment-truth-packets",
  });
  return [{
    ...action,
    workstream: "execution",
    sortTier: 0,
  }];
}

function actionsForShipment(shipment) {
  if (shipmentTruthComplete(shipment)) return [];
  const canonical = shipmentHasCanonicalAuthority(shipment);
  const visibleAction = (action) => ["gmail", "couriercloud", "tms", "couriercloud-tms", "platform", "companion", "ops-brain", "document"].includes(normalizeChannel(action.channel));
  const compactAction = (action) => !["quote-request", "broker-award", "tms-broker-award-experience"].includes(action.type);
  const currentAction = (action) => actionMatchesShipmentState(action, shipment);
  const embedded = [
    ...readyForPickupExecutionActions(shipment),
    ...stationFeeActionsForShipment(shipment),
    ...airportDwellActionsForShipment(shipment),
    ...(canonical ? [] : (shipment.recommendedActions || [])),
  ].filter((action) => visibleAction(action) && compactAction(action) && currentAction(action));
  const queued = canonical ? [] : state.actions.filter((action) => action.shipmentId === shipment.id && visibleAction(action) && compactAction(action) && currentAction(action));
  const byId = new Map([...embedded, ...queued].map((action) => [action.id, action]));
  return [...byId.values()].sort(compareActionCardsForUi);
}

function actionWorkstreamForUi(action = {}) {
  if (action.workstream) return action.workstream;
  if (action.type === "money-context-review") return "economics";
  if (["source-backfill", "station-contact-research", "carrier-tracking-refresh"].includes(action.type)) return "truth-repair";
  if (action.type === "prearrival-quote-decision") return "decision";
  return "execution";
}

function actionTierForUi(action = {}) {
  if (Number.isFinite(Number(action.sortTier))) return Number(action.sortTier);
  const workstream = actionWorkstreamForUi(action);
  if (workstream === "execution") return 0;
  if (workstream === "decision") return 1;
  if (workstream === "truth-repair") return 2;
  if (workstream === "economics") return 3;
  return 4;
}

function actionPriorityRankForUi(action = {}) {
  return {
    critical: 0,
    urgent: 0,
    high: 1,
    medium: 2,
    normal: 3,
    low: 4,
  }[String(action.priority || "normal").toLowerCase()] ?? 3;
}

function compareActionCardsForUi(a = {}, b = {}) {
  return (
    actionPriorityRankForUi(a) - actionPriorityRankForUi(b) ||
    actionTierForUi(a) - actionTierForUi(b) ||
    todayActionTypeRank(a) - todayActionTypeRank(b) ||
    String(a.label || "").localeCompare(String(b.label || ""))
  );
}

function actionPanelStatus(action) {
  const outboxStatus = outboxRequestStatus(outboxRequestForAction(action.id));
  const agentJob = activeJobForAction(action.id);
  const completedByAgent = agentJobCompleted(agentJob);
  const completedStatus = completedByAgent ? agentJobStatus(agentJob) : "";
  const effectiveStatus = completedStatus || outboxStatus || action.status || "suggested";
  return draftDisplayStatus(action, String(effectiveStatus).toLowerCase());
}

function activeActionPanelItem(action) {
  if (isHandledOpsBrainAction(action)) return false;
  const status = actionPanelStatus(action);
  if (["drafted", "sent", "succeeded", "cancelled", "canceled", "skipped"].includes(status)) return false;
  return true;
}

function draftActionsForShipment(shipment) {
  const rows = [
    ...quoteActionsForShipment(shipment),
    ...awardActionsForShipment(shipment),
    ...actionsForShipment(shipment),
  ].filter((action) => isVisibleDraftWork(action) && actionMatchesShipmentState(action, shipment));
  const byId = new Map(rows.map((action) => [action.id, action]));
  return [...byId.values()];
}

function draftWorkSummary(shipment) {
  const actions = draftActionsForShipment(shipment);
  if (!actions.length) return null;
  const tms = actions.some(isTmsAction);
  const awards = actions.filter((action) => action.type === "broker-award").length;
  const quotes = actions.filter((action) => action.type === "quote-request").length;
  let label = `${actions.length} draft${actions.length === 1 ? "" : "s"}`;
  if (awards && actions.length === awards) {
    label = "Award ready";
  } else if (quotes && actions.length === quotes) {
    label = `${quotes} quote${quotes === 1 ? "" : "s"}`;
  } else if (tms && actions.length === 1) {
    label = "TMS alert";
  }
  return {
    count: actions.length,
    label,
    detail: `${actions.length} agent draft${actions.length === 1 ? "" : "s"}`,
    tms,
  };
}

function queuedActionForShipment(shipment, actionId) {
  return state.actions.find((item) => item.id === actionId && item.shipmentId === shipment.id) ||
    (shipment.recommendedActions || []).find((item) => item.id === actionId);
}

function generatedActionsForShipment(shipment, type) {
  const canonical = shipmentHasCanonicalAuthority(shipment);
  const rows = [
    ...(canonical ? [] : (shipment.recommendedActions || [])),
    ...(canonical ? [] : state.actions.filter((action) => action.shipmentId === shipment.id)),
  ].filter((action) => action.type === type);
  const byId = new Map(rows.map((action) => [action.id, action]));
  return [...byId.values()].sort((a, b) => {
    const brokerA = quoteBrokers.findIndex((broker) => broker.email.toLowerCase() === String(a.targetEmail || "").toLowerCase());
    const brokerB = quoteBrokers.findIndex((broker) => broker.email.toLowerCase() === String(b.targetEmail || "").toLowerCase());
    const orderA = brokerA === -1 ? 99 : brokerA;
    const orderB = brokerB === -1 ? 99 : brokerB;
    return orderA - orderB || String(a.targetName || "").localeCompare(String(b.targetName || ""));
  });
}

function quoteAmountLabel(quote) {
  if (quote?.rate) return quote.rate;
  const amount = Number(quote?.amount);
  if (!Number.isFinite(amount)) return "rate unknown";
  return amount % 1 === 0 ? `$${amount}` : `$${amount.toFixed(2)}`;
}

function brokerAliasProfile(value) {
  const text = String(value || "");
  return freightBrokerAliases.find((profile) =>
    profile.aliases.some((alias) => new RegExp(`\\b${alias.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(text))
  );
}

function brokerNamesMatch(left, right) {
  const leftText = String(left || "").trim();
  const rightText = String(right || "").trim();
  if (!leftText || !rightText) return false;
  const leftProfile = brokerAliasProfile(leftText);
  const rightProfile = brokerAliasProfile(rightText);
  if (leftProfile || rightProfile) {
    return (leftProfile?.name || leftText).toLowerCase() === (rightProfile?.name || rightText).toLowerCase();
  }
  return leftText.toLowerCase() === rightText.toLowerCase();
}

function sameQuote(left, right) {
  return (
    brokerNamesMatch(left?.broker, right?.broker) &&
    Number(left?.amount) === Number(right?.amount)
  );
}

function moneyDeltaLabel(amount) {
  const value = Number(amount);
  if (!Number.isFinite(value) || value <= 0) return "";
  return value % 1 === 0 ? `+$${value}` : `+$${value.toFixed(2)}`;
}

function compactQuoteDecisionQuote(quote) {
  if (!quote) return null;
  return {
    broker: quote.broker || "",
    amount: Number.isFinite(Number(quote.amount)) ? Number(quote.amount) : null,
    rate: quoteAmountLabel(quote),
    service: quote.service || "",
  };
}

function quoteDecisionForAction(shipment, quote, recommended, quotes) {
  const lowest = quotes.find(isActionablePickupQuote) || quotes[0] || null;
  const selectedByThread = shipment.freightBroker?.quoteDecision?.status === "override-selected";
  const recommendedMatch = sameQuote(quote, recommended);
  const lowestMatch = sameQuote(quote, lowest);
  const delta = lowest && Number.isFinite(Number(quote.amount)) && Number.isFinite(Number(lowest.amount))
    ? Number(quote.amount) - Number(lowest.amount)
    : 0;
  const basis = recommendedMatch
    ? selectedByThread
      ? "selected"
      : lowestMatch
      ? "lowest"
      : "recommended"
    : "override-option";
  const summary = basis === "selected"
    ? `Selected in email: ${quote.broker} ${quoteAmountLabel(quote)}`
    : basis === "lowest"
    ? `Lowest actionable: ${quote.broker} ${quoteAmountLabel(quote)}`
    : basis === "recommended"
    ? `Recommended: ${quote.broker} ${quoteAmountLabel(quote)}`
    : `Override option: ${quote.broker} ${quoteAmountLabel(quote)}${delta > 0 ? ` (${moneyDeltaLabel(delta)})` : ""}`;

  return {
    basis,
    summary,
    selectedByThread,
    isRecommended: recommendedMatch,
    isLowest: lowestMatch,
    deltaFromLowest: delta,
    totalQuotes: quotes.length,
    quote: compactQuoteDecisionQuote(quote),
    lowest: compactQuoteDecisionQuote(lowest),
    recommended: compactQuoteDecisionQuote(recommended),
  };
}

function contactEmailList(value) {
  return [...new Set(String(value || "").match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])]
    .map((email) => email.toLowerCase());
}

function isPickupDeliveryQuote(quote) {
  if (quote?.category === "pickup-delivery") return true;
  if (["station-cost", "customs-cost", "air-freight"].includes(quote?.category)) return false;
  const text = [
    quote?.broker,
    quote?.service,
    quote?.rate,
    ...(Array.isArray(quote?.evidence) ? quote.evidence : [quote?.evidence]),
  ].filter(Boolean).join(" ").toLowerCase();
  if (/\b(cargosprint|payment|paid|receipt|amount paid|station fee|terminal fee|storage|last free|free day|demurrage|not delivery|not pickup|customs bond|bond fee|7501|dut(?:y|ies)|clearance|customs|handling)\b/.test(text)) {
    return false;
  }
  const pickupSignals = /\b(pickup|delivery|deliver|truck|trucker|straight|box truck|flatbed|hotshot|ltl|recover)\b/.test(text);
  if (pickupSignals) return true;
  return false;
}

function quoteReviewBlockers(quote) {
  const text = [
    quote?.broker,
    quote?.service,
    quote?.rate,
    ...(Array.isArray(quote?.evidence) ? quote.evidence : [quote?.evidence]),
  ].filter(Boolean).join(" ").toLowerCase();
  const blockers = [];
  if (quote?.stale || quote?.actionable === false) blockers.push("quote superseded by newer operating facts");
  if (!contactEmailList(quote?.contactEmail).length) blockers.push("broker email missing");
  if (/\b(address ambiguous|ambiguous address|confirm(?:ing)? address|address (?:needs|must be) confirmed|address mismatch|wrong address)\b/.test(text)) {
    blockers.push("address needs confirmation");
  }
  return blockers;
}

function isActionablePickupQuote(quote) {
  return isPickupDeliveryQuote(quote) && quoteReviewBlockers(quote).length === 0;
}

function memoryDateTime(value) {
  const date = Date.parse(`${String(value || "").slice(0, 10)}T12:00:00`);
  return Number.isFinite(date) ? date : 0;
}

function storageRiskForShipment(shipment, now = new Date()) {
  const storage = storageMemoryForShipment(shipment);
  if (!storage) return null;
  if (["delivered", "airport-picked-up"].includes(shipment.pickupStatus)) return null;
  if (!(shipment.arrivalStatus === "arrived" || shipment.pickupStatus === "ready")) return null;

  const today = Date.parse(`${now.toISOString().slice(0, 10)}T12:00:00`);
  const text = storageTextBlob(storage);
  const startsValue = storage.storageStartsAt || storageDateFromText(text, "storage starts?|storage start date");
  const lastFreeValue = storage.lastFreeDay || storageDateFromText(text, "last free(?: day)?");
  const accruingValue = storage.storageAccruingSince || storageDateFromText(text, "storage accruing since|storage accrues since");
  const startsAt = memoryDateTime(startsValue);
  const lastFree = memoryDateTime(lastFreeValue);
  const accruingSince = memoryDateTime(accruingValue);
  const rate = compactStorageRate(storage.dailyStorageRate) || compactStorageRate(text);

  if (accruingSince && accruingSince <= today) {
    return {
      label: "Storage accruing",
      detail: `Since ${compactStorageDate(accruingValue) || accruingValue}${rate ? ` · ${rate}` : ""}`,
      chip: rate || "Storage accruing",
    };
  }
  if (startsAt && startsAt <= today) {
    return {
      label: "Storage starts",
      detail: `${compactStorageDate(startsValue) || startsValue}${rate ? ` · ${rate}` : ""}`,
      chip: rate ? `Storage · ${rate}` : "Storage starts",
    };
  }
  if (lastFree && lastFree <= today) {
    const storageLikelyStarted = lastFree < today;
    return {
      label: storageLikelyStarted ? "Storage likely started" : "Last free day",
      detail: `${compactStorageDate(lastFreeValue) || lastFreeValue}${rate ? ` · ${rate}` : ""}`,
      chip: storageLikelyStarted ? "Storage" : "Last free day",
    };
  }
  return null;
}

function quoteRecordsForShipment(shipment) {
  const quotes = Array.isArray(shipment.freightBroker?.quotes) ? shipment.freightBroker.quotes : [];
  const recommended = shipment.freightBroker?.recommendedAward;
  const rows = [...quotes];
  if (recommended && !rows.some((quote) =>
    String(quote.broker || "").toLowerCase() === String(recommended.broker || "").toLowerCase() &&
    Number(quote.amount) === Number(recommended.amount)
  )) {
    rows.push(recommended);
  }
  return rows
    .filter((quote) => quote?.broker && Number.isFinite(Number(quote.amount)) && isPickupDeliveryQuote(quote))
    .sort((a, b) => Number(a.amount) - Number(b.amount) || String(a.broker).localeCompare(String(b.broker)));
}

function recommendedQuoteForShipment(shipment) {
  if (operationalException(shipment) || shipment.freightBroker?.quoteDecision?.status === "stale-operational-exception") {
    return null;
  }
  const recommended = shipment.freightBroker?.recommendedAward;
  if (recommended?.broker && Number.isFinite(Number(recommended.amount)) && isActionablePickupQuote(recommended)) {
    return recommended;
  }
  return quoteRecordsForShipment(shipment).find(isActionablePickupQuote) || null;
}

function prearrivalQuoteDecisionMatchesShipmentState(shipment) {
  if (!shipment || isHandled(shipment)) return false;
  if (["delivered", "airport-picked-up"].includes(shipment.pickupStatus) || freightPickedUpFromAirport(shipment)) return false;
  if (shipment.arrivalStatus === "arrived" || shipment.pickupStatus === "ready") return false;
  if (shipment.emailValidation?.status === "email-conflict") return false;
  if (/hold|exam/i.test(shipment.customsBroker?.status || "")) return false;
  if (shipment.freightBroker?.selectedBroker || shipment.freightBroker?.awardedBroker) return false;
  if (/\b(awarded|dispatched|pickup-confirmed|pickup-window|confirmed|assigned|pickup-blocked|release-not-in-system)\b/i.test(shipment.freightBroker?.status || "")) return false;
  return Boolean(recommendedQuoteForShipment(shipment));
}

function canAwardPickupBroker(shipment) {
  if (operationalException(shipment)) return false;
  if (["delivered", "airport-picked-up"].includes(shipment.pickupStatus)) return false;
  if (!(shipment.arrivalStatus === "arrived" || shipment.pickupStatus === "ready")) return false;
  if (!isCustomsResolvedStatus(shipment.customsBroker?.status || "")) return false;
  if (shipment.freightBroker?.cargoAvailable === false || shipment.freightBroker?.cargoReleased === false) {
    return false;
  }
  return true;
}

function awardBlockersForShipment(shipment) {
  const blockers = [];
  if (["delivered", "airport-picked-up"].includes(shipment.pickupStatus)) {
    blockers.push("already picked up");
  } else if (!(shipment.arrivalStatus === "arrived" || shipment.pickupStatus === "ready")) {
    blockers.push("arrival pending");
  }
  if (!isCustomsResolvedStatus(shipment.customsBroker?.status || "")) blockers.push("customs pending");
  if (shipment.freightBroker?.cargoAvailable === false) blockers.push("availability not confirmed");
  if (shipment.freightBroker?.cargoReleased === false) blockers.push("release not confirmed");
  return blockers;
}

function awardActionsForShipment(shipment) {
  if (!canAwardPickupBroker(shipment)) return [];
  return [
    ...generatedActionsForShipment(shipment, "broker-award"),
    ...generatedActionsForShipment(shipment, "tms-broker-award-experience"),
  ];
}

function quoteActionsForShipment(shipment) {
  if (shouldApplyElpPickupMemory(shipment)) return [];
  return generatedActionsForShipment(shipment, "quote-request");
}

function uiQuoteActionsForShipment(shipment) {
  return quoteActionsForShipment(shipment)
    .filter((action) => actionMatchesShipmentState(action, shipment));
}

function allQuoteActionsForShipment(shipmentId) {
  const shipment = state.shipments.find((item) => item.id === shipmentId);
  return shipment ? quoteActionsForShipment(shipment) : [];
}

function brainProposedActions() {
  return (state.opsBrainChatHistory || []).flatMap((message) => message.actions || []);
}

function findActionById(actionId) {
  return storedOpsBrainAction(actionId) ||
    state.actions.find((item) => item.id === actionId) ||
    state.shipments.flatMap((shipment) => shipment.recommendedActions || []).find((item) => item.id === actionId) ||
    state.shipments.flatMap((shipment) => actionsForShipment(shipment)).find((item) => item.id === actionId) ||
    state.shipments.flatMap((shipment) => quoteActionsForShipment(shipment)).find((item) => item.id === actionId) ||
    state.shipments.flatMap((shipment) => awardActionsForShipment(shipment)).find((item) => item.id === actionId) ||
    completedSourceBackfillActionsForUi(Infinity).find((item) => item.id === actionId) ||
    brainProposedActions().find((item) => item.id === actionId);
}

function activeJobForAction(actionId) {
  const transient = state.actionStatusById?.[actionId] || {};
  return state.agentJobs.find((job) => {
    if (!agentJobIsDraftMode(job) && !agentJobIsTmsAction(job)) return false;
    const payload = job.payload || {};
    return payload.actionId === actionId || payload.action?.id === actionId ||
      (transient.agentJobId && job.id === transient.agentJobId);
  });
}

function activeAgentJobForOutboxRequest(request) {
  if (!request) return null;
  return state.agentJobs.find((job) => {
    if (!activeAgentJobStatuses.has(String(job.status || "").toLowerCase())) return false;
    const payload = job.payload || {};
    return (
      (request.agentJobId && job.id === request.agentJobId) ||
      (request.id && payload.outboxRequestId === request.id) ||
      (request.actionId && payload.actionId === request.actionId)
    );
  }) || null;
}

function staleQueuedOutboxRequest(request) {
  if (!request) return false;
  const status = String(request.status || "").toLowerCase();
  if (
    ["sent", "drafted", "failed"].includes(status) ||
    request.sentAt ||
    request.draftedAt ||
    request.gmailMessageId ||
    request.gmailDraftId ||
    request.draftId
  ) return false;
  if (activeAgentJobForOutboxRequest(request)) return false;
  if (!activeOutboxStatuses.has(status) && !request.queuedAt) return false;
  const queuedAt = Date.parse(request.queuedAt || request.createdAt || "");
  return Number.isFinite(queuedAt) && Date.now() - queuedAt > outboxStaleAfterMs;
}

function outboxRequestStatus(request) {
  const status = String(request?.status || "").toLowerCase();
  if (status === "sent") return requestIsDraftMode(request) ? "drafted" : "sent";
  if (
    status === "drafted" ||
    request?.draftedAt ||
    request?.gmailDraftId ||
    request?.draftId ||
    (requestIsDraftMode(request) && request?.sentAt)
  ) return "drafted";
  if (staleQueuedOutboxRequest(request)) return "failed";
  if (activeOutboxStatuses.has(status)) {
    return status === "validated" ? "queued" : status;
  }
  if (status === "failed") return "failed";
  return status || "";
}

function outboxRequestForAction(actionId) {
  const transient = state.actionStatusById?.[actionId] || {};
  return state.outboxRequests.find((request) =>
    request.actionId === actionId ||
    request.id === transient.outboxRequestId ||
    request.agentJobId === transient.agentJobId
  );
}

function persistedActionStatus(shipment, actionId) {
  const history = (shipment.actionHistory || []).find((event) => event.actionId === actionId);
  const job = activeJobForAction(actionId);
  if (job) {
    const status = agentJobStatus(job);
    return {
      status,
      queuedAt: job.created_at,
      draftedAt: status === "drafted" ? job.completed_at : "",
      sentAt: status === "sent" ? job.completed_at : "",
      agentJobId: job.id,
      outboxRequestId: job.payload?.outboxRequestId || "",
    };
  }
  const request = outboxRequestForAction(actionId);
  const outboxStatus = outboxRequestStatus(request);
  if (request && outboxStatus && outboxStatus !== "suggested") {
    return {
      status: outboxStatus,
      queuedAt: request.queuedAt || request.createdAt || "",
      draftedAt: outboxStatus === "drafted" ? request.draftedAt || request.completedAt || "" : "",
      sentAt: outboxStatus === "sent" ? request.sentAt || request.completedAt || "" : "",
      failedAt: outboxStatus === "failed" ? request.failedAt || request.updatedAt || "" : "",
      agentJobId: request.agentJobId || "",
      outboxRequestId: request.id,
      gmailDraftId: request.gmailDraftId || request.draftId || "",
      gmailMessageId: request.gmailMessageId || "",
      gmailThreadId: request.gmailThreadId || "",
      lastError: request.lastError || "",
    };
  }
  if (!history || history.status === "suggested") return null;
  const historyStatus = draftDisplayStatus(history, history.status);
  return {
    status: historyStatus,
    queuedAt: historyStatus === "queued" ? history.at : "",
    draftedAt: historyStatus === "drafted" ? history.at : "",
    sentAt: historyStatus === "sent" ? history.at : "",
    outboxRequestId: history.id,
  };
}

function agentJobCompleted(job) {
  return job?.status === "succeeded" && (job.result?.sent || job.result?.drafted);
}

function actionCompleteLabel(job) {
  if (job?.job_type === "complete_tms_pod_closeout") return "Closed POD";
  if (agentJobIsTmsAction(job)) return "Sent";
  return agentJobIsDraftMode(job) ? "Drafted" : "Done";
}

function agentJobLine(job) {
  if (!job) return "";
  const isDraft = agentJobIsDraftMode(job);
  const isTms = agentJobIsTmsAction(job);
  const isPodCloseout = job.job_type === "complete_tms_pod_closeout";
  const isGmail = isDraft;
  const prefix = autonomousDraftPrefix(job);
  if (job.status === "queued") return isPodCloseout ? "POD closeout queued" : isTms ? "TMS alert queued" : isDraft ? `${prefix}draft pending` : "Queued";
  if (job.status === "running") return isPodCloseout ? "Closing POD in TMS" : isTms ? "Sending TMS alert" : isDraft ? `${prefix}creating Gmail draft` : "Agent running";
  if (job.status === "failed") return `Agent failed: ${job.last_error || "check worker logs"}`;
  if (job.status === "waiting_external") return isGmail ? "Waiting for Gmail connector" : "Waiting for external connector";
  if (agentJobCompleted(job)) return [actionCompleteLabel(job), formatShortDate(job.completed_at)].filter(Boolean).join(" ");
  if (job.status === "succeeded") return "Agent completed";
  return "";
}

function actionStatusLine(action) {
  if (isDocumentAction(action)) {
    const transient = state.actionStatusById?.[action.id] || {};
    if (state.sendingActions.has(action.id) || transient.status === "generating") return "Generating PDF";
    if (action.status === "generated" || transient.status === "generated") {
      return ["PDF generated", transient.fileName || action.fileName || ""].filter(Boolean).join(" · ");
    }
    if (action.status === "failed" || transient.status === "failed") return "PDF failed - tap Generate to retry";
    return "Generate PDF only";
  }
  if (isPlatformAlertAction(action)) {
    const transient = state.actionStatusById?.[action.id] || {};
    const status = transient.status || action.status || "";
    if (isSourceBackfillAction(action)) {
      const sourceStatus = sourceBackfillStatusForAction(action);
      if (sourceStatus.sending) return "Recording source repair";
      if (sourceStatus.blocked) return "Source repair blocked by older repair job";
      if (sourceStatus.status === "cron-owned") return "Source repair owned by direct Gmail";
      if (sourceStatus.status === "running") return "Source backfill running";
      if (sourceStatus.status === "waiting_external") return "Source backfill waiting for processor";
      if (["queued", "validated"].includes(sourceStatus.status)) return "Source backfill queued";
      if (sourceStatus.status === "recorded") return "Source backfill recorded";
      if (["succeeded", "done", "completed"].includes(sourceStatus.status)) return "Source backfill complete";
      if (sourceStatus.failed) return "Source backfill failed - tap Backfill to retry";
      return "Needs source backfill";
    }
    if (isMoneyContextAction(action)) {
      const moneyStatus = moneyRefreshStatusForAction(action);
      if (moneyStatus.sending) return "Checking TMS charges";
      if (moneyStatus.status === "running") return "TMS charge check running";
      if (moneyStatus.status === "waiting_external") return "TMS charge check waiting";
      if (["queued", "validated"].includes(moneyStatus.status)) return "TMS charge check queued";
      if (moneyStatus.status === "recorded") return "TMS charge check recorded";
      if (["succeeded", "done", "completed"].includes(moneyStatus.status)) return "TMS charge check complete";
      if (moneyStatus.failed) return "TMS charge check failed - confirm manually";
      return "Needs TMS charge confirmation";
    }
    if (isCarrierTrackingRefreshAction(action)) {
      const trackingStatus = carrierTrackingRefreshStatusForAction(action);
      if (trackingStatus.sending) return carrierActionNeedsFlightStatus(action) ? "Checking flight status" : "Checking movement";
      if (trackingStatus.status === "running") return "Movement check running";
      if (trackingStatus.status === "waiting_external") return "Movement check waiting";
      if (["queued", "validated"].includes(trackingStatus.status)) return "Movement check queued";
      if (trackingStatus.status === "recorded") return "Movement check recorded";
      if (["succeeded", "done", "completed"].includes(trackingStatus.status)) return "Movement check complete";
      if (trackingStatus.failed) return "Movement check failed - confirm flight/station";
      return "Needs movement confirmation";
    }
    if (isStationFeeAction(action)) return "Needs fee confirmation";
    if (isPrearrivalQuoteDecisionAction(action)) return "Needs quote decision";
    if (isStationContactResearchAction(action)) return "Save verified station contact";
    if (isReleaseContactGapAction(action)) return "Save pickup broker contact";
    if (isOperatorStateCheckAction(action)) return "Save structured state outcome";
    if (isHandledOpsBrainAction(action)) return "Resolved in Brain";
    if (action.type === "operator-state-check") return "Needs your update";
    return "Needs your call";
  }
  const aiPrefix = autonomousDraftPrefix(action);
  const agentJob = activeJobForAction(action.id);
  const agentLine = agentJobLine(agentJob);
  if (agentLine) return agentLine;
  const outboxRequest = outboxRequestForAction(action.id);
  const outboxStatus = outboxRequestStatus(outboxRequest);
  const outboxAiPrefix = autonomousDraftPrefix(outboxRequest) || aiPrefix;
  if (outboxStatus === "queued" || outboxStatus === "running" || outboxStatus === "waiting_external") {
    return isTmsPodAction(action) ? "POD closeout queued" : isTmsAction(action) ? "TMS alert queued" : `${outboxAiPrefix}draft pending`;
  }
  if (outboxStatus === "drafted") {
    const draftedAt = formatShortDate(outboxRequest.draftedAt || outboxRequest.completedAt);
    return isTmsAction(action)
      ? [`${outboxAiPrefix}${isTmsPodAction(action) ? "POD closeout queued" : "TMS alert queued"}`, draftedAt].filter(Boolean).join(" ")
      : [`${outboxRequest.gmailDraftId || outboxRequest.draftId ? "Gmail draft created" : `${outboxAiPrefix}drafted`}`, draftedAt].filter(Boolean).join(" ");
  }
  if (outboxStatus === "sent") {
    const label = requestIsDraftMode(outboxRequest) ? "Drafted" : "Sent";
    const completedAt = formatShortDate(outboxRequest.sentAt || outboxRequest.completedAt);
    return isTmsAction(action)
      ? [isTmsPodAction(action) ? "POD closed in TMS" : "Sent from TMS", completedAt].filter(Boolean).join(" ")
      : [label, completedAt].filter(Boolean).join(" ");
  }
  if (outboxStatus === "failed") {
    return staleQueuedOutboxRequest(outboxRequest)
      ? "Draft expired - tap Draft to retry"
      : "Draft failed - tap Draft to retry";
  }
  if (state.sendingActions.has(action.id)) return isTmsPodAction(action) ? "Closing POD" : isTmsAction(action) ? "Sending TMS alert" : "Drafting";
  if (action.safety?.mode === "tms-experience" || isTmsAction(action)) {
    if (isTmsPodAction(action)) return action.missing?.length ? action.missing.join(", ") : "Approve POD closeout";
    return action.targetEmail ? `Send from TMS to ${action.targetEmail}` : "Broker email needed";
  }
  if (action.status === "drafted") {
    const transient = state.actionStatusById?.[action.id] || {};
    return [
      action.gmailDraftId || transient.gmailDraftId ? "Gmail draft created" : "Drafted",
      formatShortDate(action.draftedAt || action.sentAt || transient.draftedAt),
    ].filter(Boolean).join(" ");
  }
  if (action.status === "sent") {
    const label = actionIsDraftMode(action) ? "Drafted" : "Sent";
    return [label, formatShortDate(action.sentAt)].filter(Boolean).join(" ");
  }
  if (action.status === "failed") return "Not drafted - tap Draft to retry";
  if (action.status === "queued" && action.channel === "gmail") {
    return action.agentJobId ? `${aiPrefix}draft pending` : `${aiPrefix}draft pending`;
  }
  if (action.status === "queued") return action.agentJobId ? `${aiPrefix}draft pending` : `${aiPrefix}draft pending`;
  if (action.missing?.length) return action.missing.join(", ");
  if (action.safety?.mode === "draft-only" || action.channel === "gmail") {
    return action.targetEmail ? `Draft to ${action.targetEmail}${action.cc ? ` · CC ${action.cc}` : ""}` : "Recipient needed";
  }
  return action.targetEmail ? action.targetEmail : "Recipient needed";
}

function deliveryOrderObjectUrlFromBase64(base64) {
  const value = String(base64 || "");
  if (!value || typeof URL === "undefined" || typeof Blob === "undefined" || typeof atob === "undefined") return "";
  try {
    const binary = atob(value);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) {
      bytes[index] = binary.charCodeAt(index);
    }
    return URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
  } catch {
    return "";
  }
}

function documentActionFileState(action) {
  if (!isDocumentAction(action)) return null;
  const transient = state.actionStatusById?.[action.id] || {};
  const status = transient.status || action.status || "";
  if (status !== "generated") return null;
  const fileName = transient.fileName || action.fileName || "delivery-order.pdf";
  const href = transient.pdfObjectUrl || action.pdfObjectUrl || transient.publicPath || action.publicPath || "";
  return { fileName, href };
}

function renderDocumentActionResult(action) {
  const file = documentActionFileState(action);
  if (!file) return "";
  return `
    <div class="document-action-result">
      <span>${escapeHtml(file.fileName)}</span>
      ${file.href ? `<a class="mini-button primary" href="${escapeHtml(file.href)}" target="_blank" rel="noopener">Open PDF</a>` : ""}
    </div>
  `;
}

function quoteDecisionSummary(action, fallback = "") {
  return action.quoteDecision?.summary || fallback || action.reason || "";
}

function blockedLowerQuoteSummary(decision) {
  const blockedItems = Array.isArray(decision?.blockedLowerQuotes) ? decision.blockedLowerQuotes : [];
  const item = blockedItems.find((entry) => entry?.blocked?.broker || entry?.quote?.broker);
  if (!item) return "";
  const quote = item.blocked || item.quote || {};
  const broker = quote.broker || "lower quote";
  const rate = quote.rate || quoteAmountLabel(quote);
  const blockers = Array.isArray(item.blockers) && item.blockers.length
    ? ` blocked: ${item.blockers.join(" + ")}`
    : " blocked";
  return `Lower ${broker}${rate ? ` ${rate}` : ""}${blockers}`;
}

function quotePlanReasonLine(action) {
  return [quoteDecisionSummary(action), blockedLowerQuoteSummary(action.quoteDecision)].filter(Boolean).join(" · ");
}

function quoteContextDetail(action) {
  const context = action.quoteContext;
  if (!context?.selected?.broker) return "";
  const selected = `${context.selected.broker} ${context.selected.rate || quoteAmountLabel(context.selected)}`;
  const options = Number(context.optionCount || 0) > 1 ? `${context.optionCount} options` : "";
  const lowerBlocked = Array.isArray(context.blockedLowerQuotes) && context.blockedLowerQuotes.length
    ? "lower blocked"
    : "";
  return [context.summary || "Quote comparison", selected, options, lowerBlocked].filter(Boolean).join(" · ");
}

function quoteDecisionDetail(action) {
  const decision = action.quoteDecision;
  if (!decision) return actionStatusLine(action);
  if (decision.basis === "blocked-lower") {
    const blockers = Array.isArray(decision.blockers) && decision.blockers.length
      ? `Needs ${decision.blockers.join(" + ")}`
      : "";
    const recommended = decision.recommended?.broker
      ? `Safe ${decision.recommended.broker} ${decision.recommended.rate}`
      : "";
    const total = decision.totalQuotes > 1 ? `${decision.totalQuotes} quotes` : "";
    return [blockers, recommended, total, actionStatusLine(action)].filter(Boolean).join(" · ");
  }
  const lowest = decision.lowest?.broker && !decision.isLowest
    ? `Lowest ${decision.lowest.broker} ${decision.lowest.rate}`
    : "";
  const total = decision.totalQuotes > 1 ? `${decision.totalQuotes} quotes` : "";
  const unlock = Array.isArray(decision.unlockWhen) && decision.unlockWhen.length
    ? `Unlock: ${decision.unlockWhen.join(" + ")}`
    : "";
  return [lowest, blockedLowerQuoteSummary(decision), total, unlock, quoteContextDetail(action), action.costContext?.summary, actionStatusLine(action)]
    .filter(Boolean)
    .join(" · ");
}

function actionModeLabel(action) {
  if (action.type === "source-backfill") return "Backfill";
  if (action.type === "money-context-review") return "Charges";
  if (action.type === "carrier-tracking-refresh") return "Movement";
  if (action.type === "station-fee-confirmation") return "Fees";
  if (action.type === "operator-state-check") return "State check";
  if (action.type === "release-packet-contact-gap") return "Find contact";
  if (isDocumentAction(action)) return "PDF";
  if (action.type === "tms-pod-closeout-experience") return "Close POD";
  if (action.safety?.mode === "tms-experience" || isTmsAction(action)) return "TMS alert";
  if (action.etaLabel) return action.etaLabel;
  if (action.stationContactMissing) return "Find contact";
  if (action.type === "ops-escalation") return "Escalate";
  if (action.type === "storage-risk") return "Storage";
  if (action.type === "quote-followup") return "Follow up";
  if (action.type === "quote-review") return "Review quote";
  if (action.type === "prearrival-quote-decision") return "Quote plan";
  if (action.type === "station-confirmation") return "Station";
  if (isOperatorApprovedInternalAction(action)) return "Internal";
  if (isPlatformAlertAction(action)) return "Alert";
  if (action.type === "dispatch-pickup-followup") return linehaulAction(action) ? "Destination" : "Pickup/POD";
  if (action.type === "broker-status-followup" && /\b(?:customs|clearance|release|d\/?o|delivery order)\b/i.test(`${action.threadTopic || ""} ${action.label || ""} ${action.subject || ""} ${action.reason || ""}`)) return "Customs";
  if (action.type === "broker-status-followup") return "Broker follow-up";
  if (action.type === "broker-award") return quoteDecisionModeLabel(action);
  if (action.type === "quote-request") return "Draft quote";
  return "Draft";
}

function operatorFacingActionLabel(action = {}) {
  const raw = cleanFactText(action.label || action.nextAction || action.subject || action.reason || "");
  const search = `${action.type || ""} ${raw} ${action.problem || ""} ${action.nextAction || ""}`.toLowerCase();
  if (isCarrierTrackingRefreshAction(action) || /refresh carrier tracking|carrier tracking refresh|tracking refresh/.test(search)) {
    return carrierActionNeedsFlightStatus(action) ? "Check flight status" : "Verify movement";
  }
  if (isMoneyContextAction(action) || /review zero economics|zero economics|money context|charge check/.test(search)) {
    return "Check charges";
  }
  if (isSourceBackfillAction(action) || /source backfill|source trail debt/.test(search)) {
    if (/dispatch|pickup/.test(search)) return "Find dispatch proof";
    if (/release|customs|d\/?o|delivery order/.test(search)) return "Find release proof";
    if (/pod|delivered|delivery/.test(search)) return "Find delivery proof";
    return "Find source proof";
  }
  if (/review unit economics/.test(search)) return "Check charges";
  return raw || "Action";
}

function linehaulAction(action) {
  return /\b(linehaul|ltl|destination arrival|destination recovery|loaded on|destination station)\b/i.test(
    `${action.label || ""} ${action.subject || ""} ${action.reason || ""} ${action.body || ""}`,
  );
}

function quoteDecisionModeLabel(action) {
  const basis = action.quoteDecision?.basis;
  if (basis === "selected") return "Selected";
  if (basis === "lowest") return "Lowest";
  if (basis === "recommended") return "Recommended";
  if (basis === "override-option") return "Override";
  return "Draft award";
}

function actionModePill(action) {
  const tms = action.safety?.mode === "tms-experience" || isTmsAction(action);
  const internal = isOperatorApprovedInternalAction(action);
  const platformAlert = isPlatformAlertAction(action);
  const documentAction = isDocumentAction(action);
  const eta = action.etaStatus ? ` eta ${action.etaStatus === "passed" ? "late" : "due"}` : "";
  const basis = !tms && !platformAlert && action.type === "broker-award" && action.quoteDecision?.basis
    ? ` quote-basis-${action.quoteDecision.basis}`
    : "";
  return `<small class="action-mode-pill ${internal ? "operator-approved-internal" : platformAlert ? "platform-alert" : documentAction ? "document" : tms ? "tms" : "draft"}${eta}${basis}">${actionModeLabel(action)}</small>`;
}

function actionReasonLine(action) {
  if (isPlatformAlertAction(action)) {
    if (action.type === "operator-state-check") {
      const options = Array.isArray(action.operatorUpdateOptions) && action.operatorUpdateOptions.length
        ? `Options: ${action.operatorUpdateOptions.slice(0, 4).join(" / ")}`
        : "";
      return [action.reason, options].filter(Boolean).join(" · ");
    }
    return [
      action.problem ? `Problem: ${action.problem}` : "",
      action.nextAction ? `Do now: ${action.nextAction}` : "",
    ].filter(Boolean).join(" · ") || action.reason || "";
  }
  if (action.type === "tms-pod-closeout-experience" && action.podProposal) {
    return [
      action.podProposal.signedBy ? `Signed ${action.podProposal.signedBy}` : "",
      action.podProposal.actualAt ? `Actual ${action.podProposal.actualAt}` : "Confirm actual time",
      "approve to Save Next",
    ].filter(Boolean).join(" · ");
  }
  if (action.type === "quote-review" && action.quoteDecision?.summary) {
    return action.quoteDecision.summary;
  }
  if (action.type === "prearrival-quote-decision" && action.quoteDecision?.summary) {
    return quotePlanReasonLine(action);
  }
  if (action.type === "station-confirmation" && action.etaLabel) {
    const station = action.station || action.originalTargetName || action.targetName || "station";
    const task = action.stationContactMissing ? `find ${station} contact` : "ask station status";
    return `${action.etaLabel} · ${task}`;
  }
  return action.reason || "";
}

function tmsPreviewSubject(subject) {
  return String(subject || "CourierCloud action").replace(/^\[TMS (?:TEST|REVIEW)\]\s*/i, "");
}

function tmsPreviewBody(action) {
  return action.body || action.reason || "";
}

function draftPreviewForAction(action) {
  if (isPlatformAlertAction(action)) {
    return {
      tms: false,
      platformAlert: true,
      stationContactMissing: false,
      mode: "Ops Brain alert",
      to: "",
      cc: "",
      bcc: "",
      subject: action.label || "Ops Brain alert",
      body: action.body || action.reason || "",
      podProposal: null,
      originalTarget: "",
      attachmentIntent: null,
      attachmentIntents: [],
      attachments: [],
      safety: "No email is drafted. Shown inside the platform; no TMS job is queued.",
    };
  }
  const tms = action.safety?.mode === "tms-experience" || isTmsAction(action);
  const originalTarget = action.stationContactMissing
    ? [action.originalTargetName, action.originalTargetEmail].filter(Boolean).join(" / ")
    : tms
    ? action.targetEmail || action.targetName || ""
    : "";
  return {
    tms,
    stationContactMissing: Boolean(action.stationContactMissing),
    mode: tms ? "CourierCloud action" : actionThreadLabel(action),
    to: action.targetEmail || "",
    cc: tms ? action.tmsIntent?.copyEmail || action.cc || "" : action.cc || "",
    bcc: tms ? "" : action.bcc || "",
    subject: tms ? String(action.subject || "CourierCloud action").replace(/^\[TMS (?:TEST|REVIEW)\]\s*/i, "") : action.subject || "",
    body: action.body || "",
    podProposal: action.podProposal || null,
    originalTarget,
    attachmentIntent: action.attachmentIntent || null,
    attachmentIntents: Array.isArray(action.attachmentIntents)
      ? action.attachmentIntents
      : action.attachmentIntent
        ? [action.attachmentIntent]
        : [],
    attachments: Array.isArray(action.attachments) ? action.attachments : [],
    safety: tms
      ? isTmsPodAction(action) ? "Will write Actual/Signed in CourierCloud and click Save Next after you confirm." : "Will send from CourierCloud after you confirm."
      : "Draft only. Nothing is sent until approved in Gmail.",
  };
}

function hasOwnDraftEdit(edit, field) {
  return Object.prototype.hasOwnProperty.call(edit || {}, field);
}

function actionThreadPolicyForUi(action) {
  const policy = String(action?.threadPolicy || "").toLowerCase();
  if (["reply_existing", "start_new", "unavailable"].includes(policy)) return policy;
  return action?.replyMessageId || action?.conversation?.replyMessageId || action?.conversation?.threadId
    ? "reply_existing"
    : "start_new";
}

function draftEditThreadModeForAction(action) {
  const edit = state.actionDraftEditsById[action?.id] || {};
  if (edit.threadMode === "reply" || edit.threadMode === "new") return edit.threadMode;
  return actionThreadPolicyForUi(action) === "reply_existing" ? "reply" : "new";
}

function stripReplyPrefixForNewThread(subject) {
  return String(subject || "").replace(/^(?:\s*re\s*:\s*)+/i, "").trim();
}

function actionWithDraftEdits(action) {
  if (!action || isPlatformAlertAction(action) || isDocumentAction(action)) return action;
  const edit = state.actionDraftEditsById[action.id] || null;
  if (!edit) return action;
  const next = { ...action };
  if (hasOwnDraftEdit(edit, "targetEmail")) next.targetEmail = edit.targetEmail;
  if (hasOwnDraftEdit(edit, "cc")) next.cc = edit.cc;
  if (hasOwnDraftEdit(edit, "bcc")) next.bcc = edit.bcc;
  if (!isTmsAction(next)) {
    const threadMode = draftEditThreadModeForAction(action);
    if (threadMode === "new") {
      next.threadPolicy = "start_new";
      next.replyMessageId = "";
      next.conversation = null;
      next.subject = stripReplyPrefixForNewThread(next.subject);
    } else {
      next.threadPolicy = "reply_existing";
      next.replyMessageId = action.replyMessageId || action.conversation?.replyMessageId || "";
      next.conversation = action.conversation || null;
    }
  }
  return next;
}

function draftPreviewFromRequest(action, previewState) {
  const request = previewState?.request;
  if (!request) return draftPreviewForAction(action);
  const tms = requestIsTmsExperience(request);
  return {
    tms,
    stationContactMissing: Boolean(request.stationContactMissing),
    mode: tms ? "CourierCloud action" : actionThreadLabel(action),
    to: request.to || "",
    cc: request.cc || "",
    bcc: request.bcc || "",
    subject: request.subject || "",
    body: request.body || "",
    podProposal: request.tmsIntent?.kind === "pod-actual-signed-closeout"
      ? {
          signedBy: request.tmsIntent?.signedBy || "",
          actualDate: request.tmsIntent?.actualDate || "",
          actualTime: request.tmsIntent?.actualTime || "",
          actualAt: [request.tmsIntent?.actualDate, request.tmsIntent?.actualTime].filter(Boolean).join(" "),
        }
      : action.podProposal || null,
    originalTarget: request.originalTargetEmail || request.originalTargetName || "",
    attachmentIntent: request.attachmentIntent || action.attachmentIntent || null,
    attachmentIntents: Array.isArray(request.attachmentIntents) && request.attachmentIntents.length
      ? request.attachmentIntents
      : Array.isArray(action.attachmentIntents)
        ? action.attachmentIntents
        : action.attachmentIntent
          ? [action.attachmentIntent]
          : [],
    attachments: Array.isArray(request.attachments) && request.attachments.length
      ? request.attachments
      : Array.isArray(action.attachments)
        ? action.attachments
        : [],
    safety: tms
      ? isTmsPodAction(action) ? "Checked. Will write Actual/Signed in CourierCloud and click Save Next." : "Checked. Will send from CourierCloud after you confirm."
      : "Validated by the draft-safe endpoint. Nothing is sent until approved in Gmail.",
  };
}

function renderDraftField(label, value) {
  if (!value) return "";
  return `
    <div class="draft-preview-row">
      <span>${label}</span>
      <strong>${value}</strong>
    </div>
  `;
}

function deliveryOrderAttachmentFileName(awb) {
  const safeAwb = String(awb || "").trim().replace(/[^A-Za-z0-9-]+/g, "-") || "shipment";
  return `delivery-order-${safeAwb}.pdf`;
}

function draftPreviewAttachmentRows(action, preview) {
  const rows = [];
  const seen = new Set();
  const addRow = (label, value) => {
    const text = String(value || "").replace(/\s+/g, " ").trim();
    const key = `${label}:${text}`;
    if (!text || seen.has(key)) return;
    seen.add(key);
    rows.push({ label, value: text });
  };
  const attachments = Array.isArray(preview.attachments) ? preview.attachments : [];
  for (const attachment of attachments) {
    const name = attachment.fileName || attachment.filename || attachment.name || "";
    if (name) addRow("Attachment", `${name}${attachment.size ? ` · ${attachment.size} bytes` : ""}`);
  }
  const intents = [
    ...(Array.isArray(preview.attachmentIntents) ? preview.attachmentIntents : []),
    preview.attachmentIntent,
    ...(Array.isArray(action.attachmentIntents) ? action.attachmentIntents : []),
    action.attachmentIntent,
    action.documentIntent,
  ].filter(Boolean);
  for (const intent of intents) {
    const kind = String(intent.kind || intent.type || "").toLowerCase();
    if (kind !== "delivery-order") continue;
    const awb = intent.awb || action.awb || "";
    const carrier = intent.carrierName || action.carrierName || action.targetName || "";
    addRow("Attachment", `${deliveryOrderAttachmentFileName(awb)} will be generated${carrier ? ` for ${carrier}` : ""}`);
  }
  return rows;
}

function renderDraftAttachmentRows(action, preview) {
  return draftPreviewAttachmentRows(action, preview)
    .map((row) => renderDraftField(row.label, escapeHtml(row.value)))
    .join("");
}

function renderDraftEditField(actionId, label, field, value) {
  return `
    <label class="draft-preview-row draft-preview-edit-row">
      <span>${escapeHtml(label)}</span>
      <input
        type="text"
        data-draft-edit-action="${escapeHtml(actionId)}"
        data-draft-edit-field="${escapeHtml(field)}"
        value="${escapeHtml(value)}"
        autocomplete="off"
        spellcheck="false"
      />
    </label>
  `;
}

function shipmentForAction(action = {}) {
  const actionAwb = opsBrainAwbKey(action.awb || action.shipmentAwb || "");
  return state.shipments.find((shipment) =>
    (action.shipmentId && shipment.id === action.shipmentId) ||
    (actionAwb && opsBrainAwbKey(shipment.awb || shipment.shipmentAwb || "") === actionAwb)
  ) || null;
}

function addDraftParticipantCandidate(candidates, name, email, source = "") {
  const address = contactEmailList(email)[0] || "";
  if (!address || candidates.has(address)) return;
  candidates.set(address, {
    email: address,
    name: String(name || "").trim() || address.split("@")[0].replace(/[._-]+/g, " "),
    source,
  });
}

function addDraftParticipantEmails(candidates, value, source = "") {
  for (const email of contactEmailList(value)) addDraftParticipantCandidate(candidates, "", email, source);
}

function draftParticipantCandidates(action = {}, editableAction = action) {
  const candidates = new Map();
  const shipment = shipmentForAction(action);
  addDraftParticipantCandidate(candidates, action.targetName, editableAction.targetEmail || action.targetEmail, "to");
  addDraftParticipantEmails(candidates, editableAction.cc || action.cc, "cc");
  addDraftParticipantEmails(candidates, editableAction.bcc || action.bcc, "bcc");
  addDraftParticipantCandidate(candidates, action.originalTargetName, action.originalTargetEmail, "original");
  addDraftParticipantCandidate(candidates, action.freightBroker?.broker || action.tmsIntent?.brokerName, action.tmsIntent?.brokerEmail, "broker");
  addDraftParticipantCandidate(candidates, "Copy", action.tmsIntent?.copyEmail, "copy");
  addDraftParticipantCandidate(candidates, shipment?.freightBroker?.broker, shipment?.freightBroker?.contactEmail || shipment?.freightBroker?.email, "pickup broker");
  addDraftParticipantCandidate(candidates, shipment?.customsBroker?.broker, shipment?.customsBroker?.contactEmail || shipment?.customsBroker?.email, "customs broker");
  for (const contact of Object.values(shipment?.contacts || {})) {
    addDraftParticipantCandidate(candidates, contact?.name, contact?.email, contact?.role || "shipment contact");
  }
  return [...candidates.values()]
    .filter((candidate) => candidate.email)
    .slice(0, 8);
}

function renderDraftParticipantToggles(action, editableAction) {
  const candidates = draftParticipantCandidates(action, editableAction);
  if (candidates.length <= 1) return "";
  const toEmails = new Set(contactEmailList(editableAction.targetEmail));
  const ccEmails = new Set(contactEmailList(editableAction.cc));
  const bccEmails = new Set(contactEmailList(editableAction.bcc));
  return `
    <div class="draft-participant-toggles" aria-label="Thread people">
      <span>People</span>
      <div>
        ${candidates.map((candidate) => {
          const inTo = toEmails.has(candidate.email);
          const inCc = ccEmails.has(candidate.email);
          const inBcc = bccEmails.has(candidate.email);
          const checked = inTo || inCc || inBcc;
          const role = inTo ? "To" : inCc ? "CC" : inBcc ? "BCC" : "Add";
          return `
            <label class="draft-participant-toggle ${checked ? "selected" : ""} ${inTo ? "locked" : ""}">
              <input
                type="checkbox"
                data-draft-participant-action="${escapeHtml(action.id)}"
                data-draft-participant-email="${escapeHtml(candidate.email)}"
                ${checked ? "checked" : ""}
                ${inTo ? "disabled" : ""}
              />
              <strong>${escapeHtml(candidate.name)}</strong>
              <em>${escapeHtml(role)} · ${escapeHtml(candidate.email)}</em>
            </label>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function renderDraftThreadEdit(action, preview) {
  const mode = draftEditThreadModeForAction(action);
  const hasReplyThread = Boolean(action.replyMessageId || action.conversation?.replyMessageId || action.conversation?.threadId);
  return `
    <label class="draft-preview-row draft-preview-edit-row">
      <span>Thread</span>
      <select data-draft-edit-action="${escapeHtml(action.id)}" data-draft-edit-field="threadMode">
        <option value="new" ${mode === "new" ? "selected" : ""}>New Gmail thread</option>
        <option value="reply" ${mode === "reply" ? "selected" : ""}>Reply in current thread${hasReplyThread ? "" : " (needs Gmail thread)"}</option>
      </select>
    </label>
    ${mode === "reply" && hasReplyThread ? renderDraftField("Reply", preview.originalTarget || preview.subject || "Existing Gmail thread") : ""}
  `;
}

// The one desktop action composer (email-client grade). Every desktop
// email/draft path renders through here; the phone keeps its legacy preview
// untouched. Honest affordances only: while platform send is off, the primary
// is "Save draft to Gmail" and the send button says exactly why it's disabled.
function composerRecipientChips(value = "") {
  const emails = String(value || "").split(/[,;]+/).map((item) => item.trim()).filter(Boolean);
  if (!emails.length) return `<span class="ac-chip empty">none</span>`;
  return emails.map((email) => `<span class="ac-chip">${escapeHtml(email)}</span>`).join("");
}

// Mirrors the server allowlist in lib/platform-send.js — the server is the
// authority; this only decides what the button says.
const COMPOSER_SENDABLE_ACTION_TYPES = new Set([
  "customs-followup", "station-confirmation", "station-fee-confirmation",
  "quote-followup", "pod-followup", "broker-followup", "ops-escalation",
]);

// Returns the exact reason the send button is disabled, or null when every
// client-visible gate passes (the server re-checks everything on click).
function composerSendDisabledReason(action, shipment) {
  const platformSend = state.truthHealth?.platformSend;
  if (!platformSend?.enabled) return "Sending from Pikiio isn't enabled yet — this saves a Gmail draft instead.";
  if (!COMPOSER_SENDABLE_ACTION_TYPES.has(String(action.type || ""))) {
    return "This action type isn't approved for sending from Pikiio yet — save a Gmail draft instead.";
  }
  const hasThread = Boolean(action.replyMessageId || action.conversation?.replyMessageId || action.conversation?.threadId);
  if (!hasThread || draftEditThreadModeForAction(action) !== "reply") {
    return "Only replies in an existing Gmail thread can send — this would start a new email.";
  }
  if (shipment && shipmentHasSourceGap(shipment)) {
    return `This shipment has a source gap — ${sourceGapOperatorAction(shipment)}`;
  }
  const lock = desktopStageActionLock(action, shipment);
  if (lock) return lock;
  const contested = (shipment?.truthPacket?.contradictions || []).length > 0 || Boolean(shipment?.truthPacket?.mustAskHuman);
  if (contested) return "Conflicting shipment info needs a decision before sending.";
  const recipients = Array.isArray(action.recipients?.to) ? action.recipients.to : [];
  if (!recipients.length) return "Recipients aren't roster-backed yet — confirm who this should go to first.";
  if (recipients.some((item) => String(item.confidence || "").toLowerCase() !== "high")) {
    return "Recipient confidence isn't high — confirm who this should go to first.";
  }
  return null;
}

async function composerSha256Hex(text = "") {
  const bytes = new TextEncoder().encode(String(text || ""));
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function showPlatformSendToast(message, tone = "ok") {
  const toast = document.createElement("div");
  toast.className = `urgent-interrupt-toast platform-send-toast ${tone}`;
  toast.setAttribute("role", "status");
  toast.innerHTML = `<strong>${escapeHtml(message)}</strong>`;
  document.body.appendChild(toast);
  window.setTimeout(() => toast.remove(), 6500);
}

// The real send: stage/refresh the Gmail draft, then approve-send with the
// reviewed body hash. On failure NOTHING changes — the draft body stays, the
// error is shown, and retry is a click away.
async function performPlatformSend(action) {
  const editableAction = actionWithDraftEdits(action);
  const preview = draftPreviewFromRequest(editableAction, state.previewDraftsByActionId[action.id] || null);
  if (!(state.composerSending instanceof Set)) state.composerSending = new Set();
  if (!state.composerSendError) state.composerSendError = {};
  state.composerSending.add(action.id);
  delete state.composerSendError[action.id];
  renderActionSurfaces();
  try {
    const draftResponse = await fetch("/api/actions/send", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ actionId: action.id, action: editableAction }),
    });
    const draftResult = await draftResponse.json().catch(() => ({}));
    const gmailDraft = draftResult.gmailDraft || {};
    if (!draftResponse.ok || !gmailDraft.draftId) {
      throw new Error(draftResult.error || "Could not stage the Gmail draft to send.");
    }
    const body = preview.body || "";
    const to = contactEmailList(editableAction.targetEmail || preview.to);
    const cc = contactEmailList(editableAction.cc || preview.cc);
    const sendResponse = await fetch("/api/actions/approve-send", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        actionId: action.id,
        awb: action.awb || "",
        dryRun: false,
        action: editableAction,
        draft: {
          gmailDraftId: gmailDraft.draftId,
          body,
          subject: preview.subject || "",
          to,
          cc,
          threadId: gmailDraft.threadId || action.conversation?.threadId || "",
        },
        approval: {
          approvedBy: "Alex",
          approvedAt: new Date().toISOString(),
          confirm: "SEND",
          reviewedBodyHash: await composerSha256Hex(body),
          reviewedTo: to,
          reviewedCc: cc,
        },
      }),
    });
    const sendResult = await sendResponse.json().catch(() => ({}));
    if (sendResult.status !== "sent") {
      // ONE plain reason: the server orders refusals most-fundamental-first,
      // and a paragraph of every failed gate reads as noise, not guidance.
      const reason = (sendResult.refusals || [])[0]?.reason || sendResult.error || "The send was refused.";
      throw new Error(reason);
    }
    showPlatformSendToast(`Sent to ${to.join(", ")} — waiting for their reply.`);
    state.previewActionId = null;
    markOpsBrainActionHandled(opsBrainActionKey(action), `Sent from Pikiio to ${to.join(", ")}`, { persistRemote: false });
    // The ball is now with the counterparty: the work item goes to waiting
    // immediately; the refresh makes it durable via the sent-email fact.
    state.shipments = state.shipments.map((shipment) =>
      opsBrainAwbKey(shipment.awb || shipment.id) === opsBrainAwbKey(action.awb || "")
        ? { ...shipment, operatorAgency: { agency: "waiting_on_external_party", reason: `We sent the reply from Pikiio — waiting for ${to[0] || "their"} response.`, countsAsWork: false } }
        : shipment);
    renderList();
  } catch (error) {
    state.composerSendError[action.id] = error instanceof Error ? error.message : String(error);
    renderActionSurfaces();
  } finally {
    state.composerSending.delete(action.id);
    if (state.composerSendConfirm instanceof Set) state.composerSendConfirm.delete(action.id);
    renderActionSurfaces();
  }
}

function renderDesktopActionComposer(action, context) {
  const { editableAction, preview, loading, dirty, ready, blocked, body, statusLine } = context;
  const shipment = shipmentForAction(action);
  const threadMode = draftEditThreadModeForAction(action);
  const hasThread = Boolean(action.replyMessageId || action.conversation?.replyMessageId || action.conversation?.threadId);
  const threadSource = threadMode === "reply" && hasThread
    ? `Reply in the shipment's Gmail thread${preview.originalTarget ? ` · ${escapeHtml(shortText(preview.originalTarget, "", 60))}` : ""}`
    : "New email";
  const confidence = String((Array.isArray(action.recipients?.to) ? action.recipients.to : [])[0]?.confidence || "").toLowerCase();
  const editOpen = state.composerRecipientEditOpen instanceof Set && state.composerRecipientEditOpen.has(action.id);
  const sendReason = composerSendDisabledReason(editableAction, shipment);
  const confirmOpen = state.composerSendConfirm instanceof Set && state.composerSendConfirm.has(action.id);
  const sending = state.composerSending instanceof Set && state.composerSending.has(action.id);
  const sendError = (state.composerSendError || {})[action.id] || "";
  const honestStatus = loading || dirty || blocked || previewErrorText(context)
    ? statusLine
    : "Draft ready — saves to Gmail; nothing sends from Pikiio yet.";
  return `
    <div class="draft-preview action-composer" data-draft-preview="${escapeHtml(action.id)}">
      <header class="ac-head">
        <div class="ac-head-copy">
          <span class="ac-mode">${threadSource}</span>
          <strong class="ac-status">${escapeHtml(shortText(String(honestStatus || ""), "", 120))}</strong>
        </div>
        ${confidence ? `<span class="ac-confidence ${escapeHtml(confidence)}">${escapeHtml(confidence)} confidence</span>` : ""}
      </header>
      <div class="ac-recipients">
        <div class="ac-recipient-row"><span>To</span><div class="ac-chips">${composerRecipientChips(editableAction.targetEmail || preview.to)}</div></div>
        ${(editableAction.cc || preview.cc) ? `<div class="ac-recipient-row"><span>Cc</span><div class="ac-chips">${composerRecipientChips(editableAction.cc || preview.cc)}</div></div>` : ""}
        ${(editableAction.bcc || preview.bcc) ? `<div class="ac-recipient-row"><span>Bcc</span><div class="ac-chips">${composerRecipientChips(editableAction.bcc || preview.bcc)}</div></div>` : ""}
        <button class="ac-edit-toggle" type="button" data-composer-edit-recipients="${escapeHtml(action.id)}">${editOpen ? "Done editing" : "Edit recipients"}</button>
      </div>
      ${editOpen ? `
        <div class="ac-edit-panel">
          ${renderDraftEditField(action.id, "To", "targetEmail", editableAction.targetEmail || preview.to)}
          ${renderDraftEditField(action.id, "CC", "cc", editableAction.cc || preview.cc)}
          ${renderDraftEditField(action.id, "BCC", "bcc", editableAction.bcc || preview.bcc)}
          ${renderDraftParticipantToggles(action, editableAction)}
          ${renderDraftThreadEdit(action, preview)}
        </div>
      ` : ""}
      ${blocked ? "" : `<div class="ac-subject">${escapeHtml(shortText(preview.subject, "(no subject)", 120))}</div>`}
      <div class="draft-preview-body ac-body">${body}</div>
      <details class="ac-safety">
        <summary>Why this is safe</summary>
        <p>${escapeHtml(shortText(String(preview.safety || "Validated against current shipment truth before drafting."), "", 200)).replace(/Nothing is sent until approved in Gmail\.?/i, "Nothing sends from Pikiio; you approve every send.")}</p>
        ${renderDraftAttachmentRows(editableAction, preview)}
        ${preview.originalTarget ? renderDraftField("Thread", escapeHtml(preview.originalTarget)) : ""}
      </details>
      <footer class="draft-preview-actions ac-actions">
        <button class="mini-button" data-close-action-preview="${escapeHtml(action.id)}" type="button">Close</button>
        <button class="mini-button" data-recheck-action="${escapeHtml(action.id)}" type="button" ${loading ? "disabled" : ""}>${loading ? "Checking" : "Recheck"}</button>
        <button class="mini-button ${sendReason ? "primary" : ""}" data-confirm-action="${escapeHtml(action.id)}" type="button" ${!ready ? "disabled" : ""}>${loading ? "Checking" : dirty ? "Recheck first" : "Save draft to Gmail"}</button>
        ${sendReason ? `
          <button class="mini-button ac-send" type="button" disabled title="${escapeHtml(sendReason)}" data-send-disabled-reason="${escapeHtml(sendReason)}">Send from Pikiio</button>
        ` : sending ? `
          <button class="mini-button primary ac-send" type="button" disabled>Sending…</button>
        ` : confirmOpen ? `
          <button class="mini-button primary ac-send confirm" data-composer-send="${escapeHtml(action.id)}" type="button" ${!ready ? "disabled" : ""}>Yes — send it</button>
        ` : `
          <button class="mini-button primary ac-send" data-composer-send-arm="${escapeHtml(action.id)}" type="button" ${!ready ? "disabled" : ""}>Send from Pikiio</button>
        `}
      </footer>
      ${sendError ? `<p class="ac-send-reason error">${escapeHtml(sendError)} <button class="ac-retry" type="button" data-composer-send-arm="${escapeHtml(action.id)}">Retry send</button></p>` : ""}
      ${confirmOpen && !sendReason ? `<p class="ac-send-reason confirm">Send this reply to ${escapeHtml((editableAction.targetEmail || preview.to || "").split(/[,;]/)[0].trim())} in thread “${escapeHtml(shortText(preview.subject, "this thread", 70))}”?</p>` : ""}
      ${sendReason ? `<p class="ac-send-reason">${escapeHtml(sendReason)}</p>` : ""}
    </div>
  `;
}

function previewErrorText(context = {}) {
  return context.previewState?.error || "";
}

function renderDraftPreview(action) {
  const editableAction = actionWithDraftEdits(action);
  const previewState = state.previewDraftsByActionId[action.id] || null;
  const loading = state.previewLoadingActionIds.has(action.id);
  const preview = draftPreviewFromRequest(editableAction, previewState);
  const body = shortText(preview.body, "No body", 260);
  const blocked = actionBlockedReason(editableAction);
  const dirty = Boolean(previewState?.dirty);
  const ready = Boolean(previewState?.request && !loading && !previewState.error && !dirty && !blocked);
  const podCloseout = isTmsPodAction(editableAction);
  const editableGmail = !preview.tms && !podCloseout;
  const statusLine = preview.tms && !loading && !previewState?.error
    ? podCloseout ? "POD closeout ready" : `TMS alert to ${preview.to || "broker"}`
    : loading
      ? "Validating exact draft..."
      : dirty
        ? "Recipient/thread changed. Recheck before drafting."
        : previewState?.error || blocked || preview.safety;
  if (isDesktopWorkspace() && editableGmail) {
    return renderDesktopActionComposer(action, {
      editableAction, preview, previewState, loading, dirty, ready, blocked, body, statusLine,
    });
  }
  return `
    <div class="draft-preview ${preview.tms ? "tms-experience" : ""}" data-draft-preview="${action.id}">
      <div class="draft-preview-top">
        <span>${preview.mode}</span>
        <strong>${statusLine}</strong>
      </div>
      ${blocked && !editableGmail ? "" : podCloseout ? "" : editableGmail ? renderDraftEditField(action.id, "To", "targetEmail", editableAction.targetEmail || preview.to) : renderDraftField(preview.tms ? "Send to" : "To", preview.to)}
      ${editableGmail ? renderDraftEditField(action.id, "CC", "cc", editableAction.cc || preview.cc) : renderDraftField("CC", preview.cc)}
      ${editableGmail ? renderDraftEditField(action.id, "BCC", "bcc", editableAction.bcc || preview.bcc) : renderDraftField("BCC", preview.bcc)}
      ${editableGmail ? renderDraftParticipantToggles(action, editableAction) : ""}
      ${editableGmail ? renderDraftThreadEdit(action, preview) : ""}
      ${blocked ? "" : renderDraftField("Subject", preview.subject)}
      ${podCloseout ? renderDraftField("Actual", preview.podProposal?.actualAt || [preview.podProposal?.actualDate, preview.podProposal?.actualTime].filter(Boolean).join(" ")) : ""}
      ${podCloseout ? renderDraftField("Signed", preview.podProposal?.signedBy || "Receiver") : ""}
      ${preview.tms ? renderDraftField("CourierCloud", podCloseout ? "Will Save Next" : "Will send alert") : ""}
      ${renderDraftAttachmentRows(editableAction, preview)}
      ${preview.originalTarget ? renderDraftField(preview.tms ? "TMS target" : preview.stationContactMissing ? "Not using" : "Original", preview.originalTarget) : ""}
      <div class="draft-preview-body">${body}</div>
      <div class="draft-preview-actions">
        <button class="mini-button" data-close-action-preview="${action.id}" type="button">Close</button>
        ${editableGmail ? `<button class="mini-button" data-recheck-action="${action.id}" type="button" ${loading ? "disabled" : ""}>${loading ? "Checking" : "Recheck"}</button>` : ""}
        <button class="mini-button primary" data-confirm-action="${action.id}" type="button" ${!ready ? "disabled" : ""}>${loading ? "Checking" : dirty ? "Recheck first" : podCloseout ? "Approve POD" : preview.tms ? "Send from TMS" : "Draft"}</button>
      </div>
    </div>
  `;
}

function opsBrainActionUpdatePrompt(action) {
  if (action?.type === "money-context-review") {
    const lastRefresh = action.costContext?.lastRefresh;
    const zeroValueReview = action.costContext?.reviewType === "zero-value-economics";
    const auditRows = lastRefresh?.extractionAudit?.moneyRows || [];
    const firstAuditRow = Array.isArray(auditRows) ? auditRows.find((item) => item?.row)?.row : "";
    return [
      action.reason || "Shipment economics are missing.",
      lastRefresh
        ? "The last money refresh checked CourierCloud but did not extract values. Manually confirm Charges/Costs/Billing or ask accounting, then paste the confirmed economics or blocker here."
        : zeroValueReview
        ? "CourierCloud shows zero charge/cost values. Confirm whether those zero values are intentional; if not, ask accounting or update billing/costs, then paste the confirmed outcome here."
        : "Open CourierCloud costs/billing, confirm the customer charge and vendor cost, then paste the confirmed economics or blocker here.",
      firstAuditRow ? `Extractor saw: ${firstAuditRow}` : "",
      "Useful format: customer charge <amount>, vendor cost <amount>, source <where you verified it>.",
    ].filter(Boolean).join("\n");
  }
  if (action?.type === "station-contact-research") {
    return [
      action.reason || "Station contact is missing.",
      "Find the verified station import email/phone, save it in the station-memory form, then paste the saved contact or the blocker here.",
      "Useful format: saved station email <email>, phone <phone>, source <where you verified it>.",
    ].filter(Boolean).join("\n");
  }
  if (action?.type === "release-packet-contact-gap") {
    return [
      action.reason || "Pickup broker release contact is missing.",
      "Save the pickup broker release email in the broker-contact form. If the release packet was already sent, paste who sent it, when, and on which thread.",
      "Useful format: saved pickup broker email <email>, source <where you verified it>.",
    ].filter(Boolean).join("\n");
  }
  if (action?.type === "station-fee-confirmation") {
    return [
      action.reason || "Ground fees need confirmation.",
      "Call/pay the station fee desk, then paste the amount, receipt/payment proof, or exact blocker here.",
      "Useful format: fees paid <amount>, receipt/source <where verified>, pickup released <yes/no>.",
    ].filter(Boolean).join("\n");
  }
  if (action?.type !== "operator-state-check") return "What should Yael remember about this shipment?";
  const options = Array.isArray(action.operatorUpdateOptions) && action.operatorUpdateOptions.length
    ? `\n\nUseful formats:\n- ${action.operatorUpdateOptions.join("\n- ")}`
    : "";
  return [
    action.reason || "What happened outside the system?",
    "Write the actual update with the AWB if it is not obvious.",
    options,
  ].filter(Boolean).join("\n");
}

function renderQuoteBlastPreview(shipment, actions) {
  const previews = actions.map((action) => ({
    action,
    loading: state.previewLoadingActionIds.has(action.id),
    state: state.previewDraftsByActionId[action.id],
    preview: draftPreviewFromRequest(action, state.previewDraftsByActionId[action.id]),
  }));
  const missing = actions.some((action) => action.missing?.length);
  const ready = Boolean(actions.length) &&
    actions.every((action) => state.previewDraftsByActionId[action.id]?.request && !state.previewLoadingActionIds.has(action.id));
  const error = previews.find((item) => item.state?.error)?.state?.error || "";
  return `
    <div class="draft-preview quote-blast-preview">
      <div class="draft-preview-top">
        <span>${actions.length} separate drafts</span>
        <strong>${error || (ready ? "Validated by the draft-safe endpoint. Nothing sends automatically." : "Validating exact broker drafts...")}</strong>
      </div>
      <div class="draft-preview-recipient-list">
        ${previews
          .map(
            (item) => `
              <div>
                <span>${item.loading ? "Checking..." : item.preview.to || "Recipient needed"}</span>
                <strong>${item.preview.subject || `Quote request - AWB ${shipment.awb}`}</strong>
              </div>
            `,
          )
          .join("")}
      </div>
      <div class="draft-preview-actions">
        <button class="mini-button" data-close-quote-blast-preview="${shipment.id}" type="button">Close</button>
        <button class="mini-button primary" data-confirm-quote-blast="${shipment.id}" type="button" ${missing || !ready || error ? "disabled" : ""}>${ready ? "Draft all" : "Checking"}</button>
      </div>
    </div>
  `;
}

function actionButtons(action) {
  const callButton = renderCallButton(action);
  if (isPlatformAlertAction(action)) {
    if (isHandledOpsBrainAction(action)) return `<span class="action-alert-state handled">Saved</span>`;
    if (isStationContactResearchAction(action)) {
      const saving = state.savingStationMemory.has(action.shipmentId);
      return `${callButton}<button class="mini-button primary" form="${escapeHtml(stationContactActionFormId(action))}" type="submit" ${saving ? "disabled" : ""}>${saving ? "Saving" : "Save contact"}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isReleaseContactGapAction(action)) {
      const saving = state.savingBrokerContact.has(action.id);
      return `${callButton}<button class="mini-button primary" form="${escapeHtml(brokerContactFormId(action))}" type="submit" ${saving ? "disabled" : ""}>${saving ? "Saving" : "Save contact"}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isOperatorStateCheckAction(action)) {
      const saving = state.savingStateOutcome.has(action.id);
      return `${callButton}<button class="mini-button primary" form="${escapeHtml(operatorStateCheckFormId(action))}" type="submit" ${saving ? "disabled" : ""}>${saving ? "Saving" : "Save outcome"}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isMoneyContextAction(action)) {
      const moneyState = moneyRefreshStatusForAction(action);
      const disabled = moneyState.sending || (moneyState.queued && !moneyState.failed);
      return `${callButton}<button class="mini-button primary" data-confirm-action="${action.id}" type="button" ${disabled ? "disabled" : ""}>${escapeHtml(moneyState.buttonLabel)}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isSourceBackfillAction(action)) {
      const sourceState = sourceBackfillStatusForAction(action);
      const disabled = sourceState.sending || sourceState.blocked || (sourceState.queued && !sourceState.failed);
      return `${callButton}<button class="mini-button primary" data-confirm-action="${action.id}" type="button" ${disabled ? "disabled" : ""}>${escapeHtml(sourceState.buttonLabel)}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isCarrierTrackingRefreshAction(action)) {
      const trackingState = carrierTrackingRefreshStatusForAction(action);
      const disabled = trackingState.sending || (trackingState.queued && !trackingState.failed);
      return `${callButton}<button class="mini-button primary" data-confirm-action="${action.id}" type="button" ${disabled ? "disabled" : ""}>${escapeHtml(trackingState.buttonLabel)}</button><button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Done</button>`;
    }
    if (isStationFeeAction(action)) {
      const saving = state.savingStationFee.has(action.id);
      return `${callButton}<button class="mini-button primary" form="${escapeHtml(stationFeeFormId(action))}" type="submit" ${saving ? "disabled" : ""}>${saving ? "Saving" : "Save result"}</button>`;
    }
    if (isPrearrivalQuoteDecisionAction(action)) {
      return `${callButton}<span class="action-alert-state" data-noncanonical-decision-disabled>Decision ledger required</span>`;
    }
    return `${callButton}<button class="mini-button" data-handle-ops-brain-action="${escapeHtml(opsBrainActionKey(action))}" type="button">Record result</button>`;
		  }
  const blocked = actionBlockedReason(action);
  if (isDocumentAction(action)) {
    const transient = state.actionStatusById?.[action.id] || {};
    const sending = state.sendingActions.has(action.id) || transient.status === "generating";
    const generated = action.status === "generated" || transient.status === "generated";
    const label = blocked ? "Missing info" : sending ? "Generating..." : generated ? "Generated" : "Generate";
    return `<button class="mini-button primary" data-generate-document-action="${action.id}" type="button" ${blocked || sending ? "disabled" : ""}>${label}</button>`;
  }
  const sending = state.sendingActions.has(action.id);
  const agentJob = activeJobForAction(action.id);
  const outboxStatus = outboxRequestStatus(outboxRequestForAction(action.id));
  const completedByAgent = agentJobCompleted(agentJob);
  const completedStatus = completedByAgent ? agentJobStatus(agentJob) : "";
  const effectiveStatus = completedStatus || outboxStatus || action.status;
  const displayStatus = draftDisplayStatus(action, effectiveStatus);
  const locked = ["queued", "running", "waiting_external", "sent"].includes(effectiveStatus) ||
    ["queued", "running", "waiting_external"].includes(agentJob?.status) ||
    completedByAgent;
  const previewing = state.previewActionId === action.id;
  const canSend = !blocked && !locked && !sending;
  const label = sending
    ? isTmsAction(action) ? "Sending..." : "Drafting..."
    : displayStatus === "drafted"
      ? "Drafted"
      : displayStatus === "sent"
        ? "Sent"
      : locked
        ? isTmsAction(action) ? "Sending" : "Drafting"
        : blocked
          ? "Missing info"
        : previewing
          ? "Preview"
          : "Preview";
  const sendButton = `<button class="mini-button primary" data-preview-action="${action.id}" type="button" ${canSend ? "" : "disabled"}>${label}</button>`;

  return `${callButton}${sendButton}`;
}

function actionRecipientLabel(action) {
  if (isPlatformAlertAction(action)) return action.targetName || "Operator";
  const name = String(action.targetName || "").trim();
  const email = String(action.targetEmail || "").trim();
  if (name && email && name !== email) return `${name} <${email}>`;
  return email || name || "";
}

function actionExecutionOutput(action) {
  if (isSourceBackfillAction(action)) return "Source backfill job";
  if (isMoneyContextAction(action)) return "TMS charge check job";
  if (isCarrierTrackingRefreshAction(action)) return "Movement verification job";
  if (isStationFeeAction(action)) return "Fee confirmation";
  if (isPrearrivalQuoteDecisionAction(action)) return "Quote plan decision";
  if (isPlatformAlertAction(action)) return "Operator decision";
  if (isDocumentAction(action)) return "Delivery order PDF";
  if (isTmsPodAction(action)) return "CourierCloud POD closeout";
  if (isTmsAction(action)) return "CourierCloud alert";
  if (action.documentIntent?.kind === "delivery-order" || action.attachmentIntent?.kind === "delivery-order") {
    return "Gmail draft with delivery order";
  }
  return "Gmail draft";
}

function actionExecutionThread(action) {
  if (isPlatformAlertAction(action)) return "In platform";
  if (isDocumentAction(action)) return "Local PDF";
  if (isTmsAction(action)) return action.orderLink ? "CourierCloud order" : "CourierCloud link needed";
  if (action.replyMessageId || action.conversation?.replyMessageId || action.conversation?.threadId) return "Reply in Gmail thread";
  if (action.threadPolicy === "reply_existing") return "Gmail thread needed";
  return "New Gmail thread";
}

function actionExecutionPacketRows(action) {
  const rows = [
    { label: "Output", value: actionExecutionOutput(action) },
    { label: isTmsAction(action) ? "Target" : "To", value: actionRecipientLabel(action) },
    { label: "Thread", value: actionExecutionThread(action) },
  ];
  if (action.cc && !isPlatformAlertAction(action)) rows.push({ label: "CC", value: action.cc });
  if (action.bcc && !isPlatformAlertAction(action) && !isTmsAction(action)) rows.push({ label: "BCC", value: action.bcc });
  if (isSourceBackfillAction(action)) {
    const missing = sourceCoverageMissingStagesForUi(action);
    if (missing.length) rows.push({ label: "Proof", value: missing.join(", ") });
  }
	  if (isMoneyContextAction(action)) {
	    const missing = Array.isArray(action.missingMoneyFields)
      ? action.missingMoneyFields
      : action.costContext?.missing || [];
    if (missing.length) rows.push({ label: "Money", value: missing.join(", ") });
    if (action.costContext?.lastRefresh?.note || action.costContext?.lastRefresh?.status) {
      rows.push({ label: "Last check", value: action.costContext.lastRefresh.note || action.costContext.lastRefresh.status });
    }
    const auditRows = action.costContext?.lastRefresh?.extractionAudit?.moneyRows || [];
    const firstAuditRow = Array.isArray(auditRows) ? auditRows.find((item) => item?.row)?.row : "";
	    if (firstAuditRow) rows.push({ label: "Seen", value: firstAuditRow });
	  }
	  if (isCarrierTrackingRefreshAction(action)) {
	    if (action.carrier || action.liveTracking?.source) rows.push({ label: "Carrier", value: action.carrier || action.liveTracking.source });
	    if (action.station) rows.push({ label: "Station", value: action.station });
	    const flightValue = [...new Set([
	      ...(Array.isArray(action.flights) ? action.flights : []),
	      ...(Array.isArray(action.flightDetails?.flights) ? action.flightDetails.flights : []),
	      action.flightDetails?.primaryFlight,
	    ].map((item) => typeof item === "string" ? item : item?.flight).filter(Boolean))].join(", ") || action.tmsFlight;
	    if (flightValue) rows.push({ label: "Flight", value: flightValue });
	    if (action.route || action.flightDetails?.route) rows.push({ label: "Route", value: action.route || action.flightDetails.route });
	    if (action.trackingError || action.liveTracking?.error) rows.push({ label: "Movement note", value: action.trackingError || action.liveTracking.error });
	  }
		  if (isStationFeeAction(action)) {
	    const fee = action.timing?.feeLine || action.problem || action.reason || "";
	    if (fee) rows.push({ label: "Fee", value: fee });
	  }
  if (isPrearrivalQuoteDecisionAction(action)) {
    const quote = prearrivalQuoteDecisionRecommendedQuote(action);
    const plan = [quote.broker, quote.rate || quoteAmountLabel(quote)].filter(Boolean).join(" ");
    const unlock = Array.isArray(action.quoteDecision?.unlockWhen) ? action.quoteDecision.unlockWhen.join(" + ") : "";
    if (plan) rows.push({ label: "Plan", value: plan });
    if (unlock) rows.push({ label: "Unlock", value: unlock });
    if (action.costContext?.summary) rows.push({ label: "Cost", value: action.costContext.summary });
  }
  if (isDocumentAction(action) && action.documentIntent?.carrierName) {
    rows.push({ label: "Carrier", value: action.documentIntent.carrierName });
  }
  return rows.filter((row) => String(row.value || "").trim());
}

function renderActionExecutionPacket(action) {
  const rows = actionExecutionPacketRows(action);
  if (!rows.length) return "";
  return `
    <div class="action-execution-packet" aria-label="Action execution packet">
      ${rows
        .map((row) => `
          <div>
            <span>${escapeHtml(row.label)}</span>
            <strong>${escapeHtml(shortText(row.value, "", 96))}</strong>
          </div>
        `)
        .join("")}
    </div>
  `;
}

function actionShouldLeadQuotePanel(action) {
  if (!action) return false;
  if (isExecutablePlatformAction(action) && actionPriorityRankForUi(action) <= actionPriorityRankForUi({ priority: "urgent" })) return true;
  if (actionWorkstreamForUi(action) !== "execution") return false;
  return actionPriorityRankForUi(action) <= actionPriorityRankForUi({ priority: "high" }) &&
    todayActionTypeRank(action) < todayActionTypeRank({ type: "quote-request" });
}

function renderActions(shipment) {
  const actions = actionsForShipment(shipment).filter(activeActionPanelItem);
  const quotePanel = renderQuotePanel(shipment);
  if (!actions.length && !quotePanel) return "";
  const quotePanelYields = quotePanel && actions.some(actionShouldLeadQuotePanel);
  const leadingActions = quotePanelYields ? actions.filter(actionShouldLeadQuotePanel) : [];
  const trailingActions = quotePanelYields ? actions.filter((action) => !actionShouldLeadQuotePanel(action)) : actions;

  return `
    <div class="action-list">
      ${leadingActions.map(renderActionCard).join("")}
      ${quotePanel}
      ${trailingActions.map(renderActionCard).join("")}
    </div>
  `;
}

function renderActionSection(shipment) {
  const actions = renderActions(shipment);
  if (!actions) return "";
  return `
    <section class="section operator-section">
      <h3>Actions</h3>
      ${actions}
    </section>
  `;
}

