function operatorStateOutcomeOptions(action) {
  const rows = Array.isArray(action?.operatorOutcomeOptions) && action.operatorOutcomeOptions.length
    ? action.operatorOutcomeOptions
    : (action?.operatorUpdateOptions || []).map((label) => ({
        value: String(label || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "operator-outcome",
        label,
      }));
  return rows.length ? rows : [
    { value: "picked-up", label: "Picked up" },
    { value: "delivered-pod-pending", label: "Delivered, POD pending" },
    { value: "no-movement-yet", label: "No movement yet" },
    { value: "other", label: "Other outcome" },
  ];
}

