async function sendActionFromPlatform(actionId) {
  if (state.sendingActions.has(actionId)) return;
  const action = findActionById(actionId);
  if (!action) {
    state.refresh.status = friendlyActionError("Action missing");
    renderPreservingAppScroll();
    return;
  }
  if (isPlatformAlertAction(action) && !isExecutablePlatformAction(action)) {
    state.refresh.status = "Platform alerts stay in Ops Brain";
    renderPreservingAppScroll();
    return;
  }
  if (!isExecutablePlatformAction(action) && !["gmail", "couriercloud", "tms", "couriercloud-tms"].includes(normalizeChannel(action.channel))) {
    state.refresh.status = "Only draftable operator actions are available";
    renderPreservingAppScroll();
    return;
  }
  const submittedAction = actionWithDraftEdits(action);

	  state.sendingActions.add(actionId);
	  state.refresh.status = isMoneyContextAction(action)
	    ? "Checking TMS charges"
	    : isSourceBackfillAction(action)
	      ? "Recording source repair"
	      : isCarrierTrackingRefreshAction(action)
	        ? carrierActionNeedsFlightStatus(action) ? "Checking flight status" : "Checking movement"
	      : "Preparing draft";
  renderPreservingAppScroll();

  try {
    const result = await queueActionViaApi(actionId, submittedAction);
    if (isSourceBackfillAction(action) && result.request) {
      rememberEmailSyncRequest(result.request);
    }
    if (isMoneyContextAction(action) && result.request) {
      rememberMoneySyncRequest(result.request);
    }
    if (result.request?.agentJobId) {
      const jobPayload = {
        actionId,
        shipmentId: action.shipmentId,
        awb: action.awb,
        to: result.request.to,
        cc: result.request.cc || "",
        bcc: result.request.bcc || "",
        targetName: result.request.targetName || action.targetName || "",
        subject: result.request.subject || action.subject || "",
        body: result.request.body || action.body || "",
        orderLink: result.request.orderLink || action.orderLink || "",
	        missingFields: result.request.missingFields || action.missingMoneyFields || action.costContext?.missing || [],
	        carrier: result.request.carrier || action.carrier || action.liveTracking?.source || "",
	        station: result.request.station || action.station || "",
	        trackingError: result.request.trackingError || action.trackingError || action.liveTracking?.error || "",
	        flightIntelligenceRequired: Boolean(result.request.flightIntelligenceRequired || action.flightIntelligenceRequired || action.liveTracking?.requiresFlightIntelligence),
	        flightDetails: result.request.flightDetails || action.flightDetails || action.liveTracking?.flightDetails || null,
	        flights: result.request.flights || action.flights || action.liveTracking?.flights || [],
	        tmsFlight: result.request.tmsFlight || action.tmsFlight || action.liveTracking?.tmsFlight || "",
	        route: result.request.route || action.route || action.liveTracking?.route || "",
	        publicFlightStatus: result.request.publicFlightStatus || action.publicFlightStatus || action.liveTracking?.publicFlightStatus || null,
	        mode: isMoneyContextAction(action)
	          ? "money-refresh"
	          : isSourceBackfillAction(action)
	            ? "source-backfill"
	            : isCarrierTrackingRefreshAction(action)
	              ? "movement-verification"
	            : isTmsAction(action)
	              ? "operator-approved-tms"
	              : "draft",
	        transport: isMoneyContextAction(action)
	          ? "money-refresh"
	          : isSourceBackfillAction(action)
	            ? CANONICAL_GMAIL_INGESTION_PIPELINE
	            : isCarrierTrackingRefreshAction(action)
	              ? "movement-verification"
	            : isTmsPodAction(action)
	              ? "complete_tms_pod_closeout"
              : isTmsAction(action)
                ? "send_tms_agt_alert"
                : "gmail-draft",
      };
      const job = {
        id: result.request.agentJobId,
        job_type: result.jobType || "draft_gmail_email",
        status: "queued",
        payload: jobPayload,
        created_at: result.request.queuedAt || new Date().toISOString(),
        updated_at: result.request.queuedAt || new Date().toISOString(),
      };
      if (!state.agentJobs.some((item) => item.id === job.id)) {
        state.agentJobs = [job, ...state.agentJobs];
      }
    }

	    const nextActionStatus = isMoneyContextAction(action) || isSourceBackfillAction(action) || isCarrierTrackingRefreshAction(action)
	      ? result.request?.status || (result.recorded ? "recorded" : result.queued ? "queued" : "queued")
      : result.request?.status === "drafted" || result.drafted
      ? "drafted"
      : result.request?.status === "sent" || result.sent
        ? "sent"
        : "queued";
    const nextDraftedAt = result.request?.draftedAt || result.createdAt || "";
    const resultStatus = {
      queuedAt: result.request?.queuedAt,
      draftedAt: nextDraftedAt,
      sentAt: result.request?.sentAt || result.sentAt || "",
      agentJobId: result.request?.agentJobId,
      outboxRequestId: result.request?.id,
      gmailDraftId: result.gmailDraftId || result.request?.gmailDraftId || result.execution?.gmailDraftId || "",
      gmailMessageId: result.gmailMessageId || result.request?.gmailMessageId || result.execution?.gmailMessageId || "",
      gmailThreadId: result.gmailThreadId || result.request?.gmailThreadId || result.execution?.gmailThreadId || "",
      direct: Boolean(result.direct),
      executionResult: result.execution,
    };

    state.actions = state.actions.map((action) =>
      action.id === actionId
        ? {
            ...action,
            ...submittedAction,
            status: nextActionStatus,
            ...resultStatus,
          }
        : action,
    );
    state.shipments = state.shipments.map((shipment) => ({
      ...shipment,
      recommendedActions: (shipment.recommendedActions || []).map((action) =>
        action.id === actionId
          ? {
              ...action,
              ...submittedAction,
              status: nextActionStatus,
              ...resultStatus,
            }
          : action,
      ),
    }));
    state.actionStatusById[actionId] = {
      status: nextActionStatus,
      ...resultStatus,
    };
    updateBrainActionState(actionId, {
      status: nextActionStatus,
      ...resultStatus,
    });
    if (action.operatorEventId) {
      recordOperatorEventActionViaApi(
        action.operatorEventId,
        nextActionStatus === "drafted" ? "draft_created" : "draft_requested",
        {
          actionId,
          awb: action.awb || "",
          status: nextActionStatus,
          outboxRequestId: result.request?.id || "",
          gmailDraftId: resultStatus.gmailDraftId || "",
        },
      ).catch(() => {});
    }
    state.refresh.status = nextActionStatus === "drafted"
      ? resultStatus.direct || resultStatus.gmailDraftId ? "Gmail draft created" : "Draft recorded"
      : isSourceBackfillAction(action)
        ? result.request?.duplicate
          ? "Source backfill already queued"
          : result.recorded
            ? "Source backfill recorded"
            : "Source backfill queued"
	      : isMoneyContextAction(action)
	        ? result.request?.duplicate
	          ? "TMS charge check already queued"
	          : result.recorded
	            ? "TMS charge check recorded"
	            : "TMS charge check queued"
	      : isCarrierTrackingRefreshAction(action)
	        ? result.request?.duplicate
	          ? "Movement check already queued"
	          : result.recorded
	            ? "Movement check recorded"
	            : "Movement check queued"
	      : result.request?.duplicate
        ? "Already pending"
        : normalizeChannel(action.channel) === "gmail"
          ? "Draft pending"
          : isTmsPodAction(action)
            ? "POD closeout queued"
            : "TMS alert queued";
    if (state.previewActionId === actionId) state.previewActionId = null;
    state.sendingActions.delete(actionId);
    renderPreservingAppScroll();
    if (shouldPollAgentJobs()) {
      window.setTimeout(() => {
        pollAgentJobs().catch(() => {});
      }, 2500);
    }
  } catch (error) {
    state.sendingActions.delete(actionId);
    state.refresh.status = friendlyActionError(error, "Unable to queue draft");
    renderPreservingAppScroll();
  }
}

async function generateDeliveryOrderFromPlatform(actionId) {
  if (state.sendingActions.has(actionId)) return;
  const action = findActionById(actionId);
  if (!action || !isDocumentAction(action)) {
    state.refresh.status = friendlyActionError("Delivery order action is required");
    renderPreservingAppScroll();
    return;
  }

  state.sendingActions.add(actionId);
  state.actionStatusById[actionId] = {
    ...(state.actionStatusById[actionId] || {}),
    status: "generating",
  };
  state.refresh.status = "Generating delivery order";
  renderPreservingAppScroll();

  try {
    const result = await generateDeliveryOrderViaApi(actionId, action);
    const pdfObjectUrl = deliveryOrderObjectUrlFromBase64(result.pdfBase64);
    const safeExecutionResult = { ...result };
    delete safeExecutionResult.pdfBase64;
    const generatedState = {
      status: "generated",
      generatedAt: result.createdAt || new Date().toISOString(),
      output: result.output || "",
      publicPath: result.publicPath || "",
      fileName: result.fileName || "",
      executionResult: safeExecutionResult,
    };
    const generatedTransientState = {
      ...generatedState,
      pdfObjectUrl,
    };
    state.actions = state.actions.map((item) => item.id === actionId ? { ...item, ...generatedState } : item);
    state.shipments = state.shipments.map((shipment) => ({
      ...shipment,
      recommendedActions: (shipment.recommendedActions || []).map((item) =>
        item.id === actionId ? { ...item, ...generatedState } : item
      ),
    }));
    state.actionStatusById[actionId] = generatedTransientState;
    updateBrainActionState(actionId, generatedState);
    if (action.operatorEventId) {
      recordOperatorEventActionViaApi(action.operatorEventId, "document_generated", {
        actionId,
        awb: action.awb || "",
        fileName: result.fileName || "",
        publicPath: result.publicPath || "",
      }).catch(() => {});
    }
    state.refresh.status = result.fileName ? `PDF generated: ${result.fileName}` : "Delivery order PDF generated";
  } catch (error) {
    const failedState = {
      status: "failed",
      error: friendlyActionError(error, "Unable to generate delivery order"),
    };
    state.actionStatusById[actionId] = {
      ...(state.actionStatusById[actionId] || {}),
      ...failedState,
    };
    updateBrainActionState(actionId, failedState);
    state.refresh.status = failedState.error;
  } finally {
    state.sendingActions.delete(actionId);
    renderPreservingAppScroll();
  }
}

async function saveStationMemoryFromForm(shipmentId, form) {
  if (state.savingStationMemory.has(shipmentId)) return;
  const shipment = shipmentById(shipmentId);
  if (!shipment) return;

  const entry = stationMemoryEntryFromForm(shipment, form);
  state.pendingStationMemoryEntries[shipmentId] = entry;
  state.expandedStationMemoryEditors.add(shipmentId);
  state.savingStationMemory.add(shipmentId);
  state.stationMemoryStatusById[shipmentId] = { kind: "saving", message: "Saving station memory…" };
  state.refresh.status = "Saving station memory";
  try {
    // Render calls live INSIDE the try: anything thrown before the await used
    // to strand the shipment in savingStationMemory, so every later Save
    // silently early-returned — a stuck "Saving" with no POST ever sent.
    renderActionSurfaces();
    if (state.detailOpen) renderDetail();
    const result = await saveStationMemoryViaApi(entry);
    // Keep the typed fields until the shipment row itself carries the taught
    // contact (renderStationMemoryEditor reconciles on later renders).
    state.stationMemoryStatusById[shipmentId] = {
      kind: "saved",
      message: result.note || "Saved to station memory.",
    };
    state.refresh.status = result.note || "Station memory saved";
    await loadSnapshot();
    render();
  } catch (error) {
    // companion-mode blanks the global refresh status line, so failures must
    // be visible INSIDE the form (INC-2026-07-05-STATION-MEMORY-SAVE).
    state.stationMemoryStatusById[shipmentId] = {
      kind: "error",
      message: error instanceof Error ? error.message : "Station memory save failed",
    };
    state.refresh.status = error instanceof Error ? error.message : "Station memory save failed";
    renderActionSurfaces();
    if (state.detailOpen) renderDetail();
  } finally {
    state.savingStationMemory.delete(shipmentId);
    if (state.detailOpen) renderDetail();
  }
}

