function stationFeeResolutionNote(action, entry) {
  const amount = String(entry.amount || "").trim();
  const amountText = amount ? `${amount} ` : "";
  const source = [entry.contactName, entry.contactOrganization].filter(Boolean).join(" / ");
  const receipt = String(entry.receipt || "").trim();
  const note = String(entry.note || "").trim();
  const sourceText = source ? ` Source: ${source}.` : "";
  const receiptText = receipt ? ` Receipt/reference: ${receipt}.` : "";
  const noteText = note ? ` Note: ${note}.` : "";
  if (entry.outcome === "due") {
    return `Station fee pickup blocked: ground fees ${amountText}due/open for ${action.awb}.${sourceText}${noteText}`;
  }
  if (entry.outcome === "blocked") {
    return `Station fee pickup blocked for ${action.awb}: station could not release the freight after fee check.${sourceText}${noteText}`;
  }
  if (entry.outcome === "not-blocking") {
    return `Ground fees confirmed not blocking pickup for ${action.awb}; station fee desk cleared pickup execution.${sourceText}${receiptText}${noteText}`;
  }
  return `Ground fees ${amountText}paid and receipt/payment confirmed for ${action.awb}.${sourceText}${receiptText}${noteText}`;
}

