function operatorStateOutcomeResolutionNote(action, entry) {
  const source = [entry.contactName, entry.contactOrganization].filter(Boolean).join(" / ");
  const proof = String(entry.proof || "").trim();
  const note = String(entry.note || "").trim();
  const suffix = [
    source ? `Source/contact: ${source}.` : "",
    proof ? `Proof/thread: ${proof}.` : "",
    note ? `Note: ${note}.` : "",
  ].filter(Boolean).join(" ");
  const awb = action.awb || entry.awb || "";
  const base = {
    "approved-recommended-broker": `Pickup broker approved for ${awb}: operator approved the recommended pickup broker.`,
    "approved-different-broker": `Pickup broker approved for ${awb}: operator approved a different pickup broker.`,
    "hold-pickup": `Pickup remains on hold for ${awb}: operator decided not to award or dispatch pickup yet.`,
    "picked-up": `Picked up: operator confirmed AWB ${awb} was picked up.`,
    "out-for-delivery": `Out for delivery today: operator confirmed AWB ${awb} is out for delivery.`,
    "delivered-pod-pending": `Delivered, POD pending: operator confirmed AWB ${awb} was delivered and POD is still pending.`,
    "delivered-with-pod": `Delivered with POD: operator confirmed AWB ${awb} was delivered and signed POD was received.`,
    "still-waiting-station": `Still waiting at station: operator confirmed AWB ${awb} has not been picked up and is still waiting at the station.`,
    "quote-requests-sent": `Quote requests were sent for AWB ${awb}.`,
    "broker-approved": `Pickup broker approved for AWB ${awb}.`,
    "no-movement-yet": `No movement yet for AWB ${awb}: operator confirmed the stale state is still accurate.`,
  }[entry.outcome] || `${entry.outcomeLabel || "State outcome"} for AWB ${awb}.`;
  return [base, suffix].filter(Boolean).join(" ").replace(/\s+/g, " ").trim();
}

