async function loadActionPreview(actionId) {
  const action = findActionById(actionId);
  if (!action || state.previewLoadingActionIds.has(actionId)) return;
  if (isPlatformAlertAction(action)) {
    state.previewActionId = null;
    state.refresh.status = "Platform alert";
    renderActionSurfaces();
    return;
  }
  state.previewLoadingActionIds.add(actionId);
  state.previewDraftsByActionId[actionId] = {
    ...(state.previewDraftsByActionId[actionId] || {}),
    error: "",
  };
  const editFingerprint = draftEditFingerprint(actionId);
  renderActionSurfaces();
  try {
    const result = await previewActionViaApi(actionId, action);
    if (draftEditFingerprint(actionId) !== editFingerprint) {
      state.previewDraftsByActionId[actionId] = {
        ...(state.previewDraftsByActionId[actionId] || {}),
        request: null,
        error: "",
        dirty: true,
      };
      return;
    }
    state.previewDraftsByActionId[actionId] = {
      request: result.request || null,
      safety: result.safety || result.request?.safety || null,
      jobType: result.jobType || "",
      validatedAt: new Date().toISOString(),
      error: "",
      dirty: false,
    };
  } catch (error) {
    state.previewDraftsByActionId[actionId] = {
      request: null,
      error: friendlyActionError(error, "Unable to preview draft"),
      dirty: true,
    };
  } finally {
    state.previewLoadingActionIds.delete(actionId);
    renderActionSurfaces();
  }
}

