function closeDetail() {
  if (isDesktopWorkspace()) {
    state.selectedId = null;
    state.selectedGroupId = null;
    state.selectedVisualGroupKey = null;
    state.selectedCompletedSourceAwb = "";
  }
  state.detailOpen = false;
  state.detailScrollKey = "";
  syncDetailShell();
  renderList();
}

function renderTime() {
  if (document.body.classList.contains("companion-mode")) {
    $("snapshotTime").textContent = "";
    return;
  }
  const date = state.snapshotTime ? new Date(state.snapshotTime) : new Date();
  $("snapshotTime").textContent = `Snapshot ${new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(date)}`;
}

function renderRefreshStatus() {
  state.syncHealth = computeSyncHealth();
  const refreshButton = $("refreshButton");
  const manualRefreshAuthorized = canUseLocalApi();
  if (document.body.classList.contains("companion-mode")) {
    $("refreshStatus").textContent = "";
    if (!refreshButton) return;
    refreshButton.disabled = state.refresh.running || !manualRefreshAuthorized;
    refreshButton.textContent = "";
    refreshButton.title = "";
    refreshButton.setAttribute("aria-label", "Refresh");
    refreshButton.classList.remove("health-ok", "health-watch", "health-problem", "health-running", "health-unknown");
    refreshButton.classList.add("health-unknown");
    return;
  }
  const emailProofRequest = latestEmailProofRefreshRequest();
  const needsEmailProof = emailProofNeedsRefresh();
  const shouldRequestEmailProof = needsEmailProof && !emailProofRequest;
  const emailProofRequestStatus = String(emailProofRequest?.status || "").toLowerCase();
  const emailProofRequestStale = staleEmailProofRefreshRequest(emailProofRequest);
  const emailProofRequestClaimable = emailProofRequestStale && claimableEmailProofRefreshRequest(emailProofRequest) && canUseLocalApi();
  const emailProofRequestHostedRunnable = hostedRunnableEmailProofRefreshRequest(emailProofRequest);
  const emailProofRunBlocked = Boolean(emailProofRequest?.runStatus === "blocked" || emailProofRequest?.lastRunError);
  const refreshButtonLabel = !manualRefreshAuthorized
    ? "Automatic refresh"
    : state.refresh.running
    ? "Refreshing"
    : shouldRequestEmailProof
      ? "Refresh email proof"
      : needsEmailProof && emailProofRunBlocked
        ? "Email proof blocked"
      : needsEmailProof && emailProofRequestClaimable
        ? "Claim email proof"
      : needsEmailProof && emailProofRequestHostedRunnable
        ? "Run hosted proof"
      : needsEmailProof && emailProofRequestStale
        ? "Email proof waiting"
      : needsEmailProof && emailProofRequestStatus === "cron-owned"
        ? "Direct Gmail pending"
      : needsEmailProof && emailProofRequest
        ? emailProofRequestStatus === "running"
          ? "Email proof running"
          : "Email proof queued"
        : "Refresh";
  const refreshTitle = !manualRefreshAuthorized
    ? "Manual refresh is disabled until an authenticated operator session can authorize mutations. Email and shipment truth refresh through server automation."
    : state.refresh.running
    ? state.refresh.status
    : shouldRequestEmailProof
      ? "Queue email proof refresh and rebuild the dashboard after Gmail evidence is updated."
      : needsEmailProof && emailProofRunBlocked
        ? emailProofRequest.lastRunError || "Email proof run is blocked."
      : needsEmailProof && emailProofRequestClaimable
        ? `Claim this Gmail proof refresh and generate the AWB-specific Gmail work packet. Queued since ${shortAge(emailProofRequestActivityTime(emailProofRequest)) || "earlier"}.`
      : needsEmailProof && emailProofRequestHostedRunnable
        ? `Run hosted Gmail proof for this stale request. It has been ${emailProofRequest.status || "queued"} since ${shortAge(emailProofRequestActivityTime(emailProofRequest)) || "earlier"}.`
      : needsEmailProof && emailProofRequestStale
        ? `Email proof refresh ${emailProofRequest.status || "queued"} since ${shortAge(emailProofRequestActivityTime(emailProofRequest)) || "earlier"}. The Gmail processor needs to claim this request.`
      : needsEmailProof && emailProofRequestStatus === "cron-owned"
        ? "Hosted Gmail OAuth direct ingestion owns this stale-proof repair. No legacy email_refresh job was queued from the dashboard."
      : needsEmailProof && emailProofRequest
        ? `Email proof refresh ${emailProofRequest.status || "queued"} ${shortAge(emailProofRequestActivityTime(emailProofRequest)) || "recently"}. Click to refresh TMS and dashboard data.`
        : state.syncHealth.detail;
  const operatorStatus = state.refresh.status && state.refresh.status !== "Ready" ? state.refresh.status : "";
  $("refreshStatus").textContent = state.refresh.running ? state.refresh.status : operatorStatus || state.syncHealth.label;
  if (!refreshButton) return;
  refreshButton.disabled = state.refresh.running || !manualRefreshAuthorized;
  refreshButton.dataset.refreshAuthority = manualRefreshAuthorized ? "local-operator" : "server-only";
  refreshButton.textContent = refreshButtonLabel;
  refreshButton.title = refreshTitle;
  refreshButton.setAttribute(
    "aria-label",
    state.refresh.running ? state.refresh.status : `${state.syncHealth.label}. ${refreshTitle}`,
  );
  refreshButton.classList.remove("health-ok", "health-watch", "health-problem", "health-running", "health-unknown");
  refreshButton.classList.add(`health-${state.refresh.running ? "running" : state.syncHealth.level}`);
}

function render() {
  const typing = captureOperatorTyping();
  document.body.classList.toggle("companion-mode", state.filter === "brain" || isDesktopWorkspace());
  renderTime();
  renderRefreshStatus();
  renderEmailProofPacket();
  renderList();
  if (detailShouldRender()) {
    renderDetail();
  } else {
    $("detailPane").innerHTML = "";
    syncDetailShell();
  }
  // Restore AFTER the whole pass (renderList's own restore can be undone by
  // the detail-pane work above). Deferred so it wins over any late DOM work.
  if (typing) window.setTimeout(() => restoreOperatorTyping(typing), 0);
}

async function waitForRefresh() {
  for (;;) {
    const response = await fetch("/api/refresh/status");
    if (!response.ok) throw new Error("Refresh status unavailable");
    const status = await response.json();
    const step = status.currentStep;
    state.refresh.running = status.state === "running";
    state.refresh.status = step?.label || (status.state === "error" ? status.lastError : "Ready");
    renderRefreshStatus();

    if (status.state !== "running") {
      if (status.state === "error") throw new Error(status.lastError || "Refresh failed");
      return status;
    }

    await new Promise((resolve) => setTimeout(resolve, 900));
  }
}

function rememberEmailSyncRequest(request) {
  if (!request?.id) return;
  const current = state.emailSyncRequests && typeof state.emailSyncRequests === "object"
    ? state.emailSyncRequests
    : { requests: [] };
  state.emailSyncRequests = {
    ...current,
    snapshotTime: request.queuedAt || request.createdAt || new Date().toISOString(),
    requests: [request, ...(current.requests || []).filter((item) => item?.id !== request.id)].slice(0, 100),
  };
}

function rememberMoneySyncRequest(request) {
  if (!request?.id) return;
  const current = state.moneySyncRequests && typeof state.moneySyncRequests === "object"
    ? state.moneySyncRequests
    : { requests: [] };
  state.moneySyncRequests = {
    ...current,
    snapshotTime: request.queuedAt || request.createdAt || new Date().toISOString(),
    requests: [request, ...(current.requests || []).filter((item) => item?.id !== request.id)].slice(0, 100),
  };
}

async function queueEmailProofRefresh(options = {}) {
  const existing = latestEmailProofRefreshRequest();
  if (existing) return { queued: false, alreadyQueued: true, request: existing };
  const source = options.source || "dashboard";
  const trigger = options.trigger || "";
  if (canUseLocalApi()) {
    const response = await fetch("/api/email-refresh", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ source, trigger }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || "Email proof refresh request failed");
    rememberEmailSyncRequest(result.request);
    return result;
  }
  const now = new Date().toISOString();
  const proofSnapshotTime = gmailProofSnapshotTimeForUi();
  const request = {
    id: `email-sync-${Date.parse(now)}`,
    type: "gmail-proof-refresh",
    reason: "email-proof-stale",
    status: "cron-owned",
    requestedAt: now,
    recordedAt: now,
    queuedAt: null,
    snapshotTime: state.snapshotTime,
    proofSnapshotTime,
    proofAgeMinutes: gmailProofAgeMinutesForUi(),
    source,
    trigger,
    awbs: activeShipmentAwbsForUi(),
    canonicalPipeline: CANONICAL_GMAIL_INGESTION_PIPELINE,
    note: "Hosted Gmail OAuth direct ingestion owns stale email proof repair; dashboard did not queue a legacy email_refresh job.",
  };
  rememberEmailSyncRequest(request);
  return { queued: false, alreadyQueued: false, cronOwned: true, request };
}

async function claimEmailProofRefresh(request) {
  if (!request?.id) throw new Error("Email proof request missing");
  if (!canUseLocalApi()) throw new Error("Email proof claim requires local dashboard runtime");
  const response = await fetch("/api/email-refresh/claim", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ requestId: request.id }),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok || result.error) throw new Error(result.error || "Email proof claim failed");
  if (result.request) rememberEmailSyncRequest(result.request);
  return result;
}

async function loadEmailProofPacket(requestId, options = {}) {
  if (!requestId || !canUseLocalApi()) return null;
  state.emailProofPacket = { requestId, loading: true };
  if (!options.silent) renderEmailProofPacket();
  try {
    const response = await fetch(`/api/email-refresh/context?requestId=${encodeURIComponent(requestId)}`);
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.error) throw new Error(result.error || "Email proof packet unavailable");
    state.emailProofPacket = {
      ...result,
      requestId,
      loaded: result.found === true,
      loading: false,
      loadedAt: new Date().toISOString(),
    };
    if (!result.found) state.refresh.status = result.reason || "Email proof packet not ready";
    render();
    return result;
  } catch (error) {
    state.emailProofPacket = {
      requestId,
      loading: false,
      error: error instanceof Error ? error.message : "Email proof packet unavailable",
    };
    renderEmailProofPacket();
    return null;
  }
}

async function completeEmailProofPacket(requestId) {
  if (!requestId || !canUseLocalApi()) return null;
  state.emailProofPacket = {
    ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
    requestId,
    completing: true,
    error: "",
  };
  state.refresh.status = "Completing email proof";
  render();
  try {
    const response = await fetch("/api/email-refresh/complete", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ requestId }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.error) throw new Error(result.error || "Email proof completion failed");
    if (result.request) rememberEmailSyncRequest(result.request);
    state.refresh.status = "Email proof completed";
    state.emailProofPacket = {
      requestId,
      completing: false,
      completed: true,
      result,
    };
    await loadSnapshot();
    render();
    return result;
  } catch (error) {
    state.emailProofPacket = {
      ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
      requestId,
      completing: false,
      error: error instanceof Error ? error.message : "Email proof completion failed",
    };
    state.refresh.status = "Email proof completion blocked";
    render();
    return null;
  }
}

async function runEmailProofPacket(requestId) {
  if (!requestId || !canUseLocalApi()) return null;
  state.emailProofPacket = {
    ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
    requestId,
    running: true,
    error: "",
  };
  state.refresh.status = "Running Gmail proof";
  render();
  try {
    const response = await fetch("/api/email-refresh/run", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ requestId }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.error && !result.blocked) throw new Error(result.error || "Email proof run failed");
    if (result.request) rememberEmailSyncRequest(result.request);
    const blockedMessage = result.error || result.reason || result.request?.lastRunError || "";
    state.refresh.status = result.completed
      ? "Email proof run complete"
      : result.blocked
        ? "Email proof run blocked"
        : "Email proof output ready";
    state.emailProofPacket = {
      ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
      requestId,
      running: false,
      result,
      error: result.blocked ? blockedMessage : "",
    };
    await loadSnapshot();
    if (!result.completed && result.request?.contextFile) {
      await loadEmailProofPacket(requestId, { silent: true });
    } else {
      render();
    }
    return result;
  } catch (error) {
    state.emailProofPacket = {
      ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
      requestId,
      running: false,
      error: error instanceof Error ? error.message : "Email proof run failed",
    };
    state.refresh.status = "Email proof run blocked";
    render();
    return null;
  }
}

async function runHostedEmailProofPacket(requestId) {
  if (!requestId || !canUseLocalApi()) return null;
  state.emailProofPacket = {
    ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
    requestId,
    runningHosted: true,
    error: "",
  };
  state.refresh.status = "Running hosted Gmail proof";
  render();
  try {
    const response = await fetch("/api/email-refresh/hosted-run", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ requestId }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.error && !result.blocked) throw new Error(result.error || "Hosted email proof run failed");
    if (result.request) rememberEmailSyncRequest(result.request);
    const blockedMessage = result.error || result.reason || result.request?.lastHostedRunError || "";
    state.refresh.status = result.blocked
      ? result.hosted?.ok && result.hostedImport?.error
        ? "Hosted proof refreshed; local import blocked"
        : "Hosted email proof blocked"
      : result.completed || result.hostedImport?.ok
        ? "Hosted email proof imported"
        : "Hosted email proof complete";
    state.emailProofPacket = {
      ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
      requestId,
      runningHosted: false,
      hostedResult: result,
      error: result.blocked ? blockedMessage : "",
    };
    await loadSnapshot();
    render();
    return result;
  } catch (error) {
    state.emailProofPacket = {
      ...(state.emailProofPacket?.requestId === requestId ? state.emailProofPacket : {}),
      requestId,
      runningHosted: false,
      error: error instanceof Error ? error.message : "Hosted email proof run failed",
    };
    state.refresh.status = "Hosted email proof blocked";
    render();
    return null;
  }
}

function maybeLoadCurrentEmailProofPacket() {
  const request = currentEmailProofPacketRequest();
  if (!request?.id || !canUseLocalApi()) return;
  if (state.emailProofPacket?.requestId === request.id && (state.emailProofPacket.loading || state.emailProofPacket.loaded)) return;
  loadEmailProofPacket(request.id, { silent: true }).catch(() => {});
}

async function maybeQueueStaleEmailProofRefresh(trigger = "initial-load") {
  // Production email refresh is owned by the hosted cron (and the operator's
  // run-now button). The legacy email-proof request queue exists only for the
  // local development runtime — a production "queued" record is fake state.
  if (!canUseLocalApi()) return { requested: false, reason: "cron-owned" };
  if (!emailProofNeedsRefresh() || latestEmailProofRefreshRequest() || state.refresh.running) {
    return { requested: false };
  }
  const key = emailProofAutoRefreshKey();
  if (emailProofAutoRefreshOnCooldown(key)) return { requested: false, reason: "cooldown" };
  if (hostedPersistenceDegraded()) {
    state.refresh.status = "Hosted truth persistence degraded";
    renderRefreshStatus();
    return { requested: false, reason: "truth-health-degraded" };
  }

  state.refresh.status = "Requesting email proof";
  renderRefreshStatus();
  try {
    const result = await queueEmailProofRefresh({ source: "dashboard-auto", trigger });
    writeEmailProofAutoRefreshRecord({
      key,
      queuedAt: new Date().toISOString(),
      requestId: result.request?.id || "",
      proofSnapshotTime: gmailProofSnapshotTimeForUi(),
      trigger,
    });
    state.refresh.status = result.alreadyQueued ? "Email proof already queued" : "Email proof requested";
    render();
    return { requested: true, result };
  } catch (error) {
    state.refresh.status = error instanceof Error ? error.message : "Email proof refresh needs operator";
    renderRefreshStatus();
    return { requested: false, error };
  }
}

async function runRefresh() {
  const shouldRequestEmailProof = emailProofNeedsRefresh() && !latestEmailProofRefreshRequest();
  const emailProofRequest = latestEmailProofRefreshRequest();
  const shouldClaimEmailProof = emailProofNeedsRefresh() &&
    staleEmailProofRefreshRequest(emailProofRequest) &&
    claimableEmailProofRefreshRequest(emailProofRequest) &&
    canUseLocalApi();
  const shouldRunHostedEmailProof = hostedRunnableEmailProofRefreshRequest(emailProofRequest);
  state.refresh.running = true;
  state.refresh.status = shouldRequestEmailProof
    ? "Requesting email proof"
    : shouldClaimEmailProof
      ? "Claiming email proof"
    : shouldRunHostedEmailProof
      ? "Running hosted email proof"
    : canUseLocalApi()
      ? "Starting refresh"
      : "Queueing agent";
  renderRefreshStatus();

  try {
    if (!canUseLocalApi()) {
      state.refresh.status = "Email and shipment truth refresh automatically; manual refresh requires a signed-in operator session";
      renderRefreshStatus();
      return;
    }
    if (shouldRequestEmailProof) {
      const result = await queueEmailProofRefresh({ source: "dashboard-manual", trigger: "manual-refresh-button" });
      state.refresh.status = result.alreadyQueued ? "Email proof already queued" : "Email proof requested";
      renderRefreshStatus();
      return;
    }

    if (shouldClaimEmailProof) {
      const result = await claimEmailProofRefresh(emailProofRequest);
      const request = result.request || {};
      const context = request.contextFile || result.contextFile || "";
      state.refresh.status = result.claimed
        ? context
          ? `Email proof claimed: ${context}`
          : "Email proof claimed"
        : result.reason || "No claimable email proof request";
      renderRefreshStatus();
      if (request.id && context) await loadEmailProofPacket(request.id, { silent: true });
      return;
    }

    if (shouldRunHostedEmailProof) {
      const result = await runHostedEmailProofPacket(emailProofRequest.id);
      state.refresh.status = result?.blocked
        ? result.reason || result.error || result.request?.lastHostedRunError || "Hosted email proof blocked"
        : result?.completed || result?.hostedImport?.ok
          ? "Hosted email proof imported"
          : "Hosted email proof complete";
      renderRefreshStatus();
      return;
    }

    const response = await fetch("/api/refresh", { method: "POST" });
    if (!response.ok) throw new Error("Refresh API unavailable");
    await waitForRefresh();
    await loadSnapshot();
    state.refresh.status = "Refresh complete";
  } catch (error) {
    await loadSnapshot();
    state.refresh.status =
      error instanceof Error && error.message !== "Refresh API unavailable"
        ? error.message
        : "Static reload only";
  } finally {
    state.refresh.running = false;
    await loadOperatorEventsFromApi().catch(() => {});
    render();
  }
}

function shouldPollBoard() {
  return !shouldPreferLocalSnapshots();
}

async function pollBoardFreshness() {
  try {
    const activeElement = document.activeElement;
    if (
      !shouldPollBoard() ||
      document.hidden ||
      activeElement?.tagName === "INPUT" ||
      activeElement?.tagName === "TEXTAREA" ||
      activeElement?.isContentEditable
    ) return;

    const priorOperatorEventsKey = operatorEventsContentKey();
    const operatorEventsLoaded = await loadOperatorEventsFromApi();
    const operatorEventsChanged = operatorEventsLoaded && operatorEventsContentKey() !== priorOperatorEventsKey;
    if (state.refresh?.running || latestEmailProofRefreshRequest()) {
      if (operatorEventsChanged) render();
      return;
    }

    const hosted = await loadHostedSnapshots(["shipment-truth-packets"]);
    const hostedSnapshotTime = hosted?.["shipment-truth-packets"]?.snapshotTime || hosted?.updatedAt || "";
    const hostedSnapshotTimeMs = Date.parse(hostedSnapshotTime);
    const currentSnapshotTimeMs = Date.parse(state.snapshotTime || "");
    if (
      !Number.isFinite(hostedSnapshotTimeMs) ||
      !Number.isFinite(currentSnapshotTimeMs) ||
      hostedSnapshotTimeMs <= currentSnapshotTimeMs
    ) {
      if (operatorEventsChanged) render();
      return;
    }

    await loadSnapshot();
    applyOperatorEventsToNotifications();
    render();
  } catch {
    // Board freshness polling is best-effort and must not disrupt the operator.
  }
}

function startBoardPolling() {
  if (state.boardPoller || !shouldPollBoard()) return;
  state.boardPoller = window.setInterval(() => {
    pollBoardFreshness().catch(() => {});
  }, BOARD_POLL_INTERVAL_MS);
}

function stopBoardPolling() {
  if (state.boardPoller) window.clearInterval(state.boardPoller);
  state.boardPoller = null;
}

function shouldPollAgentJobs() {
  return !shouldPreferLocalSnapshots() && truthHealthKnown() && !hostedPersistenceDegraded();
}

function draftJobActivity(jobs = state.agentJobs) {
  return jobs.some((job) =>
    job?.job_type === "draft_gmail_email" &&
    ["queued", "running", "waiting_external", "succeeded", "failed"].includes(String(job.status || "").toLowerCase())
  );
}

function queuedDraftOutboxActivity() {
  return state.outboxRequests.some((request) =>
    ["queued", "running", "waiting_external"].includes(outboxRequestStatus(request)) &&
    requestIsDraftMode(request)
  );
}

async function pollAgentJobs() {
  if (!shouldPollAgentJobs()) return;
  const nextJobs = await loadAgentJobs();
  state.agentJobs = nextJobs;
  if (draftJobActivity(nextJobs) || queuedDraftOutboxActivity()) {
    await loadHostedDraftState();
  }
  pruneRuntimeWorkToActiveShipments();
  state.actions = state.actions.map((action) => {
    const job = nextJobs.find((item) => {
      const payload = item.payload || {};
      return payload.actionId === action.id || payload.action?.id === action.id;
    });
    if (!agentJobCompleted(job)) return action;
    const status = agentJobStatus(job);
    return {
      ...action,
      status,
      draftedAt: status === "drafted" ? job.completed_at || action.draftedAt : action.draftedAt,
      sentAt: status === "sent" ? job.completed_at || action.sentAt : action.sentAt,
      executionResult: job.result || action.executionResult,
    };
  });
  state.shipments = state.shipments.map((shipment) => ({
    ...shipment,
    recommendedActions: (shipment.recommendedActions || []).map((action) => {
      const job = nextJobs.find((item) => {
        const payload = item.payload || {};
        return payload.actionId === action.id || payload.action?.id === action.id;
      });
      if (!agentJobCompleted(job)) return action;
      const status = agentJobStatus(job);
      return {
        ...action,
        status,
        draftedAt: status === "drafted" ? job.completed_at || action.draftedAt : action.draftedAt,
        sentAt: status === "sent" ? job.completed_at || action.sentAt : action.sentAt,
        executionResult: job.result || action.executionResult,
      };
    }),
  }));
  render();
}

function startAgentJobPolling() {
  if (state.agentJobPoller || !shouldPollAgentJobs()) return;
  state.agentJobPoller = window.setInterval(() => {
    pollAgentJobs().catch(() => {});
  }, 15000);
}

function bindEvents() {
  $("searchInput").addEventListener("input", (event) => {
    state.query = event.target.value.trim();
    renderList();
  });

  $("refreshButton")?.addEventListener("click", runRefresh);

  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      stopBoardPolling();
      return;
    }
    pollBoardFreshness().catch(() => {});
    startBoardPolling();
  });

  // Station-memory forms render inside regenerated HTML on every surface
  // (detail deck, desktop action cards, cockpit), so their handlers must be
  // persistent document-level delegates: per-render bindings died with their
  // detached nodes and the desktop surface had NO submit handler at all —
  // Save fired a browser-native reload and the POST never happened
  // (INC-2026-07-05-STATION-MEMORY-SAVE-UNBOUND-AND-UNAPPLIED).
  document.addEventListener("submit", (event) => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement) || !form.matches("[data-station-memory-form]")) return;
    event.preventDefault();
    event.stopPropagation();
    saveStationMemoryFromForm(form.dataset.stationMemoryForm, form);
  });
  document.addEventListener("input", (event) => {
    const form = event.target instanceof Element ? event.target.closest("[data-station-memory-form]") : null;
    if (!form) return;
    const shipment = shipmentById(form.dataset.stationMemoryForm);
    if (!shipment) return;
    state.pendingStationMemoryEntries[form.dataset.stationMemoryForm] = stationMemoryEntryFromForm(shipment, form);
    const status = state.stationMemoryStatusById[form.dataset.stationMemoryForm];
    if (status && status.kind !== "saving") delete state.stationMemoryStatusById[form.dataset.stationMemoryForm];
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    const target = event.target;
    if (!(target instanceof Element) || target.tagName !== "INPUT") return;
    if (!target.closest("[data-station-memory-form]")) return;
    event.preventDefault();
  });
  // details "toggle" does not bubble; capture phase reaches it from document.
  document.addEventListener("toggle", (event) => {
    const item = event.target;
    if (!(item instanceof Element) || !item.matches("[data-station-memory-editor]")) return;
    const id = item.dataset.stationMemoryEditor;
    if (!id) return;
    if (item.open) {
      state.expandedStationMemoryEditors.add(id);
    } else {
      state.expandedStationMemoryEditors.delete(id);
    }
  }, true);
  document.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const packetButton = target?.closest("[data-load-email-proof-packet]");
    if (packetButton) {
      event.preventDefault();
      loadEmailProofPacket(packetButton.dataset.loadEmailProofPacket || "").catch(() => {});
      return;
    }
    const runProof = target?.closest("[data-run-email-proof]");
    if (runProof) {
      event.preventDefault();
      runEmailProofPacket(runProof.dataset.runEmailProof || "").catch(() => {});
      return;
    }
    const runHostedProof = target?.closest("[data-run-hosted-email-proof]");
    if (runHostedProof) {
      event.preventDefault();
      runHostedEmailProofPacket(runHostedProof.dataset.runHostedEmailProof || "").catch(() => {});
      return;
    }
    const completeProof = target?.closest("[data-complete-email-proof]");
    if (completeProof) {
      event.preventDefault();
      completeEmailProofPacket(completeProof.dataset.completeEmailProof || "").catch(() => {});
      return;
    }
    const copyButton = target?.closest("[data-copy-email-proof-command]");
    if (copyButton) {
      event.preventDefault();
      const command = copyButton.dataset.copyEmailProofCommand || "";
      navigator.clipboard?.writeText(command).then(() => {
        state.refresh.status = "Email proof command copied";
        renderRefreshStatus();
      }).catch(() => {
        state.refresh.status = command || "Email proof command unavailable";
        renderRefreshStatus();
      });
    }
  });

  document.addEventListener("click", handleCopyAwbClick, true);
  document.addEventListener("click", handleTodayDoneControlClick, true);

  $("shipmentList").addEventListener("pointerdown", startTodayCardSwipe);
  $("shipmentList").addEventListener("pointermove", moveTodayCardSwipe);
  $("shipmentList").addEventListener("pointerup", finishTodayCardSwipe);
  $("shipmentList").addEventListener("pointercancel", () => {
    resetSwipeElement(state.todaySwipe?.element);
    state.todaySwipe = null;
  });
  $("shipmentList").addEventListener("toggle", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLDetailsElement) || !target.classList.contains("today-action-more")) return;
    state.todayMoreOpen = target.open;
  }, true);
  $("shipmentList").addEventListener("input", (event) => {
    const target = event.target;
    if (target instanceof HTMLTextAreaElement && target.matches("[data-ops-brain-input]")) {
      state.opsBrainDraftInput = target.value;
      resizeOpsBrainTextarea(target);
      const form = target.closest("[data-ops-brain-form]");
      if (form instanceof HTMLFormElement) {
        const hasDraft = Boolean(target.value.trim());
        form.toggleAttribute("data-has-draft", hasDraft);
        const button = form.querySelector("button[type='submit']");
        if (button instanceof HTMLButtonElement) {
          button.disabled = !hasDraft;
        }
      }
      return;
    }
    if (!(target instanceof HTMLTextAreaElement)) return;
    const key = target.dataset.todayDoneReason;
    if (!key) return;
    target.removeAttribute("aria-invalid");
    updateTodayDoneReason(key, target.value);
  });

  $("shipmentList").addEventListener("change", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const draftEdit = target.closest("[data-draft-edit-field]");
    if (!draftEdit) return;
    event.preventDefault();
    event.stopPropagation();
    updateDraftEditFromControl(draftEdit);
  });

  $("shipmentList").addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (handleTodayDoneControlClick(event)) return;
    if (target.closest("a[href^='tel:']")) {
      event.stopPropagation();
      return;
    }

    const enablePushAlerts = target.closest("[data-enable-push-alerts]");
    if (enablePushAlerts) {
      event.preventDefault();
      event.stopPropagation();
      subscribeToOperatorPush().then(() => renderList()).catch(() => renderList());
      return;
    }

    const dismissPushAlerts = target.closest("[data-dismiss-push-alerts]");
    if (dismissPushAlerts) {
      event.preventDefault();
      event.stopPropagation();
      state.pushAlertPromptDismissed = true;
      persistPushPromptDismissed();
      renderList();
      return;
    }

    const openShipmentInboxNotification = target.closest("[data-open-shipment-inbox-notification]");
    if (openShipmentInboxNotification) {
      event.preventDefault();
      event.stopPropagation();
      const opened = openOperatorNotificationTarget({
        notificationId: openShipmentInboxNotification.dataset.openShipmentInboxNotification || "",
        awb: openShipmentInboxNotification.dataset.awb || "",
      }, { askFallback: true });
      if (opened) render();
      return;
    }

    const previewAction = target.closest("[data-preview-action]");
    if (previewAction) {
      event.preventDefault();
      event.stopPropagation();
      state.previewActionId = previewAction.dataset.previewAction;
      state.previewQuoteBlastShipmentId = null;
      renderActionSurfaces();
      loadActionPreview(previewAction.dataset.previewAction).catch(() => {});
      return;
    }
    const desk2Roll = target.closest("[data-desk2-roll]");
    if (desk2Roll) {
      event.preventDefault();
      event.stopPropagation();
      if (!(state.desk2OpenRollups instanceof Set)) state.desk2OpenRollups = new Set();
      const key = desk2Roll.dataset.desk2Roll || "";
      if (state.desk2OpenRollups.has(key)) state.desk2OpenRollups.delete(key);
      else state.desk2OpenRollups.add(key);
      renderList();
      return;
    }
    const desk2Lane = target.closest("[data-desk2-lane]");
    if (desk2Lane) {
      event.preventDefault();
      event.stopPropagation();
      const laneId = desk2Lane.dataset.desk2Lane;
      state.desk2LaneFilter = state.desk2LaneFilter === laneId ? null : laneId;
      renderList();
      return;
    }
    const desk2LaneClear = target.closest("[data-desk2-lane-clear]");
    if (desk2LaneClear) {
      event.preventDefault();
      event.stopPropagation();
      state.desk2LaneFilter = null;
      renderList();
      return;
    }
    const composerSendArm = target.closest("[data-composer-send-arm]");
    if (composerSendArm) {
      event.preventDefault();
      event.stopPropagation();
      if (!(state.composerSendConfirm instanceof Set)) state.composerSendConfirm = new Set();
      state.composerSendConfirm.add(composerSendArm.dataset.composerSendArm);
      if (state.composerSendError) delete state.composerSendError[composerSendArm.dataset.composerSendArm];
      renderActionSurfaces();
      return;
    }
    const composerSend = target.closest("[data-composer-send]");
    if (composerSend) {
      event.preventDefault();
      event.stopPropagation();
      const action = findActionById(composerSend.dataset.composerSend);
      if (action) performPlatformSend(action).catch(() => {});
      return;
    }
    const composerEditToggle = target.closest("[data-composer-edit-recipients]");
    if (composerEditToggle) {
      event.preventDefault();
      event.stopPropagation();
      if (!(state.composerRecipientEditOpen instanceof Set)) state.composerRecipientEditOpen = new Set();
      const actionId = composerEditToggle.dataset.composerEditRecipients;
      if (state.composerRecipientEditOpen.has(actionId)) state.composerRecipientEditOpen.delete(actionId);
      else state.composerRecipientEditOpen.add(actionId);
      renderActionSurfaces();
      return;
    }

    const recheckAction = target.closest("[data-recheck-action]");
    if (recheckAction) {
      event.preventDefault();
      event.stopPropagation();
      loadActionPreview(recheckAction.dataset.recheckAction).catch(() => {});
      return;
    }

    const confirmAction = target.closest("[data-confirm-action]");
    if (confirmAction) {
      event.preventDefault();
      event.stopPropagation();
      sendActionFromPlatform(confirmAction.dataset.confirmAction);
      return;
    }

    const openCompletedSource = target.closest("[data-open-completed-source]");
    if (openCompletedSource) {
      event.preventDefault();
      event.stopPropagation();
      state.selectedCompletedSourceAwb = openCompletedSource.dataset.openCompletedSource || "";
      state.selectedId = null;
      state.selectedGroupId = null;
      state.selectedVisualGroupKey = null;
      state.detailOpen = true;
      renderList();
      renderDetail();
      return;
    }

    const generateDocumentAction = target.closest("[data-generate-document-action]");
    if (generateDocumentAction) {
      event.preventDefault();
      event.stopPropagation();
      generateDeliveryOrderFromPlatform(generateDocumentAction.dataset.generateDocumentAction);
      return;
    }

    const closeActionPreview = target.closest("[data-close-action-preview]");
    if (closeActionPreview) {
      event.preventDefault();
      event.stopPropagation();
      if (state.previewActionId === closeActionPreview.dataset.closeActionPreview) state.previewActionId = null;
      renderActionSurfaces();
      return;
    }

    const openTodayDone = target.closest("[data-open-today-done]");
    if (openTodayDone) {
      openTodayDoneAction(openTodayDone.dataset.openTodayDone);
      return;
    }

    const cancelTodayDone = target.closest("[data-cancel-today-done]");
    if (cancelTodayDone) {
      closeTodayDoneAction(cancelTodayDone.dataset.cancelTodayDone);
      return;
    }

    const confirmTodayDone = target.closest("[data-confirm-today-done]");
    if (confirmTodayDone) {
      confirmTodayDoneAction(confirmTodayDone.dataset.confirmTodayDone);
      return;
    }

    const dismissToday = target.closest("[data-dismiss-today-action]");
    if (dismissToday) {
      dismissTodayAction(dismissToday.dataset.dismissTodayAction);
      return;
    }

    const todayActionCard = target.closest(".today-action-card[data-today-shipment-id]");
    if (todayActionCard) {
      if (Date.now() < state.suppressTodayClickUntil || target.closest(".today-done-modal")) return;
      state.selectedId = todayActionCard.dataset.todayShipmentId;
      state.selectedGroupId = null;
      state.selectedVisualGroupKey = null;
      state.selectedCompletedSourceAwb = "";
      state.detailOpen = true;
      syncOpsBrainContextFromSelection("today-action");
      renderList();
      renderDetail();
      return;
    }

    const openControlInbox = target.closest("[data-open-control-inbox]");
    if (openControlInbox) {
      event.preventDefault();
      event.stopPropagation();
      if (isDesktopWorkspace()) {
        state.operatorInboxOpen = true;
        if (state.filter === "inbox") state.filter = "control";
      } else {
        state.filter = "inbox";
      }
      state.selectedCompletedSourceAwb = "";
      $("searchInput").placeholder = isDesktopWorkspace() ? "Search AWB, client, broker, station — ⌘K" : "Search inbox by AWB, client, station, broker";
      render();
      if (Date.now() - state.operatorEventsLoadedAt > 30000) {
        loadOperatorEventsFromApi().then(() => {
          if (state.filter === "inbox" || state.operatorInboxOpen) render();
        }).catch(() => {});
      }
      return;
    }

    const closeControlInbox = target.closest("[data-close-control-inbox]");
    if (closeControlInbox) {
      event.preventDefault();
      event.stopPropagation();
      state.operatorInboxOpen = false;
      if (state.filter === "inbox") state.filter = "control";
      $("searchInput").placeholder = "Search AWB, client, broker, station";
      renderList();
      renderDetail();
      return;
    }

    const controlLane = target.closest("[data-control-lane]");
    if (controlLane) {
      event.preventDefault();
      event.stopPropagation();
      state.controlLane = controlLane.dataset.controlLane || "ready";
      state.controlLaneExplicit = true;
      state.selectedCompletedSourceAwb = "";
      renderList();
      renderDetail();
      return;
    }

    const tile = target.closest(".journey-tile[data-filter]");
    if (tile) {
      const nextFilter = tile.dataset.filter;
      const enteringBrain = nextFilter === "brain" && state.filter !== "brain";
      const enteringInbox = nextFilter === "inbox" && state.filter !== "inbox";
      if (nextFilter === "inbox" && isDesktopWorkspace()) {
        event.preventDefault();
        event.stopPropagation();
        state.operatorInboxOpen = true;
        if (state.filter === "inbox") state.filter = "control";
        $("searchInput").placeholder = "Search AWB, client, broker, station";
        render();
        if (Date.now() - state.operatorEventsLoadedAt > 30000) {
          loadOperatorEventsFromApi().then(() => {
            if (state.operatorInboxOpen) render();
          }).catch(() => {});
        }
        return;
      }
      state.filter = nextFilter;
      if (state.filter === "brain") state.opsBrainHasReadyAnswer = false;
      if (enteringBrain) {
        blurActiveElement();
        settleOpsBrainComposer();
      }
      $("searchInput").placeholder = state.filter === "brain"
        ? "Search memory, or ask in chat below"
        : state.filter === "inbox"
          ? "Search inbox by AWB, client, station, broker"
          : "Search AWB, client, broker, station";
      render();
      if (enteringInbox && Date.now() - state.operatorEventsLoadedAt > 30000) {
        loadOperatorEventsFromApi().then(() => {
          if (state.filter === "inbox") render();
        }).catch(() => {});
      }
      return;
    }

    const brainQuestion = target.closest("[data-brain-question]");
    if (brainQuestion) {
      const surface = brainQuestion.closest("[data-companion-dock]")
        ? "dock"
        : brainQuestion.closest("[data-cockpit-chat]") ? "cockpit" : "";
      activateOpsBrainScopeForSurface(surface);
      submitOpsBrainQuestion(brainQuestion.dataset.brainQuestion || "", {
        clarificationOptionId: brainQuestion.dataset.brainClarificationOption || "",
      });
      return;
    }

    const expandOpsBrainResults = target.closest("[data-expand-ops-brain-results]");
    if (expandOpsBrainResults) {
      event.preventDefault();
      event.stopPropagation();
      const key = expandOpsBrainResults.dataset.expandOpsBrainResults || "";
      if (key) {
        state.expandedOpsBrainResults.add(key);
        renderList();
      }
      return;
    }

    const clearBrainChat = target.closest("[data-clear-ops-brain-chat]");
    if (clearBrainChat) {
      clearOpsBrainChat();
      return;
    }

    const prodHealthSummary = target.closest("[data-prod-health-panel] > summary");
    if (prodHealthSummary) {
      window.setTimeout(() => {
        state.prodHealthOpen = Boolean(prodHealthSummary.parentElement?.open);
      }, 0);
    }

    const dismissOpsBrainAlert = target.closest("[data-dismiss-ops-brain-alert]");
    if (dismissOpsBrainAlert) {
      event.preventDefault();
      event.stopPropagation();
      const key = dismissOpsBrainAlert.dataset.dismissOpsBrainAlert || "";
      if (key) {
        state.dismissedOpsBrainAlerts.add(key);
        persistDismissedOpsBrainAlerts();
        renderList();
      }
      return;
    }

    const openOpsBrainAlert = target.closest("[data-open-ops-brain-alert]");
    if (openOpsBrainAlert) {
      event.preventDefault();
      event.stopPropagation();
      const alert = opsBrainPlatformAlerts().find((item) => item.key === openOpsBrainAlert.dataset.openOpsBrainAlert);
      if (alert?.awb) {
        submitOpsBrainQuestion(`what needs action on ${alert.awb}?`);
      } else if (alert?.shipmentId) {
        state.selectedId = alert.shipmentId;
        state.selectedGroupId = null;
        state.selectedVisualGroupKey = null;
        state.selectedCompletedSourceAwb = "";
        state.detailOpen = true;
        syncOpsBrainContextFromSelection("ops-brain-alert");
        renderList();
        renderDetail();
      }
      return;
    }

    const handleOpsBrainAction = target.closest("[data-handle-ops-brain-action]");
    if (handleOpsBrainAction) {
      event.preventDefault();
      event.stopPropagation();
      const action = findOpsBrainActionByKey(handleOpsBrainAction.dataset.handleOpsBrainAction || "");
      const note = window.prompt(opsBrainActionUpdatePrompt(action));
      if (note === null) return;
      markOpsBrainActionHandled(handleOpsBrainAction.dataset.handleOpsBrainAction || "", note.trim());
      return;
    }

    const companionToggle = target.closest("[data-open-companion-panel]");
    if (companionToggle) {
      event.preventDefault();
      event.stopPropagation();
      // Top-bar "Ask Yael" is the GENERAL companion entry: opening always
      // lands in the all-shipments scope so the operator knows exactly who
      // they are talking to. Clicking again closes.
      if (state.companionPanelOpen) {
        state.companionPanelOpen = false;
      } else {
        activateOpsBrainChatScope("global");
        state.companionPanelOpen = true;
      }
      renderList();
      focusDesktopCompanionInput();
      return;
    }
    const companionClose = target.closest("[data-close-companion-panel]");
    if (companionClose) {
      event.preventDefault();
      event.stopPropagation();
      state.companionPanelOpen = false;
      // Returning to a shipment cockpit re-arms its in-page chat.
      const cockpitShipment = desktopStageSelectedShipment();
      if (cockpitShipment) activateOpsBrainChatScopeForShipment(cockpitShipment, "selection");
      renderList();
      return;
    }
    const companionOpen = target.closest("[data-companion-open-awb]");
    if (companionOpen) {
      event.preventDefault();
      event.stopPropagation();
      const opened = openOperatorInboxItemTarget({ awb: companionOpen.dataset.companionOpenAwb || "" }, { keepFilter: isDesktopWorkspace() });
      if (opened) render();
      return;
    }
    const openInboxShipment = target.closest("[data-open-inbox-shipment]");
    if (openInboxShipment) {
      const operatorInboxItem = openInboxShipment.closest("[data-open-operator-inbox-item]");
      if (operatorInboxItem) {
        event.preventDefault();
        event.stopPropagation();
        const opened = openOperatorInboxItemTarget({
          notificationId: operatorInboxItem.dataset.notificationId || "",
          shipmentId: operatorInboxItem.dataset.shipmentId || "",
          awb: operatorInboxItem.dataset.awb || "",
        }, { askFallback: !isDesktopWorkspace(), keepFilter: isDesktopWorkspace() });
        if (opened) render();
        return;
      }
    }

    const operatorInboxItem = target.closest("[data-open-operator-inbox-item]");
    if (operatorInboxItem && !target.closest("[data-preview-action], [data-recheck-action], [data-confirm-action], [data-generate-document-action], [data-handle-ops-brain-action], form, input, textarea, select, a")) {
      event.preventDefault();
      event.stopPropagation();
      const opened = openOperatorInboxItemTarget({
        notificationId: operatorInboxItem.dataset.notificationId || "",
        shipmentId: operatorInboxItem.dataset.shipmentId || "",
        awb: operatorInboxItem.dataset.awb || "",
      }, { askFallback: !isDesktopWorkspace(), keepFilter: isDesktopWorkspace() });
      if (opened) {
        if (isDesktopWorkspace()) {
          state.stageFocus = "shipment";
          state.operatorInboxOpen = false;
          state.detailOpen = false;
        }
        render();
      }
      return;
    }

    const brainShipment = target.closest("[data-brain-shipment-id]");
    if (brainShipment) {
      event.preventDefault();
      event.stopPropagation();
      const shipmentId = brainShipment.dataset.brainShipmentId || "";
      const shipment = opsBrainShipments().find((item) => item.id === shipmentId || item.awb === shipmentId);
      const awb = brainShipment.dataset.brainAwb || shipment?.awb || shipmentId;
      if (awb) {
        if (shipment) setOpsBrainContextFromShipment(shipment, "ops-brain-result");
        submitOpsBrainQuestion(`what about ${awb}?`);
      }
      return;
    }

    const cargoCard = target.closest(".cargo-card[data-visual-group]");
    if (cargoCard) {
      openCargoCard(cargoCard);
      return;
    }

    const stageBack = target.closest("[data-stage-back]");
    if (stageBack) {
      state.stageFocus = "queue";
      renderList();
      return;
    }

    const detailDrawer = target.closest("[data-open-detail-drawer]");
    if (detailDrawer) {
      state.detailOpen = true;
      renderList();
      renderDetail();
      return;
    }

    const stageSelect = target.closest("[data-stage-select]");
    if (stageSelect) {
      const stageShipmentId = stageSelect.dataset.stageSelect || "";
      if (stageShipmentId) {
        state.selectedId = stageShipmentId;
        state.selectedGroupId = null;
        state.selectedVisualGroupKey = null;
        state.selectedCompletedSourceAwb = "";
        state.stageFocus = "shipment";
        const stageShipment = state.shipments.find((item) => item.id === stageShipmentId);
        if (stageShipment) {
          state.controlLane = controlRoomLaneForShipment(stageShipment);
          state.controlLaneExplicit = true;
        }
        state.operatorInboxOpen = false;
        // Desktop works in the stage; full detail opens on demand.
        state.detailOpen = !isDesktopWorkspace();
        syncOpsBrainContextFromSelection("selection");
        renderList();
        renderDetail();
      } else {
        state.operatorInboxOpen = true;
        renderList();
      }
      return;
    }

    const row = target.closest(".shipment-row[data-id]");
    if (row) {
      state.selectedId = row.dataset.id;
      state.selectedGroupId = null;
      state.selectedVisualGroupKey = null;
      state.selectedCompletedSourceAwb = "";
      state.stageFocus = "shipment";
      const rowShipment = state.shipments.find((item) => item.id === row.dataset.id);
      if (rowShipment) {
        state.controlLane = controlRoomLaneForShipment(rowShipment);
        state.controlLaneExplicit = true;
      }
      state.operatorInboxOpen = false;
      state.detailOpen = !isDesktopWorkspace();
      syncOpsBrainContextFromSelection("selection");
      renderList();
      renderDetail();
      return;
    }

    const groupRow = target.closest(".shipment-row[data-group-id]");
    if (groupRow) {
      state.selectedGroupId = groupRow.dataset.groupId;
      state.selectedId = null;
      state.selectedVisualGroupKey = null;
      state.selectedCompletedSourceAwb = "";
      state.detailOpen = true;
      renderList();
      renderDetail();
    }
  });

  $("shipmentList").addEventListener("submit", (event) => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement) || !form.matches("[data-ops-brain-form]")) return;
    event.preventDefault();
    const input = form.querySelector("[data-ops-brain-input]");
    submitOpsBrainInput(input);
  });

  $("shipmentList").addEventListener("beforeinput", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLTextAreaElement) || !target.matches("[data-ops-brain-input]")) return;
    if (event.inputType !== "insertLineBreak" || event.isComposing) return;
    if (opsBrainShiftLineBreakInputs.has(target)) {
      opsBrainShiftLineBreakInputs.delete(target);
      return;
    }
    event.preventDefault();
    submitOpsBrainInput(target);
  });

  $("shipmentList").addEventListener("keydown", (event) => {
    const target = event.target;
    if (target instanceof Element) {
      const operatorInboxItem = target.closest("[data-open-operator-inbox-item]");
      if (operatorInboxItem && ["Enter", " "].includes(event.key) && !target.closest("[data-preview-action], [data-recheck-action], [data-confirm-action], [data-generate-document-action], [data-handle-ops-brain-action], form, input, textarea, select, a")) {
        event.preventDefault();
        const opened = openOperatorInboxItemTarget({
          notificationId: operatorInboxItem.dataset.notificationId || "",
          shipmentId: operatorInboxItem.dataset.shipmentId || "",
          awb: operatorInboxItem.dataset.awb || "",
        }, { askFallback: !isDesktopWorkspace(), keepFilter: isDesktopWorkspace() });
        if (opened) render();
        return;
      }
    }
    if (!(target instanceof HTMLTextAreaElement) || !target.matches("[data-ops-brain-input]")) return;
    if (event.key !== "Enter" || event.isComposing) return;
    if (event.shiftKey) {
      opsBrainShiftLineBreakInputs.add(target);
      window.setTimeout(() => opsBrainShiftLineBreakInputs.delete(target), 0);
      return;
    }
    event.preventDefault();
    submitOpsBrainInput(target);
  });

  document.addEventListener("keydown", (event) => {
    if ((event.metaKey || event.ctrlKey) && String(event.key || "").toLowerCase() === "k") {
      const search = document.getElementById("searchInput");
      if (search && isDesktopWorkspace()) {
        event.preventDefault();
        search.focus();
        search.select();
      }
      return;
    }

    if (event.key === "Escape" && state.companionPanelOpen && !state.operatorInboxOpen) {
      state.companionPanelOpen = false;
      const cockpitShipment = desktopStageSelectedShipment();
      if (cockpitShipment) activateOpsBrainChatScopeForShipment(cockpitShipment, "selection");
      renderList();
      return;
    }
    if (event.key === "Escape" && state.operatorInboxOpen) {
      event.preventDefault();
      state.operatorInboxOpen = false;
      if (state.filter === "inbox") state.filter = "control";
      renderList();
      renderDetail();
      return;
    }
    if (event.key === "Escape" && state.activeTodayDoneKey) {
      event.preventDefault();
      closeTodayDoneAction(state.activeTodayDoneKey);
      return;
    }
    if (event.target.closest?.("[data-dismiss-today-action], [data-open-today-done], [data-cancel-today-done], [data-confirm-today-done], .today-done-modal")) return;
    const todayActionCard = event.target.closest?.(".today-action-card[data-today-shipment-id]");
    if (todayActionCard && ["Enter", " "].includes(event.key)) {
      event.preventDefault();
      state.selectedId = todayActionCard.dataset.todayShipmentId;
      state.selectedGroupId = null;
      state.selectedVisualGroupKey = null;
      state.detailOpen = true;
      renderList();
      renderDetail();
      return;
    }
    const cargoCard = event.target.closest?.(".cargo-card[data-visual-group]");
    if (cargoCard && ["Enter", " "].includes(event.key) && !event.target.closest?.("[data-copy-awb]")) {
      event.preventDefault();
      openCargoCard(cargoCard);
      return;
    }
    const brainShipment = event.target.closest?.("[data-brain-shipment-id]");
    if (brainShipment && ["Enter", " "].includes(event.key) && !event.target.closest?.("[data-copy-awb]")) {
      event.preventDefault();
      const shipmentId = brainShipment.dataset.brainShipmentId || "";
      const shipment = opsBrainShipments().find((item) => item.id === shipmentId || item.awb === shipmentId);
      const awb = brainShipment.dataset.brainAwb || shipment?.awb || shipmentId;
      if (awb) submitOpsBrainQuestion(`what about ${awb}?`);
      return;
    }
    if (event.key === "Escape" && detailShouldRender()) {
      closeDetail();
    }
  });

  window.matchMedia?.(desktopWorkspaceQuery).addEventListener("change", () => {
    render();
  });

  // Desktop: Escape closes the topmost layer (preview -> detail -> inbox).
  // Phone behavior is untouched.
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !isDesktopWorkspace()) return;
    if (event.target instanceof HTMLElement && ["INPUT", "TEXTAREA", "SELECT"].includes(event.target.tagName)) return;
    if (state.previewActionId) {
      state.previewActionId = null;
      renderActionSurfaces();
    } else if (state.detailOpen) {
      closeDetail();
    } else if (state.operatorInboxOpen) {
      state.operatorInboxOpen = false;
      renderList();
    }
  });
}

async function init() {
  retireLegacyBrowserOperatorTruth();
  const initialTruthHealthPromise = loadTruthHealth().catch(() => null);
  initialSnapshotPromise = loadSnapshot();
  bindEvents();
  initPushAlerts().catch(() => {});
  await Promise.allSettled([initialSnapshotPromise, initialTruthHealthPromise]);
  if (!brainShipmentTruthLoadedAt) await loadBrainShipmentTruthOverlay();
  await loadOperatorEventsFromApi().catch(() => {});
  startAgentJobPolling();
  startBoardPolling();
  render();
  if (state.pendingOperatorNotificationTarget) {
    openOperatorNotificationTarget(state.pendingOperatorNotificationTarget, { askFallback: true });
    state.pendingOperatorNotificationTarget = null;
    render();
  }
  refreshBrainShipmentTruthAfterRender({ minAgeMs: 0 });
  window.setTimeout(refreshTruthHealthAfterRender, 60000);
  maybeLoadCurrentEmailProofPacket();
  refreshGmailProofAfterRender()
    .then(() => maybeQueueStaleEmailProofRefresh("initial-load"))
    .catch(() => {});
}

init();
